BEGIN TRANSACTION;

-- Migrations Table (adjusted for PostgreSQL)
CREATE TABLE IF NOT EXISTS "_prisma_migrations" (
    "id"                    UUID PRIMARY KEY NOT NULL,  -- Use UUID for better type safety (optional)
    "checksum"              TEXT NOT NULL,
    "finished_at"           TIMESTAMP,  -- Use TIMESTAMP instead of DATETIME
    "migration_name"        TEXT NOT NULL,
    "logs"                  TEXT,
    "rolled_back_at"        TIMESTAMP,  -- Use TIMESTAMP instead of DATETIME
    "started_at"            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,  -- Use TIMESTAMP instead of DATETIME
    "applied_steps_count"   INTEGER NOT NULL DEFAULT 0
);

-- Insert the migration data

-- "Recipe" Table (adjusted for PostgreSQL)
CREATE TABLE IF NOT EXISTS "Recipe" (
    "id" SERIAL PRIMARY KEY,  -- Use SERIAL for auto-increment in PostgreSQL
    "title" TEXT NOT NULL,
    "image" TEXT,
    "ingredients" TEXT NOT NULL,
    "instructions" TEXT NOT NULL,
    "prepTime" INTEGER,
    "cookTime" INTEGER,
    "favoriteCount" INTEGER NOT NULL DEFAULT 0
);

COMMIT;
