INSERT INTO _prisma_migrations VALUES('26447229-2856-4f08-9cd5-a2588e23beb8','4ff85c7d2756f017ad1467a7250962abe0da4588c6189d6627e24adf7f978398', '2025-01-19 08:14:52', '20250119081452_init', NULL, NULL, '2025-01-19 08:14:52', 1);
INSERT INTO "Recipe" VALUES(1,'Cheese Pork Chops','https://img.spoonacular.com/recipes/637569-556x370.jpg','2 tablespoons dijon mustard, 0.5 cup gruyere cheese, 0.5 cup heavy cream, 1 teaspoon olive oil, 4  pork chops, 4 servings salt and pepper, 1 tablespoon butter','In a heavy bottom skillet melt the butter with the olive oil. Saut` the pork chops over medium high 3 minutes on each sided. Lower the heat to medium and cook for another 5 to 6 minutes for side.Salt and pepper to taste.Meanwhile turn on the broil. Mix together in a bowl the heavy cream, mustard and the cheese. Remove the chops from the stove and place them in a oven proof dish. Spread the cheese-cream mixture over the chops and broil for about 5 minutes.',30,30,3);
INSERT INTO "Recipe" VALUES(2,'Spaghetti With Pesto Trapanese','https://img.spoonacular.com/recipes/660835-556x370.jpg','1 pound spaghetti, 0.5 cup almonds, 0.25 cup pine nuts, 0.5 cup extra virgin olive oil, 3  garlic cloves, 2  tomatoes, 2.5 cups basil, 6 servings salt and pepper, 6 servings pecorino',replace('Place a large (this is key) pot of water to boil. Salt when it boils, not before.\nMeanwhile, make the pesto: In a mortar (or use a food processor with a blade) pound together the oil, almonds and pine-nuts. Add the garlic, 2 ice cubes and the rest of the ingredients, pounding quickly to make a paste.You want to leave a bit of a texture for crunch.\nCook the pasta al dente, as per directions, drain and reserve some of the boiling water. Toss the pasta with the pesto, using some of the reserved water to make it creamier. Grate some fresh pecorino or ricotta salata (or both) over and serve hot with a leaf of basil to garnish.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(3,'Triple Chocolate Whoppers','https://img.spoonacular.com/recipes/663833-556x370.jpg','6 ounces semisweet baking chocolate, 2 teaspoons baking powder, 0.75 cup brown sugar, 2 oz chocolate into chunks, 2  eggs, 1 teaspoon plus 2 espresso powder, 0.5 cup pecans, 0.5 teaspoon sea salt, 1 cup semisweet chocolate chips, 0.5 cup unbleached flour, 0.5 cup butter, 1 teaspoon vanilla extract, 1 cup walnuts','Preheat the oven to 325 degrees F (163 degrees C).Lightly grease 2 baking sheets. Set aside.Combine semisweet chocolate, unsweetened chocolate chunks, and  butter in a double boiler. Melt the chocolate over low heat until just melted, stirring occasionally. Be careful, not to burn the chocolate. Remove immediately. Stir to blend the butter and chocolate off the heat, and set aside.Combine the eggs, espresso powder, and vanilla extract in a large bowl and cream together using an electric mixer. Add the brown sugar and mix until creamy.In a separate bowl, sift together the flour, baking powder, and sea salt. Set aside.Add the melted chocolate and butter to the egg mixture and blend together using an electric mixture. Then add the flour mixture and stir by hand just until the dry ingredients and are moist.Add the chopped nuts and the chocolate chips to the chocolate and flour mixture folding them in gently. Note:  The dough will be relatively soft.Drop by large tablespoonfuls onto the greased baking sheets at least 3 inches apart. If you want your cookies to look uniform in size then use a 2 oz. cookie or ice cream scoop.  Bake immediately to prevent the chocolate from hardening for 10 to 12 minutes. Rotate the pan halfway through the baking time. The cookies will still be very soft and sticky inside, but do not overcook the cookies or they will be crispy, rather than chewy. Cool for 10 minutes on the baking sheets before gently removing the whoppers to a baking rack to cool completely.Store the cookies in an airtight container separating the layers with wax paper.Makes about 1 dozen 3-inch cookies',45,45,0);
INSERT INTO "Recipe" VALUES(4,'Chocolate Asparagus Bundt Cake','https://img.spoonacular.com/recipes/638819-556x370.jpg','1 pound asparagus, 1 teaspoon baking soda, 0.33333334 cup cocoa powder, 3  eggs, 2 cups flour, 1 teaspoon ground cinnamon, 1 tablespoons orange peel, 1 cup pecans, 0.5 teaspoon salt, 0.75 cup sugar, 2 teaspoons vanilla extract, 0.5 cup vegetable oil','Preheat oven to 350 F.In a large bowl, combine flour, sugar, baking soda, cinnamon, cocoa powder, and salt.Add oil, eggs, asparagus, orange peel and vanilla; mix well.Fold in pecans.Pour into a greased and floured 10-in. bundt pan. Bake for 1 hour or until a toothpick inserted comes out clean. Cool for 10 minutes; remove from pan to a wire rack to cool completely.',45,45,0);
INSERT INTO "Recipe" VALUES(5,'Blue Cheese Tartlets With Fig Jam and Walnuts','https://img.spoonacular.com/recipes/635370-556x370.jpg','3 ounces cheese, 0.5 cup butter, 1 cup fig jam, 1.25 cups flour, 1  orange zest, 30 servings walnuts','Preheat the oven to 350F. Lightly grease the cups of the mini muffin pans, unless youre using non-stick pans.In a medium bowl cream together the blue cheese and butter. Add the flour and use your hands to bring the dough together in the bowl.Divide the dough into 30 pieces and roll into balls. (If you prefer a more delicate shell, divide the dough into 36 pieces.)Using lightly floured fingers evenly press the dough against the sides of the mini tart pan until the dough rises slightly above the rim of the muffin cup.Bake for 15 minutes, until golden brown. Cool in pans for 5 minutes. Remove shells to a wire rack to finish cooling.Store cooled shells in an airtight container until ready to use. (They freeze well too. Bake frozen shells for 8 minutes at 325F before filling.)Spoon jam into cooled tartlet shells. Sprinkle with toasted walnuts, orange zest, and thyme leaves if using.',45,45,0);
INSERT INTO "Recipe" VALUES(6,'Zabaglione with Roasted Plums','https://img.spoonacular.com/recipes/665620-556x370.jpg','12  plums, 6 tablespoons sugar, 4 large egg yolks, 0.25 cup plum brandy, 4 servings kosher salt',replace('1.Heat the oven the to 400F. Place the plums on a rimmed cookie sheet (lined with parchment paper for easier cleanup) and sprinkle with 2 tablespoons of the sugar. Roast until the plums are browning and tender but not falling apart, about 15 minutes.\n2.Bring about 2 inches of water to a bare simmer in a saucepan over medium-high heat. Reduce the heat to maintain a bare simmer. Combine the egg yolks, the remaining 4 tablespoons sugar, the plum brandy mixture, and a pinch of salt in a round-bottomed metal mixing bowl; whisk thoroughly.\n3.Set the bowl over the simmering waterthe base of the bowl should not touch the waterand whisk continuously. The egg yolks will begin to froth, lighten, and grow greatly in volume. If you sense that the yolks are at risk of scrambling, quickly remove the bowl from the heat and whisk to cool slightly, then continue. When soft peaks form, after 5 to10 minutes, the zabaglione is done. Transfer to a clean bowl, cover, and refrigerate.\n4.To serve, place 6 plum halves in the bottom of each of 4 glasses. Give the zabaglione a quick whisk and spoon it on top of the plums. Serve immediately.','\n',chr(10)),20,20,0);
INSERT INTO "Recipe" VALUES(7,'Rosemary Rum Raisin Soda Bread with Pecans','https://img.spoonacular.com/recipes/658803-556x370.jpg','0.5 cup raisins, 0.33333334 cup rum, 2 cups flour, 2 cups flour, 2 teaspoons baking soda, 1 teaspoon salt, 1 tablespoon rosemary, 0.5 cup pecans, 1.5 cups yogurt, 1 tablespoon honey, 1 tablespoon milk, 0.75 teaspoon anise seeds',replace('Combine the rum and raisins in a small saucepan. Bring to a boil. Simmer for 30 seconds, then remove from heat. Cover and allow the raisins to macerate for at least 4 hours, but preferably overnight.\nWhen youre ready to bake the bread, preheat the oven to 375F.\nCoat a baking sheet with olive oil and lightly dust it with flour, or line it with parchment paper.\nIn a large mixing bowl whisk together the flours, baking soda, salt, and rosemary. Stir in the toasted pecans.\nIn a separate bowl combine the raisins with the rum, the yogurt, and honey.\nAdd the wet ingredients to the dry. Mix until the dough is too stiff to stir. Use your hands to bring it together in the bowl. Add additional yogurt one teaspoon at a time if its too dry. You want a stiff, slightly tacky ball.\nTurn dough onto a lightly floured board and shape into a round loaf. (Dont over-knead the dough. Too much kneading will produce a tough bread.).\nTransfer the loaf to the prepared baking sheet. Use a sharp knife to make deep slashes across the top of the loaf, 4-6 cuts about half way through. Brush the top with milk. Sprinkle with seeds or oats if using.\nBake for 40-45 minutes, until a toothpick comes out clean. When you tap the loaf, it will sound hollow.\nCool on a wire rack. Serve warm or at room temperature with a generous slather of butter.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(8,'Savory Slow Roasted Tomatoes with Filet of Anchovy','https://img.spoonacular.com/recipes/631757-556x370.jpg','4  round tomatoes, 1 small handful any herbs you like, 4 servings salt & pepper, 4 servings extra virgin olive oil, 8  anchovy filets',replace('Preheat oven to 150 C or 280 F\nCut the top 3rd off the tomatoes & discard top.\nPlace tomatoes on a baking tray, lined with parchment paper. Sprinkle generously with salt, pepper & herbs. Drizzle with a generous amount of olive oil.  Place in the oven for 4-6 hours depending on the size of your tomatoes. Every once in a while as you pass the kitchen, baste the tomatoes in the juices & olive oil in the pan.\nOnce the tomatoes shrivel up a bit & start to look sun-dried, they are ready. They should still hold their shape & not become mush.\nRemove from oven, top each tomato with a whole anchovy filet. Serve warm or room temperature with olive oil from the baking pan drizzled over the top.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(9,'Brown Butter Twice Baked Sweet Potatoes','https://img.spoonacular.com/recipes/715544-556x370.jpg','2  avocados, 2 tablespoons buttermilk, 4 strips bacon, 0.25 cup parsley, 6 ounces goat''s cheese, 4 servings salt and pepper, 0.5 cup cream, 4 medium sweet potatoes, 6 tablespoons butter','Preheat your oven to 400 degrees F. Poke your sweet potatoes with a fork and place them directly on the rack of your oven. Place a piece of foil on the rack below to reduce mess. Bake the sweet potatoes for 45-50 minutes or until tender. Times may vary depending on how hot your oven gets.Remove the potatoes from the oven and let stand at room temperature until they are cool enough to handle, about 20-30 minutes. Leave the oven on.While your potatoes are cooling, melt the butter over medium heat. Continue to cook the butter, stirring frequently, until brown bits begin to form on the bottom of the pan, about 5-6 minutes. Pay close attention as the butter can quickly go from brown to burnt in a matter of seconds. Once you see the brown bits forming and a nutty aroma fills the air, pull the butter from the heat immediately. Set aside.Cut the tops off of the sweet potatoes, lengthwise. Scoop the sweet potato flesh into a medium bowl, leaving the skins in tact. To the bowl, add the brown butter, 2 tablespoons of the fresh parsley, 3/4 of the chopped bacon, and 4 ounces of the goats cheese. Sprinkle with salt and black pepper to taste and mash the ingredients together until combined. Scoop the filling back into the sweet potatoes.Place the potatoes on a baking sheet that has been lined with foil or parchment paper. Place them back in the oven to bake for 25 minutes.While your potatoes are baking for a second time, prepare your avocado cream. In the bowl of your food processor or blender, combine the avocados, sour cream and buttermilk. Add a dash of salt and pepper and pulse until completely smooth and creamy.Once your potatoes have baked, remove from oven. Sprinkle on the remaining parsley, bacon and goats cheese. Drizzle with avocado cream and serve immediately.Enjoy!I hope you enjoy this "Recipe" for brown butter twice baked sweet potatoes!',95,95,0);
INSERT INTO "Recipe" VALUES(10,'Blueberry Basil Galette','https://img.spoonacular.com/recipes/635414-556x370.jpg','3 cups blueberries, 2 teaspoons virgin coconut oil oil, 0.25 cup basil leaves, 0.5 tablespoon lemon juice, 1 teaspoon lemon zest, 0.25 cup maple syrup, 2 tablespoons quick-cooking tapioca, 0.125 teaspoon sea salt, 1.5 cups spelt flour, 0.25 cup sugar, 1 cup up to ¼ water','To make sweet tart dough:Mix flour and salt.Melt coconut oil, then stir with flour and salt until mixture resembles coarse meal.Add maple syrup gradually (if dough does not hold together on its own, add just enough ice water to hold dough together).Mix until a soft workable ball forms in the bowl; do not overmix.Add a small amount of flour if necessary.Shape the dough with your hands into a flattened disc.Roll dough out between two sheets of parchment paper; dust flour over the bottom sheet and on top of the dough.Use quick gentle strokes to start rolling from the center outward in each direction, like a compass.Transfer the parchment covered dough onto a baking sheet.Refrigerate the dough on the baking sheet while preparing the blueberry filling.To make blueberry basil filling:Preheat oven to 350 F.In a medium bowl, whisk 1/4 cup of the sugar, arrowroot powder, and sea salt together.Rinse and drain blueberries in a strainer, then transfer to a towel and blot dry.Gently stir in blueberries, basil, lemon zest, and lemon juice; set aside.Remove dough from refrigerator.Peel off top layer of parchment paper.Pour blueberry filling over tart dough, leaving a 2-inch border.Fold the dough border over the blueberry filling to form a pleated ruffle.Brush the folded dough border with 2 teaspoons oil, then pat the berries with the rest.Sprinkle the crust with 2 teaspoons of sugar.Bake about 45-55 minutes, or until the galette is golden and thick juices bubble on top.Cool completely before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(11,'Spare Ribs','https://img.spoonacular.com/recipes/660884-556x370.jpg','2 tablespoons oil, 3 tablespoons clear honey, 1 piece ginger root, 2 tablespoons soy sauce, 2 tablespoons hoisin sauce, 1 teaspoon five-spice powder, 2  garlic cloves, 2 pounds spare ribs',replace('Preheat oven 400 degrees.\nCombine all the ingredients, except the spare ribs, in a jug and mix well. Pour over the ribs and leave to marinate for as long as possible, ideally overnight.\nPlace the ribs on a rack in a roasting pan. Cook in a preheated oven at 400 degrees for about 45 minutes, turning the ribs over half way through the cooking time. Allow to cool and serve cold.','\n',chr(10)),45,45,5);
INSERT INTO "Recipe" VALUES(12,'Chocolate Banana Zucchini Cake','https://img.spoonacular.com/recipes/638831-556x370.jpg','0.5 cup butter, 2 cups all purpose flour, 0.5 cup cocoa powder, 1 teaspoon baking soda, 0.5 teaspoon baking powder, 0.5 teaspoon salt, 1 cup brown sugar, 4 tablespoons sugar, 1 teaspoon vanilla extract, 1 teaspoon coffee granules, 2 large eggs, 1 cup zucchini, 1 large overripe banana, 1 cup bittersweet chocolate chips, 8 servings confectioner''s sugar - optional',replace('Pre-heat the oven to 350 degrees F and grease a 10-inch cake or springform pan with oil.\nIn a large mixing bowl, whisk together the flour, cocoa powder, baking soda, baking powder and salt.\nIn a food processor, process the sugar and butter until creamy. You can also do this by hand using a sturdy spatula.\nAdd the vanilla essence, coffee granules and eggs mixing well between each addition.\nReserve a cup of the flour mixture and add the rest to the egg mixture. Mix until just combined. The batter will be thick.\nAdd the mashed banana and mix. Don''t overmix.The batter will be lumpy.\nAdd the zucchini and chocolate chips to the reserved flour mixture and toss to coat.\nFold into the batter and blend with a spatula- don''t overmix.\nPour into the prepared cake pan and level the surface with a spatula.\nBake for 40-50 min, until a knife inserted in the center comes out clean. Let it cool for 10 min, run a knife around the pan to loosen the cake and take the cake out carefully on the cooling rack.\nLet it come to room temperature. Sprinkle with confectioner''s sugar or glaze with melted chocolate.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(13,'Grilled Chuck Burgers with Extra Sharp Cheddar and Lemon Garlic Aioli','https://img.spoonacular.com/recipes/645680-556x370.jpg','4 servings arugula, 8.5 inch cheddar cheese, 1  garlic clove, 1 pound ground chuck, 1 teaspoon lemon juice, 0.25 cup mayonnaise, 2 tablespoons olive oil, 0.125 cup parsley, 4 servings bell pepper, 1  onion, 4 servings salt, 4  kaiser rolls, 2 teaspoons worcestershire sauce','To prep the burgers:  In a medium bowl, toss in the ground meat, 1/2 teaspoon salt, 1/2 teaspoon pepper, and Worcestershire sauce.Mix together with a fork.Once the ingredients have been combined, form four patties.To prep the red onion:  Brush olive oil on both sides of all the slices and then sprinkle with some salt and pepper.For the lemon garlic aioli:  In a small bowl, mix all the ingredients together.Place back in refrigerator until burgers are cooked.To cook:  Preheat grill to around 350.If using cast iron grates, use a paper towel or cloth to wipe all grates with canola oil.Place burger patties on grill.Close lid and prep the buns by brushing canola oil on insides.After a few minutes, check the patties.  If the bottom half looks just about cooked, roughly 3 minutes, flip over, and place cheese on top.Add red onions and buns (cut side down).Close lid.  After another 3 or so minutes, remove everything from grill.  The cheese wont be completely melted, because of the thickness, but its okay, thats the point ;-)  The cheese will stay extra sharp if the inside isnt melted.  On the red onions, youre looking for good char marks on one side, but the onion still a bit crunchy.  For the buns, youre looking to get the bottoms nice and charred, but not so much as to make the bread tough.To assemble the burger:  Place a handful of arugula leaves on the bottom slice of the bun.Place burger with cheese slice on top.Add the grilled red onions.Slather the aioli liberally on the top half of the bun.',45,45,0);
INSERT INTO "Recipe" VALUES(14,'Vegetable Tart With Goat Cheese','https://img.spoonacular.com/recipes/664615-556x370.jpg','1 cup spinach, 0.25 cup goat cheese, 1 cup mushrooms, 1 sheet puff pastry, 1  bell pepper, 4 servings salt and pepper','Pre-heat oven to 350F. Roll out puff pastry onto a cookie sheet, leaving parchment paper on pan to keep it from sticking. Spread spinach over the top, leaving an inch of the sides uncovered. Spread mushrooms on top of spinach and add bell pepper slices on top. Sprinkle crumbled goat cheese over the top. Salt and pepper to taste. Bake for 15-20 minutes',25,25,0);
INSERT INTO "Recipe" VALUES(15,'Cheese Tortellini With Shrimp In Tomato Cream Sauce','https://img.spoonacular.com/recipes/637593-556x370.jpg','14 ounces canned tomatoes, 1 bag cheese tortellini, 1  chicken bullion cube, 2 teaspoons parsley, 4 teaspoons thyme, 2 large garlic cloves, 1.5 cups half and half, 4 Tbs olive oil, 4 servings parmesan cheese, 4 servings salt and freshly grounded pepper, 0.5 pound shrimp','Thaw frozen shrimp according to package directions if using frozen, and then peel, devein and rinse shrimp in a colander.While shrimp are draining, fill a medium size saucepan with cold water and cook tortellini according to package directions.  Do NOT overcook your tortellini, no more than 2-3 mins once tortellini are added to boiling water.Drain pasta and set aside.Using the same saucepan combine diced tomatoes, crushed bullion, parsley and thyme and bring to a low simmer.While tomatoes are simmering bring a large skillet to medium heat and add olive oil.  Heat olive oil and add minced garlic, cooking just until slightly opaque (approx. 1 min).  Add garlic and olive oil to tomatoes, stir.  Taking a fork crush tomatoes, breaking up the pieces until you have a chunky sauce.Add cream to skillet that you used for garlic and bring to a low simmer.  Add tomato sauce, Parmesan cheese and salt and pepper to taste to cream and bring to slow simmerAdd cream to skillet that you used for garlic and bring to a slow simmer.Add tomato sauce, Parmesan cheese and salt and pepper to taste to cream and bring back up to a slow simmer.Reduce heat on cream sauce to low to keep warm and continue to stir occasionally.At this point you can butterfly your shrimp, which helps to make the amount of shrimp seem more substantial, but this is not a necessary step.To butterfly your shrimp, place on cutting board and with a very sharp knife, open up shrimp along the back but not cutting all the way through.Add shrimp to cream sauce and cover, allowing shrimp to cook for approximately 4-5 minutes.Add tortellini to pan coating  with cream sauce and seasoning if necessary with additional salt and pepper.  Remove from heat.Plate and top with a sprinkle of shredded parmesan cheese.',45,45,0);
INSERT INTO "Recipe" VALUES(16,'The BEST Sweet Potato Casserole','https://img.spoonacular.com/recipes/1043340-556x370.jpg','2  eggs, 0.5 tsp ground cinnamon, 2 tbsp heavy cream, 1 cup sugared pecans make these the day before, 0.25 tsp salt, 2 large cans sweet potatoes yams -or- 5 and sweet potatoes, 0.25 cup butter, 1 tsp vanilla extract, 0.5 cup sugar','InstructionsStep 1: Heat your oven to 350. Place your sweet potatoes in a medium sized mixing bowl. Add your salt, butter, eggs, vanilla extract, ground cinnamon, white sugar, and heavy cream. Mix thoroughly for a minute.Step 2:  Take your sugared pecans and place them in a blender.  Chop up your pecans until they are small and easy to sprinkle.Step 3: Take your sweet potato mixture and place in a  prepared 9 x 13 glass baking dish.  Cover the top with finely chopped sugar pecans.  Bake for 30 minutes or until the topping is lightly browned.',40,40,0);
INSERT INTO "Recipe" VALUES(17,'Fenugreek Roti','https://img.spoonacular.com/recipes/716202-556x370.jpg','0.5 teaspoon ajwain seeds, 1 pinch asafetida, 0.25 teaspoon baking soda, 0.5 teaspoon cayenne, 1 cup chickpea flour, 0.5 teaspoon chili powder, 0.5 cup fenugreek leaves, 10 servings ghee, 0.5 teaspoon ground coriander, 0.5 teaspoon ground cumin, 2 tablespoons yogurt, 1 teaspoon sea salt, 0.5 cup flour','Soak the dried fenugreek leaves in warm water for 5 to 10 minutes.  Drain, making sure to squeeze out excess liquid.Sift the flours and baking soda in a small strainer into a medium bowl. Stir in the salt, chili powder, cayenne, cumin, coriander, ajwain seeds, asafetida, yogurt and fenugreek leaves. Mix in about 1/4 cup of water to make a semi-hard batter. Cover and let stand at room temperature for 1 hour. Dusting your hands with flour, divide the dough into 10 to 12 small balls. Roll out each ball into a roughly 3-inch circle. Brush a non-stick pan with a bit of ghee or oil and heat over medium heat. When hot, add a rolled out portion to the pan and cook for 4 minutes or until the bottom is browned. Sprinkle with a bit of oil, flip and fry for another 2 to 3 minutes or until both sides are browned. Transfer to a plate, keep heated in a 150 oven, and repeat for the rest of the pancakes.',45,45,0);
INSERT INTO "Recipe" VALUES(18,'Vegan Stuffed Portobello Mushroom over Quinoa','https://img.spoonacular.com/recipes/664491-556x370.jpg','4 servings quinoa, 4 large portobello mushrooms, 1 package tofu, 0.5  tomato, 1 cup spinach, 0.25  onion, 4 cloves garlic, 1.5 teaspoons oregano, 1 teaspoon basil, 1.5 tablespoons nutritional yeast, 1 teaspoon lemon juice, 1 oz daiya vegan m zarella “cheese, 4 servings olive oil, 4 servings balsamic vinegarrette, 4 servings salt and pepper',replace('Cook quinoa\nAfter the tofu has thawed, drain and squeeze the excess water off.\nBrush off portobello mushrooms and remove the stems.\nMake the marinade for the mushroom:  3 tablespoons of olive oil, 3 tablespoons of balsamic vinaigrette, salt, and pepper (just keep adding the salt little by little until the marinade tastes good to you).\nHeat 3 tablespoons of olive oil in a pan and add the onions, garlic, oregano, and basil.  After you sweat the onions, add the tofu.  Note: smash the tofu with your hands and place it into the pan.  Keep stirring and cook on medium heat for about 15 to 20 minutes.\nAdd Nutritional yeast, spinach, tomato, and lemon juice to the tofu.  Cook for another minute then set aside.\nDip the mushroom in the marinade and place on a baking pan (top side down).\nStuff the mushrooms with the tofu and veggies.\nTop it off with vegan cheese.\nPreheat oven 370 degrees.\nBake stuffed mushrooms for 15 to 20 minutes.\nServe over quinoa.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(19,'Homemade pineapple ice cream','https://img.spoonacular.com/recipes/647068-556x370.jpg','8  eggs, 1 cup heavy cream, 3 cups pineapple, 0.25 cup powdered milk, 1 cup sugar, 1 tsp vanilla extract, 2 cups milk','In a large pot mix the milk, sugar and powdered milk. Bring the mix to a low simmer over medium heat and stir to dissolve the sugar, then turn the heat down and just keep it warm.Put the egg yolks in a medium bowl and whisk for 2 minutes until they are thickened.While constantly whisking, slowly add 1 cup of the hot milk mixture and whisk until it is blended. Then pour the egg mixture back into the pot of hot milk and increase heat to medium. Stir the mixture constantly with a wooden or plastic spoon, until the mixture is thickened (like gravy).Stir in whipping cream and vanilla. Cover and put into the refrigerator for at least 6 hours (or overnight) before making the ice cream in the ice cream maker.Blend fruit in a food processor or blender to a puree consistency.Stir the pureed fruit into the milk and egg mixture. Mix thoroughly.Pour the mixture into an ice cream machine and churn until frozen, 15-20 minutes, according to the manufacturers instructions.Transfer to plastic container and place in the freezer for an hour before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(20,'Brown Rice Vegetable Pulao','https://img.spoonacular.com/recipes/636295-556x370.jpg','175 grams brown basmati rice, 1  carrot, 2  celery stalks, 1 small chilly, 75 grams lentils, 1  onion, 2 tablespoons orange juice, 3 servings salt and pepper, 1  spring onion including the part, 4 tablespoons vegetable oil, 80 ml vegetable stock, 20 grams almonds, 1 leaves to garnish','Heat 2 tbsp of oil in a frying pan over medium heat. Add the chopped onion and saute well till softened.Add the celery, carrot, chilli, spring onions and almonds. Stir-fry for 2 minutes or until the vegetables are done. Transfer to a bowl and set aside.Add the remaining oil to the pan. Stir in the rice and lentils. Cook over medium heat, stirring for 2 minutes.Reduce the heat and stir in the veg stock and orange juice. Season with salt and pepper.Mix the already cooked vegetables to the pan. Toss with the rice for a few minutes until heated through.Transfer to a warmed dish, garnish with leaves and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(21,'Asian Chickpea Lettuce Wraps','https://img.spoonacular.com/recipes/632819-556x370.jpg','2 oz chickpeas, 1 tbsp chili sauce, 2 tbsp hoison sauce, 1 tbsp soy sauce, 1 tbsp olive oil, 2 tbsp rice vinegar, 0.5 tbsp sugar, 1 tsp pepper flakes, 1 tbsp sirachi sauce, 0.5 cup basil, 6  romaine leaves',replace('Drain and rinse both cans of chickpeas.\nPlace chickpeas in a food processor and puree in 5-10 second increments. You do not want to turn the chickpeas into a mash, you simply want to grind them into pieces.\nAdd 1 tbsp of olive oil to a pan and heat.\nAdd the chickpeas and let cook over medium heat for 3-4 minutes, continuously stirring so as not to burn.\nAdd remaining ingredients, except basil, and stir. Cook over low heat for 10 minutes, stirring occassionally.\nIf using basil leaves, add them and cook for 1-2 minutes, stirring the basil in and allowing it to wilt.\nWash lettuce leaves and pat dry.\nSpoon a healthy serving of chickpea mixture onto lettuce wraps and serve immediately. Drizzle with sirachi sauce if desired.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(22,'Red Quinoa and Roasted Cauliflower Salad','https://img.spoonacular.com/recipes/658087-556x370.jpg','1 medium cauliflower, 1 cup quinoa, 0.33333334 cup walnuts, 0.25 cup apricots, 0.33333334 cup feta cheese, 3  green onions, 3 Tbsp parsley, 4 servings salt and pepper, 1  lemon, 4 servings olive oil',replace('Cook the quinoa according to package directions.\nPreheat the oven to 400 F\nCut head of cauliflower into florets.  Toss with olive oil, salt and pepper and place on a baking sheet.  Roast cauliflower for 20 minutes or until tender.\nMeanwhile, crumble the cheese and chop the rest of the ingredients.\nMix them all together, sprinkle with some extra virgin olive oil and juice from 1/2 a lemon season to taste.\nServe warm or cold.','\n',chr(10)),45,45,1);
INSERT INTO "Recipe" VALUES(23,'Classic Pumpkin Pie','https://img.spoonacular.com/recipes/639631-556x370.jpg','15 ounce pumpkin, 2 large eggs, 1 teaspoon ground cinnamon, 0.5 teaspoon ground ginger, 0.5 teaspoon ground nutmeg, 8 servings salt, 14 ounce condensed milk, 1 9-inch unbaked pie crust, 8 servings whipped cream','Preheat oven to 425 degrees F.Whisk pumpkin, sweetened condensed milk, eggs, spices and salt in medium bowl until smooth. Pour into crust. Bake 15 minutes.Reduce oven temperature to 350 degrees F and continue baking 35 to 40 minutes or until knife inserted 1 inch from crust comes out clean. Cool.Garnish with whipped cream.',45,45,0);
INSERT INTO "Recipe" VALUES(24,'Pasta e Fagioli (Pasta and Beans)','https://img.spoonacular.com/recipes/654835-556x370.jpg','2 tablespoons olive oil, 15 ounce cannellini beans, 1 cup vegetable stock, 3 cups water, 2 small tomatoes, 0.25 cup onion, 2  garlic clove, 0.75 cup elbow macaroni, 0.25 cup parmesan cheese, 1 teaspoon pepper flakes, 0.25 teaspoon salt, 1 teaspoon pepper, 1 tablespoon parsley',replace('In a large stock pan over medium-high heat, add the olive oil and the onion. Allow the onion to cook until it is tender (about 3 minutes). Add the tomato (or marinara sauce) and garlic and incorporate it into the mixture. Cook for just 1-2 minutes (be careful not to burn the garlic).\nAdd the vegetable stock, water, salt, pepper and red pepper flakes. Bring this to a boil and then add your pasta. Lower the heat and allow the pasta to cook until its about 3/4 of the way finished (still slightly firm).\nAdd your beans and allow the mixture to continue cooking until the pasta is fully cooked (about 10-15 minutes). Add the parsley toward the end of your cooking time. Taste and adjust the seasoning as needed.\nServe in individual bowls with extra parsley as garnish and sprinkle with the Parmesan cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(25,'Cannoli Ice Cream w. Pistachios & Dark Chocolate','https://img.spoonacular.com/recipes/716410-556x370.jpg','2 ounces chocolate, 0.5 cup milk, 0.25 cup pistachios, 1.75 cups ricotta, 1 small pinch salt, 0.5 cup sugar, 0.5 tsp vanilla','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(26,'Tapioca Pudding with Pineapple and Coconut','https://img.spoonacular.com/recipes/662871-556x370.jpg','200 ml .8 fl oz. coconut milk, 2  egg yolks, 250 ml .5 fl oz. full milk, 2 tsp honey, 1  lime, 250 gr .8 oz. pineapple, 1 pinch salt, 1 tbsp sugar, 65 gr .3 oz. of pearl tapioca, 1  vanilla pod','The place to start is with the tapioca, the pudding is a custard. So, in a heavy bottomed saucepan add the full milk, salt, tapioca, the seeds from the vanilla pod, and the empty vanilla pod. Bring this mix to a gentle simmer and stir occasionally. Do this until the tapioca is translucent and tender, this takes about 20 minutes. When cooked, stir in the coconut milk.While the tapioca mix is cooking you can whisk the egg yolks and sugar together in a bowl - quite big as it has to hold half of your tapioca mix too. Mix the egg and sugar together until the color lightens.Taking your cooked tapioca mix from the heat, pour half of it into the bowl with the eggs and sugar, whisk together using a metal hand whisk. Then pour this back into the pan and place on a medium heat.On a medium heat keep whisking until the mix thickens, this takes about 5 minutes or so. It is important not to use too high a heat as the eggs will scramble. The mix will not become really thick, the chilling process with thicken it further. I like to check the sweetness level at this stage, you can add a little more sugar if you wish, but if you do, stir it through until it dissolves. Put your tapioca pudding in a clean, cool bowl, remove the vanilla bean and set aside to cool. When it has cooled, cover with cling film and put in the fridge.Now for the pineapple. Combine the fruit with the honey, lime juice and most of the zest. Keep back a little lime zest to dress.Place half of the mix in a food processor and blend until smooth. Transfer this back into the bowl with the rest of the pineapple and stir together  check the flavour and add more honey or lime if you wish.Once your tapioca has chilled, place some of the pineapple mix in the bottom of your serving dishes, then add the tapioca and top with a little pineapple and some lime zest to finish.',60,60,0);
INSERT INTO "Recipe" VALUES(27,'Powerhouse Almond Matcha Superfood Smoothie','https://img.spoonacular.com/recipes/756814-556x370.jpg','2 tablespoons natural almond butter, 1.5 cups almond milk, 1 medium banana, 2 teaspoons chia seeds, 1 cup baby kale, 0.5 cup mango pieces, 1 tablespoon matcha tea powder, 0.75 cup pineapple, 0.5 teaspoon vanilla extract','Combine all of the ingredients in a blender. Blend on high until smooth. Serve immediately.',10,10,0);
INSERT INTO "Recipe" VALUES(28,'Jambalaya Stew','https://img.spoonacular.com/recipes/648432-556x370.jpg','6 oz chicken sausage links, 14.5 oz canned tomatoes, 0.75 cup onion, 1 large bell pepper, 1 cup celery, 1 cup chicken broth, 0.5 cup brown rice, 1 tbsp garlic, 1 tsp cajun seasoning, 0.5 tsp hot sauce, 0.25 tsp oregano, 0.25 tsp thyme, 6 oz shrimp',replace('Add all ingredients except shrimp to a large pot on the stove. Mix thoroughly. Bring to a boil.\nReduce heat to medium low. Cover and simmer until vegetables are tender and rice is fluffy, about 35 minutes.\nAdd shrimp and re-cover. Continue to cook until shrimp are tender and cooked through, about 6 minutes.\nIf you like, season to taste with salt, black pepper, and additional hot sauce. Serve and enjoy!!!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(29,'How to Make the Best Chicken Jambalaya','https://img.spoonacular.com/recipes/715545-556x370.jpg','2 tbsp ▢ butter, 1 lb ▢ sausage, 1 lb ▢ chicken breasts, 1 cup ▢ onion, 1 cup ▢ celery, 0.5 cup ▢ bell pepper, 1 tbsp ▢ garlic, 1 cup ▢ tomato sauce, 14.5 oz ▢ tomatoes, 2.5 cups ▢ chicken stock, 1.5 cups ▢ rice, 1 leaves ▢ 2 bay, 2 tsp ▢ ground pepper, 1 tsp ▢ salt, 1 tsp ▢ pepper, 1 tsp ▢ thyme, 1 tsp ▢ pepper flakes, 0.5 tsp ▢ sage',replace('Instructions\n\nCombine the creole seasoning ingredients in a small bowl and set aside.\n\nMelt butter in a large dutch oven over medium-high heat.\n\nAdd the sausage until it starts to brown, about 3 minutes.\n\nAdd the chicken and continue to cook until brown, about 3-5 minutes. Stir frequently.\n\nTurn the stove top down to medium heat.\n\nPreheat your oven to 350 degrees.\n\nStir in the seasoning mix of cajun spices and 1/2 of the chopped onion, celery, green bell pepper, and garlic. Cook until vegetables get tender, about 3-5 minutes. Stir frequently and scrape the bottom of the pot frequently.\n\nStir in the tomato sauce and cook for about one minute.\n\nStir in the remaining onion, celery, bell pepper, garlic, and the diced tomatoes then remove from heat.\n\nStir in the rice and chicken stock, mix the ingredients well.\n\nBake uncovered in the oven at 350 degrees for one hour or until the rice is tender but still has a little crunch.\n\nRemove from the oven, add the bay leaves and stir well.\n\nAllow the dish to cool for five minutes before serving. OPTIONAL: Top with green onions before serving.','\n',chr(10)),55,55,3);
INSERT INTO "Recipe" VALUES(30,'Bacon Caramels','https://img.spoonacular.com/recipes/633302-556x370.jpg','14 strips bacon, 2 cups sugar, 0.5 cup water, 0.5 cup corn syrup, 1 cup butter, 1 cup heavy cream, 2 teaspoons vanilla',replace('Preheat oven to 400 degrees. Line a rimmed baking sheet with parchment paper. Lay bacon strips on sheet and bake in oven for 20 to 25 minutes or until crispy. Remove bacon to paper towel-lined plate to cool. Crumble 5 to 6 strips of bacon and leave the rest in strips.\nLine an 913 (or larger!) rimmed baking sheet with parchment. In a heavy-bottomed pot (I love my Le Creuset), add sugar, water and corn syrup over medium-high heat. Let mixture bubble and stir occasionally, to evaporate water. Sugar will begin to caramelize and turn a lovely shade of amber.\nUse a thermometer to monitor caramel. When it reaches 320 degrees and is golden brown in color, slowly whisk in cream, butter and vanilla, until completely combined. When caramel reaches 243 degrees, remove from heat and pour into lined baking sheet. Cool for 15 minutes, and add bacon strips. Cool further, until caramel is pliable and easier to handle.\nRoll caramel and bacon strips jelly-roll style once, and trim off excess. Continue to roll and trim until youve finished off the pan. Cut the bacon caramel logs into bite-sized pieces. Top with reserved bacon bits.\nServe on a platter, or roll in wax paper. Keep refrigerated, but let come to room temperature before eating.http://www.fureyandthefeast.com/2009/09/bacon-caramels/','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(31,'Easy Eggplant Curry','https://img.spoonacular.com/recipes/641958-556x370.jpg','2 medium eggplants, 3 tablespoons ghee/vegetable oil, 1 medium onion, 2  centimeters piece of ginger, 6 cloves garlic, 1 teaspoon fennel seeds, 1 teaspoon cumin seeds/ground cumin, 1 tablespoon ground coriander, 0.5 teaspoon ground turmeric, 0.5 teaspoon a pinch of chilli powder, 1 teaspoon sea salt, 14 oz tomatoes',replace('Wash eggplants and dice into 2 cm cubes.\nHeat ghee/oil in a large frying pan over medium heat. Add the onion and cook, stirring occasionally for about 10 minutes until a deep golden brown colour. (Be patient and don''t be tempted to rush this stage).\nAdd the grated ginger, crushed garlic, fennel and cumin seeds (if using, if you are using cumin powder however, add in the next stage with the other ground spices). Cook for about 2 minutes until garlic and ginger are fragrant. Add ground coriander, turmeric, cayenne/chilli powder and salt. Cook for 30 seconds. Add the diced eggplant and stir well to coat evenly with spices. Pour in the tin of chopped tomatoes, give it a big stir, then place the lid on and continue to cook over low-medium heat for about 10-15 minutes. Check and stir a few times to ensure it''s not catching on the bottom. Turn temperature down a little if need be.\nWhen the sauce has thicken and the eggplant is meltingly soft, check the seasoning once more. Serve sprinkled with coriander/cilantro leaves and steamed rice. Enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(32,'Salmon In Banana Leaf','https://img.spoonacular.com/recipes/659083-556x370.jpg','2 large banana leaves, 1 pinch cinnamon, 1 pinch fennel seed, 1 tablespoon fish sauce, 1 clove garlic, 1 piece ginger, 1.5 tablespoons peach preserves, 2 servings chiles, 0.25 cup rice, 0.75 teaspoon rice wine vinegar, 2  steaks salmon, 2  eachs scallions, 6  scallions, 0.75 teaspoon sesame oil, 1.25 teaspoons soy sauce, 1  star anise, 2 tablespoons tahini, 1 tablespoon vegetable oil','Begin by mixing all of your marinade ingredients together and pouring it over the salmon in a big baggy or container. Marinate under refrigeration for at least a half an hour or up to 2 hours.While salmon is marinating, put all of your scented rice powder ingredients into a spice grinder and pulse until everything is coarsely ground. Remember, you want a few larger crumbles of rice for mouth-feel!Remove the salmon from the marinade (discarding any leftover marinade) and coat it with some of the scented rice powder on each side. You won''t use it all with just the 2 pieces of salmon. Save some for another time.Lay your banana leaves out flat. Place one salmon fillet in the center of each leaf. Fold one side over the salmon.Fold the opposite side over that, then both ends to make a little package.Place salmon packets in a steamer basket over boiling water.Put all of the marinade ingredients into a small sauce pot or alternately, a microwave safe dish and bring to a heat. Whisk everything together and it''s ready to serve.After ~10-13 minutes, salmon will be finished. Flip the smooth side of the banana leaves up and make a slit through them to serve....they kinda look like tamales, huh!I served with chinese noodles, corn and the dipping sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(33,'Lemon Pilaf Chicken','https://img.spoonacular.com/recipes/649733-556x370.jpg','2 cups broccoli flowerets, 1.5 cups chicken, 3 tablespoons lemon juice, 1 teaspoon lemon peel, 1 tablespoon olive oil, 1  pkt near east rice pilaf see note','In large skillet bring 2 cups water, olive oil, lemon juice and spice sack to a boil. Stir in chicken and rice pilaf. Reduce heat and simmer for 10 minutes. Add broccoli and grated lemon peel. Simmer for 8 to 10 minutes, or until all water is absorbed.NOTES : For a colorful twist, substitute Near East Chicken Flavor Pilaf.',45,45,3);
INSERT INTO "Recipe" VALUES(34,'Mascarpone & Ricotta Cheese Cake','https://img.spoonacular.com/recipes/651189-556x370.jpg','0.25 cup almonds, 1 tablespoon butter, 16 oz whipped cream cheese, 4 large eggs, 2 tbsp flour, 1.5 cups graham crackers, 1 tbsp lemon juice, 8 oz mascarpone cheese, 8 oz ricotta cheese, 0.5 tsp salt, 1.25 cups sugar, 2 tbsp sugar, 1 tsp vanilla extract','DirectionsPreheat oven to 325.Crust:Grind graham crackers and almonds using food processor or a mortar and pestle. Add melted butter and salt and press into bottom of greased springform pan or deep dish pie pan. Bake for 10 minutes. Let cool. Mix sugar and flour together and sprinkle over top of crust. (This prevents crust from getting soggy)Filling:Beat cream cheese, mascarpone cheese, ricotta cheese and sugar in a large bowl until smooth. Beat in lemon juice and vanilla. Add in eggs one at a time. Pour cheese mixture over crust in pan. Bake until the center of the cheesecake is wobbly when shaken, about 1hr and 5 mins. Let cool then refrigerate, preferably overnight.',45,45,0);
INSERT INTO "Recipe" VALUES(35,'Cinnamon Twists','https://img.spoonacular.com/recipes/639492-556x370.jpg','1 package active yeast, 1 cup butter, 2  eggs, 1 cup milk, 0.5 teaspoon salt, 1 cup sugar','Combine 2 cups flour with yeast.Heat and stir milk, butter or margarine, sugar and salt until warm and butter is almost completely melted.Add this  to the flour mixture along with the eggs.Beat with an electric mixer on low speed for 30 seconds, scraping the bowl, then beat on high speed for approx. 3 minutes. Stir in as much of the remaining flour ( 2 to 2 1/3 cups) as you can.Turn out onto a lightly floured surface. Knead in enough remaining flour to make a moderately soft dough that is smooth and elastic (about 3 - 5 minutes). Shape into a ball. Place in a lightly greased bowl. Cover and let rise in a warm place till double in size. (About 1 hour)Punch dough down. Divide in half. Cover and let rest 10 minutes.Roll half of the dough into a 12x8 inch rectangle. Melt 3 tablespoons butter or margarine; brush half over the dough. combine 3/4 cup sugar and 2 1/2 teaspoons ground cinnamon; sprinkle half of the mixture over dough. Fold dough in half and then in half once more. Cut strips of dough along the short end and twist sealing the seams.Place in a baking sheet. Cover; let rise till nearly double about 30 minutes.Bake in a 375 degree oven for 20 to 25 minutes. (Be sure to check them, they brown easily.)For the sugar glaze combine 1 cup sifted powdered sugar with 1/4 teaspoon vanilla and 1 tablespoon milk. Continue to add milk 1 teaspoon at a time until you get a drizzling consistency.',45,45,0);
INSERT INTO "Recipe" VALUES(36,'Elk Sliders With Pancetta Bacon and Smoked Mozzarella','https://img.spoonacular.com/recipes/642373-556x370.jpg','1 cup bread crumbs, 8 servings cherry tomatoes, 1  egg, 1 tablespoon garlic powder, 1 pound ground elk meat, 8 servings hawaiian rolls, 8 servings mozzarella, 8 servings pancetta, 8 servings salt and pepper, 1 tablespoon steak sauce, 2 tablespoons grain mustard, 1 tablespoon worcestershire','In a large bowl, add mustard, bread crumbs, egg, garlic powder, salt and pepper to ground elk meat. Mix all ingredients by hand and then form into small patties. Use a  cup measuring cup to size how much meat to use when forming your patties.  Place meat on tinfoil and press gently with your thumb creating a small indent in the center. This will help keep patties from shrinking when cooking.Pre-heat the barbecue to high temperature.I recommend leaving the elk burgers on the tinfoil while cooking on the BBQ. The elk meat is very lean and can have the tendency to dry out if overcooked. Cooking on tinfoil reduces the risk of overcooking.Cook 7 minutes or until brown and then flip patties. Continue cooking on other side until brown  7 minutes. Add smoked mozzarella cheese to the top of burgers during the last 2 minutes of cooking. Close lid and melt cheese.While cooking your burgers, place pancetta bacon slices on tinfoil and place on the barbeque for the last few minutes of cooking. Toast buns on grill.Place elk sliders on Hawaiian Sweet Rolls, top with a slice of pancetta bacon and a few cherry tomatoes and you are set! Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(37,'Mango Salsa','https://img.spoonacular.com/recipes/716290-556x370.jpg','1 handful cherry tomatoes, 0.5  bell pepper, 1 tablespoon lime juice, 2  mangoes, 3 leaves mint leaves, 0.5  bell pepper, 2 handfuls onions, 1 pinch sugar','Peel and chop your mango into small cubesCube your bell peppers and onions as well and mix in with the mangoes. Add the cherry tomatoes and mix in.sprinkle your sugar and lime juice over it.Chop your scent/mint leaves and mix in and refrigerate.Serve cool as a side dish or if you want something refreshing on a hot day.',45,45,0);
INSERT INTO "Recipe" VALUES(38,'Brussel Sprouts in Bacon and Garlic Sauce','https://img.spoonacular.com/recipes/636359-556x370.jpg','250 g brussel sprouts, 0.5 teaspoon salt, 4 cups water, 1 tablespoon butter, 1 tablespoon garlic, 1 tablespoon bacon bits, 0.25 teaspoon salt and pepper, 1 teaspoon lemon juice',replace('Wash 250g of brussel sprouts. Remove any old hard out leaves.\nBring 4 cups of water to the boil and add 1/2 teaspoon of salt.\nAdd the brussel sprouts to the boiling water and leave to boil at medium heat for 4 minutes or until sprouts are tender but still crunchy.\nDrain the brussel sprouts.\nReturn the saucepan to the hot stove and add 1 tablespoon of butter.\nWhile the butter is melting, cut the brussel sprouts in half.\nAdd 1 tablespoon of minced garlic to the melted butter. Saut for a few seconds till garlic is fragrant but not brown.\nReturn the cut brussel sprouts to the saucepan. Toss the brussel sprouts lightly in the garlic-butter sauce.\nAdd 1 tablespoon of bacon bits. I keep a jar of ready to use bacon bits in the fridge at all times for this dish (and for my Mushroom Delight dish). You can also use freshly pan fried and crumbled bacon, but I like to cook this fast.\nSeason to taste with salt and pepper. I always use Masterfoods Garlic Pepper to season my dishes. A few shakes of this and its done.\nAdd a squeeze of fresh lemon juice (about 1 teaspoon).\nToss everything together. Serve with some fresh lemons on the side for extra tangy flavour, if preferred. You can also garnish with some toasted almond flakes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(39,'Peanut Butter Sriracha Cookies','https://img.spoonacular.com/recipes/655335-556x370.jpg','1 cup butter, 1.5 cups crunchy peanut butter, 1 cup sugar, 1 cup brown sugar, 0.25 c sriracha, 2  eggs, 1 tsp vanilla extract, 2.75 cups flour, 1 teaspoon baking powder, 0.5 teaspoon salt, 1.5 teaspoons baking soda, 60 servings granulated sugar, 1 cups add a hershey''s chocolate kiss on top as done',replace('Cream together butter, peanut butter and sugars.\nSlowly add in sriracha, eggs and vanilla. Beat until combined.\nIn another bowl mix together flour, baking powder, baking soda and salt.\nGently mix flour into peanut butter mixture until well combined. Place batter into refrigerator for 1 hour to chill.\nPre-heat oven to 375 degrees.\nRoll dough into approx 1 sized balls or use a Medium sized cookie scoop/Size 40  1tbs portion. Dip the top of dough ball into granulated sugar and place onto cookie sheet.\nFlatten each ball with a fork, making a criss-cross pattern. Bake for 8-10 minutes or just until the cookies begin to brown. Do NOT over-bake!\nCool on wire racks and enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(40,'Crawfish Cake Sliders','https://img.spoonacular.com/recipes/640461-556x370.jpg','2 tablespoons oil, 1 cup crawfish tails, 2 tablespoons onion, 0.5 teaspoon garlic, 8 servings creole spice, 1  egg, 0.5 cup bread crumbs, 8  slider buns, 8 servings tartar sauce',replace('In a saute pan heat 1 teaspoon oil, add chopped onion, red pepper and celery and cook until tender, about 2-3 minutes.\nRemove pan from heat and add garlic, crawfish meat, and 1 teaspoon Creole spice (or to taste). Transfer to a mixing bowl and set aside to cool.\nMix in egg and enough bread crumbs for mixture to bind; adjust seasonings to taste with salt, pepper and Creole spice.\nForm into 8 equal patties and flatten to 3/4-inch thick. Heat remaining oil in a saute pan and cook cakes on both sides until brown and crispy.\nServe with a dollop of tartar sauce.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(41,'Crab Cakes Rockefeller','https://img.spoonacular.com/recipes/640279-556x370.jpg','1 pound lump crab claw meat, 0.5  bell pepper, 4  green onions, 1 cup bread crumbs, 4 tablespoons honey, 1 teaspoon chili powder, 1 tablespoon butter, 2 slices bacon, 4 cups baby spinach, 0.25 cup watercress stems, 4 cloves garlic, 6 servings salt & pepper',replace('Preheat your oven to 375F and set the top rack to the middle position (BTW, this "Recipe" is a great toaster oven candidate).  Line a baking sheet with aluminum foil or a nonstick cooking mat.\nIn a large bowl, combine the crab meat, diced red bell pepper, half of the diced green onion (reserving the other half) and half of the bread crumbs (reserving the other half).  Mix in the honey and chili powder, then season to taste with salt and pepper.\nI like to form my crab cakes by pressing them into a 1/2 cup measure, squeezing tightly so theyll hold their shape.  You can mould them with your hands as well, but be sure to press them together tightly or they might fall apart in transit to the plates.  Arrange the crab cakes on the lined baking sheet, leaving at least 1 between each crab cake.\nUsing your olive oil sprayer (if you have one; or by drizzling olive oil) lightly coat the outside of each crab cake.  This will help with browning and to form an outer crust.  Bake at 375F for 25 minutes, or until golden brown.\nMeanwhile, fry the bacon or prosciutto in a large skillet until crispy.  Set aside to drain, then crumble into small pieces using a sharp knife.\nFinely chop the spinach and watercress stems.  In a large skillet, melt the butter over medium heat.  Add the garlic and saut 1 minute.  Then, add the remaining green onion, bread crumbs and watercress stems.  Saut 1 minute more.  Finally, add the chopped spinach and cook until wilted, 1-2 minutes.  Season to taste with salt and pepper.\nTo serve, plate a crab cake atop a smear of the spinach mixture, then sprinkle the whole plate with crumbled bacon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(42,'Almond Coffee Cupcakes with Kahlua Liqueur','https://img.spoonacular.com/recipes/632115-556x370.jpg','0.25 cup almond meal - 30g, 40 g butter, 0.25 cup kahlua coffee liqueur, 2  egg whites - 80g, 6 servings chocolate icing, 0.5 cup icing sugar - 55g, 2 tsp coffee powder, 2 tbsp flour','Preheat oven to 180C (335F). Place the flour, sugar, almond meal, coffee, butter and egg whites in a bowl and mix well combine with a hand whisk.Spoon mixture into 6 lightly greased or use cooking spray on medium size muffin pan or 12 mini muffin pan and bake for 20-25 minutes or until cooked when tested with a skewer.Drizzle with the liqueur (about 1/2 tablespoon on each cake) and set aside for 2 minutes before turning out on a wire rack to cool.Decorate with chocolate icing on top (I used Wiltion chocolate icing) or just dust with some icing sugar.You can serve them warm or store it in an airtight container for 2-3 days.',45,45,0);
INSERT INTO "Recipe" VALUES(43,'Greek Inspired Spring Omelet','https://img.spoonacular.com/recipes/645315-556x370.jpg','3  asparagus spears, 0.33333334 cup egg whites, 1 Tbsp feta cheese, 1 serving green onions, 1 serving salt and pepper, 1 Tbsp tzatziki, 4  cherry tomatoes','In a medium skillet saute asparagus until tender, about 7 minutes. Set aside.In a small bowl combine egg whites and tzatziki; stir to combine.Spray non stick skillet with cooking spray and bring to medium heat. Pour in egg white and allow it to spread over the skillet surface. Cook until egg turns white; about 2 minutes.Slide omelette onto a plate and place asparagus, tomatoes, green onions and feta in the middle. Fold the omelette into thirds to cover the fillings.Serve hot with additional tzatziki. Salt and pepper to taste.',20,20,0);
INSERT INTO "Recipe" VALUES(44,'Peanut Butter And Chocolate Oatmeal','https://img.spoonacular.com/recipes/655219-556x370.jpg','1 cup cooking oats, 1 teaspoon cocoa, 1 teaspoon agave, 1 tablespoon crunchy peanut butter, 0.5 cup non-fat milk','Microwave all ingredients in a small bowl or mug for 1 minute, stir and enjoy!  Serve with crushed peanuts or almonds for some extra crunch!',45,45,1);
INSERT INTO "Recipe" VALUES(45,'Sweet Corn Pudding','https://img.spoonacular.com/recipes/662501-556x370.jpg','8 tablespoons butter, 1 medium onion, 2 cloves garlic, 12  ears corn, 0.25 cup flour, 1 quart heavy cream, 1 cup grits, 3 tablespoons jalapeño peppers, 10 servings salt, 10 servings pepper, 9  eggs, 1 cup cheddar cheese',replace('Preheat the oven to 425. Melt the butter in a heavy-bottomed pot over medium heat. Add the onions and garlic and cook for 3 minutes. Add the corn kernels and cook, stirring, for an additional 3 minutes. Add the flour and stir for 1 minute, then add the cream. Once the cream is incorporated, continue to stir until the mixture comes to a boil. Add the cooked grits, remove from the heat, and stir in jalapeo peppers. Taste and season well with salt and pepper.\nWith a hand-held immersion blender in the pot (or transfer the mixture to a food processor), pure the corn mixture while slowly adding the beaten eggs, until the eggs are thoroughly mixed in.\nPour the mixture into an ovenproof dish and sprinkle with the cheese. Bake for 2530 minutes, until the center puffs and the corn pudding turns golden brown.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(46,'Polish Rugelach','https://img.spoonacular.com/recipes/656569-556x370.jpg','2 cups all purpose flour, 2 tablespoons cocoa powder, 8 ounce cream cheese, 0.33333334 cup cranberries, 0.33333334 cup raisins, 1 teaspoon ground cinnamon, 1 teaspoon nutmeg, 0.75 cup sugar, 0.5 cup butter, 0.6666667 cup walnuts','For dough: Beat butter and cream cheese in large bowl until light. Add sugar; beat until fluffy. Mix in flour. Gather dough into ball and gently knead until smooth. Gather into ball and flatten wrap in plastic wrap and chill 1 hour. When ready, divide dough into four pieces.For filling: Combine  cup sugar, cranberries walnuts, butter, cinnamon, nutmeg and cocoa powder in food processor and give it a few good chops. Set aside.Preheat oven to 350 degrees.Place 1 dough piece on floured work surface. Roll out dough to about 1/8 inch thickness. Spread 3 tablespoons filling over round, leaving  - inch border. Cut round into 1/8 in. wedges. Starting at wide end',45,45,0);
INSERT INTO "Recipe" VALUES(47,'Duck with Dried Cranberries, Tangerines and Mascarpone Sauce','https://img.spoonacular.com/recipes/641720-556x370.jpg','2 servings duck breast, 6  juice of 6 tangerines, 2 tablespoons mascarpone, 2 servings salt and pepper, 0.25  to','Preheat oven at 350. In an ovenproof skillet heat a shadow of oil on high heat. Generously salt and pepper both sides of the duck breast. When the skillet is hot, add the duck skin side down. Cook until the skin is golden brown, about 5 minutes, turn to the other side and cook for 3 minutes. Turn again, skin side up, discard all of the fat from the pan and place in the hot oven. Cook for another 10 to 15 minutes.Remove from the oven and cover with aluminum foil to keep warm.Meanwhile in a separate small sauce pan place the dried cranberries and the tangerine juice. Cook over medium heat until the cranberries have softened and the juice is reduced. Lower the heat and add the mascarpone. When the mascarpone is melted and the juice starts to thickens, remove from the heat. With an immersion hand held mixer, puree the mascarpone, tangerine-cranberries sauce until nice and smooth. Add less than a tablespoon of the juices from the duck. Mix well. Return the pan to the heat and warm for a minute or so.Spread the sauce on the bottom of the plate and serve the duck sliced over it.',45,45,0);
INSERT INTO "Recipe" VALUES(48,'Gluten Free Vegetarian Spring Rolls With Thai-Style Peanut Sauce','https://img.spoonacular.com/recipes/644859-556x370.jpg','1.25 ounces rice vermicelli, 1.25 cups carrots, 1.25 cups cabbage, 2  scallions, 15  basil leaves, 15  mint leaves, 2 tablespoons cilantro, 0.25 cup peanuts, 1 tablespoon ginger, 1 tablespoon soy sauce, 0.5 tablespoon lime juice, 1 teaspoon sesame seed oil, 1 t es round spring roll wrappers, 0.5 cup warm water, 0.5 tablespoon sugar, 0.5 cup creamy peanut butter, 1.5 tablespoons soy sauce, 1 tablespoon coconut milk, 1 tablespoon lime juice, 1 teaspoon chili paste depending on your taste pref, 1 large clove garlic',replace('Bring a large pot of water to boil over high heat. Remove from heat and stir in the rice noodles. Let stand 10 minutes, stirring occasionally, or until soft and opaque. Drain and rinse under cold water for 30 seconds; drain again. Cut into 1-inch lengths and transfer to a large bowl.\nAdd all of the remaining ingredients, except the rice papers and sauce, to the noodles and mix well.\nPrepare a bowl of warm water large enough to dip the rice papers. Working with one at a time, dip the rice paper in the warm water until it begins to soften, 8-10 seconds. Transfer to a flat work surface. Working quickly, put about 1/4 cup filling on each wrapper. Fold the bottom of the wrapper up over the filling, and then fold each side toward the center. Roll from the bottom to the top of each roll, as tightly as you can without ripping the wrapper. Wrap in plastic to keep from drying out. Repeat with remaining wrappers and filling. Serve at room temperature, with Peanut Dipping sauce. Alternatively, refrigerate for a minimum of 2 hours, or overnight, and serve 4To prepare Peanut Dipping Sauce:\nTo prepare Peanut Dipping Sauce:\nIn a small bowl, combine the warm water and sugar, stirring until the sugar is dissolved. Add the remaining ingredients, whisking until smooth and well blended. Serve at room temperature.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(49,'Grilled Ham and Cheese French Toast For A Quick Weeknight Dinner','https://img.spoonacular.com/recipes/645732-556x370.jpg','0.5 cup buttermilk, 2 large egg whites, 0.25 cup dijon mustard, 8 slices wheat bread, 4 oz jarlsberg cheese, 8 ounces turkey ham, 3  dill pickles, 2 tablespoons smart balance heart right',replace('Preheat oven to 350 degrees.\nIn a shallow bowl or pie plate, whisk together buttermilk and egg whites. Set aside.\nSpread mustard on one side of each slice of bread.  Top 4 slices with 1 slice of cheese.  Arrange ham on top of cheese.  Add to each 3-4 thin slices of pickle. Top with remaining bread slices, mustard side down.\nMelt 1 tablespoon reduced-fat butter in a large nonstick pan over medium heat.  Dip 2 sandwiches into buttermilk mixture; carefully flip and dip other side.  Dont soak the sandwiches in this mixture. Just lightly dip and remove sandwiches, allowing excess buttermilk mixture to drip back into dish.\nAdd sandwiches to pan; cover and cook 3-5 minutes.  Uncover, flip sandwiches, press top down with a spatula, cover and cook for 2-3 minutes until golden and cheese is melted.  Remove sandwiches, place on a baking sheet and keep warm in oven.\nRepeat steps 4 and 5 with remaining 2 sandwiches.\nSlice each sandwich in half and serve with a fork and knife.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(50,'Gluten And Dairy Free Peanut Butter Cups','https://img.spoonacular.com/recipes/644782-556x370.jpg','18 oz enjoy life semi-sweet chocolate chips, 1 Tbsp non-hydrogenated shortening, 0.5 C creamy peanut butter, 0.25 C agave nectar, 0.125 tsp salt',replace('1. Line a mini muffin tin with paper liners or spray with cooking oil.\n2. Mix together the filling ingredients and set aside.\n3. In a heatproof bowl, melt the chocolate and shortening over simmering water. Do not allow the water to touch the bottom of the bowl.\n4. Spoon 1 tsp. of the melted chocolate into each of the muffin cups.\n5. Top with a scant teaspoon of the peanut butter mixture.\n6. Then top with another teaspoon of the melted chocolate.\n7. Refrigerate until set. Store in an airtight container in the refrigerator.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(51,'Lemon Chia Seed Cornmeal Bread','https://img.spoonacular.com/recipes/841432-556x370.jpg','2 teaspoons baking powder, 0.25 teaspoon baking soda, 0.6666667 cup brown sugar, 3 tablespoons chia seeds, 1 cup flour, 2  juice of lemon, 0.25 cup olive oil, 0.5 cup pastry flour, 3 pinches sea salt, 0.5 teaspoon turmeric, 0.75 cup unsweetened apple sauce, 0.5 cup yellow cornmeal','Line a standard 9  5 inch loaf pan with parchment paper or grease the pan well. Preheat an oven to 350.In a large bowl, combine the flours, cornmeal, chia seeds or poppy seeds, baking powder and soda, turmeric if using, and sea salt.In a medium bowl, whisk together the lemon zest, lemon juice, sugar, apple sauce and olive oil.Make a well in the center of the flour mixture and pour in the moist ingredients. Stir until just combined. Transfer to the prepared pan, spreading evenly.Bake for 30 to 40 minutes or until lightly golden and a cake tester inserted into the middle of the bread comes out clean. Let cool in the pan before removing. Slice and serve.',45,45,1);
INSERT INTO "Recipe" VALUES(52,'Asparagus and Asiago Frittata','https://img.spoonacular.com/recipes/632925-556x370.jpg','5  eggs, 0.75 pound asparagus, 1 tablespoon butter, 1 tablespoon olive oil, 1.5 tablespoons heavy whipping cream, 1 tablespoon thyme, 1  garlic clove, 0.25 teaspoon salt, 0.25 teaspoon ground pepper, 3 ounces asiago cheese, 4  cherry tomatoes',replace('In a large bowl, combine the eggs, whipping cream, salt, pepper, and half the fresh thyme. Beat with a whisk until the eggs and cream are incorporated.\nIn an ovenproof saut pan over medium heat, add the butter and olive oil. When the mixture is hot, add the asparagus pieces and cook for 3-4 minutes, stirring. Add the garlic and cook for about a minute. Spread the asparagus so it is evenly distributed across the bottom of the pan.\nAdd the egg mixture to the pan and allow the eggs to cook without mixing them. Use a rubber spatula to run around the edges of the frittata as it cooks so the edges dont stick and burn. After 1-2 minutes, add the cheese evenly to the egg mixture.\nWhen the outer edges of the frittata have set but the center is still slightly runny, arrange the cherry tomatoes and asparagus spears on the top of the frittata, sprinkle the remaining thyme over the top, then remove the pan from the heat and place it in an oven set to broil.\nThe broiler will allow the top portion of the egg mixture to set and cook thoroughly. Keep a close watch so the frittata doesnt burn.\nAfter a few minutes, when the eggs have set completely and begin to turn golden, carefully remove the pan from the oven.\nUse a rubber spatula to run around the edges and underside of the frittata, and slide it onto a round serving plate.\nSlice and serve warm or at room temperature.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(53,'Homemade Broccoli Cheddar Soup','https://img.spoonacular.com/recipes/646930-556x370.jpg','8 cups broccoli, 1  shallot, 1  juice of lemon, 3 cups vegetable broth, 1 teaspoon pepper, 1 teaspoon salt, 1 small onion, 1 cup yogurt, 3 cups yukon gold potatoes, 1 cup parsley, 1  bay leaf, 0.5 cup olive oil, 1 cup almond milk, 1.5 cups cheddar cheese',replace('In your soup pot, saute over med-high heat: 2 Tbsp of your olive oil with the shallot, onion and jalapeno. When cooked lightly, add in lemon juice, veggie broth, remaining oil, salt and pepper. Reduce heat to medium. Add Potatoes and bring broth to a boil. Cook until potatoes are tender.\nAdd chopped Broccoli (florets and steams). Remember to leave out a few florets for later use though.Cover with lid, when broccoli is tender, turn heat off.\nTransfer contents of pot into a large mixing bowl. Allow to cool slightly. Add to the bowl the fresh parsley, Chobani and almond milk. Fold new ingredients into the hot soup mixture.\nIn batches, puree the soup in a food-processor (maybe someday soon, a Vitamix!) style blender. Soup should be smooth-no lumps or chunks. In the soup pot, add the broccoli florets, a dash of veggie broth and saute covered for about a minute until tender. Add the pureed soup back into the soup pot. Add a bay leaf and a few pinches of chopped basil (optional). Simmer uncovered for at least twenty minutes to cook out all the air bubbles. Stir constantly for the first few minutes. Remove the bay leaf before serving or storing.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(54,'Luscious Lemon Bars','https://img.spoonacular.com/recipes/650479-556x370.jpg','0.5 teaspoon baking powder, 4 ounces butter, 3  eggs, 50 g flour, 1  juice of lemon, 1 tablespoon lemon zest, 0.5 cup powdered sugar, 1.75 cups sugar','PREHEAT oven to 350FGREASE 9x13 inch rectangular cake panCOMBINE crust ingredients and press with fingertips into panBAKE for 20 minutesFILLING: As crust is baking combine all remaining ingredients and whisk together until well combined.When crust is baked, remove from oven, fill with lemon filling; return to ovenBAKE for an addition 23-25 minutes (don''t let the top get overbrown - see pic above for what you are looking for!)REMOVE from oven and allow to cool for 1/2 hr on a wire rack.Tip: To remove from baking pan, cut the bars in half and remove each half with a large flexible spatula. Then finish cutting bars into squaresDUST with sifted icing sugar and you are DONE.Last steps - VERY IMPORTANT: Put on a pot of tea and I will be there shortly ;)See "Recipe" PLUS photos @ my blog: http://lemondropsfoodie.blogspot.com/2011/02/luscious-lemon-bars.html',45,45,0);
INSERT INTO "Recipe" VALUES(55,'5 Minute Xocai Chocolate Mug Cake','https://img.spoonacular.com/recipes/631879-556x370.jpg','3 tbsps chocolate, 2  eggs, 4 tbsps flour, 3 tbsps honey, 3 tbsps milk, 0.125 tsp vanilla','Add egg, milk, oil, honey, and vanilla into a coffee mug. Mix together wit a fork. add the flour, Activ, and Sipping Xocolate. Mix again. Put mug in the microwave and cook for 3 minutes at high power. the cake will rise slightly over the top of the mug. Allow to cool a little. Tip out onto a plate if desired. Eat while warm. Serves 2',45,45,0);
INSERT INTO "Recipe" VALUES(56,'Funghetti Trifolati','https://img.spoonacular.com/recipes/644094-556x370.jpg','3 tablespoons extra virgin olive oil, 2 cloves garlic, 1 pound variety of mushrooms, 6 servings bell pepper, 6 servings salt, 1 cup wine, 4 sprigs parsely, 4 sprigs parsely','First, in a large skillet let the oil get hot. Then add the garlic saute until it takes on a golden color, without burning it. When the garlic is ready, add the mushrooms and let them release their juice and reduce for 5 to 10 minutes. At first the mushrooms look big, but they will shrink a lot. Don''t worry if it appears to be a lot at first. When the mushroom has released all the liquid and it is reduced a bit, add the white wine and let it reduce for another 5 minutes , until the juice reaches a nice consistency. Add salt and pepper to taste. Before serving, sprinkle the parsley on top.',45,45,0);
INSERT INTO "Recipe" VALUES(57,'Baked Fried Chicken With Cauliflower Mash','https://img.spoonacular.com/recipes/633624-556x370.jpg','0.25 cup buttermilk, 1.5 cups buttermilk, 2 heads cauliflower, 6 servings cauliflower mash, 0.5 teaspoon cayenne pepper, 6 servings chicken, 3 tablespoons dijon mustard, 1.5 teaspoons mustard, 6 tablespoons flour, 2  garlic cloves, 2 tablespoons lemon juice, 2 teaspoons lemon peel, 0.25 cup cream, 1.5 cups panko, 1 teaspoon paprika, 0.5 cup parmesan cheese, 0.25 cup ricotta, 6 servings salt and pepper, 2 pounds chicken breast, 1 tablespoon thyme','For marinade:Fillet chicken breast in half to make thinner pieces, and cut in half again to make smaller pieces.Whisk all marinade ingredients (except for the chicken) in large bowl.Add chicken and coat in marinade.Chill overnight for more intense flavor. But if you are short on time (which I usually am) it is ok to use right away as well.For breading:Preheat to 450FMix breading ingredients large bowl. Place wire rack on baking sheets. Remove chicken breast from bowl and place in coating mixture. Transfer to rack. Repeat with remaining chicken breasts.- Place chicken breasts on rack and spray with olive oil .Bake chicken 20 minutes or until coating is browned and instant-read thermometer registers 155F.For Cauliflower:Cut up cauliflower in small pieces.Place in large saut pan with about 1 cup of water (enough to cover the bottom of pan, plus a little extra to make sure it doesn''t all evaporate)Cook until tender.Combine cauliflower with buttermilk, sour cream, ricotta and salt and pepper.In batches, place in blender and puree until smooth. (if it is having a hard time blending, add either some chicken or vegetable stock, or even more buttermilk)',45,45,0);
INSERT INTO "Recipe" VALUES(58,'Halloween Mocha Cupcakes','https://img.spoonacular.com/recipes/646138-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 0.5 cup bittersweet chocolate chips, 0.75 cup bittersweet chocolate chips, 0.5 cup buttermilk, 100 g cake flour, 12 servings chocolate cocoa powder, 60 g natural cocoa powder, 4 teaspoons coffee extract, 1  egg, 12 servings halloween sprinkles, 0.5 cup heavy cream, 8 oz mascarpone cheese, 0.5 cup oil, 0.25 teaspoon salt, 0.6666667 cup sugar, 1 teaspoon vanilla extract','Step 1: Prepare the frosting by melting the chocolate in a double broiler. When the chocolate has melted, add heavy cream and coffee extract. Mix well and chill in the refrigerator until needed. Dont combine the mascarpone cheese, yet.Step 2: Preheat oven to 350 degrees F and line the cupcake pan with Halloween baking cups. In a large bowl, combine the the cake flour, cocoa powder, baking powder, baking soda, and salt.Step 3: In another large mixing bowl, mix together the oil, sugar, egg, and vanilla and coffee extract and mix well. Then add the buttermilk and mix well again.Step 4: Now stir in the flour mixture and mix until well combined.Step 5: Pour the batter into a ziploc or piping bag and pipe into the cupcake pan. Bake for 20 to 25 minutes or until an inserted toothpick comes out clean (I baked mine for about 24 minutes).Step 6: Let the cupcakes cool in the pan for about 5 to 10 minutes and then transfer them to a rack to cool completely.Step 7: While cupcakes are cooling, make the chocolate decorations. Melt the chocolate and use a ziploc or piping bag to pipe out your design onto some parchment paper. Sprinkle the halloween sprinkles before the chocolate hardens. Chill in freezer until needed.Step 8: Finish the frosting. Using an electric mixer, beat the mascarpone cheese until light and fluffy. Add the cooled chocolate cream mixture from earlier and beat until combined.Step 9: Roughly spread the frosting on the cooled cupcakes. Dust with cocoa powder and decorate with sprinkles and chocolate.',45,45,0);
INSERT INTO "Recipe" VALUES(59,'Kyuri Tsukemono','https://img.spoonacular.com/recipes/649137-556x370.jpg','3  to 4 japanese cucumbers, 2 tablespoons soy sauce, 1 tablespoon rice vinegar, 1 teaspoon sesame oil, 4 servings chili peppers',replace('Rough chop cucumbers.\nIn a medium, securely sealable container, combine soy sauce, rice vinegar, and sesame oil.\nAdd cucumbers to the marinade, close container and shake.\nRefrigerate for 1 to 2 hours. Shake cucumbers periodically, or leave overnight to marinate. Note, the longer the cucumbers are left in the marinade the saltier they become. I''ve left them in the marinade for up to 3 days and the cucumbers were good.\nServe and enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(60,'Roasted Sweet Potato Salad','https://img.spoonacular.com/recipes/658680-556x370.jpg','3 pounds sweet potatoes, 0.25 cup extra virgin olive oil, 1 inch chipotle pepper adobo sauce, 1 teaspoon balsamic vinegar, 2 teaspoons salt, 0.25 teaspoon pepper, 1 cup cranberries, 0.5 cup pecans, 2 tablespoons chives',replace('Preheat oven to 400 degrees (convection works best).\nPeel and cut potatoes into 1 pieces.\nToss to coat with 2 tablespoon of olive oil.\nArrange in a single layer on two baking sheets\nRoast for 35 minutes\nMix 2 tablespoons oil, pepper puree, vinegar, salt and pepper to make a dressing\nCombine cranberries, pecans, chives and cooked sweet potatoes in a medium bowl, drizzle with dressing, cover. Refrigerate until chilled.','\n',chr(10)),45,45,1);
INSERT INTO "Recipe" VALUES(61,'Quick and Easy Caprese Salad','https://img.spoonacular.com/recipes/657537-556x370.jpg','4 servings balsamic vinegar, 0.25 cup basil leaves, 8 ounces mozzarella cheese, 4 servings olive oil, 4 servings bell pepper, 0.5 tsp salt, 4  tomatoes','Slice mozzarella and tomatoes into 1/4 inch slices and arrange on platterSprinkle basil leaves over allDrizzle with oil and vinegarSalt and pepper to taste',45,45,1);
INSERT INTO "Recipe" VALUES(62,'Spinach and Gorgonzola Stuffed Flank Steak','https://img.spoonacular.com/recipes/661259-556x370.jpg','1.5 pounds flank steak, 3 tablespoon olive oil, 1  shallot, 0.5 pound spinach, 0.75 cup bread crumbs, 0.25 pound gorgonzola, 4 servings salt and pepper',replace('Preheat oven to 375.\nButterfly the steak by using a long sharp knife holding it parallel to the work surface, cut through the long side of the steak, stopping about  inch from the opposite side. If the steak is already thin, just pound it with a mallet to  inch thick.\nIn a large skillet over medium heat add 1 tablespoon olive oil and saut` the shallots until soft, 2 minutes. Add the spinach and cook until just wilted, about 2 to 3 minutes. Transfer to a colander.\nWhen cool enough to handle, squeeze out all the moisture from the spinach and transfer to a medium bowl. Stir in the bread crumbs and cheese. Season with salt and pepper.\nPlace the steak on a sheet of plastic wrap. Smear the spinach mixture evenly over the steak, leaving about 1 inch border along the side edge. Beginning with the side near you and using the plastic wrap as an aid, rollup the steak, gently pressing on the filling.\nTie the rolled steak with twine at 2-3 inch interval.\nSeason the outside with salt and pepper.\nHeat the remaining 2 tablespoons olive oil in a large ovenproof skillet over medium high heat. Sear the roast on all sided, about 2 minutes per side.\nPlace in the oven and roast for 20 to 25 minutes.\nTransfer to a cutting board, tend with aluminum foil and allow resting for 10 minutes.\nTo serve, remove the twine from the roast and cut into  inch to 1 inch thick slices.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(63,'Pesto Chicken Zoodles','https://img.spoonacular.com/recipes/780001-556x370.jpg','1 tsp cajun seasoning, 16 oz chicken breasts seasoned, 0.75 cup basil leaves, 1 clove garlic, 1 Tbsp garlic salt, 0.5 cup olive oil, 1 Tbsp parmesan cheese, 3 servings salt and pepper, 2 large zucchini','To get started, place 1/4 cup of olive oil into a medium saucepan and allow to heat on medium heat. Once warm, place zucchini in pan and then sprinkle with garlic salt and cajun seasoning. Toss with tongs to get all of the zucchini coated with oil and seasoning. Cover with a lid and steam for two to three minutes. Remove lid, toss zucchini noodles again and then cover for another 2 minutes. Remove from heat.In the mean time, place the basil, garlic, and grated parmesan cheese into a food processor. Slowly add the olive oil, and then set to the side.Add zucchini noodles, pesto, and chicken to a medium dish and toss until everything is fully coated. Serve immediately.This is seriously, SO GOOD!If you are looking for more healthy "Recipe"s like this Pesto Chicken Zoodles "Recipe", check out the Simple Fit Forty Section of this blog, or consider joining our secret Facebook group where we share all things healthy.If you are not making this TODAY, then make sure you pin this for later! Its a keeper.JOIN 500,000 SUBSCRIBERS!Join over 500,000 others who follow PinkWhen on Social Media, the PinkWhen blog, and email. Sign up to receive exclusive bonuses like this FREE Simple Fit Dinners Ebook.Don''t wait! You won''t want to miss a thing.Success! Now check your email to confirm your subscription and download your FREE ebook.There was an error submitting your subscription. Please try again.First NameEmail AddressSubscribePowered by ConvertKit',45,45,0);
INSERT INTO "Recipe" VALUES(64,'Lemon Pilaf Chicken','https://img.spoonacular.com/recipes/649733-556x370.jpg','2 cups broccoli flowerets, 1.5 cups chicken, 3 tablespoons lemon juice, 1 teaspoon lemon peel, 1 tablespoon olive oil, 1  pkt near east rice pilaf see note','In large skillet bring 2 cups water, olive oil, lemon juice and spice sack to a boil. Stir in chicken and rice pilaf. Reduce heat and simmer for 10 minutes. Add broccoli and grated lemon peel. Simmer for 8 to 10 minutes, or until all water is absorbed.NOTES : For a colorful twist, substitute Near East Chicken Flavor Pilaf.',45,45,2);
INSERT INTO "Recipe" VALUES(65,'How to Make OREO Turkeys for Thanksgiving','https://img.spoonacular.com/recipes/715449-556x370.jpg','36  oreo cookies 3 cups, 1 package cream cheese, 16 oz semi baking chocolate, 48 servings candy corn, 48 servings candy eyes, 48 servings icing',replace('Instructions\n\nTake a package of OREO cookies and crush them up finely.\n\nTake softened cream cheese and mix well with cookie crumbs.\n\nRoll into one inch cookie balls, and then freeze for 10 minutes.\n\nDip cookie balls into melted chocolate and place on a prepared cookie sheet covered with wax paper.\n\nPlace into the refrigerator for 15 minutes to an hour before decorating.\n\nAdd 5 candy corn to the back of the ball as tail feathers.\n\nUse icing as glue to attach the candy eyes.\n\nCut one candy corn into pieces, using the white tip as the nose, and the orange part (cut in half) as feet.','\n',chr(10)),40,40,0);
INSERT INTO "Recipe" VALUES(66,'Mascarpone & Ricotta Cheese Cake','https://img.spoonacular.com/recipes/651189-556x370.jpg','0.25 cup almonds, 1 tablespoon butter, 16 oz whipped cream cheese, 4 large eggs, 2 tbsp flour, 1.5 cups graham crackers, 1 tbsp lemon juice, 8 oz mascarpone cheese, 8 oz ricotta cheese, 0.5 tsp salt, 1.25 cups sugar, 2 tbsp sugar, 1 tsp vanilla extract','DirectionsPreheat oven to 325.Crust:Grind graham crackers and almonds using food processor or a mortar and pestle. Add melted butter and salt and press into bottom of greased springform pan or deep dish pie pan. Bake for 10 minutes. Let cool. Mix sugar and flour together and sprinkle over top of crust. (This prevents crust from getting soggy)Filling:Beat cream cheese, mascarpone cheese, ricotta cheese and sugar in a large bowl until smooth. Beat in lemon juice and vanilla. Add in eggs one at a time. Pour cheese mixture over crust in pan. Bake until the center of the cheesecake is wobbly when shaken, about 1hr and 5 mins. Let cool then refrigerate, preferably overnight.',45,45,0);
INSERT INTO "Recipe" VALUES(67,'Soy Ginger Glazed Sea Scallops With Stir Fry Vegetables','https://img.spoonacular.com/recipes/660737-556x370.jpg','1 cup asparagus, 1 tablespoon brown sugar, 1 teaspoon cornstarch, 1 teaspoon garlic, 1 tablespoon ginger, 2 cups bell pepper, 2 tablespoons scallions, 0.5 pound sea scallops, 2 teaspoons sesame oil, 2 teaspoons sesame seeds, 0.5 cup soy sauce, 0.5 cup teriyaki sauce, 2 cups bell pepper','Whisk all teriyaki sauce ingredients together in a small bowl and refrigerate for at least 30 minutes.Heat sesame oil in a large frying pan over medium-high heat. Add vegetables and saute for 5 minutes, until beginning to soften.Stir in teriyaki sauce and allow mixture to come to a simmer.Add scallops. Stir and cook mixture for 5 minutes, stirring occasionally until sauce thickens and scallops have turned an opaque white.In a small cup, mix cornstarch with two teaspoons of cold water until dissolved. Stir into the pan and let mixture come to a simmer for one minute to thicken fully and coat the scallops and vegetables.Serve!',45,45,0);
INSERT INTO "Recipe" VALUES(68,'Tapioca Pudding with Pineapple and Coconut','https://img.spoonacular.com/recipes/662871-556x370.jpg','200 ml .8 fl oz. coconut milk, 2  egg yolks, 250 ml .5 fl oz. full milk, 2 tsp honey, 1  lime, 250 gr .8 oz. pineapple, 1 pinch salt, 1 tbsp sugar, 65 gr .3 oz. of pearl tapioca, 1  vanilla pod','The place to start is with the tapioca, the pudding is a custard. So, in a heavy bottomed saucepan add the full milk, salt, tapioca, the seeds from the vanilla pod, and the empty vanilla pod. Bring this mix to a gentle simmer and stir occasionally. Do this until the tapioca is translucent and tender, this takes about 20 minutes. When cooked, stir in the coconut milk.While the tapioca mix is cooking you can whisk the egg yolks and sugar together in a bowl - quite big as it has to hold half of your tapioca mix too. Mix the egg and sugar together until the color lightens.Taking your cooked tapioca mix from the heat, pour half of it into the bowl with the eggs and sugar, whisk together using a metal hand whisk. Then pour this back into the pan and place on a medium heat.On a medium heat keep whisking until the mix thickens, this takes about 5 minutes or so. It is important not to use too high a heat as the eggs will scramble. The mix will not become really thick, the chilling process with thicken it further. I like to check the sweetness level at this stage, you can add a little more sugar if you wish, but if you do, stir it through until it dissolves. Put your tapioca pudding in a clean, cool bowl, remove the vanilla bean and set aside to cool. When it has cooled, cover with cling film and put in the fridge.Now for the pineapple. Combine the fruit with the honey, lime juice and most of the zest. Keep back a little lime zest to dress.Place half of the mix in a food processor and blend until smooth. Transfer this back into the bowl with the rest of the pineapple and stir together  check the flavour and add more honey or lime if you wish.Once your tapioca has chilled, place some of the pineapple mix in the bottom of your serving dishes, then add the tapioca and top with a little pineapple and some lime zest to finish.',60,60,0);
INSERT INTO "Recipe" VALUES(69,'Easy Shrimp Scampi','https://img.spoonacular.com/recipes/642096-556x370.jpg','4 tablespoons butter, 2 tablespoons parsley, 6 cloves garlic, 2 tablespoons lemon juice, 1 tablespoon olive oil, 0.25 teaspoon pepper, 0.5 teaspoon salt, 1 pound shrimp, 0.5 cup white wine','In a large skillet, melt butter and oil. Add garlic and saute 30 seconds.Stir in wine and lemon juice and cook 1 minute.Stir in shrimp, parsley, salt and pepper. Cook 2-3 minutes over high heat, stir constantly.Serve with pasta or rice.',45,45,0);
INSERT INTO "Recipe" VALUES(70,'Snickerdoodle Ice Cream','https://img.spoonacular.com/recipes/716411-556x370.jpg','0.5 teaspoon ground cinnamon, 0.125 teaspoon ground nutmeg, 1.5 cups half-and-half, 2 cups heavy whipping cream, 0.33333334 cup brown sugar, 2 teaspoons vanilla extract, 0.33333334 cup vanilla sugar','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(71,'Bbq Chicken','https://img.spoonacular.com/recipes/634476-556x370.jpg','3 tablespoons brown sugar, 0.25 cup catsup, 2.5 pounds chicken pieces, 1 teaspoon mustard, 2 tablespoons soy sauce, 2 tablespoons worcestershire sauce','Combine first 5 ingredients. Baste chicken pieces with 1/2 of this mixture. Broil chicken 20 minutes. Turn and baste with remaining sauce. Broil 20 minutes.',45,45,1);
INSERT INTO "Recipe" VALUES(72,'Cumin and Paprika Rubbed Chicken Drumsticks','https://img.spoonacular.com/recipes/641029-556x370.jpg','5  chicken drumsticks, 1 teaspoon cumin powder, 1 teaspoon paprika powder, 2  garlic cloves, 0.25  juice of lime, 2 servings salt and pepper, 2 servings olive oil',replace('Marinate the chicken with the spice powders, garlic, lemon juice and a tsp of olive oil. Add some salt and pepper to taste and leave at room temperature for at least half an hour.\nHeat the oven to 400F. Grease an oven proof pan. Lay the drumsticks in a single layer. Bake on high for the first fifteen minutes, then reduce to 300F and continue to cook for another fifteen, or until almost done.\nThen turn on the broiler and place the pan under it. Continue to cook the chicken until it gets a nice colour on both sides (turn them after about five minutes on each side).\n\n\nServe with corn sauted with garlic, chilli and green onions and garnished with fresh cilantro and spring onion greens','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(73,'Corn Avocado Salsa','https://img.spoonacular.com/recipes/640062-556x370.jpg','1  avocado, 1 teaspoon balsamic vinegar, 1 teaspoon cumin, 0.75 cup corn, 1 clove garlic, 0.5 medium bell pepper','Preheat oven to 375 degrees.Spread corn flat on a baking sheet.Spray lightly with olive oil spray.Roast corn in the oven for about 8-10 minutes. (Be careful not to brown too much or burn.)Remove from heat and allow to cool.Finely chop red pepper and garlic and mix in a bowl.Peel and coarsely chop avocado and add to bowl.Add cooled corn.Mix in cumin and vinegar and blend well.',25,25,0);
INSERT INTO "Recipe" VALUES(74,'Blueberry Yoghurt Cake','https://img.spoonacular.com/recipes/635554-556x370.jpg','240 g butter, 200 g sugar, 1 tsp vanilla extract, 260 g eggs, 60 g natural yoghurt, 120 g flour, 1 tsp baking powder, 60 g almond meal, 100 g blueberry filling',replace('Sieve plain flour, baking powder and almond meal together, set aside.\nBeat butter, sugar and vanilla extract till creamy and white. Add yoghurt into it and mix well.\nAdd eggs one at a time, fully incorporated before adding the next egg.\nStop machine and use a rubber spatula to fold in the flour mixture well.\nLastly fold in the blueberry filling, mix well and pour batter equally into two oval shape cake pans.\nAdd some fresh or frozen blueberries on top (optional).\nBake at preheated oven at 170C for 30-35 mins or skewer inserted into the centre of the cake comes out clean. (Cover the cake loosely with an aluminium foil at half way of baking if you find the top of the cake is too brown).','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(75,'Strawberry and Chocolate Chip Panini','https://img.spoonacular.com/recipes/661741-556x370.jpg','1 serving strawberries, 1 serving chocolate chips- handful, 2 slices sourdough bread, 1 serving olive oil and brush',replace('Open up the slices of sourdough bread\nBrush it wit some olive oil on either side\nAdd a layer of strawberries and chocolate chips\nPut it in the panini press!\nServe it hot with a side of fresh cut berries!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(76,'Torta (Filipino Omelet)','https://img.spoonacular.com/recipes/663680-556x370.jpg','1 pound ground beef, 4  garlic cloves, 1  onion, 1 can tomatoes, 6  eggs, 1 Bunch scallions, 0.25 cup cilantro, 4 tablespoons vegetable oil, 4 tablespoons soy sauce, 8 servings salt & pepper',replace('In a medium-heated large skillet, add a little oil and thoroughly cook the meat and potatoes along with soy sauce, garlic and onions. Set aside to cool.\nMeanwhile, in a mixing bowl, combine cooled meat mixture with the eggs, tomatoes, cilantro and scallions. Season with salt & pepper and whisk until evenly incorporated.\nIn the same skillet in medium heat, ladle just enough to form a thin pancake-size patty, one batch at a time. Cook both sides, flipping over after 2-3 minutes. Be careful not to over brown the eggs. Transfer to a plate, cut in wedges (for bite-size servings) and garnish with cilantro leaves, if you want.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(77,'Cheesy Turkey Meatballs','https://img.spoonacular.com/recipes/637690-556x370.jpg','1 cup bbq sauce, 0.75 cup breadcrumbs, 1  carrot, 1  egg, 1 clove garlic, 1 pound ground turkey, 1 cup milk, 1 cup onion, 0.25 teaspoon pepper, 4 servings salt, 0.5 cup cheddar, 1 teaspoon worcestershire','Add together in a large bowl your turkey, breadcrumbs, egg, salt, Worcestershire, milk, carrot, onion, cheese, garlic and pepper.Mix it together well.  I actually use my hands to mix it together (after a good washing of course).  Its just easier and youre going to need to get dirty anyway to make the meatballs.  Once youve mixed it up good, grab small handfuls of your meat mixture, roll them into balls.Heat up about a tablespoon of oil in a large skillet on medium high heat.  When the oil is heated up, drop your balls into the pan.Cook for about 5 to 10 minutes, flipping to all sides, until they are cooked through.  Once they are cooked up, drain any leftover oil and add in your bbq sauce.Heat and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(78,'Fresh Peach Margarita With Lime Sugar','https://img.spoonacular.com/recipes/643559-556x370.jpg','0.5 cup ice, 1  juice of lime, 2 servings lime sugar, 1 teaspoon orange liquor, 1 medium size peach, 2 ounces peach schnapps, 2 tablespoons sugar, 4 ounces silver tequila','If making lime sugar:  Add 1/2 teaspoon of finely minced lime zest to 1/4 cup granulated sugar and set aside for about 30 minutes, stirring occasionally.For a pretty presentation, coat the rims of the glasses you are using with lime sugar (of course you can alternatively use plain white sugar).  Do this by rubbing the rim with a lime wedge and then placing the rim into a plate that has the sugar in it until the rim is coated with sugar.Place all ingredients into the blender and puree.  Add a little cold water if it is too thick.  Either chill all ingredients before making or add some ice cubes after you have made the margarita and stir it until it is as cold as you like and strain it into your glasses (or serve on the rocks).',45,45,0);
INSERT INTO "Recipe" VALUES(79,'Classic Eggs Benedict','https://img.spoonacular.com/recipes/639594-556x370.jpg','1 package knorr hollandaise sauce, 4 Slices canadian bacon, 2  muffins, 0.5 teaspoon vinegar, 4  eggs',replace('Prepare Knorr Hollandaise Sauce according to package instructions.\nBrown Canadian Bacon in a frying pan and toast English muffins. While bacon is cooking, poach the eggs.\nFill a medium sized sauce pan half way with water. Add 1/2 teaspoon of white vinegar (this is optional but the vinegar helps hold the egg together). Bring to a gentle boil and carefully add eggs (1-2 at a time works best). Poach eggs for 2-3 minutes or until yolk has set to your preference. Remove eggs one at a time with a slotted spoon.\nLayer ingredients as follows: English muffin, Canadian Bacon, Eggs, Hollandaise Sauce.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(80,'Lamb In Red Mole Sauce','https://img.spoonacular.com/recipes/649214-556x370.jpg','2  chipotle peppers, 2  pasilla peppers, 8  plum tomatoes, 3 cloves garlic, 1 teaspoon oregano, 1 teaspoon cinnamon, 1 tablespoon sesame seeds, 0.5 teaspoon pepper, 2 tablespoons canola oil, 1.5 ounces mexican chocolate, 0.5 teaspoon salt, 8 ounces tomato sauce, 3 tablespoons canola oil, 1  lamb shoulder, 4 servings salt and pepper',replace('To make mole sauce, soak chipotle peppers in hot water until soft. Remove seeds and stem.\nPuree chipotles, roasted peppers, tomatoes and garlic until smooth and set aside.\nToast oregano, cinnamon, sesame seeds and pepper until fragrant.\nIn a saucepan, heat canola oil, then add pureed vegetables, spices, chocolate, salt and tomato sauce. Heat until chocolate melts and then continue to simmer, covered, for 15 minutes, stirring frequently. If sauce is too thick, add water to thin as needed.\nHeat oil in a large skillet.\nSeason lamb on all sides liberally with salt and pepper, then sear in skillet until a brown crust forms on all sides.\nLay browned lamb in a piece of heavy duty aluminum foil and pour mole sauce over. Seal tightly so that no air escapes and the sauce wont leak out. (Double foil is a good idea.)\nBake at 325 degrees F for 3-4 hours, until lamb is tender and falls from the bone.','\n',chr(10)),45,45,1);
INSERT INTO "Recipe" VALUES(81,'Hawaiian Chicken Chili','https://img.spoonacular.com/recipes/646358-556x370.jpg','8 servings jamaican allspice, 1 can coconut milk, 2  carrots, 3  chicken breasts, 32 oz chicken broth, 8 servings cilantro, 8 servings coconut flakes, 8 servings cumin, 4  garlic cloves, 2 Cans great northern beans, 0.5 cup brown rice, 1  pineapple, 8 servings sea salt, 8 servings cream, 8 servings thyme, 1  onion, 8 servings pepper','Cut 1/2 of a pineapple into small cubes. Add to food processor.Puree pineapple until liquified.Cut chicken into cubes. Add to pan. Pour puree''d pinapple over top. Cook chicken.Chop 1/2 onion.When chicken is almost fully cooked, add onion to chicken &amp; pineapple mixture.Add a scoop of Coconut Milk to chicken mixture. Add a tablespoon of white pepper. Add  4 cloves of pressed garlic.Grab a small bunch of cilantro and few sprigs of thyme. Chop them.Add cilantro and thyme to chicken mixture.Once chicken is fully cooked and onions are almost see through, scoop mixture into food processor. Lightly grind food until chicken looks shredded.Grate 2 medium sized carrots finely.Pour in a new pan 1 can of coconut milk, 32 oz. chicken broth, 1 can of water. Add 2 cans Great Northern Beans &amp; Shredded chicken mixture. Mix well. Bring to a boil. Then simmer. Add carrots.In another pan, add 1 cup of water. 1 tsp garlic, 1/4 tsp. cumin, 2 tbsp. coconut flakes, sea salt, 4 dashes of Jamaican Allspice. Add 1/2 cup Long Grain Brown Rice.Cook rice until al dente. (Still slightly crunchy.)Add rice to simmering mixture. Simmer until carrots and rice are cooked thoroughly.Serve with sour cream.',45,45,0);
INSERT INTO "Recipe" VALUES(82,'Coconut Israeli Couscous Studded With Pomegranate','https://img.spoonacular.com/recipes/639778-556x370.jpg','1 cup milk, 1 cup coconut milk, 8  pods cardamom, 0.25 teaspoon ground cinnamon, 1 tablespoon sugar, 0.5 cup pomegranate seeds',replace('Smash the cardamom pods open with the flat side of your knife (thats right, like a garlic clove).\nCombine the milk, coconut milk, and cardamom in a saucepan and place over low heat. Bring to just below a boil, stirring every once in awhile. It will be a little foamy.\nStrain the cardamom pods out since the shells are not so good to eat.\nAdd the couscous and simmer on low for 10-12 minutes, until all the liquid absorbs. The couscous should be tender but still with some chew to it.\nStir in the cinnamon, sugar, and pomegranate seeds. I used the seeds from half a pomegranate. If you dont have pomegranate seeds, or dont like them, try substituting raisins or dried cranberries.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(83,'Crab Stacks','https://img.spoonacular.com/recipes/640321-556x370.jpg','1  dungeness crab- cooked&, 1 cup quinoa, 1 cup orange juice, 1 cup chicken stock, 1  mango, 1  fresno chile, 1  avocado, 1  lime, 1  roma tomato, 1 tablespoon cilantro, 1 tablespoon green onion, 1  clove garlic, 3 servings salmon',replace('COMBINE THE QUINOA, OJ AND STOCK IN A SAUCEPAN. COOK OVER MEDIUM HIGH HEAT UNTIL ALL LIQUID HAS BEEN ABSORBED. REMOVE FROM HEAT AND SET ASIDE.\nCUT THE LIME INTO QUARTERS.\nCOMBINE THE MANGO AND FRESNO CHILE. SQUEEZE A 1/4 OF THE LIME OVER THE MIXTURE AND MIX TO COMBINE.\nCOMBINE THE TOMATO, CILANTRO, GREEN ONION AND GARLIC. SQUEEZE 1/4 OF THE LIME OVER THE MIXTURE AND STIR TO COMBINE.\nUSING A ROUND MOLD, SPOON SOME OF THE PREPARED QUINOA INTO THE BOTTOM. IF USING THE SALMON- SPOON IN A LAYER OF THE SALMON.- OTHERWISE USE CRAB. TOP WITH A LAYER OF THE TOMATO MIXTURE, THEN AVOCADO.\nTOP WITH A THIN LAYER OF THE QUINOA, THEN CRAB, FOLLOWED BY AVOCADO, THE MANGO MIXTURE AND MORE CRAB AND FINALLY TOPPED WITH A BIT MORE MANGO MIXTURE.\nPRESS DOWN AND THEN REMOVE THE MOLDS.\nGARNISH WITH PICKLED GINGER AND RADISHES AND USE THE REMAINING 1/2 LIME TO SQUEEZE OVER THE STACKS. SERVE COLD.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(84,'Caramel Peanut Fudge Cake','https://img.spoonacular.com/recipes/637016-556x370.jpg','100 g almonds, 25 g cocoa, 300 g chocolate of at least cocoa parts, 500 ml cream, 6  eggs, 150 g peanuts, 1 Tbs rum, 150 g sugar, 2 Tbs water','For the sponge, beat egg yolks with sugar for 3-4 minutes until the mixture doubles in volume and becomes pale yellow.Whisk the egg whites until soft peaks form.Fold the egg whites gently into the egg yolks cream.Gently stir in almonds and cocoa.Lightly butter and flour a 20 round cake pan, line with parchment paper. Pour in the sponge mixture Bake in preheated oven at 180C for about 20 minutes or until done (the trick with a toothpick).Leave the cake to cool completely in the cake pan, then carefully remove it and split into two layers.For the caramel cream heat sugar and water over medium heat and cook, stirring occasionally, until the sugar dissolves and comes to a boil. Continue cooking, but without stirring, until mixture becomes golden amber in color. Remove from flame and set aside.Whip the cream, gradually stir in the caramel syrup.Add peanuts, stir and combine. Mixture must be smooth (at first it will foam up a little). Transfer the cream to a bowl to cool down to room temperature and thicken.For the ganache bring the cream just to a boil over medium-high heat; pour over chocolate. Let stand 10 minutes. Stir very gently for 3-4 minutes until smooth and glossy, incorporating the cream steadily, without overworking.Cool ganache for an hour or until completely chilled, then beat for 2-3 minutes or until it becomes fluffy and lighter in color. Do not overbeat because it will become too thick and not spreadable.To assemble the cake, first sprinkle each cake layer with half of the rum and water syrup.Spread the caramel cream over the bottom layer, cover with the top layer (wet side down).Immediately spread ganache over top and sides of cake.',45,45,0);
INSERT INTO "Recipe" VALUES(85,'Crockpot "Refried" Beans','https://img.spoonacular.com/recipes/775585-556x370.jpg','1 tsp pepper, 2 tsp cumin, 4 Tbsp garlic, 1 large onion, 2 lbs pinto beans, 1 Tbsp up salt, 10 cups water','Rinse the beans in a colander. Pick out any bad beans.Combine all the ingredients in the crockpot. Remove any floating beans. Cover, and cook on HIGH for 4 hours and on LOW for 2 hours.Uncover, and remove extra liquid. Leave enough liquid to reach the desired consistency when the beans are mashed. (We like our beans somewhere between the very-liquidy restaurant style beans, and the canned version of refried beans.)Mash beans with a potato masher to desired consistency.Serve warm. Store in air-tight containers in the refrigerator and use within 2 weeks, or freeze in ziplock bags for later use.',45,45,0);
INSERT INTO "Recipe" VALUES(86,'Autumn Pumpkin Cake','https://img.spoonacular.com/recipes/633101-556x370.jpg','500 g pumpkin, 180 g brown rice flour, 200 ml coconut milk, 0.25 cup raisins, 100 g agave syrup','Go to my blog for the full instructions: http://gourmandelle.com/pumpkin-cake-the-ideal-dessert-for-a-sunny-autumn-day/',45,45,0);
INSERT INTO "Recipe" VALUES(87,'Flank Steak With Garlicky Mediterranean Salad','https://img.spoonacular.com/recipes/643059-556x370.jpg','2 tablespoons balsamic vinegar, 0.5 cup feta, 8 ounces flank steak, 1 clove garlic, 2 servings grill seasoning, 1 teaspoon lemon juice, 0.5 teaspoon lemon zest, 4 cups salad greens, 1 cup mushroom, 0.5 tablespoon olive oil, 10 medium olives, 2 tablespoons oregano, 2 servings bell pepper, 0.25 cup onion, 1 pinch pepper flakes, 2 large roma tomato, 2 servings salt','Combine olive oil, balsamic vinegar, lemon zest, lemon juice, oregano, garlic and red pepper in a small bowl.Add lettuce, feta, mushrooms, onion, tomato and olives in a salad bowl.Toss salad with dressing.Season flank steak with your favorite grill seasoning. I love Martha Stewarts "Recipe". Heat grill pan over medium heat. Spray with cooking spray. Add steak and cook 4  8 minutes per side, depending on how thick and your desired doneness. Let rest for 5 minutes or more before slicing.Serve with steak.',15,15,0);
INSERT INTO "Recipe" VALUES(88,'Creamy Shrimp Bisque','https://img.spoonacular.com/recipes/640700-556x370.jpg','2  celery stalks, 3  green onions, 4 Tbs butter, 1 Tbs garlic, 0.33333334 C flour, 2 C half & half, 3.5 C fish stock, 3 Tbs parsley, 12 Oz shrimp, 15 oz potatoes, 1 Tsp cayenne pepper, 1 Tbs onion powder, 1 Tsp garlic powder, 1 Tsp old bay, 4 servings salt & pepper',replace('In a medium saucepan, add the celery, onion and butter stirring occasionally until tender for about 10 minutes. When tender add the garlic and saut for another 3-4 minutes. Stir in the flour and cook for about 5 minutes to take out the flour taste then add the potatoes, half and half. Let simmer over medium heat for another 5 minutes. Stir in the fish stock, parsley and all of the seasonings then let this cook for another 10 minutes and it gets thick and bubbly. Add the shrimp meat and simmer for another 10 minutes.\nSide Note: My husband and I decided that even though this bisque was amazing the way it was it could also benefit from some smoky bacon. So next time, I will cook up some bacon pieces then set them aside and cook the onion and celery in the bacon drippings. Once the bisque is ladled into bowls, sprinkle the top with the crispy bacon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(89,'Minestrone Soup','https://img.spoonacular.com/recipes/658024-556x370.jpg','125 gr into strips, 1 can kidney beans, 1 can canned tomatoes, 3  carrots, 3 stalks celery, 1 tbsp thyme leaves, 3 large cloves garlic, 100 gr .5 oz. macaroni, 1 tbsp olive oil, 1 large onion, 8 servings some parmesan to serve, 8 servings salt and pepper, 0.33333334  savoy cabbage, 2 tbsp tomato purée, 2 large tomatoes into 8ths, 1.2 liter vegetable stock','Heat the oil in a very large pan that has a close fitting lid.  Then add the celery, bacon, onion, carrot and garlic.  Fry this off for about 5 to 7 minutes until it has softened a little.  No colour is needed on the vegetables, so make sure the heat isnt too high that they become brown, but high enough the vegetables sweat and soften.Add the tomato pure and  the thyme leaves, stir through and cook for about 30 seconds.3.Add the stock, the tin of tomatoes, fresh tomatoes, and a little salt and pepper. Stir everything through, set the heat so that your soup is on a gentle simmer, cover and cook for about 25 minutes or until the vegetables are cooked al dente.Add the pasta and cook until the pasta is ready.  Follow the timing instructions on the packet, but this is normally about 7 minutes.Add the cabbage and the beans and cook until the cabbage has wilted.  This will take about 5 minutes.Check for seasoning and add some salt and pepper if needed before serving.Sprinkle a little parmesan over each bowl of soup.',45,45,0);
INSERT INTO "Recipe" VALUES(90,'Tomato Stack Salad','https://img.spoonacular.com/recipes/663638-556x370.jpg','4 servings balsamic vinegar, 2 tablespoons herbs, 10 ounces goat cheese, 4 servings salt, 4 medium tomatoes','Mix the fresh herbs into the goat cheese.Slice the tomatoes into 4 thick rounds. Sprinkle each tomato round with salt. Gently slather the layers of each tomato with the goat cheese.Stack the rounds to reassemble the tomato. Drizzle with balsamic vinegar!',45,45,0);
INSERT INTO "Recipe" VALUES(91,'Thai Cucumber Salad (By Roz)','https://img.spoonacular.com/recipes/663100-556x370.jpg','1 tablespoon cilantro, 2  cucumbers, 0.5  jalapeno pepper, 2 tablespoons lime juice, 1  lime zest, 0.25 cup onions, 6 servings pepper flakes, 0.5 cup rice wine vinegar, 0.5 cup chop roasted peanuts, 1 teaspoon salt, 2 tablespoons coconut & sesame oil, 1 tablespoon soy sauce, 0.25 cup sugar, 1 tablespoon thai garlic chili pepper sauce, 0.25 teaspoon pepper','Blend all the dressing ingredients together.Mix in all of the chopped vegetables, herb, and peanuts (if you want the peanuts).Add more of any of the flavors that you prefer, which is the true Thai way.Garnish each plate with cilantro leaves and sliced limes.Serve with a patter of add-ins:Lime slices, red pepper flakes, chopped cilantro, chopped peanuts, Thai sweet chili sauce, sugar, salt, etc. for your guests to add more of their favorite flavors.',45,45,0);
INSERT INTO "Recipe" VALUES(92,'Shrimp & Orzo','https://img.spoonacular.com/recipes/659907-556x370.jpg','28 oz canned tomatoes, 0.75 c wine, 1  fennel bulb, 6 oz feta cheese, 2 T parsley, 6  loves of garlic, 8 servings lemon wedges, 2 c chicken broth, 3 T olive oil, 1  onion, 4 t oregano, 1 lb orzo pasta, 0.75 t pepper flakes, 8 servings salt & pepper, 1.5 lb shrimp, 2.5 c water','Preheat oven to 400 degrees f. Season the shrimp with salt &amp; pepper, refrigerate until ready to use. Grease a 13x9-inch baking dish.Heat the oil in a large Dutch oven over medium-high heat until the oil is shimmering. Add the onion, fennel bulb and 1/2 t. salt. Cook, stirring frequently until the vegetables are softened and starting to brown around the edges, about 10 minutes. Add the minced garlic and crushed red pepper flakes, cook and stir until the garlic becomes very fragrant, about 30 seconds.Add the orzo to the vegetables, stir to coat the orzo with oil, continue cooking, stirring fairly constantly, about 4 minutes, until the orzo has a toasty aroma. Add the wine, cook,stirring constantly, until the liquid evaporates, about 1 minute. Add the chicken broth, water and 1/4 t. salt. Bring to a boil, then reduce heat, simmer, until the orzo is almost completely tender, about 12 minutes, stirring fairly constantly to prevent sticking and adjusting the heat as necessary to maintain a lively simmer.After the 12 minutes, remove from heat and stir in the shrimp, tomatoes, oregano and 1 T. of the parsley. Transfer to the prepared baking dish, sprinkle with the feta. Bake for about 20 minutes, until the shrimp is cooked through and the feta is lightly browned. Before serving, sprinkle with the remaining parsley and the reserved fennel fronds. Serve with lemon wedges.',45,45,0);
INSERT INTO "Recipe" VALUES(93,'Coffee-Infused Bbq Baby Back Ribs','https://img.spoonacular.com/recipes/639893-556x370.jpg','4 teaspoons chile powder, 2 teaspoons thyme, 2 teaspoons ground cumin, 2 teaspoons garlic powder, 2 teaspoons salt, 1 teaspoon pepper, 0.5 teaspoon cayenne, 2 rack baby back ribs, 1 teaspoon liquid smoke, 1 Tb oil, 3 cloves garlic, 0.75 cup cider vinegar, 0.5 cup soy sauce, 28 ounces tomato puree, 3 Tb molasses, 1 cup brown sugar, 2 teaspoons coffee granules, 2 teaspoons cumin, 2 Tb dijon mustard, 2 teaspoons paprika',replace('Preheat the oven to *350. Mix the first seven ingredients in a small bowl.\nCut each rack in several pieces and rub the spices over all the rib sections. You can leave the ribs whole if you like the way they look better--I just think they are easier to handle on the grill in smaller pieces! Pour 4 cups of water and 1 tsp. of liquid smoke in a roasting pan.\nPlace the ribs in the pan, top up. Tightly cover the pan with foil and bake for 2 hours. Remove from the oven and rest until ready to grill. Meanwhile, add 1 Tb. oil to a sauce pan over medium heat. Add the garlic and saut for 1-2 minutes. Then add the rest of the ingredients for the BBQ sauce to the sauce pan. Simmer for at least 30 minutes, stirring occasionally.\nHeat a grill over medium-low heat. Brush the ribs completely with BBQ sauce. Place them on the grill and cook for 20 minutes, turning and brushing every 5 minutes until the desired bark has developed.\nIt''s fun to make your own BBQ sauce. But in a pinch, buy a bottled variety you like and simmer for a few minutes with the coffee granules!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(94,'Lemony Greek Lentil Soup','https://img.spoonacular.com/recipes/649886-556x370.jpg','1 pound brown lentils, 12 ounces carrot, 3 quarts water, 1 teaspoon thyme, 0.25 cup lemon juice, 2 teaspoons basil, 2 teaspoons thyme, 1 teaspoon oregano, 0.5 teaspoon pepper, 2 teaspoons salt, 1 medium onion, 3 cloves garlic, 1 tablespoon olive oil, 28 ounces canned tomatoes, 1 teaspoon teaspoon',replace('Put the lentils, water, carrot and 1 teaspoon dried thyme into an 8-quart stockpot, cover and set over medium heat.\nAfter 15 minutes, lower the heat somewhat and gently bring the water to a simmer, which should take another half an hour or so.\nOnce the lentils have reached the boiling point, turn off the burner and let them sit for 1 hour.\nAfter the hour, bring the soup back to a simmer and add the lemon juice, dry basil, fresh thyme, oregano, pepper and salt and simmer for 1 hour.\nNow, slowly saut the onion and garlic in the olive oil until the onion is tender.\nCoarsely chop the tomatoes (I do this with kitchen scissors right in the can), and add them and the onion mixture to the soup. Adjust the salt to taste.\nBring everything back to the boiling point and simmer for another hour.  After this point, you can turn your burner to its lowest setting, and this soup will happily sit steaming with its lid cocked for several hours until you are ready to enjoy it.  Add more water if necessary.\nServe with crusty bread and a soft cheese like St. Andre or Cambazola','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(95,'Spicy Banana Zucchini Balls','https://img.spoonacular.com/recipes/661014-556x370.jpg','1 cup coarsely zucchini, 1 large banana, 1  egg, 2 teaspoons turmeric, 3 tablespoons honey, 1 teaspoon curry powder, 2 teaspoons chilli pepper, 0.25 teaspoon baking soda, 0.5 cup panko breadcrumbs, 0.5 cup flour, 24 servings vegetable oil',replace('Mix all ingredients in a bowl until it forms a soft dough.  Add more flour if needed.\nHeat vegetable oil on medium heat (about 350F).  Drop a teaspoonful of dough (regular teaspoon) into the hot oil and fry until brown, turning zucchini ball around. (Make sure your oil is not too hot or your zucchini balls will get too brown!)\nDrain in paper towel.  Repeat with the rest of the dough.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(96,'My Drunken Fish Fillet','https://img.spoonacular.com/recipes/652848-556x370.jpg','12 fillet fish, 1 dash salt to fillet fish, 1 dash ground pepper to fillet fish, 2 teaspoons rice wine, 0.75 cup beer, 2  eggs the egg yolk from, 0.5 cup all purpose flour and a little more, 0.5 teaspoon salt, 2 servings oil',replace('Combine beer, egg yolk, flour and 1/2 tsp salt.\nBeat well until it becomes thick.\nSet aside in the fridge for one hour.\nSprinkle some salt and pepper over the fish. Pat them and make sure they are well coated with salt and pepper. Splash the rice wine and marinate the fish fillet for 15 to 20 minutes.\nNext, before cooking, whip the egg white until it becomes soft and foamy.\nFold the egg white into the batter. Mix carefully.\nNow you have the most precious drunken batter, dip the fish or put the fillet fish straight into the bowl of batter and start frying 3 pcs at a time.\nFor the dip.. I just prepared some Yamasa soy sauce with Wasabi from tube and lemon juice.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(97,'Cheesy Bacon Burger with Spicy Chipotle Aiolo Sauce','https://img.spoonacular.com/recipes/637631-556x370.jpg','2 teaspoons chipotle chiles in adobo, 3 Tablespoons mayonnaise, 1 clove garlic, 0.25 teaspoons garlic powder, 3 Tablespoons greek yogurt, 1 cup bell pepper, 0.5 teaspoons ground cumin, 0.25 teaspoons ground pepper, 1.5 pounds ground beef, 4 teaspoons lime juice, 0.5 cups onion, 2  wedges of laughing cow swiss cheese, 4 slices turkey bacon, 4  hamburger buns','For Burgers:In a pan cook turkey bacon according to directions on package.Once bacon is done being cooked, take the bacon out and set aside. Add bell pepper and onion into same pan, cook until tender about 10 minutes.Add ground beef to a small bowl, add garlic powder and ground pepper, mix well.Divide the raw meat into 8 equal pieces (I used my scale to measure into 2oz each piece). Flatten out the hamburger, and place 1/2 a cheese wedge onto each piece of hamburger. Take the other pieces of the hamburger and place on top of the cheese , and squish them togther and seal the edges so the cheese doesnt ozzz out. Place on grill and cook until done. About 5 minutes per side.Place burger on buns, top the burgers with bacon, peppers & onions and sauce.For Spicy Chipotle Aiolo Sauce:In a small bowl place all the ingredients together and wisk together until combined.Makes 3/4 cups or 12 Tablespoons',45,45,0);
INSERT INTO "Recipe" VALUES(98,'Fish Pie With Fresh and Smoked Salmon','https://img.spoonacular.com/recipes/642977-556x370.jpg','1  bay leaf, 0.5 teaspoon peppercorns, 1 tablespoon butter, 1 cup chicken stock, 2 teaspoons cornstarch, 1 teaspoon chives, 1 teaspoon tarragon, 0.5 cup greek, 1 tablespoon horseradish, 1 teaspoon lemon juice, 3 tablespoons milk, 1 tablespoon olive oil, 1  onion, 2 medium potatoes, 4 ounces salmon, 8 ounces salmon, 8 ounces savoy cabbage, 0.5 cup white wine','Peel potatoes and cut into chunksCook in boiling, salted water until tender, app. 15 minutesDrain potatoes, add butter, horseradish and 2 tbs milk to potatoes, mash, adding a bit more milk if neededPut fresh salmon in a medium skillet, add water to almost cover, lemon juice, bay leaf and peppercorns.  Cover and poach until done, 12 - 15 minutes. It should be opaque and flake easily with a fork.Remove salmon and cut into large chunksRoughly chop the smoked salmonSaut onion in oil until tenderAdd cabbage and saut, stirring 2 - 3 minutes.Add white wine, chicken stock, herbs, cover and simmer 10 minutesDissolve cornstarch in water and add to cabbage, stirring until thickenedRemove from heat and add yogurt and stir well to combine.Add both salmons to cabbage and stir gently.Spoon into a baking dishTop with potatoesBake, 400F (200C) for 15 minutes or until the top starts to brown.',45,45,0);
INSERT INTO "Recipe" VALUES(99,'Focaccia with Tomato, Green Onion and Garlic','https://img.spoonacular.com/recipes/643175-556x370.jpg','1 tablespoon coarse salt, 4 cups flour, 1  garlic clove, 1  green onion, 4 tablespoons olive oil, 0.5 teaspoons oregano, 2 tablespoons parmesan cheese, 1 tablespoon sugar, 1.5 small tomatoes, 0.5 pint warm water, 2 teaspoons quick-rising yeast','Note: You can use a standing mixer with a dough hook to mix the dough, but we made our bread the old-fashioned way, kneading it with our hands.Combine the yeast with warm water (this is referred to as proofing the yeast) in a small bowl along with the sugar. Gently stir the mixture to dissolve everything. Allow the yeast to stand for about 3 minutes until it gets a bit foamy.Add the flour to a large bowl and make a well in the center of it.In a small bowl, dissolve the salt in a few tablespoons of water, and add it to the flour along with the yeast mixture. Next add the olive oil to the mixture.With your hands and a spatula to scrape down the bowl, mix everything together to form the dough. Punch down and knead the dough, turning it as you go, for at least 10 minutes or until the dough is smooth, soft and pliable. Add a bit of flour to the dough as needed. Form the dough into a round ball.Add some olive oil to your hands and smooth it over the dough ball to coat it and leave it in the bowl. Cover the bowl with a thick towel and place the bowl in a warm spot to let the dough rise to double its size (about 45 minutes to an hour).Coat a baking sheet (with sides) with olive oil and sprinkle a few tablespoons of cornmeal over the entire pan. Set aside.Once the dough has risen, place it on a floured surface and punch it down 3-4 times. Allow it to stand for a few minutes while you get your toppings ready.Moving back to the dough, roll and stretch it out into an oblong shape that is about 1/2 an inch thick. Place the dough on the oiled baking sheet, cover it with plastic wrap and let it stand for about 15 minutes.Preheat your oven to 400 degrees F. After the dough has rested and youre ready to bake it, poke small wells all around the dough using your finger. Brush the surface of the dough with olive oil.Evenly sprinkle on the dried oregano, green onion, tomato and garlic. Sprinkle with coarse salt, then grated Parmesan cheese.Bake on the bottom rack for 20 minutes, checking it as it gets close to the end of the baking time.',45,45,0);
INSERT INTO "Recipe" VALUES(100,'Lemon Blondies with Lemon Glaze','https://img.spoonacular.com/recipes/649518-556x370.jpg','1 teaspoon butter, 2  eggs, 1.25 cups flour, 1.5 cups granulated sugar, 2 tablespoons lemon juice, 1  lemon zest, 1 cup powdered sugar, 1 pinch salt','Preheat oven to 350 degrees.  Spray an 8 or 9-inch square pan with nonstick cooking spray.  In a medium bowl, stir together flour and salt.  Using an electric mixer, cream the butter, sugar and lemon zest at medium speed until light and fluffy.  Add eggs, 1 at a time, beating well after each addition.  Stir in 2 tablespoons lemon juice.  Reduce speed to low and add flour mixture, mixing until incorporated.  Spread batter into prepared pan and bake for about 30-35 minutes, or until toothpick inserted in center comes out clean.  Cool on wire rack to room temperature.Meanwhile, make the glaze by combining the powdered sugar, lemon juice and zest in a small bowl.  Spread over brownies and let set for at least 10 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(101,'Sun Dried Tomato Stuffed Mushrooms','https://img.spoonacular.com/recipes/662285-556x370.jpg','24 ounces button mushrooms, 0.5 Cup bread crumbs, 1  roasted pepper, 1 cloves from one roasted garlic bulb, 2 Tbsp kalamata olives, 1 medium onion, 3 Tbsp sun-dried tomatoes, 1 tbsp olive oil, 0.25 cup mozzarella, 0.25 cup provolone, 0.25 cup asiago, 1 tbsp parmesan, 1 tbsp romano, 1 pinch pepper flakes, 1 tsp oregano, 2 tbsp mozzarella, 8 oz of',replace('Preheat oven to 350\nClean mushrooms and remove the stems. Lightly oil mushroom caps and place on a greased cookie sheet. Finely dice mushroom stems, set aside.\nIn a large bowl combine cream cheese, cheeses, half the dried bread crumbs, red pepper flakes and dried oregano. Stir until well combined. Salt and pepper to taste. Set aside.\nOver medium heat, saut onions in olive oil until translucent. Add diced mushroom stems and continue to saut for one minute. Stir in roasted garlic, olives, roasted red peppers, and sun-dried tomatoes Cook until thoroughly heated.\nAdd sauted vegetables to the reserved cream cheese mixture. Stir to combine.\nScoop one tablespoon of mixture into prepared mushroom caps. Sprinkle with remaining bread crumbs and mozzarella cheese.\nBake in the oven for 20-25 minutes until browned. Let stand 5 minutes before serving.\nServes 8','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(102,'5-Minute Rocky Road Fudge','https://img.spoonacular.com/recipes/631882-556x370.jpg','2 c semi-sweet chocolate chips, 14 oz condensed milk, 1 t vanilla extract, 0.125 t salt, 3 c mini-marshmallows, 1.5 c walnuts',replace('Line a 13x9-inch pan with foil, lightly spray with cooking spray. Set aside.\nIn a large, microwave safe bowl, add chocolate chips and condensed milk. Microwave for about 40 seconds, or until the chips are just melted when you stir them. If needed, continue to microwave in 15 second increments until melted. Do not overcook. Immediately stir in vanilla and salt. Then fold in the marshmallows and nuts.\nWorking quickly, spread and press fudge into the prepared pan. Refrigerate until completely cooled before cutting into squares.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(103,'Flank Steak with Mushroom Sauce','https://img.spoonacular.com/recipes/631750-556x370.jpg','2 packets flavor concentrated beef broth, 2 tablespoons butter, 1  flank steak, 1 tablespoon rosemary leaves, 4 cloves garlic, 3 cups mushrooms, 2 tablespoons olive oil, 1  shallot, 0.25 cup water','Heat 1 tablespoon oil in a 10-inch skillet over medium heat.  Add the beef and cook until well browned on both sides and until desired doneness, about 10 minutes for medium-rare.  Remove the beef from the skillet.Heat 1 tablespoon butter and the remaining oil in the skillet.  Add the mushrooms and cook for 5 minutes or until tender, stirring occasionally.  Add the shallot, garlic and rosemary and cook and stir for 30 seconds.   Stir in the concentrated broth, water and remaining butter and cook until the butter is melted.Cut the beef diagonally against the grain into thin slices.  Serve the mushroom mixture with the beef.',45,45,0);
INSERT INTO "Recipe" VALUES(104,'Hyderabadi baghara Baingan','https://img.spoonacular.com/recipes/647679-556x370.jpg','4 servings baby eggplants- 10-12, 4 servings kashmiri chilies- 3-4, 3 tbsp coconut, 1 tbsp coriander seeds, 1 tsp cumin seeds, 4 servings curry leaves- 8-10, 2 cloves garlic, 1 piece ginger- 1, 4 servings tamarind- a lime sized, 1 tsp oil, 1 large onion, 4 servings salt, 0.5 tsp nigella seeds, 1 tsp sesame seeds, 0.25 tsp turmeric, 2 tsp jaggeryns, 2 tbsp peanutsns, 2 tbsps cashewnuts, 2 tbsps cashewnuts','Wash the eggplants and pat them dry. Slit the eggplants length wise into fours but keep the stems intact. This way, the egg plants remain joined at the stem. Keep aside.Heat a tspn of oil in a separate pan and add the cumin seeds, peanuts and cashew nuts and fry for a few seconds. Add ginger, garlic and chopped onion and fry for a min. Add the turmeric, coriander seeds, coconut and Kashmiri red chilies and fry till the mixture is brown. Allow the mixture to cool completely and blend to a fine paste using a little water and keep aside.Heat oil in a thick bottomed pan and fry the egg plants till brown and tender, remove and keep aside.Add the nigella seeds to the same oil and allow them to crackle. Stir in the curry leaves and fry for a few seconds. Add the ground paste, tamarind pulp, salt and jaggery and mix well.Add the sauted egg plants and 1/2 cup of water and cook covered over low heat till the egg plants are cooked through and soft.Serve the curry hot with either rice or rot is.',45,45,0);
INSERT INTO "Recipe" VALUES(105,'Creamy Vegan Butternut Squash Mac and Cheese','https://img.spoonacular.com/recipes/640720-556x370.jpg','0.5 cup breadcrumbs, 1.5 cup butternut squash, 1 box elbow macaroni, 3 tbsp nutritional yeast, 1 Dash pepper, 1 dash salt, 2 cups soy milk, 1 tablespoons vegan buttery spread, 1 cup vegan cheddar shreds, 4 cups water',' Begin by Preheating oven to 350Bring a large pot of salted water to a boil over medium heat, add in elbows and cook until pasta is al dente.While waiting for pasta to cook begin preparing your sauce. In a medium size sauce pan, melt butter over medium heat, add in nutritional yeast and mix together to form a pasteAdd in soy milk, using a whisk combine together ingredients make sure your sauce is lump free, let simmer for 5 minute or until sauce begins to thickenAdd is pureed butternut squash, thoroughly mix together ingredients to ensure everything is well blended (you may notice that the butternut squash also helps to thicken the sauce).Stir in Cheese, let sit for 1 to 2 minutes or until sauce has a creamy velvety smooth consistency. Remove Sauce from heat and let sitDrain pasta and add pasta to the cheese sauce, stir together and pour mixture into a greased 9 x 9 baking panSprinkle breadcrumbs over macaroni and cheese and let bake for 15 minutes or until cheese begins to bubbleServe Warm and enjoy this creamy Vegan home-style comfort food!',45,45,0);
INSERT INTO "Recipe" VALUES(106,'Garlicky Kale','https://img.spoonacular.com/recipes/644387-556x370.jpg','3 tablespoons balsamic vinegar, 1 clove garlic, 1 bunch curly kale, 2 servings olive oil','Heat the olive oil in a large pot over medium heat.Add the kale and cover.Stir occasionally until the volume of the kale is reduced by half. Uncover. Add garlic and basalmic.Allow to cook for about another 30 seconds or so, mixing well so that the garlic and vinegar are well distributed.Serve hot.',45,45,0);
INSERT INTO "Recipe" VALUES(107,'My Asian Calamari','https://img.spoonacular.com/recipes/652825-556x370.jpg','0.25 teaspoon all spice powder, 1 cup all purpose flour, 1 tablespoon baking powder, 4 servings oil, 1 tablespoon cornstarch, 1 tablespoon curry powder, 1  egg white, 0.5 teaspoon ground pepper, 1 teaspoon paprika, 4 servings salt, 500 grams squid rings, 1.5 cups sugar','In a bowl mix the ff: salt, sugar, pepper,egg white, curry powder,all spice and cornstarch.Mix well and put squid rings, mix again and marinate for one hour or overnight if you like.When you''re about to cook, in a plastic or freezer bag, mix the ff: flour, baking powder and salt.Shake well and start to put inside the squid rings by batches.Fry them at once and make sure the oil is hot!',45,45,0);
INSERT INTO "Recipe" VALUES(108,'Caribbean black bean and sweet potato soup','https://img.spoonacular.com/recipes/637099-556x370.jpg','1 pound turtle beans, 2 tablespoons coconut oil, 1  onion, 4  jalapenos, 2 tsp ground ginger, 0.5 tsp ground allspice, 0.5 tsp thyme, 2 tsp course sea salt, 8 cups vegetable broth, 4 cups sweet potatoes and into, 1 tbsp brown sugar, 1 bunch green onions, 0.5 cup cilantro',replace('Rinse beans and place in a large bowl. Cover beans with   4 inches of water and soak overnight (or 8 hours). Strain and rinse black beans.\nIn a large soup pot, heat the oil over medium heat. Add onion and jalapeno and saut for 10 minutes, until soft.\nAdd beans and vegetable broth or water. Stir in ginger, allspice, thyme and salt. Bring to a boil, then reduce heat and simmer for 1 hour 30 minutes.\nAdd sweet potatoes and brown sugar and simmer for an additional 30 minutes, until beans and sweet potatoes are soft.\nPuree 1 cup of the soup in a blender and then add it back into the soup pot. Stir in cilantro and green onion. Salt and pepper to taste.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(109,'White Chocolate Mocha Cookies','https://img.spoonacular.com/recipes/665185-556x370.jpg','2 cups ap flour, 1 teaspoon baking soda, 0.5 cup cocoa powder, 3  eggs, 2 tablespoons espresso powder, 0.25 teaspoon salt, 0.5 cup semi-sweet chocolate chips, 0.5 cup sugar, 2 tablespoons butter, 1 teaspoon vanilla extract, 0.5 cup chocolate chips','Preheat oven to 350.Cream butter, sugar, eggs and vanilla until fluffy. Add flour, cocoa powder, coffee powder, baking soda, and salt and mix until combined. Fold in chocolate chips.Roll dough into balls; coat with sugar (optional), and set on baking sheet or Silpat. Bake at 350 for 8-10 minutes. If your cookies are too rounded, immediately after taking the cookies out of the oven, press down on the cookies lightly with a measuring cup or the bottom of a cup.',25,25,0);
INSERT INTO "Recipe" VALUES(110,'French Onion Marsala Soup','https://img.spoonacular.com/recipes/643362-556x370.jpg','0.25 cup butter, 2 tablespoons olive oil, 4 cups onions, 42 oz beef broth, 0.5 cup marsala wine, 1 teaspoon thyme, 4 servings salt and pepper, 2 tbsp sugar, 2 bags texas toast croutons, 8 slices provolone cheese, 2 slices swiss cheese, 0.25 cup parmesan cheese',replace('Melt butter with olive oil in a large pot over medium heat. Add onions and stir continually until translucent. Add beef broth, marsala and thyme. Simmer for 30 minutes. Add sugar and season with salt and pepper. Be careful not to over salt!\nLadle soup into oven-safe bowls and place a handful of croutons in each. Sprinkle parmesan and swiss cheese and layer 2 slices of provolone on top. Place bowls on cookie sheet and broil in the preheated oven until cheese bubbles and browns.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(111,'Yuzu Jelly','https://img.spoonacular.com/recipes/665616-556x370.jpg','1 packet konnyaku powder, 1 liter yuzu juice drink, 7 servings extra yuzu juice drink','Pour yuzu juice drink and 100ml water together in a pot under medium heat.Add in konnyaku powder and stir to boil with a hand whisk.Off heat and continue to stir for another 3-5 minutes.Pour yuzu liquid into a 11 inch square tray.Leave to cool and refrigerate for at least 2 hours or when ready to serve.To serve, cut yuzu jelly to cubes and place into serving glass. Pour in some yuzu drink and add in some mandarin orange pulp.',45,45,0);
INSERT INTO "Recipe" VALUES(112,'Eggplant & Artichoke Heart Galettes','https://img.spoonacular.com/recipes/642272-556x370.jpg','1 can artichoke hearts, 10 tablespoons brown rice flour, 1 teaspoon chili flakes, 1 medium eggplant, 3  eggs, 3 teaspoons rosemary, 2  garlic cloves, 0.25 cup goat cheese, 2 servings bell pepper, 1 tablespoon sea salt','Peel and thinly slice the eggplant. Place in a drainer or bowl and toss with sea salt. Let it sit for one hour for the bitter juices to be drawn out. Rinse under running water to remove the salt and squeeze tightly with your hands to remove excess water. Place in a mixing bowl.In a medium bowl, beat eggs with flour to make a thick paste. If paste is thin, add extra flour. Mix well till the mixture is smooth. Stir in eggplant &amp; artichoke hearts and mix till they are well coated.Add rosemary, chili flakes, garlic and season to taste with sea salt and pepper (be careful not to add too much salt) . Add goat cheese and mix carefully so not to cream it - you want them to be chunky.Heat a large oiled pan. When hot, pour about 2 spoonfuls of mixture into the pan and they should form into galettes or "cakes". Cook until both sides are golden brown.Makes 6 galettes/cakes. Serving size is 3 cakes per person.',45,45,0);
INSERT INTO "Recipe" VALUES(113,'PB Cup Stuffed Brownie Bites','https://img.spoonacular.com/recipes/655043-556x370.jpg','2 cups granulated sugar, 1.75 cups flour, 5  eggs, 1 teaspoon salt, 1 cup vegetable oil, 1 teaspoon vanilla, 0.5 cup cocoa powder, 0.5 cup semi chocolate chips, 60  reese''s peanut butter cups',replace('Whisk together sugar, flour, eggs, salt, oil, vanilla, and cocoa powder until well combined. Stir in the semi sweet chocolate chips. Make sure to not over mix!\nPrepare a mini muffin pan with cooking spray and preheat your oven to 350 degrees F.\nScoop batter into the pan.\nFill the slots up about  -  of the way up, so there''s a little room for the peanut butter cup stuffed brownie bites to rise.\nCook for 8 - 10 minutes, or until an inserted toothpick comes out almost clean. It''s ok if these are slightly underdone.\nOnce the brownies are done, gently push a peanut butter cup in the center of the brownie. Let these set in the pan for a couple of minutes.\nRemove from the pan and let them cool the rest of the way on a cooling rack!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(114,'chilli chicken','https://img.spoonacular.com/recipes/629963-556x370.jpg','0.25 cup bell pepper / capsicum, 250 grams chicken breast, 1  to 2 chilies slit, 0.5 tsp chilli powder, 2 tbsps corn flour, 0.75 tbsp garlic, 2 servings oil, 1 small onion, 0.25 tsp chili powder, 0.25 tsp pepper powder, 0.5 tbsp soya sauce, 0.75 tbsp soya sauce, 2 servings spring onions, 0.5 tsp sugar, 0.5 tbsp chilli sauce, 1 tsp chilli sauce, 0.75 tsp vinegar','Find Complete instructions on swasthi''s "Recipe"s',160,160,0);
INSERT INTO "Recipe" VALUES(115,'Roma Tomato Bruschetta','https://img.spoonacular.com/recipes/658753-556x370.jpg','2 tablespoons balsamic vinegar, 4 tablespoons extra virgin olive oil, 1 loaf bread, 10 leaves basil, 1 clove garlic, 4 servings bell pepper, 4 servings salt, 4 medium tomatoes','Slice the bread on a bias about 1/2 inch thick. We need about 10-12 slices.Take 2 tablespoons of extra virgin olive oil and add salt and pepper (about 1/3 teaspoon each - as per taste).Brush this on both sides of the bread.Place these slices on a sheet pan and bake for about 3-4 minutes in a 400 degree preheated oven till golden brown. Once one side is done, turn over the crostini to the other side to crisp that as well.When the crostini are hot out the oven, rub a garlic clove on them.Chop the tomatoes.Chiffonade the basil and add to the tomatoes.Add salt, pepper, olive oil and balsamic vinegar and let it rest for a few minutes.Put a generous amount of tomato on the crostini and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(116,'Chocolate Chip Peanut Butter Banana Cookies','https://img.spoonacular.com/recipes/638940-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 2  bananas, 0.5 cup brown sugar, 1 Tbs butter, 1 cup chocolate chips, 0.5 teaspoon cinnamon, 0.5 cup creamy peanut butter, 1  egg, 1.25 cup flour, 1.25 cup granulated sugar, 0.5 teaspoon salt, 1 teaspoon vanilla','Preheat oven to 350 degrees.In a large bowl, mash 2 ripened bananas.Add butter, peanut butter, both sugars, egg, vanilla and stir.In a separate bowl, whisk together flour, baking powder, baking soda, cinnamon and salt.Add dry ingredients to banana mixture and stir until combined (do not stir this to death!)Add mini chocolate chips and briefly stir.Drop by large spoonful onto parchment lined baking sheet.In a small bowl, pour 1/4 cup of sugar and 1/2 tsp of cinnamon and stir.  Sprinkle over unbaked cookies.Bake for 10-12 minutes or until slightly golden brown.  My oven is hot, and only needs 10 minutes.  ',45,45,0);
INSERT INTO "Recipe" VALUES(117,'Wholemeal Steam Bun','https://img.spoonacular.com/recipes/665306-556x370.jpg','1 tbsp double action baking powder, 1 tbsp yeast, 400 g pau flour, 0.5 teaspoon salt, 3 tbsp shortening, 1 tablespoon sugar, 250 g water, 100 g wholemeal flour','METHOD:1.Mix all the ingredients A together and knead into smooth and elastic dough.2.Cover with a piece of wet cloth and leave to prove until double its size.3.Sift B top of the dough and knead well to distribute the baking powder until the dough is smooth again.4.Cover and allow dough to rest for 15 minutes before shaping.Meat Fillings :boiled eggs (shelled and cut into )Marinade for meat : 30 minutesShredded chicken/pork2 tbsp. BBQ saucewaterFilling:1.Heat oil in a pan adds in marinated meat and stirs fry till aromatic, adds in some water and cooks for 5 minutes until soft. Taste and dish up and leave to cool and chill in the fridge for 3 hours.2.Divide dough 12 portions and shape balls.3.Flatten, roll into a round shape and add 1 tbsp of filling and pleat the top into a Pau/Bun.4.Line Pau/Bun with a piece of white paper and let it prove again for another 15 minutes.5.Steam Pau/Bun with high heat for about 15 minutes or until the Pau/Bun is cooked.6.Serve hot.',45,45,0);
INSERT INTO "Recipe" VALUES(118,'Quick and Easy Caprese Salad','https://img.spoonacular.com/recipes/657537-556x370.jpg','4 servings balsamic vinegar, 0.25 cup basil leaves, 8 ounces mozzarella cheese, 4 servings olive oil, 4 servings bell pepper, 0.5 tsp salt, 4  tomatoes','Slice mozzarella and tomatoes into 1/4 inch slices and arrange on platterSprinkle basil leaves over allDrizzle with oil and vinegarSalt and pepper to taste',45,45,0);
INSERT INTO "Recipe" VALUES(119,'Creamy Potato Salad with Cashew Dressing and Fresh Basil','https://img.spoonacular.com/recipes/794352-556x370.jpg','3 tablespoons almond milk, 700 g baby potatoes, 0.75 cup basil leaves, 1.5 tablespoons chives, 1 tablespoon mint leaves, 2 tablespoons parsley, 0.5 cup peas, 6 servings ground pepper, 1 teaspoon dijon honey mustard, 3  juice of lemon, 0.25  kalamata olives, 3 tablespoons nutritional yeast, 0.25 cup olive oil, 0.75 cup cashews, 1 teaspoon rice vinegar, 1.5 teaspoons sea salt, 1 teaspoon dijon grain mustard','Bring the potatoes to a boil in a large pot of water. Reduce the heat to medium and cook until they are fork tender  about 10 to 12 minutes. Do not overcook. Drain well and let cool for 10 minutes or longer before transferring to a large bowl along with the peas, basil leaves and olives if using.To make the dressing, combine all the ingredients in a small blender or food processor and pulse into smooth. If it is too thick, add a bit more olive oil or almond milk. Taste for seasoning and adjust nutritional yeast, salt and pepper to taste. Toss the potatoes with the dressing and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(120,'Shortbread Lemon Cookies','https://img.spoonacular.com/recipes/659887-556x370.jpg','1.5 sticks butter, 2  eggs, 1 tablespoon lemon zest, 2 cups almond flour, 0.5 cup caster sugar, 1.25 cups flour, 1 tablespoon lemon juice, 4 small lemons, 36 servings powdered sugar',replace('Beat butter with one egg.\nAdd almond flour, sugar, all-purpose flour, and lemon juice, and mix with the mixer on the lowest setting.\nShape the dough into two rolls, about 2 inches each in diameter, and put in the refrigerator for 3 hours.\nPreheat oven to 350.\nSlice each log into cookies, about 1/8 inch thick, and place on a lightly greased baking sheet.\nBeat the second egg and brush the top of each cookie with it.\nPlace one lemon slice on top of each cookie.\nSprinkle with sugar and bake for 12-15 minutes.\nIf you like the tops of the cookies browned, put them under the broiler the last 5 minutes of baking.\nCool and optionally sprinkle with powdered sugar (optional).','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(121,'Chicken Noodle Casserole Dish','https://img.spoonacular.com/recipes/982376-556x370.jpg','0.5 c bread crumbs, 2 tbsp butter, 1 c carrots, 3 c chicken broth, 16 oz egg noodles, 0.5 c flour, 1 c corn, 0.5 tsp garlic powder, 1 tsp seasoning, 2 c milk, 1 c parmesan, 0.6666667 c parmesan cheese, 1 c peas, 6 servings salt and pepper, 1 lb chicken, 0.5 c mozzarella, 1 c cream, 1  onion',replace('Preheat oven to 350 degrees\nSautee onion in 2 tbsp olive oil\nWhen onion is soft, add chicken broth\nAdd frozen veggies\nBring to a boil then reduce heat and simmer 2 min\nSlowly whisk in flour\nSlowly whisk in milk\nAdd sour cream, cheeses and chicken\nMix in noodles\nPour into a 13x9 casserole dish coated with butter\nMix rest of parmesan, bread crumbs and butter in a separate bowl\nSprinkle topping on top of casserole\nBake for 25 minutes until top is golden\nEnjoy!','\n',chr(10)),35,35,0);
INSERT INTO "Recipe" VALUES(122,'Walnut Pesto','https://img.spoonacular.com/recipes/664932-556x370.jpg','2 cups basil leaves, 2 cloves garlic, 1 cup olive oil, 3 tablespoons parmesan cheese, 1 pinch sea salt, 3 tablespoons walnuts','Combine walnuts, basil, garlic, Parmesan and salt in food processor and process to a coarse puree.With the machine running, slowly add the oil. Scrape down the sides and process again. Store pesto in an airtight jar, preferably opaque to keep out the light. Keep pesto covered with a layer of oil to prevent the surface from browning. Store in refrigerator.',45,45,0);
INSERT INTO "Recipe" VALUES(123,'Mediterranean eggplants','https://img.spoonacular.com/recipes/651407-556x370.jpg','50 g almonds, 4 Tbs bread crumbs, 1  egg, 4 small eggplants, 50 g feta cheese, 4 servings dill, 100 g mozzarella cheese, 2 tablespoons olive oil, 0.5 tsp pepper, 350 g sausage without the casing','Wash eggplants, cut the stems and halve lengthwise. Scoop out the middle.In a bowl mix and combine sausage meat, egg, feta cheese, mozzarella, almonds and pepper.With a spoon, stuff the eggplants.Sprinkle with breadcrumbs (about  tablespoon on each eggplant) and olive oil.Place the eggplants on a baking sheet lined with parchment paper and bake in the oven for 25 minutes on 230C.Serve hot, sprinkled with fresh, chopped dill, chives or basil.',45,45,0);
INSERT INTO "Recipe" VALUES(124,'Citrus Arugula Salad with Seared Scallops','https://img.spoonacular.com/recipes/639512-556x370.png','2 cups arugula, 1  cara cars orange, 2  radish, 0.5  persian cucumber, 1  green onion, 2 servings salt, 8  scallops',replace('First, you''ll want to thinly slice the radishes and cucumber; and, dice the green onion.\nIn a bowl, squeeze half of the Cara Cara orange and pulp, add salt and whisk together. Add in the radish and cucumber slices, arugula and toss together.\nFor the scallops: heat oil in a high heat. Place the scallops flat-side down in the hot pan. Don''t overcrowd the pan, or the pan won''t stay hot enough to give the scallops a good sear. If you have a lot of scallops, it''s better to work in batches.\nOnce you''ve placed the scallops in the pan, don''t touch them. (Let them do their thing!) If you give in to the temptation to move the scallops around the pan, all you''ll be doing is preventing them from forming the nice brown crust that you want. Because of variations in scallop thickness, pan temperatures and so on, it''s not easy to pinpoint an exact cooking time. But after a couple of minutes, it''s OK to peek underneath. If you see a nice, caramel-colored crust on the underside, they''re ready to flip.\nPlate your salad and place 4 scallops on top. Scallops start to turn rubbery if you wait too long to serve them, so get them on the plate right away. And be sure to serve them with the beautiful caramel-colored crust facing up.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(125,'Pasta With Butternut Parmesan Sauce @ Dw Magazine.Com','https://img.spoonacular.com/recipes/654897-556x370.jpg','1 pound butternut squash weighing, 8 ounces bow-tie pasta, 1 tablespoon olive oil, 1 cup shallots, 0.5 cup parmesan cheese, 0.5 cup heavy cream, 0.125 teaspoon nutmeg, 1 tablespoon parsley, 2 teaspoons lemon juice, 4 servings salt and pepper, 4 servings water to the sauce',replace('METHOD\nPreheat the oven to 350F. \n\nCut the butternut squash lengthwise in half* and scoop out the guts and seeds and discard them . \nPour 1/4 cup of water into a pyrex or ceramic baking dish and place the butternut squash halves cut side down. Bake for 40 minutes or until a fork easily pierces the squash. \nAllow to cool for 10 minutes. \nScoop out the squash flesh from the skins and pure with a blender (work in batches or place in a bowl and use a hand blender). \nDiscard the skins.\nFill a pot with water\n and salt (1 tablespoon of salt for every 2 quarts of water). Set over high heat to bring to a hard boil.\n Add the pasta and cook at a hard boil, uncovered until al dente.\nWhile the pasta is cooking, pour the olive oil into a wide skillet on medium heat.\n Add the shallots and saut until soft and translucent, about 5 minutes. \nAdd the butternut squash pure and c\nook for about a minute, mixing it in with the shallots. Add the cream, a tablespoon at a time, slowly stirring it in to incorporate and to avoid lumps. \nStir in the Parmesan. \nAdd the nutmeg, salt and pepper. \nAdd water (or chicken stock) to thin to the consistency you want. \nTake off heat and add the parsley and lemon juice. Cover the pan to keep warm.\nCheck pasta. When ready (al dente) drain and plate. \nPour the sauce over the pasta. \nGarnish with a little extra parsley and Parmesan. Serve immediately.\nBe careful when you cut the squash, winter squash are hard! The best way to do it safely is to slice a bit off of both ends so that you can stand the squash upright without it rolling. Then cut down the middle.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(126,'Turkey Pot Pie With Cornbread Crust','https://img.spoonacular.com/recipes/664058-556x370.jpg','1 tablespoon baking powder, 2 tablespoons canola oil, 2 large carrots, 3 stalks celery, 2 cups chicken stock, 1 large egg, 0.25 cup flour, 0.75 cup flour, 2 cloves garlic, 0.5 cup green beans, 2 teaspoons ground sage, 2 teaspoons ground thyme, 0.75 cup milk, 2 tablespoons olive oil, 1 medium onion, 5 servings cracked pepper, 0.5 teaspoon salt, 1.5 tablespoons sugar, 3 cups turkey, 0.75 cup cornmeal','To make filling: Preheat the oven to 400F. Coat a pie plate (or any baking dish you like) generously with nonstick cooking spray. Heat olive oil in a large pan over medium heat. Add onion, carrots, celery, and green beans, and saut for about 10 minutes, until tender. Add garlic and stir constantly for 30 seconds. Sprinkle the flour into the pan and stir until it coats the vegetables, about 30 seconds. Slowly stir in 2 cups of hTo make crust: In a large bowl, whisk the cornmeal, flour, baking powder, sugar and salt. Stir milk, egg and canola oil until well combined in a separate bowl. Stir wet ingredients into dry ingredients. Spoon the batter evenly over the filling. Bake until the top is golden brown, about 22 to 25 minutes. Let cool for at least 15 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(127,'Siew Mai',NULL,'40  wonton wrappers, 700 g fatty pork, 2 tablespoons corn starch, 1 teaspoon salt, 1 teaspoon ground pepper, 0.5 teaspoon sugar, 2 tablespoons shaoxing huatiao wine, 1 teaspoon worcestershire sauce, 2 tablespoons sesame oil, 80 g water chestnuts, 4 large mushrooms, 400 g shrimp, 1 small carrot, 200 g glutinous rice, 40 g shallots, 1 small piece ginger, 4 tablespoons cooking oil, 30 g shrimps, 20 g scallops, 5 pieces mushrooms, 3 tablespoons water, 1 tablespoon soy sauce, 0.5 teaspoon salt, 1 tablespoon oyster sauce, 40 servings ground pepper, 2 sticks lap cheong, 2 sticks lap cheong',replace('To prepare the pork filling -\nMince 700g of pork and place them in a large mixing bowl. Add 2 tablespoons of corn starch, 1 teaspoon of salt, 1 teaspoon of ground white pepper,  1/2 teaspoon of sugar, 1 teaspoon of Maggie Seasoning Sauce or Worcestershire sauce, 2 tablespoons of Shaoxing Huatiao wine and 2 tablespoons of sesame oil.\nRoughly chop 80g of water chestnuts into fine pieces. I used canned ones.\nChop 4 large Chinese mushrooms into fine pieces too.\nAdd the water chestnuts and mushrooms to the pork mixture. Mix all the ingredients well to combine.\nFinely dice a small carrot. These will be placed on top each pork siew mai to garnish. Use salmon roe or salted egg yolk if preferred.\nSet aside the pork mixture and the diced carrots till ready to wrap dumplings.\n\nTo make the glutinous rice filling -\nSoak 2 lap cheongs (Chinese sausages) in boiling water until the skin is separated from the meat. Remove the skin from the lap cheong and cut them into small dices.\nIn a large sauce pan over medium-high heat, pan fry the lap cheong dices until they are golden but not brown. They should be a lovely red.\nFollow the instructions at Glutinous Rice in Lotus Leaf (http://cooking.storyofbing.com/2010/07/glutinous-rice-in-lotus-leaf-2/) and prepare the glutinous rice. Once the rice and other ingredients are stir fried till fragrant, add the pieces of fried lap cheong and set aside to cool.\n\nPrepare the ingredients necessary for the wrapping of the dumplings.\nStart by placing a sheet of wonton wrapper on a flat surface. Place a small teaspoon of filling in the centre of the wonton wrapper.\nDap finger in some water and gently wet the sides of the wonton wrapper.\nGather the wonton wrapper with the filling in the palm of hand and squeeze gently while folding the wrapper skin upwards and against the filling so that the wonton wrapper wraps the filling tightly.\nMake sure the dumplings are tight. Otherwise they may fall apart while being steamed. Use more water to seal them if necessary.\nPlace a large shrimp on the top of each pork siew mai.\nAdd a few pieces of chopped carrot or salmon roe or salted egg yolk to add a fresh colour to the dumpling.\nDo the same for the glutinous rice siew mai, adding more lap cheong pieces on the top if preferred.\nPlace the dumplings in a steamer lined with baking paper. Cut some holes through the baking paper to let the steam through.\nPlace the steamer over boiling water for 14-15 minutes or until the filling is cooked.\nServe hot.\nUncooked dumplings may be frozen and steamed at a later date. Dust some flour in a container so that the dumplings wont stick to it.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(128,'Pasta with Raw Tomato & Lemon Infused Olive Oil','https://img.spoonacular.com/recipes/654936-556x370.jpg','250 ml extra virgin olive oil, 3  lemon zest, 1 kilo canned tomatoes, 8 servings salt and chili flakes, 1 handful aged pecorino',replace('A day or so before you would like to use the sauce combine lemon zest and oil in a bowl, cover and allow to sit out.\nThe next day, strain out zest from oil and drizzle slowly into passed tomatoes as you constantly stir.  When all the oil is incorporated, season with salt and pepper.  Allow the sauce to sit once more for a bit to allow the flavors to come together.\nTo serve: Give the sauce a good stir as it will have surely separated and toss with hot thin pasta and a sprinkle of grated aged pecorino (sheep''s milk cheese) or parmesan.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(129,'Cajun Potato Wedges','https://img.spoonacular.com/recipes/636733-556x370.jpg','1 tsp cayenne pepper, 1 tsp garlic powder, 1 tsp seasoning, 3 tbsp olive oil, 1 tsp onion powder, 2 tsp paprika, 0.5 tsp pepper, 2 large russet potatoes, 0.75 tsp salt','Preheat oven to 425 degrees Fahrenheit. Slice potatoes into  inch thick wedges that are half the length of the potato.Make spice mixture: combine all spices and mix together in a small bowl.Spray cookie sheet with olive oil cooking spray. Place potatoes on cookie sheet. Toss with olive oil. Sprinkle spice mixture over potatoes and toss.Cook for 25 minutes. Flip over and cook for another 5 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(130,'Avocado Chicken Salad','https://img.spoonacular.com/recipes/633132-556x370.jpg','2  avocados, 10 g cherry tomatoes, 50 ml extra virgin olive oil, 2  limes, 2 servings mayonnaise, 1 dash pepper, 100 g salad, 150 g chicken breast','Season chicken breast with a little salt and pepper then place in a pot of boiling water until cooked. Leave to cool and cut into cubes, set aside.Cut avocados into cubes.Place mixed salad in a large bowl and add olive oil and lime juice, toss well and divide mixed salad into two serving bowls.Place avocados, chicken meat and cherry tomatoes evenly on top of salad.Drizzle mayonaise  and a dash of black pepper over salad and serve.',45,45,2);
INSERT INTO "Recipe" VALUES(131,'Black Bean Feijoada','https://img.spoonacular.com/recipes/635066-556x370.jpg','15 oz black beans, 0.25 teaspoon cayenne pepper or, 2 tablespoons extra virgin olive oil, 2 tablespoons ginger, 0.5 teaspoon ground cumin, 2 medium onions, 2 tablespoons ume plum vinegar, 3  peppers, 1 teaspoon sea salt','Heat oil, saute onions until translucent. Add cent. Add remaining ingredients, saute for 2 minutes, and set aside. Prepare topping. and sea salt. Simmer for 5 more minutes.Partially mash beans for a thick bean sauce consistency.',45,45,0);
INSERT INTO "Recipe" VALUES(132,'Chocolatey Overnight Oats with Strawberries','https://img.spoonacular.com/recipes/639303-556x370.jpg','1 tsp agave nectar, 0.33333334 cup almond milk, 0.5 Tbs chia seeds, 1 Tbs cocoa powder, 0.5 cup non-fat greek yogurt, 0.33333334 cup oatmeal, 3 large strawberries','Mix all the ingredients, except for the strawberries.Place a bit of the oatmeal batter into a jar or other airtight container. Add slices of strawberries on top. Add another layer of oatmeal batter and strawberries. Top with the remaining oatmeal batter.Put it in the refrigerator overnight.Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(133,'Grilled Portabella and Poblano Tacos','https://img.spoonacular.com/recipes/645812-556x370.jpg','1 tbsp canola oil, 0.5 tsp chipotle powder, 0.25 cup cilantro, 4 servings cilantro sprigs, 8 small corn tortillas, 0.5 head garlic, 4 servings guacamole, 1 tsp lime juice, 4 servings lime wedges, 0.25 cup olive oil, 1  poblano chile, 6  portabella mushrooms, 1 large onion, 2  roma tomatoes, 1 tablespoon salt, 4 servings salt and pepper, 4 servings cheddar cheese','Preheat a lightly oiled grill on medium-high heat.While the grill is heating up, prepare the pico de gallo. In a small mixing bowl, combine tomatoes, onion, cilantro, garlic, salt and lime juice. Set aside.Next, prepare the grilled portabella filling. Remove the stems from the portabellas, and discard. Using a spoon, scrape out the dark gills from the underside of the mushroom caps.Lightly brush the portabellas and the onions on both sides with canola oil, and sprinkle generously with salt and pepper.Arrange the mushrooms, onion, and poblano on the hot grill, and cook for 5-6 minutes per side or until the mushrooms are softened and the onion is lightly charred. Remove from heat and transfer to a cutting board.Remove the stem and seeds from the poblano, and discard. Cut the poblano and the portabellas into thin strips, and roughly chop the onion. Transfer to a mixing bowl and toss with lime juice and chipotle powder until well coated.To assemble, arrange 2 tortillas per plate, and divide the mushroom filling evenly between them.  Serve with pico de gallo and bowls of the different toppings so that everyone can garnish their tacos as they please.',45,45,0);
INSERT INTO "Recipe" VALUES(134,'Greek Yogurt Chicken Salad','https://img.spoonacular.com/recipes/645384-556x370.jpg','0.5 cup cashews, 1 pound chicken breasts, 0.33333334 cup craisins, 2 teaspoon dijon mustard, 4 servings garlic powder, 0.5 cup greek yogurt, 4 servings salt','Start by cooking some chicken breasts. I like boiling them in chicken broth or stock, but feel free to boil in water, too. Boiling the chicken in broth, however, will give it significantly more flavor. Bring the chicken broth/stock to a boil and put in whole chicken breasts. Cook until no pink remains. Depending on the size of the chicken breasts, this could take anywhere from 15 - 20 minutes.While the chicken is boiling, put together your sauce. Whisk together greek yogurt, dijon mustard, and garlic powder together until well mixed. Add in salt and pepper, to taste.Next, stir in dried cranberries or raisins and cashews. If you''re worried about the cashews getting too soft, you could add them right before serving!After the chicken is done boiling, I like to let it rest for about 5 minutes. This ensures that the juice stays in the chicken instead of spilling out when you cut it!Dice up the chicken and mix it into the sauce. Serve.',30,30,0);
INSERT INTO "Recipe" VALUES(135,'Homemade Broccoli Cheddar Soup','https://img.spoonacular.com/recipes/646930-556x370.jpg','8 cups broccoli, 1  shallot, 1  juice of lemon, 3 cups vegetable broth, 1 teaspoon pepper, 1 teaspoon salt, 1 small onion, 1 cup yogurt, 3 cups yukon gold potatoes, 1 cup parsley, 1  bay leaf, 0.5 cup olive oil, 1 cup almond milk, 1.5 cups cheddar cheese',replace('In your soup pot, saute over med-high heat: 2 Tbsp of your olive oil with the shallot, onion and jalapeno. When cooked lightly, add in lemon juice, veggie broth, remaining oil, salt and pepper. Reduce heat to medium. Add Potatoes and bring broth to a boil. Cook until potatoes are tender.\nAdd chopped Broccoli (florets and steams). Remember to leave out a few florets for later use though.Cover with lid, when broccoli is tender, turn heat off.\nTransfer contents of pot into a large mixing bowl. Allow to cool slightly. Add to the bowl the fresh parsley, Chobani and almond milk. Fold new ingredients into the hot soup mixture.\nIn batches, puree the soup in a food-processor (maybe someday soon, a Vitamix!) style blender. Soup should be smooth-no lumps or chunks. In the soup pot, add the broccoli florets, a dash of veggie broth and saute covered for about a minute until tender. Add the pureed soup back into the soup pot. Add a bay leaf and a few pinches of chopped basil (optional). Simmer uncovered for at least twenty minutes to cook out all the air bubbles. Stir constantly for the first few minutes. Remove the bay leaf before serving or storing.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(136,'Butterscotch Pie','https://img.spoonacular.com/recipes/636620-556x370.jpg','8 servings the pie crust, 1.5 cups sleeve of graham crackers, 5 tablespoons butter, 0.25 cup sugar, 3 tablespoons butter, 0.5 cup brown sugar or, 1 cup heavy cream, 1 cup percent milk, 0.25 teaspoon salt, 0.25 cup cornstarch, 0.25 cup water, 1 teaspoon vanilla, 2 teaspoons scotch whiskey, 8 servings the pie topping, 1.5 cups heavy whipping cream, 0.5 teaspoon vanilla',replace('First, the crust. Place the graham crackers in a Ziploc bag, and with a rolling pin, crush them. My guy always comes around when it''s time to do this, and does it for me. I think he likes it.\nIn a medium bowl, mix the graham cracker crumbs with the sugar.\nAdd the melted butter, and mix well.\nPress the graham cracker mixture into a pie plate, and refrigerate for about a half hour.\nNow, the filling! Melt the butter in a medium saucepan over low heat.\nStir in the brown sugar (and molasses, if you''re using it). Keep the heat low, and stir until the brown sugar is all melted and bubbly.\nAdd 1/2 cup of the heavy cream, and stir until the brown sugar and butter are dissolved.\nStir in the remaining 1/2 cup of the heavy cream, all of the milk, and the salt.\nRemove from heat, and let cool until lukewarm. I find this only takes about 10 minutes.\nMix together the cornstarch and water, and pour it into the pudding mixture.\nReheat over medium high heat, stirring constantly, until the mixture starts to thicken. It''ll thicken fast with all that corn starch!\nTurn heat to low, and continue to stir vigorously while keeping it at a good simmer for about a minute.\nRemove from heat, and stir in the whiskey and vanilla. Whiskey wasn''t in my original Butterscotch Pudding "Recipe", but I love the addition for this pie. Gives it a little extra somethin'' somethin''.\nPour the pudding mixture into the chilled pie crust.\nCover with plastic wrap and chill for at least two hours.\nReady for the topping? Whip the 1 1/2 cups chilled heavy whipping cream with the wire whisk attachment on your stand mixer (you can do this by hand, but it would be quite the workout).\nAdd the sugar and vanilla to the cream while it''s whipping. It''s ready when soft peaks form. Yum.\nI''m stating the obvious, but remove the pie from the fridge and take off the plastic wrap.\nPile on the whipping cream. I like to spread it almost to the edges, but not quite - gotta give folks a glimpse of the actual pie yumminess!\nIf you want, garnish with a little shaved chocolate. I just took the carrot peeler to a Hershey bar.\nOr leave it plain. Either way!\nEnjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(137,'All American Sloppy Joes','https://img.spoonacular.com/recipes/632071-556x370.jpg','100 grams american barbecue sauce, 4  burger buns, 2  garlic cloves, 0.5  bell pepper, 450 grams ground beef, 1 teaspoon hot sauce, 1 tablespoon olive oil, 4 servings salt and pepper, 2  shallots, 180 grams tomato sauce, 0.6666667 tablespoon worcestershire sauce','Heat the olive oil in a large skillet. Add in minced garlic, shallots, and green bell pepper.  Stir until fragrant and tender, about 3 minutes. Season it with salt and black pepper.Add the ground beef to the vegetables. Stir and cook about 5 minutes, until the meat is no longer pink and fully cooked. Add tomato sauce, barbecue sauce, Worcestershire, and hot sauce into the skillet. Stir to combine. Simmer until thickened.To serve, spoon and pile sloppy meat onto the toasted, buttered bun bottoms and cover with bun tops with your favourite side dish or pickles.',45,45,0);
INSERT INTO "Recipe" VALUES(138,'Pesto Zucchini "Spaghetti','https://img.spoonacular.com/recipes/655853-556x370.jpg','4 medium zucchini, 1 pinch salt, 6 slices bacon, 0.5 cup green onions, 2 cups broccoli florets, 2 T basil pesto, 4 servings romano cheese',replace('Place zucchini strips in a colander over a bowl or in the sink. Sprinkle zucchini with salt and toss to combine. Let the zucchini sit for 15 minutes while the salt extracts the moisture. Drain excess water, squeezing zucchini, if necessary.\nMeanwhile, cook bacon in a skillet over medium heat until crisp, turning frequently. Remove bacon to a stack of paper towels to drain. Crumble bacon. Remove all but 2 T of bacon drippings from the pan.\nReturn the pan to medium heat. Add the green onions and broccoli, stirring frequently for about 3-5 minutes or until crisp-tender. Add zucchini and 2 T of pesto, tossing to combine all ingredients. Taste and add more pesto, if needed. The mixture only needs to warm up, so 2-3 minutes of cooking ought to do it.\nServe with bacon crumbles and freshly grated Parmesan cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(139,'Croissants With Sesame Seeds (Kifli)','https://img.spoonacular.com/recipes/640907-556x370.jpg','2 cups milk, 1 package active yeast, 6 teaspoons sugar, 2 tablespoons flour, 1 tablespoon baking powder, 2 teaspoons salt, 0.5 cup vegetable oil, 4  eggs, 6 cups flour, 1 stick margarine, 50 servings sesame seeds',replace('In a large, deep mixing bowl pour in lukewarm milk.\nStir in the sugar, 2 tablespoons of flour, and the yeast.\nLet stand for ten minutes.\nAdd in the baking powder, salt, vegetable oil, egg whites, and 6 cups of flour.\nStir with a wooden spoon until the mixture is well incorporated, you may need to get your hands in there towards the end, and then bring the dough to a lightly floured surface.\nKnead the dough for 10 minutes.\nPut the dough in a large bowl, cover it, and let it stand for one hour.\nPreheat oven at 375.\nBring the dough back to your working area and knead it again for another 5 minutes. You want to make sure that all those air bubbles are out.\nForm the dough into a log and cut it into 5 or 6 equal pieces.\nTake one piece (cover the rest with a kitchen towel), and roll it out to a size as big as a medium pizza.\nWith a knife, cut the rolled out dough into 8 equal slices.\nBeginning at the widest point of the slice start rolling it towards the narrowest point.\nPlace the croissants on a lightly greased baking sheet.\nContinue to do this with the rest of the dough.\nIn a small mixing bowl, whisk the 4 egg yolks.\nBrush each croissant with the egg yolk.\nTop each croissant with sesame seeds.\nPut 4 or 5 small pieces of margarine throughout the baking sheet.\nBake for  15 to 20 minutes, or until golden brown.\nCover with a kitchen towel while they are cooling.\nServe immediately or store in an airtight container.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(140,'Cinnamon Sugar Fried Apples','https://img.spoonacular.com/recipes/639487-556x370.jpg','150 g all purpose flour, 4  apples, 0.33333334 cup brown sugar, 1 Tbsp cinnamon, 2  eggs, 2 Tbsp granulated sugar, 0.5 Tsp lemon zest, 250 ml milk, 16 servings oil, 1 pinch salt, 1 Tbsp butter','Mix all ingredients for batter (flour, salt, granulated sugar, milk, lightly beaten eggs, lemon zest, and melted unsalted butter) in a bowl until smooth. Cover with plastic wrap and set aside to rest for 30 minutes.While batter is resting core and slice apples 1 cm thick. Set aside. Start heating oil.Dip apple slices in batter, then fry until golden on each side. Drain the apples well on double lined paper towels. Then sprinkle the cinnamon sugar (brown sugar and cinnamon combined) on the slices. Serve immediately.',60,60,0);
INSERT INTO "Recipe" VALUES(141,'Nutella Crepes and Ice Cream','https://img.spoonacular.com/recipes/716272-556x370.jpg','6 servings strawberries/ bananas, 1 tablespoon butter, 1.25 cup butter milk, 0.5 teaspoon cinnamon, 2  eggs, 1 cup flour, 6 servings ice cream, 6 servings nutella, 6 servings oil, 0.25 cup sugar, 1  tea spoon of vanilla extract','In a dry clean bowl, mix together the dry ingredients (flour, sugar, cinnamon)In another bowl, break the eggs and whisk properly, add the milk, butter (or oil), vanilla extract and whisk properly.Add the wet ingredients to the dry ingredients and whisk, ensuring that there are no lumps (Tip: you can use a blender in order to prevent lumps , and if normal whisk is used and you notice lumps you can sieve out the lumps)Grease (with oil or butter) a crepe pan or a big frying panSet to medium to low heatPour batter in the middle of pan and move pan around to ensure that the batter covers the entire pan ( the idea is to make the crepe as thin as possible so avoid pouring a lot of batter into the pan at once)Fry each side of the crepe for 3-4 minutesScoop Nutella into a bowl and microwave for 45 secs to soften it up, so that it doesn’t rip the crepesSlice bananas or strawberrySpread Nutella on one half of the crepe, put the strawberries/bananas and fold over',45,45,0);
INSERT INTO "Recipe" VALUES(142,'Sex in a glass','https://img.spoonacular.com/recipes/659782-556x370.jpg','6 servings caramel dessert topping, 2 cups cream, 1 cup dulce de leche ice cream, 3 tablespoons espresso, 1 cup sugar, 1 tablespoon sugar, 0.25 cup water, 3 cups water','To make the espresso bring water to a boil and then pour it over the espresso. Set aside to cool. When cooled add the melted ice creamFor the caramel-cream: Place 1 cup sugar and water in a 2 quart pot with a glass lid. Cover and bring to a boil over medium-high heat. Do not remove lid or stir the sugar mixture or it will begin to crystallize. The glass lid is a convenient way of watching the sugar so you know when it changes color as well as keeping the steam inside and preventing crystallization.When the sugar begins to look caramelized watch it carefully and remove from heat when it reaches deep amber color. Be very careful as the sugar is extremely hot and also watch that it doesn''t burn. It can go from amber to burnt very quickly.Immediately off the heat pour the one cup cream into the caramel. The caramel will stiffen, sizzle and splatter so be careful. Return to a medium heat and cook until the caramel melts together with the cream.Pour the caramel cream into the coffee and refrigerate until cold.To assemble, fill a glass with ice, scoop two ice cream scoops into each glass.Pour the iced espresso cream over and top with sweetened whipped cream (the other cup of cream whipped with 1 tablespoon sugar).Garnish with caramel syrup and serve chilled.',45,45,0);
INSERT INTO "Recipe" VALUES(143,'Bridget Jones''s Shepherd''s Pie','https://img.spoonacular.com/recipes/636096-556x370.jpg','2  onions, 2 tablespoons olive oil, 600 grams lamb, 2 tablespoons flour, 4 servings thyme, 4 servings rosemary, 1 small tomatoes, 100 milliliters lamb stock, 4 servings salt and pepper, 700 grams potatoes, 55 milliliters milk, 75 grams butter, 1  egg yolk',replace('Preheat the oven to 180 C.\nIn a large frying pan, heat a little olive oil and fry the chopped onion and garlic.\nAdd the mince, stirring, until browned all over.\nWhile the meat is frying, break up any lumps with the back of the spoon.\nAdd the flour (this helps to thicken the juices) and stir.\nMix well and add the thyme and the rosemary and stir.\nAdd the chopped tomatoes and pour the stock mixture.\nAdd a pinch of salt and freshly ground black pepper and let it simmer for about 5 minutes.\nFor the mash, boil the potatoes, then drain them in a sieve and place into a clean bowl.\nAdd the milk, butter and egg yolk, and mash together.\nSeason with salt and freshly ground black pepper.\nPour the meat into an ovenproof dish and spread the mash on top, smooth over and mark with a spatula.\nPut the dish into the oven and cook until the surface is bubbling and golden-brown.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(144,'Hot Cross Buns','https://img.spoonacular.com/recipes/647442-556x370.jpg','1 teaspoon baking powder, 0.5 teaspoon baking soda, 0.5 teaspoon cinnamon, 2 tablespoons flour, 0.25 teaspoon nutmeg, 0.5 cup raisins, 1 teaspoon salt, 4 tablespoons shortening, 0.75 cup milk, 0.25 cup sugar','Sift flour once, measure, add baking soda, baking powder, salt, sugar and spices, and sift again. Cut in shortening. Add raisins. Add enough sour milk to make a stiff dough.  Turn onto floured board. Knead slightly. Roll 1/2 inch thick. Cut with 2 inch cutter. Place close together in shallow pan.With sharp knife, cut a cross in each roll. Brush with a solution of milk and sugar.Bake in hot 475 degrees for 20 minutes. Brush again with sugar and milk solution. Fill cross with plain frosting. Serve hot. Makes 12 buns.',45,45,0);
INSERT INTO "Recipe" VALUES(145,'Moroccan Lemon Shish Kebabs','https://img.spoonacular.com/recipes/652433-556x370.jpg','1 pound chicken breast fillets, 8 servings moroccan lemon marinade, 1 teaspoon parsley, 1 teaspoon rosemary leaves, 2 teaspoons thyme leaves, 2 cloves garlic, 1 teaspoon peppercorns, 1  juice of lemon, 2 teaspoons olive oil',replace('The chicken breast fillets trimmed of fat, cut into 1" cubes\nFor Moroccan lemon marinade\nPut everything in a bowl\nAdd this Marinated chicken cubes, mix well, cover with Plastic Wrap and let stand at least 1/2 hour before use ... I like to leave more time in the fridge\nThe time for rest, place the bamboo skewers or metal rods in a tray with water (to cover only), that is to avoid burning\nThread the meat on each rod are more or less as 4 pieces of meat\nShish Kebbab cooking on the grill, skillet or the oven ... I like the first option, you know the smell of charcoal, wood ...\nOnce the Shish Kebab cooked, serve immediately on a bed of Rice, Mediterranean Cous Cous, etc. ... or only with Pita Bread and ready','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(146,'Spanish Meatballs In Tomato Sauce','https://img.spoonacular.com/recipes/660868-556x370.jpg','1  bay leaf, 2 cloves garlic, 1 pound ground beef, 1 cup olive oil, 2 tablespoons olive oil, 0.5 cup onion, 20 servings half an onion, 2 tablespoons parsley, 1 pinch pimenton de la vera, 20 servings salt and pepper, 1 teaspoon sugar, 600 g tomatoes, 4 slices sandwich bread, 1 large egg','Start by making the tomato sauce.Finely chop 1 onion.Peel 600g of tomatoes with a serrated peeler. Chop the peeled tomatoes into small pieces.Add 2 tablespoons of olive oil in a sauce pan. Add the chopped onions.Add a pinch of Pimenton de la Vera (Dulce), which is Spanish smoked sweet paprika. I used 1/4 teaspoon. Add more if you prefer the sauce to be spicy.Add the chopped tomatoes to the onions mixture and stir well to combine.Add 1 fresh bay leaf. I used 2 dried pieces here because I couldnt find fresh ones.Add 1 teaspoon of sugar andd salt and pepper to taste. I added 1/2 teaspoon of salt and 1/4 teaspoon of ground black pepper. Adjust seasoning to taste.Cover the sauce pan and reduce the heat to a medium-low and let the tomato mixture simmer gently till it reduces to a sauce like consistency.In the meantime, make the meatballs by adding 1/2 an onion to a food processor.Add 2 cloves of garlic. I used 1 tablespoon of minced garlic. Process till the onions and garlic are finely chopped.Sweat the onion-garlic mixture in a frying pan with some olive oil. I just realised that I had missed this step. The meatballs still tasted great.Add the onion-garlic mixture to 500g ground beef in a mixing bowl.Slice off the crust of 4 slices of white bread. Cut the soft white bread into small cubes of 1cm all round.Add the chopped bread to the beef mixture.Add 2 tablespoons of chopped parsley. Use Italian flat parsley where possible. I couldnt find any, so I used English parsley.Add 1 large egg.Add salt and pepper to taste. I used approximately 1/4 teaspoon of salt and a pinch of black pepper.Mix well to combine.Shape the meat mixture into balls that are slightly bigger than the size of a golf ball size. Roll the meat tightly to form meatballs.Add 3/4 cup of olive oil to frying pan. The layer of oil should be approximately 3/4cm in the pan.Put the pan on medium-high heat and add the meatballs to the oil. Gently roll them around in the oil to brown all surfaces and ensure even cooking.When the meatballs are a deep golden brown, remove them from the frying pan and set aside.The tomatoes-onion mixture should have reduced to a sauce consistency now. You can use a hand blender to puree the mixture. Or leave the small bits of tomatoes and onions as they are.Add the meatballs to the tomato sauce and let the meatballs warm through.Garnish with more chopped parsley.',45,45,0);
INSERT INTO "Recipe" VALUES(147,'Eggplant Parmesan','https://img.spoonacular.com/recipes/642293-556x370.jpg','1 large eggplant, 3  eggs, 1 cup bread crumbs, 0.75 cup olive oil, 0.5 cup parmesan cheese, 0.5 pound mozzarella cheese, 24 oz tomato sauce, 1 clove garlic, 2 medium onions, 0.5 teaspoon oregano',replace('Preheat oven to 350 degrees.\nSlice eggplant into 1/4 inch thick rounds and salt for 30 minutes to remove water.\nSaute onions and garlic in a tablespoon of oil. \nAdd tomatoes and oregano, simmer until sauce thickens slightly.\nDip each eggplant slice first into eggs, then into crumbs. Saute in hot olive oil until golden brown on both sides.\nPlace a layer of browned slices in 2 quart casserole; sprinkle with some of Parmesan, oregano and mozzarella; then cover well with some of tomato sauce. \nRepeat until all eggplant is used, topping last layer of sauce with several slices of mozzarella. \nBake until the sauce bubbles and the cheese is melted and browned, about 30 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(148,'Classic Pot Roast','https://img.spoonacular.com/recipes/639628-556x370.jpg','2 pounds chuck roast, 6 servings salt and pepper, 2 tablespoons vegetable oil, 2 inches onions, 20 inches baby carrots, 3 inches celery stalks, 8 ounces beer, 2 sprigs thyme, 1 cup beef stock, 1 tablespoon worcestershire sauce',replace('Heat a cast iron skillet or dutch oven to medium high heat, and preheat the oven to 325 degrees.\nTrim excess fat off the chuck roast and season all over with salt and pepper, then coat the meat with canola oil, rubbing all sides of it.\nSear the meat in the skillet, browning for several minutes on all sides.\nRemove the meat and set aside, then add the vegetables. Saute for several minutes and season with salt and pepper.\nDeglaze the pan with beer and let reduce for several minutes.\nAdd the beef back to the pan and add the thyme, stock and Worcestershire.\nCover the pan and place in the oven and let cook for 6-8 hours, until the meat is fork tender. Serve with steamed potatoes or crusty bread.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(149,'Steak with lemon and capers','https://img.spoonacular.com/recipes/661531-556x370.jpg','400 g beef steak, 2 tablespoons butter, 2 Tbs capers, 0.75 cup wine, 1 cup flour, 2 large cloves garlic, 0.25 tsp ground pepper, 1 teaspoon lemon juice, 2 servings lemon wedges, 2 Tbs olive oil, 2 teaspoons parsley, 0.75 tsp salt','Flatten the steaks lightly with a meat mallet.Combine flour, salt and pepper, dip steaks into the mixture, coating both sides.Saut the steaks in a hot mixture of butter and olive oil over medium heat, about 4 minutes on each side. Remove from the pan and set aside.Saut the garlic in the same fat for about 1 minute, stirring.Add the wine and lemon juice, stir and simmer for 5 minutes to slightly reduce the liquid.Add capers, stir. Return the steaks to the pan, cover and simmer over low heat for 4 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(150,'Grilled Lemon Garlic Chicken','https://img.spoonacular.com/recipes/645753-556x370.jpg','2 pounds chicken breast, 0.25 cup garlic olive oil, 0.5 cup lemon juice, 2 teaspoons tumeric, 4 servings salt and pepper, 4 servings cilantro',replace('Trim any fat and clean Chicken\nPut Chicken in bowl with Garlic Oil, Lemon Juice, Salt and Pepper and Tumeric, combine all.\nIf you have time, do this in the morning and marinate all day in the fridge.  If this is last minute try to give Chicken about an hour in the marinade)\nPre heat Grill, Medium High Heat.\nGrill Chicken about 5 minutes per side until inside is cooked through.\nPlate and garnish with chopped Cilantro or Parsley','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(151,'Beef With Oranges and Spices','https://img.spoonacular.com/recipes/634715-556x370.jpg','0.5 teaspoon allspice, 600 grams beef, 500 milliliters beef bouillon from cube, 0.5 teaspoon cumin, 3 cloves garlic, 2 tablespoons olive oil, 2 small oranges, 1 tablespoon parsley, 1 teaspoon saffron, 4 servings salt and pepper','Peel and slice one orange. Squeeze juice from the other orange and set aside.Heat olive oil in a casserole or Dutch oven. Add the diced meat and crushed garlic cloves. Saut until meat is nicely browned on all sides.Add orange pieces and drizzle with orange juice.Season with saffron, cumin, allspice, salt and pepper. Mix and cover. Reduce heat and simmer for 10 minutes.Pour 300ml of beef bouillon over meat and cover again. Simmer over low heat until meat is thoroughly cooked and tender (about 1 hour). Add remaining amount of bouillon during cooking so the meat does not dry.Sprinkle meat with chopped parsley. Serve immediately, with rice or couscous and a green salad.',45,45,0);
INSERT INTO "Recipe" VALUES(152,'Baked Scallops With Parma Ham','https://img.spoonacular.com/recipes/633786-556x370.jpg','12 small big scallops, 4 slices parma ham, 1  garlic clove, 3 tablespoons breadcrumbs, 2 tablespoons parsley, 2 tablespoons olive oil, 6 servings bell pepper',replace('Preheat oven to 410 F (210 C / T 7).\nMix breadcrumbs, Parma ham, garlic, parsley and 1 teaspoon of olive oil in a food processor.\nFold a piece of kitchen paper, pour 1 teaspoon of olive oil on it and use it to grease an oven rack.\nPlace scallops on the greased rack and top them with Parma ham mix.\nPour a dash of olive oil on top and bake in oven for 8 minutes.\nServe as a starter with a few leaves of lamb''s lettuce or rocket if you like.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(153,'Navajo Fry Bread By Mommie Cooks','https://img.spoonacular.com/recipes/652980-556x370.jpg','1  pd sausage, 1 bunch cilantro, 0.5  onion, 1 teaspoon cumin, 1 teaspoon chili powder, 1 teaspoon oregano, 1 tablespoon water, 1 tablespoon tomato paste, 6 servings oil, 1 teaspoon corriander, 1 teaspoon corriander',replace('For the fry bread dough, mix together all the listed ingredients; the flour, milk, baking powder, and salt.\nAllow the bread to rest for at least 10 minutes.\nWhile the dough is resting, grab a frying pan and start cooking up the meat for a minute or two.\nAdd to the meat the garlic, cilantro, and onion.\nCook the meat all the way through and then add in the cumin, chili powder, and oregano\nMix it up well and then add in the water and tomato paste\nStir it all together and turn the heat down to low to keep warm\nGrab a clean frying pan and pour enough oil in the bottom to create about a 1" depth of oil. Turn the heat on medium high and allow it to heat up.\nWhile the oil is heating, take your rested dough ball, rip of a chunk and roll it out thin with a rolling pin.\nDrop the rolled bread into the hot oil and allow it to cook up for about a minute on each side or until gold brown.\nServe meat on top of bread along with additional desired toppings.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(154,'Baked Swedish Pancake','https://img.spoonacular.com/recipes/633830-556x370.jpg','2 tbsp butter, 6  eggs, 1 cup flour, 4 servings jam, 4 servings maple syrup, 1 cup milk, 4 servings cranberry-orange relish, 4 servings powdered sugar, 1 Dash salt, 4 servings strawberries','Heat oven to 400 degrees and place butter in 9 x 13 inch casserole to melt. Mix other ingredients into a batter and pour into hot pan. Bake 20 minutes. It will puff up and edges will curl in and brown when done. Cut in squares and serve with a variety of toppings. Makes 10 slices per pan. Serves 6 to 8.',45,45,0);
INSERT INTO "Recipe" VALUES(155,'Farfalle with Peas, Ham and Cream','https://img.spoonacular.com/recipes/642583-556x370.jpg','1 teaspoon butter, 3 slices ham, 4 servings farfalle pasta, 0.5 cup heavy cream, 0.5 cup parmesan cheese, 1 cup peas, 4 servings salt and pepper','Cook pasta according to package directions.In a skillet add the peas, butter, ham. Sautee for 5 minutes. Add the cream, salt and pepper and cook under medium heat for 5 to 10 minutes, or until the cream is slightly becoming thick. Remove from heat. When the pasta is cooked and drained, return to pan and add the sauce. Stir well and add the cheese.Serve nice and hot.',30,30,0);
INSERT INTO "Recipe" VALUES(156,'White Chocolate Cheesecake With Raspberries','https://img.spoonacular.com/recipes/665172-556x370.jpg','1.3333334 cups graham wafer crumbs, 3 tablespoons sugar, 0.33333334 cup butter, 0.33333334 cup whipping cream, 1 cup chocolate chips, 3 ounces eight packages ounces cream cheese, 0.5 cup sugar, 3  eggs, 3 teaspoons vanilla extract, 1 cup whipping cream, 2 pints raspberries',replace('To make the crumb crust\nIn a small bowl combine the graham crumbs, sugar and melted butter.\nPress into the bottom of a lightly greased springform pan. (Grease bottom only! I also like to line the bottom with parchment paper for easy release of the cheesecake from the pan when it has cooled.)\nTo prepare the cheesecake\nIn a double boiler, melt together the  cup whipping cream and 1 cup pf white chocolate chips. You want this just at the melting point, so be careful not to overheat it. Let it cool to lukewarm if necessary after melting. Set aside to cool while you prepare the rest of the cheesecake batter.\nCream together the cream cheese and  cup sugar for a few minutes, scraping the bowl often.\nAdd the eggs, one at a time, beating well after each addition.\nStir in the vanilla extract and melted white chocolate.\nFinally blend in the 1 cup of whipping cream until smooth.\nPour over the prepared base and bake in a bain marie (See Note) at 325 degrees F for 60 to 70 minutes. The cheesecake may be beginning to lightly brown at the edges but a cheesecake does not need to brown at all to be fully baked. The surface of the cheesecake should lose any shine when the cake is properly baked. It can still be slightly wobbly just at the center at this point.\nRemove the cake from the oven and run a sharp knife completely around the edge of the pan. This will allow for the cheesecake to shrink as it cools and hopefully not crack (but who cares if it does? I am never bothered by a crack or two in the surface)\nAllow the cheesecake to cool thoroughly on a wire rack at room temperature. (Do not put a hot cheesecake into the fridge to cool quickly, this may result in an under baked cheesecake because the residual heat actually continues to set the cheesecake after it comes out of the oven).\nTo finish the cheesecake\nWhen completely cool cover the top with fresh raspberries and garnish with melted white chocolate if desired.\nChill completely in the refrigerator until ready to serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(157,'Wholesome Spelt Waffles','https://img.spoonacular.com/recipes/665307-556x370.jpg','2 cups spelt flour, 1 tablespoon baking powder, 0.25 teaspoon salt, 2  eggs, 1 cup milk, 0.75 cup seltzer water, 0.25 cup oil',replace('Preheat your waffle iron.\nMix the dry ingredients on a large bowl. Then whisk in all the wet ingredientuntil smooth.\nScoop the batter onto the waffle iron and close. Cook for 2-5 minutes, then repeat.\nMake 12-  4 inch waffles.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(158,'Lemon Fish with Sweet Potatoes','https://img.spoonacular.com/recipes/716369-556x370.jpg','1 tablespoon butter, 1  chili pepper, 1 serving coconut sauce, 0.5 cup coconut milk, 2 fillet croaker fish, 1  garlic clove, 1  seasoning cube, 1 serving half of a seasoning cube, 0.25  lemon, 0.5  bulb of onion, 1 serving sprinkle of parsley, 1 tablespoon pepper soup spice, 1 large sweet potato, 1 teaspoon vegetable oil','Wash and place your potatoes in a pot and bring to boil till soft. Peel, slice and set aside.Season your fish with pepper soup spice and set aside.Preheat your butter and vegetable oil and fry your onions and pepper on medium heat for one minute.Add your fish and squeeze your lemon over the fish and sprinkle the seasoning cube and allow to cook on low heat. When brown, flip over so it can brown on the other side.For your sauce, heat up your coconut milk, garlic, seasoning cube and parsley and allow to thicken a bit.Serve the fish and potato with the sauce drizzled over it and garnish with extra chili. ',45,45,0);
INSERT INTO "Recipe" VALUES(159,'Fish Pie With Fresh and Smoked Salmon','https://img.spoonacular.com/recipes/642977-556x370.jpg','1  bay leaf, 0.5 teaspoon peppercorns, 1 tablespoon butter, 1 cup chicken stock, 2 teaspoons cornstarch, 1 teaspoon chives, 1 teaspoon tarragon, 0.5 cup greek, 1 tablespoon horseradish, 1 teaspoon lemon juice, 3 tablespoons milk, 1 tablespoon olive oil, 1  onion, 2 medium potatoes, 4 ounces salmon, 8 ounces salmon, 8 ounces savoy cabbage, 0.5 cup white wine','Peel potatoes and cut into chunksCook in boiling, salted water until tender, app. 15 minutesDrain potatoes, add butter, horseradish and 2 tbs milk to potatoes, mash, adding a bit more milk if neededPut fresh salmon in a medium skillet, add water to almost cover, lemon juice, bay leaf and peppercorns.  Cover and poach until done, 12 - 15 minutes. It should be opaque and flake easily with a fork.Remove salmon and cut into large chunksRoughly chop the smoked salmonSaut onion in oil until tenderAdd cabbage and saut, stirring 2 - 3 minutes.Add white wine, chicken stock, herbs, cover and simmer 10 minutesDissolve cornstarch in water and add to cabbage, stirring until thickenedRemove from heat and add yogurt and stir well to combine.Add both salmons to cabbage and stir gently.Spoon into a baking dishTop with potatoesBake, 400F (200C) for 15 minutes or until the top starts to brown.',45,45,0);
INSERT INTO "Recipe" VALUES(160,'Broccoli Tartar','https://img.spoonacular.com/recipes/636228-556x370.jpg','1 tablespoon apple vinegar, 0.5  broccoli, 2  peeled/ tomatoes, 2 handfuls parsley, 1 teaspoon herbs de provence, 1 tablespoon olive oil, 1  onion, 1  bell pepper, 1 small pinch chili powder, 12 servings sea salt, 12 servings sesame seeds to decorate, 1 dash soy sauce, 12 servings colorful tartar on a bed of vegetables. also an touch, 12 servings a hand blender, 1 cup soaked arame, 12 servings hand blender, 1 cup soaked arame','Soak arame (seaweed can be found in a health-food store) in a bowl of pure water.Put the grill of the oven and put a pot of water on the fire with a pinch of sea salt.Wash the pepper, broccoli, parsley and tomatoes. Carve a cross down the tomatoes, halve the peppers and remove the seeds and cut the broccoli into chunks.When the water boils you immerse the tomatoes and leave them for a swim, get them and let them scare in cold water. They are now ready to go out of their jackets.Meanwhile, the broccoli  can be swimming for 6 minutes in the boiling water. Note: The water will cool off and when back to a boil, then add 5 minutes. Get them dry and cool under cold water, then they stay nice and green.The pepper may be under the grill until it sees black. Let them cool and peel them.Chop the parsley.Put the cooled broccoli in a long narrow bowl and blend finely with a hand blender. Add the oil and vinegar with the salt. Add half the parsley and mix into a smooth puree. If too grainy (dry) put some extra oil.Cut the unseeded, peeled tomatoes and peppers into very small pieces.The shallot or onion may be chopped in mini pieces.Add the chopped vegetables to the puree and stir gently with a spoon. The rest of the chopped parsley may be added now. A little salt, soy sauce and chili powder. Start with a little bit and add some more later if desired. The herbs de Provence can now embellish the whole with its bright flavor.The seaweed may now well out of the water and squeeze out any excess moisture. Cut the seaweed finely and mix carefully with the puree.With an ice cream spoon you  create beautiful balls and sprinkle with toasted sesame seeds.bon apptit',45,45,0);
INSERT INTO "Recipe" VALUES(161,'Meyer Lemon Ricotta Pancakes with Blackberry Compote','https://img.spoonacular.com/recipes/651765-556x370.jpg','0.75 cup all purpose flour, 6 ounce blackberries, 2 servings butter, 3 large eggs, 0.5 tablespoon granulated sugar, 1.5 tablespoons granulated sugar, 0.5 teaspoon lemon zest, 1  lemon zest, 2 tablespoons meyer lemon juice, 1 cup ricotta, 1 pinch salt, 0.25 cup water','In a small saucepan over medium heat, add the blackberries, Meyer lemon zest, sugar, and water.Stir to combine and cook until the water starts to thicken and the berries lose their shape, stirring occasionally. This should take about 10 minute.Remove from the heat and set aside.In a medium bowl, whisk together the ricotta cheese, Meyer lemon zest, juice, sugar and egg yolks.Gradually stir in the flour until just combined.Using a stand or hand mixer, whisk the egg whites with a pinch of salt until stiff peaks are formed.Take a large spoonful of the eggs whites and stir it into the batter. With the remaining eggs whites, fold in half, slowly turning the bowl while you fold. It is fine if there are some white streaks left in the batter before you add the second half. Fold in the remaining eggs white and set the batter aside while you heat up a griddle or non-stick pan on medium heat.Add some butter to the pre-heated pan, and swirl to coat.Add about a 1/4 cup of batter and cook until bubbles start to form on the top and the edges begin to brown slightly.Flip the pancakes and cook for an additional minute.Remove and keep warm, while you repeat with the remaining batter.Serve the pancakes with the blackberry compote and if you like a little pure maple syrup.',45,45,0);
INSERT INTO "Recipe" VALUES(162,'Green Tea Fruit Medley Smoothie','https://img.spoonacular.com/recipes/645530-556x370.jpg','1 cup water, 3  tea bags, 1 cup berries, 0.25 cup pineapple juice, 0.5 cup vanilla yogurt, 0.5 cup ice cubes',replace('Prepare tea by steeping 3 Bigelow Green tea bags in 1 cup of boiling water for 5 minutes. Squeeze out bags and discard.\nCombine tea and remaining ingredients in blender and blend until smooth.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(163,'Mexican Chicken Lettuce Wraps','https://img.spoonacular.com/recipes/651585-556x370.jpg','3 cups chicken breast, 1 tablespoon lime juice, 0.5 teaspoon ground cumin, 0.5 teaspoon ground chile powder, 0.5 teaspoon seasoned salt, 0.25 teaspoon garlic powder, 3 tablespoons olive oil, 15 ounces black beans, 1 medium tomato, 0.25 cup onion, 0.25 cup bell pepper, 1 medium avocado, 12  boston lettuce leaves',replace('Marinate chicken with lime, cumin, chile powder, seasoned salt, garlic powder and olive oil for 30 minutes.\nCook chicken in a skillet over medium heat.\nIn a separate bowl add beans, red pepper, tomato, and onion.\nAdd to chicken to the bowl and stir ingredients together.  Adjust seasoning if needed.\nWhen ready to serve cut avocado into thin slices.\nFill each lettuce cup with mixture and  top with avocado slice.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(164,'Turkish squares','https://img.spoonacular.com/recipes/664101-556x370.jpg','125 g butter, 150 g sugar, 4  eggs, 500 g milk, 0.5 tsp vanilla extract, 400 g semolina, 1 Tbs baking powder, 100 g almonds, 200 ml water, 200 g sugar, 2  juice of lemon',replace('For the syrup mix all ingredients, bring to the boil, then reduce the flame and cook over low heat for 5 minutes. Set aside to cool.\nBeat butter and sugar for 4 minutes until light and creamy.\nStir in egg yolks one at a time, combine.\nAdd sour milk, vanilla extract and semolina mixed with baking powder. Mix and combine.\nBeat the egg whites into stiff peaks. Gradually add to the semolina mixture, lightly stirring after each addition until completely combined.\nLine with parchment paper a baking rectangle shape (about 25x25cm) and cover evenly with the cake batter. Bake the cake in a preheated oven at 180C for about 35 minutes or until done (the trick with a toothpick).\nPrick the still hot cake with a toothpick and pour the cooled syrup over it. Leave the cake in a pan until cool, then sprinkle with flaked almonds.\nCut the cake into squares and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(165,'Arroz Con Pollo','https://img.spoonacular.com/recipes/632749-556x370.jpg','2 tablespoons butter, 3 cloves garlic, 3  chicken breasts, 2 teaspoons cumin, 2 teaspoons coriander, 5.5 teaspoons turmeric, 1  onion, 1  bell pepper, 1 can chiles, 1 can tomatoes, 4 cups chicken broth, 1 cup rice, 1 teaspoon chili powder, 0.5 teaspoon salt, 0.5 teaspoon onion powder, 0.5 cup cheese',replace('Start out by heating up a large pan on medium heat and melting your butter. Add in your garlic and give it a minute or two to cook up.\nSprinkle your chicken with about 1 tsp of the cumin, coriander, and turmeric. Throw it in the pan and cook it up.\nOnce your chicken is fully cooked, go ahead and add in your diced onion and pepper.\nCook it all up for about 3 to 4 minutes. Add in your chiles and tomatoes.\nSwirl it around once or twice and add in your broth. Now add in your rice.\nFinally, add in the remaining tsp of chili powder, cumin, and coriander, the salt, the remaining 1/2 tsp of turmeric and the onion powder.\nBring the pot to a boil and then turn down the heat to low and cover. Simmer the mixture for about 20 minutes or until the liquid is absorbed and the rice is cooked through.\nGrab your shredded cheese and spread it across the top of the chicken mixture. Cover for another minute or two and allow your cheese to melt completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(166,'Warm Quinoa Spinach and Shiitake Salad','https://img.spoonacular.com/recipes/664969-556x370.jpg','6 cups baby spinach, 6 servings pepper, 500 mL chicken broth, 50 mL feta cheese, 6 servings olive oil, 125 mL bell pepper, 2 tablespoons red wine vinegar, 225 g pc organics roasted garlic and herbs quinoa, 1 pinch salt, 2  shallots, 180 g shiitake mushrooms','In saucepan, bring chicken broth to a boil. Stir in quinoa and contents of seasoning pouch. Reduce heat to low, cover and simmer for 12 to 15 minutes or until tender. Remove from heat; let stand, covered, for 5 minutes. Fluff with a fork.In large nonstick frying pan, heat oil over medium heat; cook shallots and red pepper for 4 to 6 minutes, stirring occasionally, or until lightly golden and softened. Stir in mushrooms; cook, stirring occasionally, for 6 to 8 minutes or until mushrooms have released their juices and are starting to turn golden. Add vinegar; cook, stirring to bring up browned bits, for 1 minute. Stir in spinach; cook, stirring, for 2 minutes or just until wilted. Stir in salt and pepper. Remove from heat.In large bowl, toss quinoa with warm spinach mixture. Serve sprinkled with feta.More "Recipe" ideas are available online at pc.ca.',45,45,0);
INSERT INTO "Recipe" VALUES(167,'Hazelnut & Coconut Shortbread Sandwich Cookies','https://img.spoonacular.com/recipes/646385-556x370.jpg','0.5 cup coconut, 2 cups flour, 0.25 cup hazelnuts, 0.25 teaspoon salt, 1 cup sugar, 2 sticks butter, 1 teaspoon vanilla extract','Preheat oven to 350 degrees F.In the bowl of an electric mixer fitted with the paddle attachment, on medium blend together sugar and butter until soft and light yellow, about 5 minutes. Meanwhile finely chop (either with your knife or in a food processor) the coconut and hazelnuts. Blend vanilla into butter and sugar mixture, then add salt and flour with mixer on low. Once incorporated, add coconut and hazelnuts and stir just until blended together. Remove dough onto a piece of plastic wrap, form into a disk, wrap and refrigerate for 30-45 minutes or until firm.On a floured surface, roll out dough to 1/8-inch thick. With a cookie cutter, cut dough into large circles. Cut out a small circle in half of the circles (preferably the best looking circles) using a smaller circle shaped cutter. Place all circles onto cookie sheets.Bake cookies 12-14 minutes until edges begin to brown, rotating sheets halfway through if baking more than one sheet at a time. If not, refrigerate dough between baking. Remove trays to cooling rack to let cool for a few minutes. Remove cookies from tray and place onto cooling rack to cool completely. Once completely cool spread about 1 tsp or more of raspberry jam onto the bottom circle cookies and top with doughnut shaped cookies. Dust with powdered sugar and serve.',75,75,0);
INSERT INTO "Recipe" VALUES(168,'North Carolina-Style BBQ Pulled Pork','https://img.spoonacular.com/recipes/653308-556x370.jpg','2 cups apple cider vinegar, 3 pounds pork shoulder, 0.75 cup firmly-packed brown sugar, 2 teaspoons butter, 0.5 teaspoon celery salt, 0.5 teaspoon mustard, 0.5 teaspoon garlic salt, 1.5 teaspoons ground pepper, 0.6666667 cup ketchup, 2 teaspoons brown sugar, 3 tablespoons liquid hickory smoke, 0.5 teaspoon onion powder, 3 teaspoons pepper flakes, 12 servings salt, 1 cups water','Prepare the rub:Mix paprika, light brown sugar, celery and garlic salts, dry mustard, black pepper, onion powder and salt in a small bowl. Season the entire pork roast and cover overnight in the refrigerator.Preheat the oven to 325F. Place the pork roast in a large, disposable aluminum roasting pan.In a small bowl, mix together the melted butter and the liquid hickory smoke for the basting marinade. Pour the basting marinade over the pork and cover with aluminum foil. Cook for approximately 4 1/2 hours (or until the pork becomes tender enough to start "pulling" away, turning the pork every hour, and basting every 1/2 hour. Alternatively, cook pork over white hot coals, covered, for 3-3 1/2 hours, basting and turning frequently with basting marinade.Transfer the pork roast to a cutting board. Drain the excess juices from the pan. Slice the pork roast and pull apart the meat (trimming the fat) and place back into roasting pan.Prepare the BBQ sauce: In a large bowl, mix the cider vinegar, water, ketchup, dark brown sugar, salt, and red pepper flakes and pour over pulled pork, stirring to make sure all pork is covered; cover with aluminum foil.Place pulled pork back into the oven (still at 325F) or in pan on grill and cook for 1 1/2 hours, stirring pork and BBQ every 30 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(169,'Eggplant Parmesan','https://img.spoonacular.com/recipes/642293-556x370.jpg','1 large eggplant, 3  eggs, 1 cup bread crumbs, 0.75 cup olive oil, 0.5 cup parmesan cheese, 0.5 pound mozzarella cheese, 24 oz tomato sauce, 1 clove garlic, 2 medium onions, 0.5 teaspoon oregano',replace('Preheat oven to 350 degrees.\nSlice eggplant into 1/4 inch thick rounds and salt for 30 minutes to remove water.\nSaute onions and garlic in a tablespoon of oil. \nAdd tomatoes and oregano, simmer until sauce thickens slightly.\nDip each eggplant slice first into eggs, then into crumbs. Saute in hot olive oil until golden brown on both sides.\nPlace a layer of browned slices in 2 quart casserole; sprinkle with some of Parmesan, oregano and mozzarella; then cover well with some of tomato sauce. \nRepeat until all eggplant is used, topping last layer of sauce with several slices of mozzarella. \nBake until the sauce bubbles and the cheese is melted and browned, about 30 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(170,'Spicy Banana Zucchini Balls','https://img.spoonacular.com/recipes/661014-556x370.jpg','1 cup coarsely zucchini, 1 large banana, 1  egg, 2 teaspoons turmeric, 3 tablespoons honey, 1 teaspoon curry powder, 2 teaspoons chilli pepper, 0.25 teaspoon baking soda, 0.5 cup panko breadcrumbs, 0.5 cup flour, 24 servings vegetable oil',replace('Mix all ingredients in a bowl until it forms a soft dough.  Add more flour if needed.\nHeat vegetable oil on medium heat (about 350F).  Drop a teaspoonful of dough (regular teaspoon) into the hot oil and fry until brown, turning zucchini ball around. (Make sure your oil is not too hot or your zucchini balls will get too brown!)\nDrain in paper towel.  Repeat with the rest of the dough.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(171,'Moist Vegan Spelt Bran Muffins','https://img.spoonacular.com/recipes/652239-556x370.jpg','0.25 cup ground flaxseed, 0.5 cup water, 1 cup wheat bran, 1 cup spelt bran, 0.5 cup spelt flakes, 1 cup spelt flour, 0.5 cup psyllium fibre husks, 0.5 teaspoon stevia extract powder, 0.25 cup flaxseeds, 2 tablespoons chia seeds, 2 teaspoons baking soda, 0.5 teaspoon sea salt, 0.5 teaspoon nutmeg, 1 teaspoon cinnamon, 0.25 cup demerara sugar, 3 tablespoons agave nectar, 0.33333334 cup applesauce, 2  equivalent of eggs in ener-g egg replacer powder, 1 cup vegan" milk, 0.33333334 cup canola oil, 0.5 cup raisins, 0.33333334 cup prunes',replace('Preheat oven to 400F, line 24 muffin cups or grease well.\nIn a small bowl, whisk together flaxseed and hot water. Let stand 10 minutes.\nIn a medium bowl whisk together brans, spelt flakes, flour, psyllium, stevia, flaxseeds, chia seeds, baking soda, salt, nutmeg and cinnamon.\nIn a large bowl beat together sugar, agave, applesauce, egg replacer, flax mixture, "milk" and oil until smooth.\nAdd dry ingredients and stir in just to combine, then fold in the raisins (with their reserved liquid) and prunes.\nBake for 15-17 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(172,'Crockpot "Refried" Beans','https://img.spoonacular.com/recipes/775585-556x370.jpg','1 tsp pepper, 2 tsp cumin, 4 Tbsp garlic, 1 large onion, 2 lbs pinto beans, 1 Tbsp up salt, 10 cups water','Rinse the beans in a colander. Pick out any bad beans.Combine all the ingredients in the crockpot. Remove any floating beans. Cover, and cook on HIGH for 4 hours and on LOW for 2 hours.Uncover, and remove extra liquid. Leave enough liquid to reach the desired consistency when the beans are mashed. (We like our beans somewhere between the very-liquidy restaurant style beans, and the canned version of refried beans.)Mash beans with a potato masher to desired consistency.Serve warm. Store in air-tight containers in the refrigerator and use within 2 weeks, or freeze in ziplock bags for later use.',45,45,0);
INSERT INTO "Recipe" VALUES(173,'Grilled Chicken & Eggplant Sandwiches','https://img.spoonacular.com/recipes/645624-556x370.jpg','14.5 oz canned tomatoes, 1.5 lb chicken cutlets, 1  eggplant, 2 T basil, 1 Clove garlic, 0.25 c slivered kalamata olives, 7 T olive oil, 1 t oregano, 6 oz provolone cheese, 0.5 t pepper flakes, 4 servings salt & pepper, 4  sub roll','Combine all of the ingredients for the garlic oil. Heat 1 tablespoon of the garlic oil in a medium saucepan over medium heat. When garlic begins to sizzle and smell fragrant, add the diced tomatoes and their liquid. Bring to a simmer, and simmer for about 10 minutes, until thickened slightly, breaking up the tomatoes a bit with a wooden spoon. Add the olives and basil. Season with salt &amp; pepper to taste, set aside.Preheat your grill for at least 10 minutes. Season the chicken with salt &amp; pepper and toss with 2 tablespoons of the garlic oil. Brush the eggplant with 2 more tablespoons of the garlic oil. Split the hoagie rolls open and brush with the remaining 2 tablespoons of garlic oil.Scrape clean and oil the grill grate (using a wad of paper towel dipped in oil). Add the eggplant and cook until tender about 5-7 minutes per side, turning once, remove eggplant from the grill and cover with foil while grilling the chicken. Add the chicken and grill until cooked through, about 4-5 minutes per side, adding the cheese for about the last 30 seconds to a minute. Remove chicken from the grill. Add the hoagie rolls, cut side down and grill until toasted.To assemble the sandwiches, layer some of the eggplant on the toasted roll, topped with a little of the sauce then some of the chicken and additional sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(174,'Donkatsu - Korean Breaded Pork Cutlet','https://img.spoonacular.com/recipes/641565-556x370.jpg','0.25 head cabbage, 0.5  carrot, 2  eggs, 0.5 cup flour, 4 servings katsu sauce, 2 cups panko bread crumbs, 4  pork chops, 4 servings salt and pepper, 4 servings vegetable oil','Trim off fat from pork chops (usually on the sides), then pound into thin pieces with tenderizer. Season with salt and pepper.Coat pork with flour, then beaten egg, and lastly panko bread crumbs.Heat vegetable oil in pan or skillet on medium heat.Fry until golden brown and cooked through (you can cut to check insides). Usually takes about 8-10 minutes total if fully submerged in oil.Remove cutlets from the oil and drain on paper towel to remove excess oil and cool.Drain shredded cabbage well. Cut each cutlet into small pieces and serve on plate with cabbage slaw.Serve with katsu sauce for dipping and serve with rice.',30,30,0);
INSERT INTO "Recipe" VALUES(175,'Skinny Kale Basil Pesto','https://img.spoonacular.com/recipes/660228-556x370.jpg','2 cups kale leaves, 1.5 cups basil leaves, 0.5  juice of lemon, 3  garlic cloves, 1 Tbs miso paste, 2 Tbs parmesan cheese, 0.5 Tbs walnuts, 1 Tbs water, 0.5 Tbs olive oil',replace('Remove the kale and basil leaves from the stem and rinse.\nRoughly chop the kale leaves so that they fit inside a food processor.\nPlace the kale and basil leaves into a food processor and chop until the leaves turn into small pieces.\nAdd the rest of the ingredients into the food processor and mix until everything is well blended.\nPour out all the ingredients into a dish and enjoy with your favorite dishes!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(176,'Rustic Brie Toasts with Wild Mushroom, Cranberry and Shallot','https://img.spoonacular.com/recipes/658914-556x370.jpg','2 cups mushrooms, 1  shallot, 0.25  1/4 cup dried cranberry (juice sweetened if possible), 1 tsp thyme, 1  rustic baguette, 1 tbsp olive oil, 1  wedge of beautiful brie cheese, 1 pinch salt and pepper',replace('Start by pre-heating your oven to 350 degrees.  While the oven is pre-heating, heat the olive oil in a saut pan and add the shallot, diced mushroom, cranberry and thyme.  Saut for a few minutes until the shallot begins to wilt and then season with salt and pepper and set aside to cool.\nSlice 12 pieces of brie and place each piece on the bread.  Follow with a spoonful of the cranberry, mushroom and shallot mixture and place on an oiled cookie sheet. Bake the toasts for 15 minutes or just until the brie melts.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(177,'Apple Cheddar Palmiers','https://img.spoonacular.com/recipes/632493-556x370.jpg','2 tablespoons butter, 2  baking apples, 2  shallots, 0.5 teaspoon nutmeg, 30 servings salt and pepper, 1 cup sharp cheddar, 2 sheets puff pastry, 1  egg',replace('Preheat a skillet to medium-high. Saute the apples and shallots in butter for 3-5 minutes. Add the nutmeg and salt and pepper to taste.\nLay each piece of puff pastry on its own piece of parchment paper and roll them lightly.\nTop both pieces with apple mixture and distribute evenly. Then top with them with shredded cheese.\nFold the pastry sheets inward  of the width on both ends. Fold in again so that the dough meets in the middle. Fold one more time.\nWrap the rolls in the paper and put the rolls in the fridge for at least 30 minutes to chill before cutting. (Wrap them well if you are prepping ahead).\nWhen ready to bake, preheat the oven to 450 degrees F. Carefully slice each roll into 12-15  inch slices and lay flat on parchment paper lined baking sheets. Whisk the egg and brush it over the tops. Bake for 12-14 minutes.\nCool before lifting! Makes 24-30.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(178,'Turkish Chicken Salad with Home-made Cacik Yogurt Sauce','https://img.spoonacular.com/recipes/664090-556x370.jpg','1  carrot, 1  cucumber, 3 small pieces garlic, 2 large pickled cucumbers / gherkins, 2 large jalapeno peppers, 1  juice of lemon, 1 small lebanese cucumber, 4 servings lemon juice, 1 large head i gem lettuce, 1 cup olive oil, 1 Handful parsley, 0.25  cabbage, 1 small onion, 1  roast chicken, 4 servings salt & pepper, 2  tomatoes, 250 ml yoghurt','METHOD:1. First prepare the Cacik: For the Cacik: Chop the cucumber into tiny pieces, as small as you can, and place in a bowl. Cover the cucumber with salt and set aside for 30 minutes. The cucumbers will start to exude their juices which will flavour the yogurt nicely.2. Put a griddle pan on medium  high heat, cover the peppers with olive oil and start to char.3. Cut the tomato and cucumber into medium pieces. Slice the red onion as thin as you can. Chop the parsley fine. Place all ingredients in a bowl and cover with a the juice of 1 lemon. Season with salt and pepper. Let it sit in the fridge for 30 minutes  1 hour, stirring a couple times, so it starts to exude juice.4. Tear the lettuce into mouth-siazed peices. Cut the red cabbage into thin slices. Grate the carrot. Mix together in a bowl.5. Tear the chicken into large pieces and add to the salad.6. Remove the tomato salsa from the fridge. Drain the juice and keep for later. Now add the tomato, cucumber, parsley onion mix to the chicken salad, as well as the sliced gherkin.7. Lay out the salad on a large plate or chopping board. Serve with the charred peppers, cacik, salsa vinaigrette and some chilli sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(179,'Grilled Peach Melba with Vanilla Bean Frozen Yogurt','https://img.spoonacular.com/recipes/716421-556x370.jpg','4 servings coconut oil, 0.25 cup honey, 2 T honey, 2 large peaches, 3 cups greek yogurt, 1.5 cups raspberries, 2 tsp raspberry fruit spread, 1  vanilla bean','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(180,'Coffee Cream Martinis','https://img.spoonacular.com/recipes/639866-556x370.jpg','0.5 cup granulated sugar, 1 tablespoon ground coffee, 1.5 ounces vodka, 1.5 ounces baileys irish cream, 1.5 ounces kahlua, 4 servings chocolate syrup, 4 servings ice cubes',replace('In a small bowl combine the granualted sugar and ground coffee, mix well.\nSpoon a layer of the sugar coffee mixture onto a plate.\nMoisten the rim of a martini glass with water, hold upside down and place into the sugar coffee ground mixture getting a nice rim on the glass.\nSet aside.\nFill a martini shaker three fouths full with ice.\nAdd the vodka, Baileys and Kahlua, shake until condensation forms on the outside of the shaker.\nDrizzle chocolate syrup on the inside of the perpared martini glass.\nStrain the martini into the glass and serve immediately.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(181,'Maple-Glazed Apple Cookies','https://img.spoonacular.com/recipes/650939-556x370.jpg','2 cups apple, 1 teaspoon baking soda, 1 cup brown sugar, 0.5 cup butter, 1 teaspoon cinnamon, 1  egg, 2 cups flour, 0.25 teaspoon ground cloves, 0.25 teaspoon maple flavoring, 0.25 cup milk, 0.25 teaspoon nutmeg, 1 cup powdered sugar, 1 teaspoon salt','Preheat oven to 400 degrees F.Cream 1/2 cup butter and sugar together in a large mixing bowl until light in color, about 1-2 minutes. Add egg and 1/4 cup milk; stir to combine. Add remaining dry ingredients (except apple) and stir just until combined. Gently fold in the apples.  Drop by heaping tablespoons onto a greased baking sheet.Bake at 400 for about 10-12 min or until tops don''t look wet anymore.To make the glaze, whisk together 1 tablespoon melted butter, 1 cup powdered sugar, 1/4 tsp maple flavoring, and 3 tablespoons milk in a small bowl. When the cookies have cooled for a few minutes, drizzle each cookie with glaze.',45,45,0);
INSERT INTO "Recipe" VALUES(182,'Arroz Con Leche','https://img.spoonacular.com/recipes/632737-556x370.jpg','3 cups heavy cream, 3 cups milk, 1 cup arborio rice, 2  cinnamon sticks, 1  lemon zest, 1 pinch salt, 1 cup sugar',replace('In a saucepan, place the 2 cups heavy cream, 2 cups milk, rice, cinnamon sticks, lemon zest and salt then bring to a boil.\nTurn down the heat and simmer until the rice is cooked, about 30 minutes. Add the rest of milk and heavy cream as needed (you don''t want the rice to become too thick).\nAdd the sugar off the heat and stir to combine.\nRemove the cinnamon sticks.\nSprinkle with cinnamon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(183,'Pancakes','https://img.spoonacular.com/recipes/654495-556x370.jpg','4 teaspoons baking powder, 1  egg, 2 cups flour, 2 tablespoons margarine, 125 milliliters milk, 0.5 teaspoon salt, 1 tablespoon sugar','Beat egg until fluffy.Add milk and melted margarine.Add dry ingredients and mix well.Heat a heavy griddle or fry pan which is greased with a little butter on a paper towel.The pan is hot enough when a drop of water breaks into several smaller balls which ''dance'' around the pan.Pour a small amount of batter (approx 1/4 cup) into pan and tip to spread out or spread with spoon.When bubbles appear on surface and begin to break, turn over and cook the other side.',45,45,0);
INSERT INTO "Recipe" VALUES(184,'Boiled Egg Curry','https://img.spoonacular.com/recipes/635601-556x370.jpg','4 tablespoons canola oil, 0.5 teaspoon chilli powder, 4  hardboiled eggs, 1 leaves coriander to garnish, 2 teaspoons ginger, 1 teaspoon garam masala, 2  garlic cloves, 2  chillies, 2 teaspoons ground coriander, 1 teaspoon ground cumin, 2  onions, 2 servings salt, 3  big tomatoes, 0.5 teaspoon turmeric powder','Boil 4 eggs in boiling water for about 10 minutes.Heat 2 tablespoons canola oil in a deep pan over medium heat. Add the chopped onions and fry until golden. Take off the heat. Transfer the fried onions from the pan to a food processor. Grind the onions, tomatoes, green chillies into a smooth paste.Heat the remaining 2 tablespoons of canola oil in the same pan over medium heat. Add the onion paste. Fry for 2-3 minutes. Stir in ginger and garlic and all the dry spices. Fry until the oil begins to separate from the onion tomato mixture.Add 2 cups of water bring to a boil on a medium flame.Cut the boiled eggs into halves lengthside and add them to the gravy. Simmer for 10 minutes or till the gravy is thickened/ reduced to about 3/4 of the original quantity after you added the waterGarnish with coriander leaves. Serve hot with rice or flatbread.',45,45,0);
INSERT INTO "Recipe" VALUES(185,'Rocky Road Rice Krispie Treats','https://img.spoonacular.com/recipes/658727-556x370.jpg','0.5 teaspoon almond extract, 1 cups almonds, 0.25 cup bittersweet chocolate, 5 tablespoons butter, 24 servings kosher salt, 5 cups rice krispies, 10 ounces chocolate vanilla swirl marshmallows, 0.5 teaspoon vanilla extract','In a large soup pot, melt butter and marshmallows, stirring to combine.Add extracts and stir.Add cereal and 1 cup of almonds and mix well.Spread into a 913 dish sprayed with baking spray. Flatten until smooth and even on top.Drizzle melted chocolate on top and sprinkle over last 1/3 cup of almonds.Sprinkle salt on top (about 1/2 teaspoon).Allow to cool completely before cutting into squares.  (Putting them in the fridge for an hour or so once theyve reached room temp is the easiest way to cut into them.)',45,45,0);
INSERT INTO "Recipe" VALUES(186,'Pork with Blueberry Sauce','https://img.spoonacular.com/recipes/656846-556x370.jpg','1 Tbsp balsamic vinegar, 0.5  pint blueberries, 0.25 cup brown sugar, 1 Tbsp canola oil, 1  lime zest, 4 servings to garnish: parsley, 4 servings bell pepper, 4  pork chops, 1  onion, 4 servings salt','Preheat oven to 400 degrees Fahrenheit.In a nonreactive bowl, mash the blueberryies with the brown sugar to desired consistency, then set aside.Heat saute pan on medium. Season the pork chops with salt and pepper on both sides. Add canola oil to the saute pan. Brown pork on both sides until golden and crispy, about 2-3 min on each side.Remove from pan and place on a baking dish to finish cooking in the oven. Depending on thickness of the pork. If its thin keep warm aside until sauce is ready.In the same pan the pork was cooking in, add the chopped red onion, saute until translucent. Then add in the mashed blueberry sugar mixture and balsamic vinegar. Cook until the sauce gets thick, about 2-3 minutes.Add in the lime zest and juice and season with salt and pepper. If you put the pork in the oven, remove and place on serving plates. Serve sauce on top and garnish with parsley or cilantro. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(187,'Whole Grain Pumpkin Bread','https://img.spoonacular.com/recipes/665257-556x370.jpg','2 teaspoons baking soda, 1.5 cups firmly brown sugar, 16 ounces pumpkin, 2 teaspoons cinnamon, 2  eggs, 2 cups flour, 1 teaspoon ground cloves, 0.5 cup molasses, 1 teaspoon nutmeg, 1 cup oat bran, 1 cup oil, 0.25 cup pecans, 0.5 teaspoon salt, 1 cup wheat bran, 1 cup wheat germ, 0.5 cup flour','Preheat oven to 375 degrees. Grease 2 loaf pans. Beat oil, brown sugar and molasses until well blended. Blend in egg and pumpkin. Stir flours, brans, wheat germ, soda, cinnamon, cloves, nutmeg and salt into mixture just until moistened. Fold in nuts. Fill pans and bake about 1 hour, until pick comes out clean. Cool on rack. Better if served the day after cooking.',45,45,0);
INSERT INTO "Recipe" VALUES(188,'Baba Gonoush (Egyptian Dish)','https://img.spoonacular.com/recipes/633212-556x370.jpg','0.5 teaspoon pepper, 3 large size brinjal, 4 cloves garlic, 3 tablespoons lemon juice, 0.25 cup olive oil, 5 servings parsley/coriander leaves, 5 servings salt, 0.25 cup tahini','Pierce Brinjal with the help of fork, Then grill over a flame till tender. Check tenderness by inserting fork in skin. It takes around 20-30 minutes.Cut grilled Brinjal in two parts and scoup out flesh/pulp.Add Tahini, Lemon juice, Olive oil, Garlic , salt and pepper and process in an electical processor.Baba Gonoush is ready. Garnish with Olive oil and Fresh Parsley/Coriander leave and serve with Pita breadd/khubz.',45,45,0);
INSERT INTO "Recipe" VALUES(189,'Thai Cucumber Salad (By Roz)','https://img.spoonacular.com/recipes/663100-556x370.jpg','1 tablespoon cilantro, 2  cucumbers, 0.5  jalapeno pepper, 2 tablespoons lime juice, 1  lime zest, 0.25 cup onions, 6 servings pepper flakes, 0.5 cup rice wine vinegar, 0.5 cup chop roasted peanuts, 1 teaspoon salt, 2 tablespoons coconut & sesame oil, 1 tablespoon soy sauce, 0.25 cup sugar, 1 tablespoon thai garlic chili pepper sauce, 0.25 teaspoon pepper','Blend all the dressing ingredients together.Mix in all of the chopped vegetables, herb, and peanuts (if you want the peanuts).Add more of any of the flavors that you prefer, which is the true Thai way.Garnish each plate with cilantro leaves and sliced limes.Serve with a patter of add-ins:Lime slices, red pepper flakes, chopped cilantro, chopped peanuts, Thai sweet chili sauce, sugar, salt, etc. for your guests to add more of their favorite flavors.',45,45,0);
INSERT INTO "Recipe" VALUES(190,'Tart Raspberry Sorbet with a Hint of Heat','https://img.spoonacular.com/recipes/716198-556x370.jpg','1 pinch cardamon powder, 1 small chili, 1  juice of lime, 1.5 cups raspberries, 2 tablespoons raspberry jam, 2 tablespoons grape juice','Combine all of the ingredients in a food processor and process until smooth. Push the mixture through a strainer to remove most of the seeds from the raspberries. Transfer the mixture to a container, cover, and transfer to the freezer. Every few hours, check to see how it is setting and mix it around a little. Near the end of the freezing time, you may want to shape it into balls with an ice cream scoop or large spoon.*When the mixture is frozen, it is ready to eat. You may want to let it thaw for a few minutes before serving, depending on how cold your freezer is and how solid the sorbet is.*Note: I let the sorbet freeze overnight and then let it thaw for a few minutes until I could scoop it out of the container to serve.',45,45,0);
INSERT INTO "Recipe" VALUES(191,'Peach Melba','https://img.spoonacular.com/recipes/655130-556x370.jpg','1  sponge cake, 4 tablespoons brandy, 8  peach halves, 4 scoops vanilla ice-cream, 100 servings whipped cream, 1 tablespoon almonds, 1 cup raspberries, 4 teaspoons sugar, 1 teaspoon lemon juice',replace('Split cake in half to a thickness of about 3cm and cut 1 half into 4 rounds, roughly the size of a peach half.\nDice half the peaches.\nPlace a round of sponge cake in each glass dish and soak with brandy. Place a peach half on sponge, hollow side up, and place a scoop of ice cream on each peach.\nPour raspberry syrup over ice cream, decorate with whipped cream and chopped nuts and scatter round diced peach and extra fresh raspberries.\nRaspberry syrup:Place ingredients in blender and puree until smooth. Place in a small saucepan, bring to the boil and simmer 2 minutes. Cool before using.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(192,'Baked Eggs With Asparagus and Sun Dried Tomatoes','https://img.spoonacular.com/recipes/633595-556x370.jpg','2 large eggs, 2 large egg whites, 2 tablespoons sun tomato, 2 tablespoons onion, 1 teaspoon thyme, 0.5 cup quark, 2 tablespoons parmesan cheese, 8 small spinach',replace('Preheat oven to 375.\nSteam asparagus until tender.\nWhip eggs with quark, thyme and salt and pepper to your taste.\nHeat non-stick skillet over medium heat and spray with cooking spray. Saute onion and tomato for 4 minutes until onion is translucent.\nSpray small baking dish with cooking spray and add onion and tomato. Add eggs. Top with spinach or asparagus and parmesan cheese.\nBake for 10 - 15 minutes until egg is set.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(193,'What to make for dinner tonight?? Bruschetta Style Pork & Pasta','https://img.spoonacular.com/recipes/715538-556x370.jpg','3 cups bow tie pasta, 0.5 cup parmigiano reggiano, 5 servings "Recipe" makers chicken bruschetta pasta, 1.5 lb pork chops','wash and rinse pork chops and place into the skillet.cut them into bite sized pieces and add half of the Basil Garlic simmer sauce.boil your water and start working on cooking your bow-tie pasta.when you have finished with boiling and draining your pasta, add it to the pork along with the rest of the Basil Garlic Simmering Sauce, mixing lightly.Next you will top with the Chunky Bruschetta Finishing Sauce, cover with Parmesan, and cover. Cooking on low heat 2 to 3 minutes or until heated through.',35,35,0);
INSERT INTO "Recipe" VALUES(194,'Blueberry-Lavender Sauce and Ginger Snap Ice Cream Cups','https://img.spoonacular.com/recipes/635561-556x370.jpg','1 pound berries, 1 teaspoon lavender buds, 1 cup sugar, 1 tablespoon cornstarch, 2 teaspoons lemon juice, 1 pinch salt, 12 ounces ginger snap cookies, 1 stick butter, 1.5 tablespoons sugar, 1 pinch salt, 12 servings ice cream',replace('In a small sauce pan, bring the blueberries, lavender, sugar and cornstarch to a boil.\nLower heat and simmer for 5 minutes. Remove from heat the stir in lemon juice and a dash of salt.\nThis sauce is also great for pancakes, pound cake or cheesecake!\nGingersnap Ice Cream Cups: Preheat the oven to 300 degree F. Grind the cookies in a food processor. If you don''t have a food processor, place them in a zip bag and roll them with a rolling pin.\nMix in the butter, sugar and salt. Spray a muffin tin with non-stick spray. Scoop about 2 Tb. of the mixture into each cup. Use a small cup to press each scoop of mixture, shaping it into a tiny cup. Bake the cups for 12-15 minutes. Allow them to cool, then lift them out with your fingers or a small knife. Makes 10-12.\nPlace one scoop of ice cream in each cup and top with blueberry-lavender sauce.\nThis "Recipe" is especially good with vanilla bean, lemon curd, or peach ice cream!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(195,'Mango Guacamole','https://img.spoonacular.com/recipes/650789-556x370.jpg','2  hass avocados, 1  mango, 1 medium onion, 2  serrano chiles, 1 clove garlic, 2  juice of lime',replace('Chop mango, onion, and garlic.\nSeed and chop chiles.\nChop avocados, and put into a bowl.\nZest limes and reserve zest on the side.\nRoll limes (to activate the juice).\nCut limes in half, and squeeze all of the juice into the bowl with the avocados.\nGive the bowl a good stir.\nCombine mango, onion, garlic and chiles into the avocado mixture.\nAdd the reserved lime zest, and stir everything together until the preferred consistency is reached.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(196,'Moist Vegan Spelt Bran Muffins','https://img.spoonacular.com/recipes/652239-556x370.jpg','0.25 cup ground flaxseed, 0.5 cup water, 1 cup wheat bran, 1 cup spelt bran, 0.5 cup spelt flakes, 1 cup spelt flour, 0.5 cup psyllium fibre husks, 0.5 teaspoon stevia extract powder, 0.25 cup flaxseeds, 2 tablespoons chia seeds, 2 teaspoons baking soda, 0.5 teaspoon sea salt, 0.5 teaspoon nutmeg, 1 teaspoon cinnamon, 0.25 cup demerara sugar, 3 tablespoons agave nectar, 0.33333334 cup applesauce, 2  equivalent of eggs in ener-g egg replacer powder, 1 cup vegan" milk, 0.33333334 cup canola oil, 0.5 cup raisins, 0.33333334 cup prunes',replace('Preheat oven to 400F, line 24 muffin cups or grease well.\nIn a small bowl, whisk together flaxseed and hot water. Let stand 10 minutes.\nIn a medium bowl whisk together brans, spelt flakes, flour, psyllium, stevia, flaxseeds, chia seeds, baking soda, salt, nutmeg and cinnamon.\nIn a large bowl beat together sugar, agave, applesauce, egg replacer, flax mixture, "milk" and oil until smooth.\nAdd dry ingredients and stir in just to combine, then fold in the raisins (with their reserved liquid) and prunes.\nBake for 15-17 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(197,'Chapchae (Korean Stir-Fried Noodles)','https://img.spoonacular.com/recipes/637440-556x370.jpg','8 ounces sweet potato vermicelli noodles, 1  onion, 2 cloves garlic, 0.5 pound baby spinach, 2  carrots, 3  scallions, 5  mushrooms, 0.5 cup zucchini, 2 tablespoons olive oil, 2 tablespoons sesame oil, 3 tablespoons soy sauce, 1 teaspoon sugar, 4 servings salt',replace('Cook noodles according to package directions\nIn a large pan or wok over medium heat, heat olive oil and 1 Tbsp sesame oil\nAdd onion slices and garlic and saut for about 1 min\nAdd rest of vegetables and cook for 4-5 min, until the vegetables are half-cooked and still a bit crispy\nTurn heat to low and add cooked noodles, soy sauce, sugar, and the remaining sesame oil\nMix to combine and cook for another 2 min\nAdd salt or more soy sauce if needed (or if you want it a bit sweeter, add a touch more sugar)\nIf using sesame seeds, add them at finish','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(198,'Turkey Sausage, Chard & Sweet Potato Breakfast Scramble','https://img.spoonacular.com/recipes/664054-556x370.jpg','3  baby portabella mushrooms, 6 ounces diestel breakfast sausage, 2 stalks rainbow chard, 6  eggs, 2 stalks green onion, 2 teaspoons olive oil, 0.5  sweet potato, 0.25 cup water','In a medium-sized skillet, heat about two teaspoons of olive oil on medium heat. Add the chopped sweet potato and saut 3 or 4 minutes before adding a little liquid and covering. In about 2 minutes, check to see if the liquid has burned off. If it has, add a little more and cover again. Repeat this several times until the sweet potato is soften, but still al dente. Add the mushrooms and the chopped chard stems. Saut another 3 to 5 minutes and add additional liquid if necessary.Move the veggies to one side of the skillet with a wooden spoon and add the ground breakfast sausage. Brown the meat and using the wooden spoon break it apart. Continue sauting until the sausage is cooked all the way through.Immediately add the green onion and chard leaves. Allow to steam for about 30 seconds before pouring the scrambled egg mixture evenly over the meat and veggies. This is where the technique comes in. Avoid the temptation to stir. Simply allow the skillet to sit 2 to three minutes. Then, using a wooden spoon or spatula, begin flipping sections of egg and veggies (similar to how you would fold whipped egg whites into a cake batter, just gently fold the scramble onto itself). Once all sections have been flipped over, everything to sit and cook another 2 or 3 minutes. Repeat the flipping.  Continue doing this until the egg is no longer cooking to the skillet.Serve with your favorite toppings!',45,45,0);
INSERT INTO "Recipe" VALUES(199,'Spanish Meatballs In Tomato Sauce','https://img.spoonacular.com/recipes/660868-556x370.jpg','1  bay leaf, 2 cloves garlic, 1 pound ground beef, 1 cup olive oil, 2 tablespoons olive oil, 0.5 cup onion, 20 servings half an onion, 2 tablespoons parsley, 1 pinch pimenton de la vera, 20 servings salt and pepper, 1 teaspoon sugar, 600 g tomatoes, 4 slices sandwich bread, 1 large egg','Start by making the tomato sauce.Finely chop 1 onion.Peel 600g of tomatoes with a serrated peeler. Chop the peeled tomatoes into small pieces.Add 2 tablespoons of olive oil in a sauce pan. Add the chopped onions.Add a pinch of Pimenton de la Vera (Dulce), which is Spanish smoked sweet paprika. I used 1/4 teaspoon. Add more if you prefer the sauce to be spicy.Add the chopped tomatoes to the onions mixture and stir well to combine.Add 1 fresh bay leaf. I used 2 dried pieces here because I couldnt find fresh ones.Add 1 teaspoon of sugar andd salt and pepper to taste. I added 1/2 teaspoon of salt and 1/4 teaspoon of ground black pepper. Adjust seasoning to taste.Cover the sauce pan and reduce the heat to a medium-low and let the tomato mixture simmer gently till it reduces to a sauce like consistency.In the meantime, make the meatballs by adding 1/2 an onion to a food processor.Add 2 cloves of garlic. I used 1 tablespoon of minced garlic. Process till the onions and garlic are finely chopped.Sweat the onion-garlic mixture in a frying pan with some olive oil. I just realised that I had missed this step. The meatballs still tasted great.Add the onion-garlic mixture to 500g ground beef in a mixing bowl.Slice off the crust of 4 slices of white bread. Cut the soft white bread into small cubes of 1cm all round.Add the chopped bread to the beef mixture.Add 2 tablespoons of chopped parsley. Use Italian flat parsley where possible. I couldnt find any, so I used English parsley.Add 1 large egg.Add salt and pepper to taste. I used approximately 1/4 teaspoon of salt and a pinch of black pepper.Mix well to combine.Shape the meat mixture into balls that are slightly bigger than the size of a golf ball size. Roll the meat tightly to form meatballs.Add 3/4 cup of olive oil to frying pan. The layer of oil should be approximately 3/4cm in the pan.Put the pan on medium-high heat and add the meatballs to the oil. Gently roll them around in the oil to brown all surfaces and ensure even cooking.When the meatballs are a deep golden brown, remove them from the frying pan and set aside.The tomatoes-onion mixture should have reduced to a sauce consistency now. You can use a hand blender to puree the mixture. Or leave the small bits of tomatoes and onions as they are.Add the meatballs to the tomato sauce and let the meatballs warm through.Garnish with more chopped parsley.',45,45,0);
INSERT INTO "Recipe" VALUES(200,'Cannoli Cream-Filled Strawberries','https://img.spoonacular.com/recipes/716409-556x370.jpg','2 ounces cream cheese, 24  strawberries, 1 tsp honey, 0.25 tsp lemon zest, 2 T powdered sugar, 1.25 cup ricotta, 0.5 tsp vanilla','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(201,'Chocolate Chip Peanut Butter Banana Cookies','https://img.spoonacular.com/recipes/638940-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 2  bananas, 0.5 cup brown sugar, 1 Tbs butter, 1 cup chocolate chips, 0.5 teaspoon cinnamon, 0.5 cup creamy peanut butter, 1  egg, 1.25 cup flour, 1.25 cup granulated sugar, 0.5 teaspoon salt, 1 teaspoon vanilla','Preheat oven to 350 degrees.In a large bowl, mash 2 ripened bananas.Add butter, peanut butter, both sugars, egg, vanilla and stir.In a separate bowl, whisk together flour, baking powder, baking soda, cinnamon and salt.Add dry ingredients to banana mixture and stir until combined (do not stir this to death!)Add mini chocolate chips and briefly stir.Drop by large spoonful onto parchment lined baking sheet.In a small bowl, pour 1/4 cup of sugar and 1/2 tsp of cinnamon and stir.  Sprinkle over unbaked cookies.Bake for 10-12 minutes or until slightly golden brown.  My oven is hot, and only needs 10 minutes.  ',45,45,0);
INSERT INTO "Recipe" VALUES(202,'Chile Underground''s Texas Caviar','https://img.spoonacular.com/recipes/638533-556x370.jpg','1 ounce quality balsamic vinegar, 15 oz black beans, 15 oz blackeyed peas, 1 can corn, 0.5 bunch cilantro, 2 cloves garlic, 1 pint super-sweet grape tomatoes, 1  bell pepper, 1 teaspoon ground cumin, 3  jalapeño chiles, 1 ounce olive oil, 1 ounce olive oil, 1 teaspoon oregano, 2 oz red wine vinegar, 0.5 teaspoon salt, 1 bunch scallions, 0.5 large onion','Heat the oil in a large skillet over medium-high heatAdd onion and cook for just a minute or two with stirringAdd bell pepper and stir for another minuteAdd minced chiles and tomatoes and stir for only a couple of minutes, to slightly soften the tomatoesAdd the garlic and stir for 30 seconds or soTransfer skillet contents to a large mixing bowlCombine in the peas, beans and cornStir in the sliced scallions; set asideIn a small mixing bowl, combine remaining ingredients and whisk until smoothPour sauce over the CaviarTake most of the cilantro leaves and mince themAdd minced cilantro to the CaviarRefrigerate for at least 2 hours.Garnish with remaining cilantro leavesServe with hearty corn chips (no wimpy chips allowed!)',180,180,0);
INSERT INTO "Recipe" VALUES(203,'Oreo Cookies & Cream No-Bake Cheesecake','https://img.spoonacular.com/recipes/654028-556x370.jpg','1 pound cream cheese, 2 cups heavy cream, 2 tablespoons lemon juice, 0.75 cup oreo cookies, 0.5 teaspoon salt, 0.6666667 cup sugar, 2 teaspoons vanilla powder','Beat heavy cream until medium peaks form. Set aside.Add cream cheese, sugar, salt, vanilla powder, lemon juice to a bowl and beat with a paddle attachment until smooth (approximately 3-5 mins). If you do not have a stand mixer or a paddle attachment a hand beater will work as well, but will take twice as long to achieve a smooth consistency.Add cream cheese mixture to heavy cream and beat until incorporated.Gently fold in crushed Oreo cookies.Fill chosen pan with a slight mound at the center, as the cheesecake will become slightly sunken at the center.Refrigerate for at least 6 hours to set or overnight for best results.Remove from refrigerator and smooth top to level with edges. Serve with whipping cream and garnish with mini Oreos.',45,45,0);
INSERT INTO "Recipe" VALUES(204,'Caldo Verde - Portuguese Kale Soup','https://img.spoonacular.com/recipes/636787-556x370.jpg','0.5 large onion, 3  carrots, 3  garlic cloves, 4 large potatoes, 2  chorizo links, 4 cups chicken stock and 2 cups of water, 1 bunch kale, 1 cup of water and 2 packets of chicken boullion, 4 servings pepper flakes, 4 servings salt and pepper',replace('Chop your onions, slice your carrots and smash your garlic. Set aside.\nPeel and chop the potatoes. Set aside in a bowl of cold water.\nRemove the casing from your chorizo. This is an important step. Chorizo casing is tough and unforgiving and will make the sausage link curl during the cooking process. Just remove it and don''t worry about appearance. Cut the links length-wise then chop into half-moons. Sautee in a separate pan until the are nice and browned. Don''t put into the pot until the last minute, otherwise the color of the chorizo will leach into the soup turning it a weird red color.\nNow it''s time to prepare the kale. With each individual leaf, cut out the stem. You can do this several ways. Cut a triangle out of the leaf, or fold over the leaf and cut out the stem that way. Or rip off the halves of the leaves off the stem. I like a little bit of stem to give some crunch and texture.\nTightly roll the leaf into a bundle.\nRun your knife over it to julienne the leaf into thin strips.\nDon''t worry if it''s not perfect. Set aside the kale.\nIn a big pot, sautee your onions, carrots and garlic in a bit of olive oil.\nOnce the vegetables start to soften, add the potatoes and some crushed red pepper flakes. Stir the pot and cook the potatoes until the outer edges start turning clear.\nThen add the 6 cups of water and 2 bouillion packets (or 4 cups of broth and 2 cups of water) to the pot. Bring to a boil then let simmer until the potatoes are cooked.\nWith a wooden spoon, mash the potatoes against the side of the pot. Do this until almost all the chunks of potatoes are mashed. Leave some chunks behind. This will give your soup a wonderful hearty texture.\nNow it''s time to add the Kale. It looks like a lot and will fill up your whole pot but not to worry because it wilts down pretty quickly.\nCook for 5 minutes at a simmer then stir in chorizo sausage. Serve hot or at room temperature (the latter is my favorite). Eat with a nice crusty loaf of Portuguese bread. Enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(205,'Blast Of Color Mexican Stuffed Bell Peppers','https://img.spoonacular.com/recipes/635291-556x370.jpg','4 large bell pepper, 1 cup black beans, 2 cups rotisserie chicken breast, 2 tablespoons chile, 2 teaspoons chili seasoning, 1 cup brown rice, 1 cup corn kernels, 4 servings garlic, 4 tablespoons cheddar cheese, 0.25 cup onion, 1 large roma tomato, 4 tablespoons cream','Preheat oven to 400 degrees.Combine rice, chicken, corn, tomato, onion, black beans, 1/2 cup cheese, garlic, green chile, and chili seasoning in a large bowl.Line a baking dish with foil and spray with cooking spray.Stuff bell peppers with chicken mixture by firmly pressing mixture into the pepper and mounding on top.Top each pepper with 1/2 tablespoon of cheese.Bake for 30  40 minutes until pepper is just tender.Top with 1/2 tablespoon sour cream.',45,45,0);
INSERT INTO "Recipe" VALUES(206,'Falafel Burgers','https://img.spoonacular.com/recipes/642540-556x370.jpg','2 cans garbanzo beans, 1 tablespoon chili powder, 1 tablespoon coriander, 1 tablespoon cumin, 4 tablespoons flour, 1 large handful parsley, 2 cloves garlic, 2  juice of lemon, 4  pita pockets, 1 small onion, 4 servings salt and pepper, 0.5 cup tahini, 1.5 teaspoons turmeric, 0.25 cup vegetable oil, 3 tablespoons water','Combine the chickpeas, onion, garlic, parsley, flour, spices, and salt, and pulse until the mixture is well combined. Form the mixture into 4 large patties.Heat the oil in a large, nonstick skillet set over medium-high heat. Cook for about 3 minutes per side.Make the tahini sauce: Whisk the tahini paste with the water, lemon juice and zest, salt, and freshly ground black pepper in a mixing bowl.Serve the burgers in pita pockets or on a bun. Top them with tahini sauce, lettuce, and tomato.',45,45,0);
INSERT INTO "Recipe" VALUES(207,'Scotch Eggs','https://img.spoonacular.com/recipes/659581-556x370.jpg','1 pound bulk sausage, 1 cup corn meal, 9  eggs','Divide sausage into 8 portions. On a lightly crumb sprinkled surface, pat out each portion to about 1/8 inch thickness. Wrap 1 sausage portion completely around 1 hard boiled egg, pressing edges together to seal. Repeat with remaining sausage and hard boiled eggs.Dip sausage-covered eggs in 1 beaten egg and then roll in breadcrumbs.Deep fry or place on baking sheet and bake in a 375 degree oven for 20 minutes until lightly browned.',45,45,0);
INSERT INTO "Recipe" VALUES(208,'How to Make an Amazing Chicken Salad with Apples and Celery','https://img.spoonacular.com/recipes/1160166-556x370.jpg','3 stalks celery, 2.5 cups rotisserie chicken cut, 2 tbsp reduced fat mayo, 0.5 cup non-fat greek yogurt, 1 cup apples i use 2 granny smith apples, 2 tsp lemon juice squeezed, 3 servings avocado',replace('Instructions\n\nMix chicken, celery, and apples. \n\nIn a separate bowl mix mayo, yogurt, and lemon juice. Mix well.\n\nCombine chicken mixture with mayo mixture and stir well. Add salt and pepper to taste.\n\nOPTIONAL: Slice an avocado, remove the pit, and serve the chicken salad with avocado. It''s so good! ','\n',chr(10)),10,10,0);
INSERT INTO "Recipe" VALUES(209,'The Best Chicken Salad Sandwich','https://img.spoonacular.com/recipes/663219-556x370.jpg','3  chicken breasts, 1 stalk celery, 2  green onions, 0.5 cup grapes, 0.75 cup cranberries, 0.5 cup almonds, 0.75 cup mayonnaise, 1 tablespoon celery seeds, 1 teaspoon each: paprika and salt, 4 servings coarsely ground pepper, 4 servings bread',replace('Cut chicken into bite sized pieces.\nChop up grapes, celery, and onion.\nToast slivered almonds on the broil setting in the oven.  Watch them like a hawk--I have burned more almonds, coconut, pecans than I can count.\nThrow this all together with the chicken.  Add salad dressing, celery seed, paprika and pepper to taste.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(210,'Hush Puppies','https://img.spoonacular.com/recipes/1098392-556x370.jpg','1 small onion, 1.5 cups cornmeal, 0.5 cup flour, 1 tablespoon baking powder, 0.5 tsp salt, 1  egg, 0.75 cup milk, 6 servings oil','Place the cornmeal, flour, baking powder and salt into a large mixing bowl and stir.Crack the egg into a medium mixing bowl and beat it with a fork until it is well mixed.Add the chopped onion pieces and milk to the egg and mix well.Stir the egg, milk, and onion pieces into the cornmeal and flour mixture.Place about 2-3 inches of oil in a deep-fat fryer or skillet over medium-high heat.When the oil is hot, carefully drop the batter into the pan. Use one heaping teaspoon of batter for each hush puppy.  You may fry 5-6 hush puppies at once.The hush puppies will sink into the hot oil.  Then they will rise to the top.  After 1-2 minutes, the hush puppies will be golden brown.Use a slotted spoon to remove the hush puppies.  Let them drain on paper towels.',30,30,0);
INSERT INTO "Recipe" VALUES(211,'Roasted Acorn Squash Stuffed W/spicy Biryani (Veg/vegan)','https://img.spoonacular.com/recipes/658482-556x370.jpg','4  acorn squashes, 0.5 cup basmati rice soaked in water, 1 cup water, 3 tablespoons garam masala, 1 medium onion, 4 small peppers, 1 handful cashew nuts- a bit, 4 servings saffron, 1 handful cilantro, 4 tablespoons biryani paste- "Recipe" below, 1 medium onion, 4 servings salt, 4 servings coarse pepper, 4 servings pam original flavor, 1 tablespoon vegetable oil, 1 medium onion, 1  beefsteak tomato, 4 cloves garlic, 2 tablespoons ginger, 1 tablespoon chili powder, 1 handful cilantro, 5 tablespoons hefty biryani paste, 0.5 tablespoon vegetable oil',replace('Preheat the oven to 400 degrees. On a baking sheet place the squash halves, spray with PAM and sprinkle with 1-2 tbsp garam masala. Place in the oven and BROIL till tender and charred- about 10-15 minutes.\nWhile the squashes are roasting, in a large skillet, spray with PAM and add vegetable oil and set over medium heat. Add the cashews and saute until fragrant and slightly darkened. Add onions and peppers, sprinkle with black pepper and saute until soft, about 5-7 minutes. Once the onions and peppers are soft, but now brown, add the soaked basmati rice (make sure not to get any water in it!). Saute for 5-7 minutes. You want to toast the the rice.\nRemove the squash from the oven and cool for a few minutes before handling. Score the squash into small cubes, WITHOUT cutting through the skin. Scoop the cubes out into a bowl and set aside. Keep the shell aside, DONT throw out!\nOnce the rice is toasted add 1 cup of water, pinch of saffron, cover and cook on medium-low heat, about 15 minutes. You want the rice to be cooked thru, not mushy so dont mix it around too much! Once the rice is cooked, add the cubed squash, tossing gently (you dont want the squash to break and mush around the rice). Add the Biryani paste and toss to coat. Mix in 3/4 of the chopped cilantro. Taste for salt and biryani flavor- it should be strong, spicy and aromatic.\nIn a small skillet, spray with PAM and set over medium-high heat. Add onion slices, and saute without breaking up the circles. Cook until brown-ish about 4-5 minutes. Set aside.\nFill each squash bowl with rice, just coming over the top. Top each one with an onion round and sprinkle with remaining chopped cilantro. Serve with yogurt or raita.\nBiryani paste:\nIn a medium skillet, spray with pam, add oil and set over medium-high flame. Add onions and tomatoes, saute until golden-brown about 4-5 minutes. Add garlic, ginger, chili powder and cilantro. Saute until vegetables are soft and fragrant about 4-5 minutes. Add the biryani paste and mix well, making sure all the veggies are coated. Remove from the heat and let cool (10-15 minutes).\nIn a grinder/food processor, add the biryani mixture and grind until smooth (slightly chunky is ok). Store in an air tight container. Can be kept in the fridge for 1-2 weeks, or in the freezer- for a while!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(212,'Lebanese Tabouleh','https://img.spoonacular.com/recipes/649411-556x370.jpg','3 tablespoons bulgur wheat, 3 cups flat leaf parsley, 1 tablespoon mint, 3 tablespoons green onions, 1  juice from lemon, 2 tablespoons olive oil, 0.25 cup roma tomatoes','Remove stems from parsley and mint. Rinse leaves in a colander. Pat dry with paper towel.In a food processor pulse parsley and mint until finely chopped. Transfer to a large mixing bowl.Add green onions, tomatoes and bulgur wheat; stir to combine.Toss with lemon juice and olive oil. Refrigerate for an hour before serving.Serve on its own or with pita breadServes 2',45,45,0);
INSERT INTO "Recipe" VALUES(213,'Penne Arrabiata','https://img.spoonacular.com/recipes/655573-556x370.jpg','14.5 oz tomato, 3 tablespoons parsley, 2 Cloves garlic, 2 tablespoons olive oil, 14 oz pkt penne, 2  peppers','Bring a large pot of water to a boil. Saute about 1 teaspoon of dried red pepper in a 3 tbsp. olive oil. Add 5 cloves fresh minced garlic, 2 tbsp.Fresh Italian parsley, minced.When these ingredients are not, but not smoking, add 1 can tomatoes, chopped. (I like Pomi tomatoes which comes in a box). Stir, cover and cook untilthe sauce i heated. Cook the Penne in salted boiling water. Cook until al dante. Drain and add to sauce. Mix throughly Just before serving, add some coarsely chopped fresh basil and a little more parsley. Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(214,'Tomato Free Mexican Lasagna','https://img.spoonacular.com/recipes/663595-556x370.jpg','8 small corn tortillas, 1 pound extra ground beef, 1 small onion, 3 large garlic cloves, 1  portobello mushrooms, 4 ounces chilies [use jalapenos if desire more spicy], 1 cup black beans, 1 cup corn, 0.5 teaspoon oregano, 0.5 teaspoon chili powder, 0.25 teaspoon garlic powder, 1.25 teaspoons cumin, 0.5 teaspoon ground pepper, 1 teaspoon kosher salt, 0.5 cup reduced fat mexican blend cheese, 1 cup iceberg lettuce, 10 servings avocado',replace('Preheat oven to 350 degrees. Spray a non-stick skillet with non-stick cooking spray and heat on medium. Add beef, onion and mushrooms and cook until meat is cooked through. Drain if needed, I bought extra lean beef and there was no grease to drain today. Add garlic and cook another minute. Add beans, diced green chilies, corn, oregano, chili powder, garlic powder, cumin, pepper and kosher salt. Mix thoroughly.\nSpray a 9 x 13 pan with non-stick cooking spray. Lay half of corn tortillas on bottom of pan. Add half of the beef mixture and 1/2 c of cheese. Layer remaining corn tortillas and top with beef mixture and 3/4 c cheese. Bake in oven uncovered for 15 minutes.\nAfter cooking sprinkle with diced avocado and lettuce. Slice and serve and add a dollop of sour cream on top of slice.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(215,'Pancit Bihon (Filipino Pancit)','https://img.spoonacular.com/recipes/654504-556x370.jpg','250 grams rice vermicelli soaked in water, 1 tablespoon oil, 0.25 cup fried bacon, 1 medium onion, 6 cloves garlic, 20 pieces prawn, 150 teaspoons pork but shoulder thinly marinate, 150 teaspoons chicken breast thinly marinate, 2.5 cups chicken broth, 1 tablespoon soy sauce, 1 tablespoon soy sauce, 1 tablespoon oyster sauce, 2 teaspoons ground pepper, 1 teaspoon sugar, 1 teaspoon sesame oil, 0.5 cup shitake mushroom, 0.5 cup carrot julienne cut, 0.5 cup peas julienne cut, 1 cup cabbage',replace('Heat a saucepan,put 1 tbsp oil and fry the bacon until brown.Set Aside\nAdd 3 tbsp oil to the sauce pan and caramelized onion then add garlic\nSaute until aroma comes out then add the pork slices,cook stir frying for 10 minutes\nAdd chicken and prawn,saute for 10 minutes.\nThen add in rice vermicelli,fried bacon,shitake mushroom,chicken broth,light soy sauce,thick and dark soy sauce,oyster sauce,ground pepper and sugar.\nCook in medium heat for about 10 minutes\nThen add the veggies:carrot,cabbage and sweet peas.\nCook for another 5 minutes or until the rice noodle is cook.\nDrizzle with sesame oil\nServe hot with Lumpiang Shanghai and soy calamansi dipping.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(216,'Creamy Mushroom Soup ~ with a “Kick”','https://img.spoonacular.com/recipes/640663-556x370.jpg','0.25 pound bacon, 1 quart button mushrooms, 8 servings cilantro, 1 large clove garlic, 0.5  juice of lime, 1  long pepper, 3 cups milk, 8 servings olive oil, 1 cup potato buds, 8 servings cheddar cheese, 0.5  onion, 1 cup vegeta bouillon - plus 6 of water','Heat a large saucepot with a drizzle of olive oil. Place the garlic, long hot pepper, onion and mushrooms in the pot to saut until the onion is clear.Prepare the bacon on a heated griddle and let the bacon get nice and crispy. When the bacon is done set it aside.Add the tablespoon of bouillon and the cups of water to the pot and simmer. Add the cup of potato buds, stir and continue to simmer on low. Add the cups of milk and simmer on low for a few more minutes.When the soup is ready to be served add the lime juice and stir. Top the soup with the bacon bits, cilantro and cheddar cheese.',45,45,0);
INSERT INTO "Recipe" VALUES(217,'Pasta with Garlic, Scallions, Cauliflower & Breadcrumbs','https://img.spoonacular.com/recipes/716429-556x370.jpg','1 tbsp butter, 2 cups cauliflower florets, 2 tbsp cheese, 1 tbsp extra virgin olive oil, 5 cloves garlic, 6 ounces pasta, 2 pinches couple of pepper flakes, 2 servings salt and pepper, 3  scallions, 2 tbsp white wine, 0.25 cup bread crumbs','No instructions provided.',45,45,1);
INSERT INTO "Recipe" VALUES(218,'Tapioca Pudding with Pineapple and Coconut','https://img.spoonacular.com/recipes/662871-556x370.jpg','200 ml .8 fl oz. coconut milk, 2  egg yolks, 250 ml .5 fl oz. full milk, 2 tsp honey, 1  lime, 250 gr .8 oz. pineapple, 1 pinch salt, 1 tbsp sugar, 65 gr .3 oz. of pearl tapioca, 1  vanilla pod','The place to start is with the tapioca, the pudding is a custard. So, in a heavy bottomed saucepan add the full milk, salt, tapioca, the seeds from the vanilla pod, and the empty vanilla pod. Bring this mix to a gentle simmer and stir occasionally. Do this until the tapioca is translucent and tender, this takes about 20 minutes. When cooked, stir in the coconut milk.While the tapioca mix is cooking you can whisk the egg yolks and sugar together in a bowl - quite big as it has to hold half of your tapioca mix too. Mix the egg and sugar together until the color lightens.Taking your cooked tapioca mix from the heat, pour half of it into the bowl with the eggs and sugar, whisk together using a metal hand whisk. Then pour this back into the pan and place on a medium heat.On a medium heat keep whisking until the mix thickens, this takes about 5 minutes or so. It is important not to use too high a heat as the eggs will scramble. The mix will not become really thick, the chilling process with thicken it further. I like to check the sweetness level at this stage, you can add a little more sugar if you wish, but if you do, stir it through until it dissolves. Put your tapioca pudding in a clean, cool bowl, remove the vanilla bean and set aside to cool. When it has cooled, cover with cling film and put in the fridge.Now for the pineapple. Combine the fruit with the honey, lime juice and most of the zest. Keep back a little lime zest to dress.Place half of the mix in a food processor and blend until smooth. Transfer this back into the bowl with the rest of the pineapple and stir together  check the flavour and add more honey or lime if you wish.Once your tapioca has chilled, place some of the pineapple mix in the bottom of your serving dishes, then add the tapioca and top with a little pineapple and some lime zest to finish.',60,60,0);
INSERT INTO "Recipe" VALUES(219,'Vegan Beet Borscht','https://img.spoonacular.com/recipes/664396-556x370.jpg','1 small beetroot, 1  big carrot, 2  onions, 0.5 cup celery root, 1 tbsp unrefined sunflower oil, 3 tbsp vinegar, 0.5 cup celery leaves, 8 servings sea salt, 0.33333334 tsp ground pepper, 8 servings parsley','Go to my blog for the full instructions: http://gourmandelle.com/vegan-beetroot-borscht/',45,45,0);
INSERT INTO "Recipe" VALUES(220,'Beans Hawaiian','https://img.spoonacular.com/recipes/634545-556x370.jpg','2 cups navy beans, 1.5 cups teriyaki sauce, 1 Tbsp soy sauce, 0.6666667 cup pineapple juice, 0.5 cup brown sugar, 1 Tsp fresly ginger, 6 slices bacon, 1  onion, 1  garlic clove, 1 cup pineapple, 16 oz ham steak',replace('Soak dried navy beans overnight in a large pot. You want the water to be cold and about 2-3 inches above the beans. Cover and refrigerate at least 8 hours.\nDrain and rinse the beans. Place in a large pot and cover by 4-5 inches of fresh water. Bring to a boil, reduce heat and simmer for 1  1 hours until the beans are tender but not bursting.\nIn the meantime, combine teriyaki sauce, soy sauce, pineapple juice, brown sugar and ginger in a medium bowl. Whisk until brown sugar has dissolved. Set aside.\nPreheat oven to 350\nReserving 2 cups of the boiled water, drain the beans.\nIn a large Dutch oven, saut bacon for 3-4 minutes over medium high heat. With a slotted spoon remove bacon and set aside.\nAdd onions to the bacon fat and cook until translucent, about 5 minutes. Add garlic and pineapple and saut for an additional minute, until the garlic becomes fragrant.\nPlace bacon back into the dutch oven and add the cubed ham steak, beans, reserved water, and prepared sauce. Stir well to combine.\nBake in the oven covered for 10 minutes. Reduce heat to 200 and continue to cook for 6 hours, stirring halfway through.\nAfter 6 hours, remove lid, increase heat to 350 and cook for an additional 1-2 hours stirring every twenty minutes until the sauce has thickened.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(221,'Blackberry Honey Cocktail','https://img.spoonacular.com/recipes/635215-556x370.jpg','0.75 ounce home made clover honey syrup, 2 ounces honey vodka, 3  blackberries, 0.75 ounce lemon juice, 3  garnish: blackberry jam',replace('In a pint glass add all spirits and mixers, add ice and shake vigorously for 6 seconds.\nStrain in a Collins glass filled half way with cubed ice.\nTop off with crushed ice. Then crown with hand made jam.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(222,'Asparagus Eggs Benedict','https://img.spoonacular.com/recipes/632928-556x370.jpg','4 ounces asparagus spears, 0.33333334 cup butter, 1 pinch cayenne pepper, 3 large egg yolks, 4 large eggs, 2  muffins, 4 slices ham, 1 tablespoon lemon juice, 0.25 teaspoon salt','Fill a medium saucepan or wide deep skillet 3/4 full with hot tap water.Bring to a boil over high heat. Reduce heat to maintain a gentle boil. Trim off and discard woody ends of asparagus. Place asparagus in shallow microwave-safe casserole dish, cover with vented plastic wrap, and cook at HIGH power 1-1/2 to 2-1/2 minutes or until asparagus are crisp-tender.Cover tightly; set aside in a warm place.Break whole eggs, one at a time, into a small dish. Slip eggs into simmering water. Cook about 3 minutes for soft-set eggs or until cooked as desired.While eggs are cooking, place egg yolks in blender container. Add lemon juice, salt and cayenne pepper. Place butter in microwave-safe measuring cup and cook at HIGH power until melted and bubbly, about 1 to 1-1/2 minutes.With blender running, pour hot butter in a stream through the hole in the lid. Blend 30 seconds or until sauce has thickened.Split and toast English muffins. Place warmed ham on each muffin half and top with about 3 asparagus. Using a slotted spoon, place poached eggs over asparagus. Spoon sauce over eggs.',30,30,0);
INSERT INTO "Recipe" VALUES(223,'Easy Homemade Apple Fritters','https://img.spoonacular.com/recipes/775666-556x370.jpg','1 cup all purpose flour, 1 cup apple, 1.5 teaspoons baking powder, 1 teaspoon cinnamon, 1  egg, 0.33333334 cup milk, 1.5 tablespoons milk, 2 cups powdered sugar, 0.75 teaspoon salt, 0.25 cup sugar','Combine flour, sugar, salt, baking powder, cinnamon. Stir in milk and egg until just combined. Fold in apple. Pour oil into skillet so that it is approximately 1 1/2 deep. Heat oil on high. Oil is ready when a little dough thrown in floats to top. Carefully add dough to oil in heaping teaspoons. Cook until brown, about 2 minutes, then flip. Cook another 1-2 minutes, until both sides are browned. Transfer briefly to paper towels to absorb excess oil, then transfer to cooling rack. Make glaze by stirring milk and powdered sugar together in a small bowl. Drizzle over apple fritters. Wait approximately 3 minutes for glaze to harden, then flip fritters and drizzle glaze over the other side. Best served warm.',30,30,0);
INSERT INTO "Recipe" VALUES(224,'Medenjaci - Croatian Honey Spice Cookies','https://img.spoonacular.com/recipes/651389-556x370.jpg','250 g butter, 180 g demerara sugar, 250 g honey, 3  eggs, 1 tsp baking soda, 2 tsp ground cinnamon, 0.5 tsp ground cloves, 0.5 tsp ground nutmeg, 0.5 tsp powdered ginger, 300 g flour, 100 g flour, 350 g cake flour, 10  walnut kernels',replace('Heat the butter, sugar and honey, stirring constantly, over low heat until the sugar and butter have melted completely. Set aside to cool (10 minutes).\nLightly whisk the eggs.\nMix and combine baking soda, spices, all-purpose, whole wheat and cake flour.\nAdd the lightly beaten eggs, flour and spices to the melted honey, sugar and butter mixture. Mix and combine to obtain smooth and soft dough.\nCover the dough with foil and leave in a cool place for 1-3 days.\nThen divide and roll the dough into long rolls 1.5 cm in diameter, cut them into smaller rolls. Shape each roll into a walnut sized ball.\nPlace the dough balls, few centimetres apart from each other, on a baking sheet lined with parchment paper or a silicon sheet. Insert, only halfway, a quarter of the walnut kernel at the top of each cookie.\nBake the cookies in the oven at 190C for 10-12 minutes. Cool and store in an airtight container.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(225,'Dark Chocolate Cinnamon Easter Eggnog','https://img.spoonacular.com/recipes/641261-556x370.jpg','4  egg yolks, 2 cups milk, 1 cup granulated sugar, 0.25 cup chocolate, 2 tablespoons cocoa powder, 0.25 teaspoon cinnamon, 1 cup heavy whipping cream, 0.25 cup chocolate liqueur, 1 teaspoon vanilla',replace('In a medium saucepan over medium heat, whisk together egg yolks, milk, sugar, dark chocolate, cocoa powder, and cinnamon. When mixture is well combined and just starts to boil and bubble, remove from heat.\nPour mixture in a bowl over an ice bath and whisk for several minutes until cool. Whisk in cream, liqueur, and vanilla. Serve immediately or store in refrigerator.\nTop with whipped cream and cinnamon if desired.\nMakes 4 (about 1-cup servings)\nSNAPPY TIPS: Make sure you whisk the egg yolks and liquids well while over the heat so that the eggs dont curdle.\nSNAPPY SUBSTITUTIONS: If you dont like dark chocolate you could use original unsweetened cocoa powder, and substitute your favorite chopped chocolate for the chopped dark chocolate. You can also substitute any liqueur for the chocolate liqueur.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(226,'Super Speedy Spicy Sweet and Sour Shrimp','https://img.spoonacular.com/recipes/662363-556x370.jpg','4 servings cilantro, 4 servings rice, 3  garlic cloves, 1 piece ginger, 2 tbsp honey, 2 tbsp soy sauce, 1  bok choi, 1  chili pepper, 2 tbsp rice wine vinegar, 550 gr .2 lb shrimp, 4  spring onions to 1 cm / 0.5in. pieces, 2 tbsp sunflower oil, 4 tbsp tomato ketchup','Mix the sauce ingredients together in a bowl, taste it to check if you like the balance of flavour and adjust if you wish.  Set this aside.Heat the oil on a very high heat in a wok. Get the oil as hot as you can, just below smoking point.  Check the heat by dropping a piece of spring onion (scallion) and if it sizzles immediately, the oil is hot enough.Add the chili, garlic and ginger, stir and cook for about 30 seconds.  Add the spring onions (scallions) and cook for a further minute.Add the shrimp (prawns) cook for about 2 minutes or until they turn pink.Add the sauce, keeping the heat high so that as soon as it hits your pan or wok, it sizzles and reduces.When the sauce has thickened a little, add the pak choi, mix through and cover it, cooking only for a minute.Serve with simply boiled white rice and sprinkle with some fresh coriander (cilantro).',45,45,0);
INSERT INTO "Recipe" VALUES(227,'Cranberry-Orange Pistachio Chip Cookies','https://img.spoonacular.com/recipes/640451-556x370.jpg','2 cups flour, 1 teaspoon baking soda, 1 teaspoon salt, 1 cup butter, 0.75 cup granulated sugar, 0.75 cup brown sugar, 1.5 teaspoons vanilla extract, 2 large eggs, 6 ounces nestlé® toll house® premier morsels, 0.5 cup pistachios, 0.5 cup craisins, 0.25 cup candied orange peel',replace('Preheat oven to 375 F.\nCombine flour, baking soda and salt in small bowl.\nBeat butter, granulated sugar, brown sugar and vanilla extract in large bowl until creamy.\nAdd eggs, one at a time, beating well after each addition.\nGradually beat in flour mixture.\nFold in morsels, nuts, dried cranberries and orange peel.\nDrop by rounded tablespoonfuls onto parchment paper lined baking sheets.\nBake for 9 to 11 minutes or until golden brown.\nCool on baking sheets for 2 minutes; remove to wire racks to cool completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(228,'Strawberry Banana Stuffed Pancakes','https://img.spoonacular.com/recipes/661758-556x370.jpg','0.5 teaspoons baking soda, 0.5 cup banana, 2  egg whites, 0.33333334 cups non-fat greek yogurt, 2 servings salt, 10  strawberries, 1.5 teaspoons sugar, 0.5 teaspoons vanilla extract, 0.33333334 cups pastry flour','Mix together the Greek yogurt, 1/4 cup banana, egg whites, and vanilla extract into a small bowl.In a separate bowl combine flour, baking soda, 1/2 teaspoon sugar, and salt.Combine both bowls and whisk until evenly mixed.Fold in 5 fresh, chopped strawberries.Place 1/4-cup batter onto a non-stick skillet over medium heat and cook until bubbles start appearing through the top of the pancake. Flip (about 2 minutes on each side).For the sauce: Add 1/4 cup mashed banana, 5 frozen strawberries, and 1 teaspoon of sugar in a sauce pan (if you use fresh strawberries, add 1 tablespoon of water to the sauce pan). Cook on low, stirring frequently until thickened (about 5-7 minutes.)Evenly divide sauce over top of pancakes',30,30,0);
INSERT INTO "Recipe" VALUES(229,'Chocolate Chip Peanut Butter Mallow Dessert Bars','https://img.spoonacular.com/recipes/638942-556x370.jpg','1 Tbs butter, 9 ounces chocolate chip cookie mix, 2 Tbs chocolate syrup, 1  egg, 1 cup marshmallows, 1 teaspoon milk, 0.25 cup peanut butter','In a mixing bowl stir together the cookie mix, egg, milk and butter until smooth. Grease a 8x8 baking pan and spread the cookie mixture into the bottom. Bake in a 375 degree oven for about 15-20 minutes or until set and brown. Remove from the oven and spread on the peanut butter evenly on the top of the cookie bar then top with the marshmallows. Return the pan back into the oven just until the marshmallows start to melt. Take the pan back out of the oven and spread the marshmallows evenly over the peanut butter and then drizzle with the chocolate syrup. Let cool and cut into squares.',45,45,0);
INSERT INTO "Recipe" VALUES(230,'Amaretto Almond Cookies','https://img.spoonacular.com/recipes/632280-556x370.jpg','0.5 teaspoon almond extract, 0.25 cup amaretto, 2 large eggs, 1 cup ground almonds, 0.5 teaspoon lemon rind, 2 tablespoons molasses, 1 cup butter, 2 cups pastry flour','Cream together butter and molasses. Add eggs, ground almonds, lemon rind and almond extract; mix well. Stir in Amaretto alternately with flour.Drop by teaspoonsful onto unoiled cookie sheets. Bake at 350 degrees for 12-15 minutes. Cookies will be golden brown when done.Makes 36 cookies',45,45,0);
INSERT INTO "Recipe" VALUES(231,'Ultimate Chocolate Chunk Cookies','https://img.spoonacular.com/recipes/715483-556x370.jpg','0.6666667 cup all purpose flour, 1 tsp vanilla flavoring, 0.5 tsp baking powder, 0.25 cup brown sugar, 1 cup chocolate chips, 8 oz chocolate chunks, 2 large eggs, 0.5 cup pecans, 0.5 tsp salt, 1 stick butter','Preheat oven to 350.Mix together in a medium bowl the flour, baking soda, and salt.Carefully soften chocolate chips, butter, and vanilla flavoring in the microwave in 15 second increments, stirring in between, for one full minute.Beat eggs and sugar together until light an fluffy.Reduce blender speed and combine the melted chocolate chips, butter, vanilla, and slowly mix in the flour.Add in the chocolate chunks and pecans until mixed.Drop 1 tablespoon of dough onto cookie sheet, 2 - 3 inches apart and bake for 12-14 minutes, keeping your center soft and chewy. Allow to cool for 10 minutes before moving to a cooling rack to cool completely.',24,24,0);
INSERT INTO "Recipe" VALUES(232,'Grilled Eggplant and Heirloom Tomato Stacks With Basil and Tomato Coulis','https://img.spoonacular.com/recipes/645696-556x370.jpg','15 large basil leaves, 5 servings pepper, 1 large eggplant, 1 small garlic clove, 1 cup mild goat cheese, 2 tablespoons olive oil, 0.25 cup pecorino romano cheese, 8 ounces plum tomatoes, 5 servings salt, 0.75 cup tomato coulis, 2 large garden tomatoes','Prepare Tomato Coulis:Make shallow incisions with a paring knife around the tomato stems and scoop out the stems.Make a shallow X-incision in bottom of tomatoes.Bring a large saucepan of water to a rolling boil.Plunge tomatoes into water for 10 seconds.Remove and submerge tomatoes in bowl of ice water.Remove the cooled tomatoes from the water.Peel away skin.Remove seeds and coarsely chop tomatoes.Combine tomatoes, garlic and olive oil in bowl of food processor.Process until smooth.Add salt and pepper.Let Tomato Coulis stand at room temperature for one hour before serving.Prepare Eggplant:Preheat oven broiler or prepare grill.Lightly brush eggplant slices on both sides with olive oil.Sprinkle with salt and pepper.Arrange on baking tray and grill in oven, turning once, until golden brown, about 3 minutes per side.Or grill on barbecue, turning, until golden brown and cooked through.Arrange Stacks:Combine garlic and goat cheese in a small bowl.Add salt and freshly ground black pepper to taste.Arrange 1/2 of the eggplant slices on platter.Spoon 2 teaspoons goat cheese over.Top with 1 basil leaf.Place second eggplant slice on basil leaf.Top with one teaspoon goat cheese and basil leaf.Lightly drizzle 2-3 teaspoons Tomato Coulis over and around the eggplant stack.Garnish with one teaspoon grated Pecorino Romano cheese.Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(233,'Vegan Banana Nut Muffins','https://img.spoonacular.com/recipes/664392-556x370.jpg','0.75 cup agave nectar, 0.25 cup apple sauce, 1 teaspoon baking soda, 4 medium bananas, 1 cup flour, 1 tablespoon ground flaxseed, 1 pinch salt, 0.5 teaspoon vanilla extract, 4 cups water, 1.25 cups flour','Pre-heat oven to 325 degrees with rack in middle. Mix ground flaxseed with water and set aside.If using a loaf pan: grease & flour a 9x5x3 loaf pan.If making muffins, line with liners or grease & flour muffin pan.Whisk together flours, baking soda, and salt. In separate large bowl, mix together flaxseed mixture, agave, and apple sauce until combined. Add flour mixture and when combined add in vanilla, and bananas. Mix until combined. Fold in 1/2 cup of walnuts and pour into prepared loaf pan. Top with remaining 1/3 cup of nuts.For loaf pan: bake for 45 to 60 minutesFor muffins: bake for 25-30 minutesOr until a thin knife inserted in middle comes out clean.Cool for 10 minutes on wire rack before removing from pan.',45,45,0);
INSERT INTO "Recipe" VALUES(234,'Bing''s Mango Salsa','https://img.spoonacular.com/recipes/634992-556x370.jpg','1.5 cups mangoes, 1  lime zest, 2  juice of lime, 2 tablespoons mint leaves, 2 tablespoons shallots/red onion, 0.5 teaspoon salt, 0.5 teaspoon pepper, 1 teaspoon sugar, 2 teaspoons chilli',replace('Begin by cutting the mangoes into small 1.5cm by 1.5cm cubes.\nPlace the mangoes in a large mixing bowl. Grate the zest of 1 lime into the mangoes.\nSqueeze juice from half a lime into the mangoes. Add more lime juice to taste if required later.\nChop a bunch of coriander leaves (or use mint leaves if you hate the taste of coriander) into fine bits.\nAdd the chopped coriander to the mango mixture.\nStir well to combine. In fact, Suvarna recommended to stir well after the addition of every ingredient.\nCut the shallots or red onion into very thin slices.\nAdd the sliced shallots or red onion to the mango mixture and stir well to combine.\nAdd 1/2 teaspoon of salt or to taste.\nAdd 1/2 teaspoon of black pepper or to taste.\nAdd 1 teaspoon of sugar or to taste.\nStir well to combine and do a taste test. Add lime juice, sugar, salt or pepper as necessary to get a nice savoury sweet tangy flavour.\nFinally add the chopped chillis. Add according to your own heat tolerance. Some chillis are more spicy than others so add a little at a time till you acquire the desired spiciness. Stir well to combine.\nCover the bowl with cling wrap and place bowl in the fridge for at least 1/2 hour for the flavours to combine.\nKeep the mango salsa chilled till ready to serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(235,'Cavatappi pasta with salmon crab surimi','https://img.spoonacular.com/recipes/637325-556x370.jpg','180 g surimi crab sticks, 1 tsp basil, 4 servings basil, 1 Tbs parsley, 2 cloves garlic, 3 tablespoons olive oil, 4 servings parmesan cheese, 400 g pasta, 0.25 tsp pepper, 3  plum tomatoes, 0.25 cup red wine, 250 g salmon fillets, 0.25 tsp salt, 0.5 tsp sugar, 0.75 cup tomato puree','Saut garlic for 1 minute in hot oil, be careful not to burn it.Add salmon and surimi sticks to the pan, stir and simmer briefly.Add chopped tomatoes, tomato paste, herbs and wine, mix and combine.Sprinkle with sugar, and season with salt and pepper; stir and simmer for 2 - 3 minutes.Meanwhile, cook the pasta according to the manufacturer''s instructions, drain (keep a little of the cooking water).Combine the Cavatappi pasta with the sauce. If the sauce is too thick, add a spoonful of pasta cooking water.Serve immediately, sprinkle with Parmesan cheese and fresh, chopped basil.',45,45,0);
INSERT INTO "Recipe" VALUES(236,'No-Bake Chocolate Peanut Butter Pie','https://img.spoonacular.com/recipes/653185-556x370.jpg','2 tablespoons non-dairy cream cheese, 1 cup creamy peanut butter, 0.25 cup chocolate chips, 10  peanut butter cups, 1.25 cups powdered sugar, 0.5 cup roasted peanuts, 5 tablespoons earth balance soy free spread, 3 tablespoons vanilla coconut yogurt, 1.5 containers non-dairy whipped topping','CRUST:Crush the cookies in a food processor until fine crumbs.Transfer to a small bowl and add the earth balance.Combine with a fork, or hands until fully blended and begins to take shape.Press evenly into a 9 inch pie plate. My crust ended at about 1/2 inch before the rim.Chill in the freezer while preparing the filling.FILLING:In a stand mixer set with a paddle attachment, or using a hand held mixer set on medium speed, beat peanut butter with the cream cheese.After about a minute add the coconut yogurt.Once combined, reduce to low speed and add sifted powdered sugar, increase back to medium speed and beat until smooth.Turn off mixer, then add in 1/2 cup peanuts, and broken pieces of peanut butter cups and combine well.Fold in thawed whipped topping until well blended.Pour the filling into the chilled crust and spread evenly.Sprinkle the 3 tablespoons of peanuts, dark chocolate chips, and the reserved cookie crumbs on top.Chill for at least another 90 minutes before serving.Slice with a sharp knife to pierce through all the peanut butter chunks in the pie.',45,45,0);
INSERT INTO "Recipe" VALUES(237,'Breakfast Sticky Buns','https://img.spoonacular.com/recipes/636080-556x370.jpg','0.5 cup brown sugar, 1 tablespoon butter, 1 box butterscotch pudding, 0.5 cup pecans, 1 pkg rich''s rolls','Spray a 10-inch tube pan with a no-stick cooking spray. Spread pecans evenly on bottom of pan. Place rolls on pecans and then sprinkle pudding on top of rolls.Mix sugar into melted butter. Pour this mixture over nuts/rolls/pudding. Cover and let stand overnight. Bake at 350 degrees for 20-25 minutes. Turn over and out onto plate at once.',45,45,0);
INSERT INTO "Recipe" VALUES(238,'Crock Pot Boneless Beef Ribs','https://img.spoonacular.com/recipes/640856-556x370.jpg','1.5 cups beef broth, 4 pounds beef ribs, 0.5 cup brown sugar, 0.25 cup butter, 0.6666667 cup flour, 1 cup ketchup, 0.5 cup mustard, 1  onion, 0.5 teaspoon pepper, 2 teaspoons salt, 2 tablespoons tabasco sauce','In a large zippy bag place the flour, salt &amp; pepper, mix to combine. Add the ribs in batches and shake to coat. In a large frying pan melt the butter and brown the ribs on all sides, transfer the browned ribs to the bottom of a 5 qt crock pot. In the same frying pan combine the remaining items and bring to a boil, pour over the ribs. Cover and cook on low for 10-12 hours or until meat is tender and falling apart. Serve hot over mashed taters then ladle some of the sauce over top.',45,45,0);
INSERT INTO "Recipe" VALUES(239,'Spicy Lump Crab and Avocado Salad','https://img.spoonacular.com/recipes/661126-556x370.jpg','4  avocados, 0.5 large bell peppered, 3 Tablespoons parsley, 2 Tablespoons lemon juice, 1 pound lump crabmeat, 3 Tablespoons mayonnaise, 4 servings salt and pepper, 2  scallions, 3 Tablespoons sriracha chile sauce, 1 Tablespoon worcestershire sauce','In a small bowl, combine the mayonnaise, chile sauce, worcestershire sauce, lemon juice, salt and pepper.  Stir to combine and set aside.In a medium bowl, carefully toss together the crabmeat, scallions, bell pepper and parsley being careful to not break up the lumps of crab.  Lightly fold in the spicy sauce.Slice the avocados in half and remove the pit.  Slice a small amount from the bottom of the avocado half so it will sit flat on a plate. Pour or brush the lemon juice over the entire cut surface of the avocado to avoid browning. (You can remove the avocado from the skin with a spoon and serve that way but be sure to cover the entire avocado flesh with lemon juice before serving.)Place avocado halves on a plate and fill with the crab salad.  Serve immediately.Note: The salad can be made a few hours in advance and chilled until ready to serve.',30,30,0);
INSERT INTO "Recipe" VALUES(240,'Chive and dill muffins','https://img.spoonacular.com/recipes/638775-556x370.jpg','1 cup all purpose flour, 1 cup cornmeal, 1 Tbs sugar, 2 tsp baking powder, 1 tsp salt, 0.5 tsp baking soda, 0.5 tsp cayenne pepper, 0.25 cup chives and dill, 1.5 cups yogurt, 2 large eggs, 3 Tbs butter',replace('Whisk flour, cornmeal, sugar, baking powder, salt, baking soda, and cayenne pepper in medium bowl. Stir in chives and dill.\nWhisk yogurt, eggs, and melted butter in another medium bowl.\nAdd yogurt mixture to dry ingredients and stir just until blended.\nDivide batter among greased (or silicone) muffin cups, using about 1/3 cup batter for each standard muffin cup.\nBake at 220C for 20 minutes or until muffins are puffed and golden (trick with a toothpick).\nLet muffins cool in muffin cups, then remove from the cups and serve warm.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(241,'Fish Pie With Fresh and Smoked Salmon','https://img.spoonacular.com/recipes/642977-556x370.jpg','1  bay leaf, 0.5 teaspoon peppercorns, 1 tablespoon butter, 1 cup chicken stock, 2 teaspoons cornstarch, 1 teaspoon chives, 1 teaspoon tarragon, 0.5 cup greek, 1 tablespoon horseradish, 1 teaspoon lemon juice, 3 tablespoons milk, 1 tablespoon olive oil, 1  onion, 2 medium potatoes, 4 ounces salmon, 8 ounces salmon, 8 ounces savoy cabbage, 0.5 cup white wine','Peel potatoes and cut into chunksCook in boiling, salted water until tender, app. 15 minutesDrain potatoes, add butter, horseradish and 2 tbs milk to potatoes, mash, adding a bit more milk if neededPut fresh salmon in a medium skillet, add water to almost cover, lemon juice, bay leaf and peppercorns.  Cover and poach until done, 12 - 15 minutes. It should be opaque and flake easily with a fork.Remove salmon and cut into large chunksRoughly chop the smoked salmonSaut onion in oil until tenderAdd cabbage and saut, stirring 2 - 3 minutes.Add white wine, chicken stock, herbs, cover and simmer 10 minutesDissolve cornstarch in water and add to cabbage, stirring until thickenedRemove from heat and add yogurt and stir well to combine.Add both salmons to cabbage and stir gently.Spoon into a baking dishTop with potatoesBake, 400F (200C) for 15 minutes or until the top starts to brown.',45,45,0);
INSERT INTO "Recipe" VALUES(242,'Hot Charlotte Cocktail','https://img.spoonacular.com/recipes/647412-556x370.jpg','1.5 ounces hendrick''s gin, 1.5 ounces st. germain, 0.5 ounce lemon juice, 1 serving cucumber, 1 serving tobasco, 1 serving tobasco',replace('In a cocktail glass, muddle cucumber with Tobasco\nAdd spirits and shake well\nStrain over ice and garnish with a cucumber wheel','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(243,'Apple Roasted Pork Loin','https://img.spoonacular.com/recipes/632590-556x370.jpg','3 pounds pork loin, 3 large granny smith apples, 3 tablespoons olive oil, 2 cloves garlic, 0.5 cup honey, 0.25 cup apple cider vinegar, 0.5 teaspoon pepper, 0.25 teaspoon sea salt, 1 teaspoon five spice powder, 0.5 teaspoon nutmeg','Apple Roasted Pork LoinApples and pork is a pretty traditional combination and I couldn''t count the number of ways I''ve put the two together in the past but this one is a little different. The Granny Smith apples are diced quite small and then cooked in a reduction of honey, apple cider vinegar and spices. Granny Smiths are good to use because they won''t break down into apple sauce during the cooking. The cooked apples are then used as a top crust and glaze for the roast pork. Some garlic roast potatoes and steamed veggies completed a wonderful family meal. Here''s your Sunday supper!Lb pork loin or rib roastSeason the pork with salt and pepper and open roast on a rack in a roasting pan at 375 degrees F for about a half hour.Meanwhile dice very small, (about a 1/4 inch dice)Large Granny Smith apples, peeled and coredIn a large saute pan over medium heat add:Tbsp olive oilCloves minced garlicCook for a minute or two to soften but not brown the garlic. Add:Cup honeyCup apple cider vinegarTsp pepperTsp sea saltTeaspoon Chinese five spice powderTsp freshly grated nutmegBring the mixture to a boil and simmer until the volume is reduced by about half. Increase the heat to mediun-high. Add the diced apple and cook, stirring occasionally until most of the liquid has reduced off.After half an hour in the oven, take the roast out and spoon the apples all over the top. Return the roast to the oven, reduce the heat to 350 degrees F and cook uncovered until the internal temperature reaches 170 degrees F on a meat thermomether inserted into the center of the roast. Allow the pork to rest for about 15 minutes before carving and serving.',45,45,0);
INSERT INTO "Recipe" VALUES(244,'Beef Braised In Red Wine','https://img.spoonacular.com/recipes/634588-556x370.jpg','0.25 pound bacon, 3 lb beef chuck roast, 1 medium carrot, 2 rib celery, 2 cups full-bodied wine, 4  garlic cloves, 1 tablespoon olive oil, 1 medium onion, 0.5 teaspoon pepper, 2 sprigs rosemary, 1 teaspoon salt, 4 sprigs thyme, 3 teaspoons tomato paste, 0.25 cup water','Put oven rack in the middle and preheat oven to 325Heat oil in a large dutch oven until hot but not smoking. Meanwhile, pat meat dry and season with salt and pepper. Brown meat on both sides for about 10 minutes total. ( if the bottom of your pan starts to scorch turn down the heat some).Remove meat from pan and let rest on a plate. Add bacon to pan and saute until browned.Add the veggies and cook until they are softened and golden brown.Add garlic, thyme, rosemary and saute for 1 minute. Then add tomato paste and stir in and cook for 1 minute. Add wine and boil until liquid is reduced by half.Add water to the pan and bring to a simmer. Return meat and any juices to the pan. Cover the pot with the lid and transfer to the oven.Cook for 2 1/2 to 3 hours or until meat is very tender.Remove from pan and slice across the grain. Serve on top of potatoes or grits and top with sauce from pan.',45,45,0);
INSERT INTO "Recipe" VALUES(245,'Veal Piccatas','https://img.spoonacular.com/recipes/664359-556x370.jpg','8  veal scaloppine, 4 servings salt and pepper, 4 servings flour, 2 Tbsp butter, 2 Tbsp vegetable oil, 0.25 cup wine, 1 tsp garlic, 0.5 cup chicken broth, 2 Tbsp lemon juice, 1 Tbsp capers, 4 servings parsley',replace('Season veal scaloppine with salt and pepper, then dust with flour. In a skillet add the butter and the vegetable oil, and heat over medium-high.\nSaut the scaloppine 2-3 minutes on one side. Flip the scaloppine over and saut the other side 1-2 minutes with the pan covered. Transfer the scaloppine to a warmed platter; pour off the fat from the pan.\nDeglaze pan with wine and add minced garlic. Cook until garlic is slightly brown and liquid is nearly evaporated, about 2 minutes.\nAdd broth, lemon juice and capers. Return veal scaloppine to pan and cook on each side for 1 minute. Transfer to a warm plates.\nFinish sauce with butter and lemons. Once butter melts, pour sauce over veal.\nGarnish with chopped fresh parsley and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(246,'White Chocolate Cheesecake With Raspberries','https://img.spoonacular.com/recipes/665172-556x370.jpg','1.3333334 cups graham wafer crumbs, 3 tablespoons sugar, 0.33333334 cup butter, 0.33333334 cup whipping cream, 1 cup chocolate chips, 3 ounces eight packages ounces cream cheese, 0.5 cup sugar, 3  eggs, 3 teaspoons vanilla extract, 1 cup whipping cream, 2 pints raspberries',replace('To make the crumb crust\nIn a small bowl combine the graham crumbs, sugar and melted butter.\nPress into the bottom of a lightly greased springform pan. (Grease bottom only! I also like to line the bottom with parchment paper for easy release of the cheesecake from the pan when it has cooled.)\nTo prepare the cheesecake\nIn a double boiler, melt together the  cup whipping cream and 1 cup pf white chocolate chips. You want this just at the melting point, so be careful not to overheat it. Let it cool to lukewarm if necessary after melting. Set aside to cool while you prepare the rest of the cheesecake batter.\nCream together the cream cheese and  cup sugar for a few minutes, scraping the bowl often.\nAdd the eggs, one at a time, beating well after each addition.\nStir in the vanilla extract and melted white chocolate.\nFinally blend in the 1 cup of whipping cream until smooth.\nPour over the prepared base and bake in a bain marie (See Note) at 325 degrees F for 60 to 70 minutes. The cheesecake may be beginning to lightly brown at the edges but a cheesecake does not need to brown at all to be fully baked. The surface of the cheesecake should lose any shine when the cake is properly baked. It can still be slightly wobbly just at the center at this point.\nRemove the cake from the oven and run a sharp knife completely around the edge of the pan. This will allow for the cheesecake to shrink as it cools and hopefully not crack (but who cares if it does? I am never bothered by a crack or two in the surface)\nAllow the cheesecake to cool thoroughly on a wire rack at room temperature. (Do not put a hot cheesecake into the fridge to cool quickly, this may result in an under baked cheesecake because the residual heat actually continues to set the cheesecake after it comes out of the oven).\nTo finish the cheesecake\nWhen completely cool cover the top with fresh raspberries and garnish with melted white chocolate if desired.\nChill completely in the refrigerator until ready to serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(247,'Quinoa, Tomato, Green Onion Side Salad','https://img.spoonacular.com/recipes/657698-556x370.jpg','0.5 cup green onions, 0.5  lemon, 2 Tbs olive oil, 0.75 cup quinoa, 2 servings salt and pepper, 2 medium size tomatoes, 1.5 cups water','Put your quinoa and your water in a pan. Heat over medium heat until bubbling, then cover and reduce heat to low. Cook for about 15 minutes or until all the water is absorbed.While your quinoa is cooking, get out and wash your green onions and tomatoes. Chop them roughly.Chop a lemon in half and squeeze one half''s juice into a bowl, picking out the seeds.Let your quinoa cool. A little warm is fine.Add olive oil, lemon juice, and tomatoes and green onions to the pan. Stir.Add salt and pepper to your liking.Serve chilled',45,45,0);
INSERT INTO "Recipe" VALUES(248,'Wild Blueberry Lemon Muffins','https://img.spoonacular.com/recipes/665329-556x370.jpg','2 cups all purpose flour, 2.5 teaspoons baking powder, 14 servings butter, 1 cup buttermilk, 1  egg, 3 tablespoons lemon juice, 0.25 teaspoon lemon zest, 0.5 cup powdered sugar, 0.75 teaspoon salt, 2 teaspoons vanilla extract, 2 cups blueberries','Preheat oven to 375 degreesLine 16 muffin cups with paper linesMash 1/8 cup sugar with lemon zest until sugar is moistenedIn a medium-sized bowl, whisk together flour, baking powder, and saltUsing an electric mixer, beat 1 cup sugar and butter togetherBeat in egg, butter milk, vanilla, and lemon sugar one at a timeAdd flour mixture slowly until smoothMix in blueberries gently with a large spatulaDivide batter equally into muffin tins (filling about 3/4 of the way)Bake for about 35 minutes, or until cake tester comes out cleanAllow muffins to cool and prepare glaze by combining lemon juice, zest, and powdered sugarPlace muffins on a wire rack and spoon about 1 tbsp of glaze on top of each muffin and let it slide over the sides of the muffin',45,45,0);
INSERT INTO "Recipe" VALUES(249,'Whole Wheat Blueberry Muffins','https://img.spoonacular.com/recipes/665273-556x370.jpg','1.5 teaspoon baking powder, 1 teaspoon baking soda, 2 large bananas, 7 ounces blueberries, 1 cup butter, 1.25 cup buttermilk, 1 large egg, 0.5 cup brown sugar, 1 teaspoon sugar, 1 pinch sea salt, 2 cups flour','Preheat oven to 350 degrees an line a muffin tin with paper or silicon cups.Peel bananas and mash them in a bowl. Set aside.In a large bowl, combine flour, baking powder, baking soda, salt and light brown sugar. Make a well in the center an add buttermilk, beaten egg, olive oil (or butter) and bananas. Combine until just mixed. Do not overmix! Add in blueberries and give a couple of stirs.Spoon batter into muffin cups until full and then sprinkle the tops with raw sugar. Bake for 20 - 25 minutes until golden brown.Let cool a few minutes in the pan and then transfer to a wire rack to cool completely.',45,45,0);
INSERT INTO "Recipe" VALUES(250,'Cheesy Bacon Burger with Spicy Chipotle Aiolo Sauce','https://img.spoonacular.com/recipes/637631-556x370.jpg','2 teaspoons chipotle chiles in adobo, 3 Tablespoons mayonnaise, 1 clove garlic, 0.25 teaspoons garlic powder, 3 Tablespoons greek yogurt, 1 cup bell pepper, 0.5 teaspoons ground cumin, 0.25 teaspoons ground pepper, 1.5 pounds ground beef, 4 teaspoons lime juice, 0.5 cups onion, 2  wedges of laughing cow swiss cheese, 4 slices turkey bacon, 4  hamburger buns','For Burgers:In a pan cook turkey bacon according to directions on package.Once bacon is done being cooked, take the bacon out and set aside. Add bell pepper and onion into same pan, cook until tender about 10 minutes.Add ground beef to a small bowl, add garlic powder and ground pepper, mix well.Divide the raw meat into 8 equal pieces (I used my scale to measure into 2oz each piece). Flatten out the hamburger, and place 1/2 a cheese wedge onto each piece of hamburger. Take the other pieces of the hamburger and place on top of the cheese , and squish them togther and seal the edges so the cheese doesnt ozzz out. Place on grill and cook until done. About 5 minutes per side.Place burger on buns, top the burgers with bacon, peppers & onions and sauce.For Spicy Chipotle Aiolo Sauce:In a small bowl place all the ingredients together and wisk together until combined.Makes 3/4 cups or 12 Tablespoons',45,45,0);
INSERT INTO "Recipe" VALUES(251,'Gluten Free Yellow Cake And Cupcakes','https://img.spoonacular.com/recipes/644861-556x370.jpg','0.5 cup coconut flour, 0.75 cup tapioca flour, 1 teaspoon salt, 1 teaspoon baking soda, 3 teaspoons baking powder, 1 teaspoon xanthan gum, 4  eggs, 1.25 cups sugar, 0.6666667 cup veganaise, 0.75 cup milk alternative, 2 teaspoons vanilla extract, 1 cup earth balance butter, 2 cups dairy free chocolate chips, 2 pinch salt, 4 tablespoons powdered sugar',replace('Preheat oven to 350 degrees. Grease two 8 or 9 inch round cake pans and sprinkle with tapioca flour if youre making a layer cake. Otherwise, line a muffin tin with baking cups.\nMix together the coconut flour, tapioca flour, salt, xanthan gum, baking soda, and baking powder. Set aside.\nBeat the eggs, sugar, and mayonnaise until fluffy.\nThen slowly add the vanilla, flour mixture, and milk. Alternating between the flour and milk to make a nice fluffy cake. Note- I usually use just barely under 3/4 C of the milk alternative.\nPour the batter into the greased cake pans or fill the baking cups 3/4 full (makes 24 cupcakes).\nBake for 20-25 minutes for the cakes or 12-15 minutes for the cupcakes. Cakes are done when they are nicely browned and spring back when lightly touched or when a toothpick inserted in center comes out clean. Let cool completely before icing.\nFor The Icing:\nBring a small saucepan of water to a boil. Place a heatproof bowl over the saucepan (make sure the water isnt touching the bottom) and add the chocolate and butter.\nStir until melted. Then, add the remaining ingredients.\nPlace uncovered in freezer for 15 minutes.\nBeat with hand mixer until light and fluffy. If its too runny, place back in freezer a few minutes and repeat process until the icing is a good consistency.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(252,'Loaded Baked Potato Soup with Crispy-Fried Potato Skins','https://img.spoonacular.com/recipes/650231-556x370.jpg','8 slices bacon, 3 lbs russet potatoes, 1  onion, 2 t thyme, 2 T flour, 4 c chicken broth, 1 c half n half, 8 servings salt & pepper, 2 c sharp cheddar cheese, 1 c cream, 8 servings thin- scallion',replace('Using a vegetable peeler, remove wide, long strips of potato peel and set aside. Finish peeling the potatoes. ( I had probably around a 1 1/2 c. peels.)\nHeat a large Dutch oven over medium heat. Add chopped bacon and cook until crisp, about 10 minutes. Remove bacon to a paper towel-lined plate.\nTo the fat in the pan, add the potato skins and cook until crisp about 10 min. (You want to be sure they are crisp, or else they''ll just be soggy and greasy, I took mine out at just the 10 minute mark and they weren''t truly crisp, so I just spread them out on a cookie sheet and baked them in a 400 degree oven for around 5 minutes and they were very crisp after that.)\nRemove the crisped potato skins to the paper-lined plate with the bacon. Add the onion to the fat remaining in the pan, cook until tender and lightly browned, about 6 minutes. Add the thyme and flour, cook and stir for about a minute. Slowly whisk in the chicken broth and the half n half. Add the potatoes and bring to a boil over high heat. Reduce heat to medium-low, cover and cook until the potatoes are very tender, (you should be able to easly crush a piece of potato against the side of the pot with the back of a wooden spoon) about 10-15 minutes.\nUsing a blender, puree (in small batches) all but about 3 cups of the soup. Using a potato masher or your wooden spoon, lightly crush the potato chunks in the reserved potion of the soup. Add the pureed soup back to the pot and return to a low burner to keep the soup hot. Add in the 2 c. cheese, stir until melted, then add in the sour cream, stir well. Season to taste with salt & pepper. (Sometimes I like to add some of the crisped bacon into the soup mixture at this point, but that''s optional.)\nTo serve, top bowls of soup with crisped bacon and potato skins, additional cheddar, sour cream and sliced scallion.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(253,'Buttery Pull Apart Monkey Bread','https://img.spoonacular.com/recipes/636632-556x370.jpg','1 cup milk, 1 cup potatoes, 0.6666667 cup shortening, 0.6666667 cup sugar, 2 teaspoons salt, 1 package yeast, 0.5 cup water, 2  eggs, 5.5 cups flour, 2 sticks butter',replace('Combine scalded milk, mashed potatoes, shortening, sugar and salt in a large mixing bowl and let stand until lukewarm.\nAdd one package of yeast (softened in 1/2 cup lukewarm water).\nAdd two well-beaten eggs and 1 1/2 cups flour. Beat well.\nAdd about four more cups of sifted flour to make stiff dough.\nPut in a large greased bowl and turn so that all of the dough is greased.\nLet rise at least two hours.\nAbout 1 1/2 hours before serving, punch down and roll out dough.\nCut into walnut-sized squares and dip each into melted butter, then pile in fluted tube pan.\nPour remaining butter over top.\nLet rise (about one hour) then bake 20-25 minutes at 375 degrees F (If crispier bread desired, cook at 400 degrees F)\nServe hot.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(254,'Wholemeal Steam Bun','https://img.spoonacular.com/recipes/665306-556x370.jpg','1 tbsp double action baking powder, 1 tbsp yeast, 400 g pau flour, 0.5 teaspoon salt, 3 tbsp shortening, 1 tablespoon sugar, 250 g water, 100 g wholemeal flour','METHOD:1.Mix all the ingredients A together and knead into smooth and elastic dough.2.Cover with a piece of wet cloth and leave to prove until double its size.3.Sift B top of the dough and knead well to distribute the baking powder until the dough is smooth again.4.Cover and allow dough to rest for 15 minutes before shaping.Meat Fillings :boiled eggs (shelled and cut into )Marinade for meat : 30 minutesShredded chicken/pork2 tbsp. BBQ saucewaterFilling:1.Heat oil in a pan adds in marinated meat and stirs fry till aromatic, adds in some water and cooks for 5 minutes until soft. Taste and dish up and leave to cool and chill in the fridge for 3 hours.2.Divide dough 12 portions and shape balls.3.Flatten, roll into a round shape and add 1 tbsp of filling and pleat the top into a Pau/Bun.4.Line Pau/Bun with a piece of white paper and let it prove again for another 15 minutes.5.Steam Pau/Bun with high heat for about 15 minutes or until the Pau/Bun is cooked.6.Serve hot.',45,45,0);
INSERT INTO "Recipe" VALUES(255,'Almond Plum Cake with Creme Fraiche','https://img.spoonacular.com/recipes/632169-556x370.jpg','9 oz almond paste, 1 teaspoon baking powder, 15 grams butter, 1 cup cake flour, 6 servings crème fraiche and slivered almond, 6  eggs, 1.25 cup granulated sugar, 12 oz plums, 0.25 teaspoon salt, 1  vanilla-bean - lengthwise seeds scraped, 1 teaspoon vanilla extract','. Preheat the oven at 350. Butter and flour a 9-inch spring form pan. In a small bowl, mix the cake flour with the baking powder and salt.2. In a bowl of a standing mixer fitted with a paddle, beat the sugar with the almond paste until crumbly. Add the butter and beat t high speed until light in color and fluffy, about 2 minutes. Add the eggs, one at the a time, beating until fully incorporated between additions. Beat the vanilla extract and vanilla seeds. Gently fold in the flour mixture until fully incorporated.3. Scrape the batter into the prepared pan. Arrange the plums over the top of the batter. Bake for 1 hour and 5 minutes, or until the cake is deeply golden and a toothpick inserted in the center comes out clean.4. Transfer the cake to a rack and let cool for 15 minutes. Run a knife around the edge of the cake and remove the outside ring of the pan. Let the cake cool for at least 30 minutes longer. Serve warm or at room temperature topped with crme fraiche and slivered almonds.Make ahead: The cake can be made one day ahead and stored in an airtight container at room temperature.',45,45,0);
INSERT INTO "Recipe" VALUES(256,'Chicken and White Bean Chili','https://img.spoonacular.com/recipes/637932-556x370.jpg','4 pounds chicken, 1 liter water, 2 tablespoons chicken soup base, 1 large bay leaf, 1 medium size onion, 1  bell pepper, 3 large garlic cloves, 5 tablespoons flour, 439 g .5 can cannellini beans, 2 tablespoons mild chili powder, 1 teaspoon ground coriander, 2 teaspoons ground cumin, 1 tablespoon coriander, 250 ml heavy whipping cream, 187 ml soured cream, 9 servings bell pepper',replace('Rinse the chicken quarters really well and place them in a stock pot.\nTo the chicken in the pot, add the water (water should mostly cover the chicken), bouillon, bay leaf, onion, bell pepper and garlic.\nPlace the stock pot over medium high heat and bring to a boil; reduce the heat to medium, cover and simmer until chicken is cooked through, approximately 30 minutes.\nRemove pot from the heat.\nRemove chicken quarters from the pot and transfer them to a cutting board and cool until they can be comfortably handled. \n \nRemove meat from the bones and chop it into small pieces then shred slightly; set aside.\nRemove approximately 1 cup (250ml) of the liquid from the stock pot and set aside.\nReturn the stock pot to medium heat and bring to a simmer. \n \nPlace the flour into a small bowl.\nWhile stirring constantly, gradually add the reserved liquid to the flour until a smooth paste is formed.\nPour the paste into the stock pot and stir constantly until the mixture starts to thicken.\nAdd the beans, chopped chicken, chili powder, coriander and cumin.\nIncrease the heat to medium and, stirring frequently, simmer, uncovered for approximately 15-20 minutes or until the mixture is thick enough to coat the back of a spoon.\nReduce the heat to low and add the fresh coriander, single cream and soured cream.\nStir well until the single and soured creams are completely incorporated into the chili.\nAdd pepper to taste.\nServe immediately.\nGarnish with chopped avocado, spring onion, fresh coriander or grated cheese.\nLike most soups, this chili is great refrigerated and served the next day but if you intend on freezing it, leave out the whipping cream and soured cream (they separate when frozen) and add them just before serving.\nIf youd like to spice things up a bit, add  -  teaspoon cayenne pepper or red pepper flakes for a slightly hot flavor.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(257,'Ham and Red Bean Soup','https://img.spoonacular.com/recipes/646185-556x370.jpg','3 medium leeks, 4 sprigs thyme, 1  bay leaf, 1 teaspoon coriander seeds, 0.5 teaspoon peppercorns, 1 teaspoon cumin seeds, 1 teaspoon olive oil, 3  carrots, 2 stalks celery, 2 cloves garlic, 1 teaspoon tomato paste, 1 pound beans, 1 can bone from ham 3 cups ham 1 teaspoon ground chipotle chile powder salt and pepper, 10 cups water, 3 cups ham, 1 teaspoon ground chipotle chile powder, 6 servings salt and pepper, 1 t add he ham and chipotle chile powder and stir in. allow to simmer until beans are and are just begin',replace('Take the thyme sprigs and bay leaf, and wrap the reserved green leek top around. Tie with butchers twine to secure. Place the coriander seeds, peppercorns, and cumin seeds in the middle of a coffee filter or small piece of cheesecloth, and tie into a bundle using butchers twine. Set aside.\nHeat the olive oil in a large stockpot over medium heat. Add leeks, carrots, and celery. Saute for 5 minutes or until softened. Add garlic and saute for another minute. Add tomato paste and saute for another minute. Add the beans, ham bone, the herb bundle and the spice bundle, and enough water to cover. Bring to a boil and reduce to a simmer, partially covering. Allow to simmer for 1 hour.\nAdd the diced ham and chipotle chile powder and stir in. Allow to simmer until beans are soft and are just beginning to break open, another 1 1/2 to 2 hours. Adjust seasoning to taste. Remove ham bone and pull any remaining ham from the bone and return to pot. Remove herb bundle and spice bundle, and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(258,'Pasta e Fagioli (Pasta and Beans)','https://img.spoonacular.com/recipes/654835-556x370.jpg','2 tablespoons olive oil, 15 ounce cannellini beans, 1 cup vegetable stock, 3 cups water, 2 small tomatoes, 0.25 cup onion, 2  garlic clove, 0.75 cup elbow macaroni, 0.25 cup parmesan cheese, 1 teaspoon pepper flakes, 0.25 teaspoon salt, 1 teaspoon pepper, 1 tablespoon parsley',replace('In a large stock pan over medium-high heat, add the olive oil and the onion. Allow the onion to cook until it is tender (about 3 minutes). Add the tomato (or marinara sauce) and garlic and incorporate it into the mixture. Cook for just 1-2 minutes (be careful not to burn the garlic).\nAdd the vegetable stock, water, salt, pepper and red pepper flakes. Bring this to a boil and then add your pasta. Lower the heat and allow the pasta to cook until its about 3/4 of the way finished (still slightly firm).\nAdd your beans and allow the mixture to continue cooking until the pasta is fully cooked (about 10-15 minutes). Add the parsley toward the end of your cooking time. Taste and adjust the seasoning as needed.\nServe in individual bowls with extra parsley as garnish and sprinkle with the Parmesan cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(259,'Overnight Oatmeal','https://img.spoonacular.com/recipes/654271-556x370.jpg','1 cup cranberries, 1 cup figs, 0.5 cup half-and-half, 1 cup steel-cut oats, 4 cups water','In a crock-pot, combine all ingredients and set to low heat. Cover and let cook for 8 to 9 hours.Stir and remove to serving bowls. This method works best if started before you go to bed. This way your oatmeal will be finished by morning.This "Recipe" yields 4 servings.',45,45,0);
INSERT INTO "Recipe" VALUES(260,'Swordfish with Orange Caramel Sauce','https://img.spoonacular.com/recipes/662694-556x370.jpg','4  equal sizes of swordfish, 0.5 cup milk, 1 cup panko, 0.5 cup bread crumbs, 0.5 cup parmesan cheese, 4 servings salt and pepper, 4 servings sage and marjoram, 1  orange, 4 tablespoon butter, 4 servings sugar',replace('Pat dry the swordfish. In a plate mix together the panko, bread crumbs, parmesan cheese, dry sage and marjoram and the salt and pepper. Mix well.\nIn another plate place the milk or cream.\nDip the swordfish into the milk and let any excess drip away.\nRoll into the panko-parmesan mixture and press it against the swordfish to adhere.\nIn a large skillet melt 2 tablespoons of butter. When melted add the swordfish and cook until nicely golden on each side and the fish is springy yet cooked.\nRemove the swordfish from the skillet and let it rest while preparing the sauce.\nRemove all the cooking butter from the skillet and place the skillet over medium high heat.\nAdd the orange juice and reduce by half.\nAdd the butter remaining, the sugar and reduce until a thick sauce is crated.\nServe the sauce over the fish or alongside.\nIf the sauce is too thick and too tangy; add a bit more sugar and swirl in another tablespoon of butter.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(261,'Baby Beet Salad','https://img.spoonacular.com/recipes/633221-556x370.jpg','2 pounds baby beets, 6 servings pepper, 1 cup mint leaves, 3 tablespoons olive oil, 2 tablespoons red-wine vinegar, 1 pinch salt','Scrub the beets well. Wrap groups of 2 or 3 beets together in little packets of aluminum foil. Place the packets on a baking sheet and bake at 350 degrees until very tender, about 1 hour.When the beets are cool enough to handle, slip off and discard the skins (using rubber gloves). Halve beets lengthwise and place in a bowl.Whisk together the oil, vinegar, salt and pepper; toss with the beets. Sprinkle with the mint leaves.',45,45,0);
INSERT INTO "Recipe" VALUES(262,'Cilantro Lime Fish Tacos','https://img.spoonacular.com/recipes/639413-556x370.jpg','2 packets flavor concentrated seafood broth, 8 6-inch corn tortillas, 1 tablespoon cilantro leaves, 1 cup lettuce, 2 tablespoons lime juice, 4 servings olive oil, 2 tablespoons onions, 0.25 cup chunky salsa, 0.25 cup cream, 1 pound tilapia fillets','Heat the oil in a 12-inch skillet over medium-high heat.  Add the fish and cook for 8 minutes or until it flakes easily when tested with a fork, turning over once halfway through the cooking time.Add the concentrated broth, lime juice and cilantro to the skillet.  Break the fish into large pieces with a spoon, stirring to coat with the broth mixture.Divide the fish mixture among the tortillas.  Top with the lettuce, onion, sour cream and salsa.  Fold the tortillas around the filling.',45,45,0);
INSERT INTO "Recipe" VALUES(263,'Creamy Mushrooms Over Soba Noodles (Vegan)','https://img.spoonacular.com/recipes/640666-556x370.jpg','1 tablespoon all purpose flour, 4 servings white wine, 4 servings cremini; but your choice), 1 teaspoon thyme, 2 cloves garlic, 0.5  juice of lemon, 4 servings salt & pepper, 12 ounces soba noodles, 2 tablespoons earth balance buttery spread, 1.25 cups soy milk, 12 ounces mushrooms','Melt 1 tbs of the Earth Balance in a saute pan.Add mushrooms & garlic stirring until the mushrooms are dark and reduced.Set the mushrooms aside.In the same pan, melt the second tbs of Earth Balance and stir in the flour.  Cook stirring for about a minute, making a roux to thicken your sauce.  Slowly add the soy milk, stirring until it is smooth and thickened.Add the mushrooms, lemon juice, thyme, salt, & pepper Add a 1/4 cup of white wine.And cook until reduced and sauce has a pleasant consistencyDivide the cooked soba noodles into bowlsLadle the sauce over soba noodles.Garnish with sprigs of fresh thyme if you like.Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(264,'Hot Crab Dip','https://img.spoonacular.com/recipes/631751-556x370.jpg','8 ounces cream cheese, 1 tablespoon milk, 1 can crabmeat, 2 tablespoons onion, 0.5 teaspoon horseradish, 0.125 cup breadcrumbs, 2 tablespoons butter, 4 servings salt',replace('Add all ingredients to softened cream cheese, mix with fork\nPlace in small casserole dish\nCover with breadcrumbs and butter\nBake 375 for 15 minutes','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(265,'Raspberry Walnut Coffee Cake','https://img.spoonacular.com/recipes/657917-556x370.jpg','1.25 cups almond milk, 1 tablespoon baking soda, 1 teaspoon cinnamon, 0.5 tablespoon flaxseed, 0.25 cup maple syrup, 0.25 cup oat flour, 1 tablespoon oil, 0.25 cup raspberry jam, 0.25 cup rolled oats, 0.5 teaspoon salt, 1.5 tablespoons turbinado sugar, 2 teaspoons vanilla, 0.25 cup walnuts','Preheat oven to 375 and grease an 8x8 pan.Combine all wet ingredients (milk, flax, vanilla, syrup, oil). Let stand while grinding the walnuts. Whisk together with the baking soda, cinnamon, and salt.Pour half the batter into prepared pan. Using a spoon, dollop lines of jam across the batter and swirl into batter using a knife. Pour the rest of the batter on top.Mix up the crumble topping: add the walnuts to a bag and crush until broken down into pea-sized crumbs. Toss with the oat flour, cinnamon, sugar and rolled oats if using. Stir in the tablespoon of oil until the everything starts to come together--mixture should be crumbly. Sprinkle the topping evenly across the top of the batter and bake for 25 minutes, or until browned on top and it springs back slightly when touched. Serve warm.',35,35,0);
INSERT INTO "Recipe" VALUES(266,'Market Stuffed Squash Blossoms','https://img.spoonacular.com/recipes/651103-556x370.jpg','10  squash blossoms, 4  garlic-scapes, 2 tablespoons cherries, 1 tablespoon butter, 0.75 cup panko bread crumbs, 0.5 cup goat cheese, 2 tablespoons basil, 4 servings salt and pepper, 0.5 cup flour, 0.5 teaspoon pepper, 0.5 teaspoon curry powder, 0.5 teaspoon salt, 0.5 cup club soda, 4 servings oil',replace('Set a large skillet over medium heat. Add a pat of butter, chopped scapes and chopped cherries. Saut for 2-3 minutes.\nAdd the panko and stir for 1-2 minutes until the panko has toasted. Turn the heat off and stir in the goat cheese and basil. Salt and Pepper to taste.\nSpoon the filling into the squash blossoms and gently twist the petals together to seal.\nWipe out the skillet with a damp paper towel. Then pour in enough oil to thoroughly coat the bottom of the skillet. Return the heat to medium-high. Mix the flour, white pepper, curry and salt in a small bowl. Whisk in the club soda.\nDip each blossom in the batter. Shake off the drippings and carefully place in the hot oil.\nPan-fry for 1-2 minutes per side. I usually turn mine 2-3 times. Remove from the pan the drain on a paper towel. Repeat if needed.\nServe alone as an appetizer, with aioli, or over a salad as a light meal.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(267,'Cinnamon Mocha Quick Bread','https://img.spoonacular.com/recipes/639465-556x370.jpg','4 cups flour, 2 cups granulated sugar, 3 teaspoons coffee granules, 1 tablespoon cocoa, 2 teaspoons baking soda, 1 teaspoon salt, 2  eggs, 2 cups buttermilk, 0.5 cup canola oil, 3 teaspoons ground cinnamon, 0.5 cup optional: raisins',replace('1.  In a bowl, combine the flour, 1 1/2 cups sugar, coffee granules, cocoa, baking soda, and salt. In a small bowl, whisk the eggs, buttermilk and oil. Stir into the dry ingredients just until moistened. (Optional -- fold in raisins)\n2.  Transfer a fourth of the batter into each of two greased 8"x4" loaf pans. Combine cinnamon and remaining sugar; sprinkle half over batter in each loaf pan. Repeat layers.\n3.  Cut through batter with a knife to swirl.\n4.   Bake at 350 degrees for 55 to 60 minutes or until a toothpick inserted near the center comes out clean. Cool in pans for 10 minutes; remove from pans to wire racks to cool completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(268,'Fall Farro Salad with Pomegranate, Walnut & Truffles','https://img.spoonacular.com/recipes/642556-556x370.jpg','0.33333334 cup extra virgin olive oil, 8 ounces farro, 4 servings parmesan into ribbons, 1  pomegranate, 1 small head radicchio thinly, 4 servings salt and pepper, 1  truffle mushroom, 30 ml vinegar, 4 ounces walnuts','In plenty of cold water boil farro until al dente (cooked but with a bite) - about 20-35 minutes. Feel free to add some vegetable scraps if available (unused piece of carrot, onion, celery, etc.) Drain the farro in a colander &amp; remove vegetable scraps if used.  Allow to cool for a few minutes.In a large separate bowl combine the farro with radicchio, nuts &amp; pomegranate seeds. Give it a good mix and season with salt &amp; pepper.For the dressing: Drizzle over the salad a couple tablespoons of vinegar followed by three times the amount of extra virgin olive oil. Give it another good mix.To finish, give it a good shave of fresh truffles, if not available truffle salt or oil works well too. Top with a few pulls of a potato peeler across a wedge of parmesan.Allow to sit for at least 20 minutes up to a day - it needs a little time for it to all come together.Before serving - give it one last good stir, taste &amp; adjust the seasoning - making sure the dressing is balanced (not too vinegary or oily). ',75,75,0);
INSERT INTO "Recipe" VALUES(269,'Buffalo Ranch Chicken Dip','https://img.spoonacular.com/recipes/715432-556x370.jpg','4  chicken breasts, 16 oz cream cheese, 0.5 cup green onions, 12 oz louisiana hot sauce, 7 servings paul prudhommes poultry seasoning, 16 oz ranch dressing, 8 oz sharp cheddar cheese','Take your chicken breasts and give them a light coat of the Poultry Magic seasoning, and then coat them with Pam cooking spray. (The Pam keeps the chicken from drying out while cooking.) Grill your chicken breasts and then allow to cool slightly.Preheat your oven to 350 degrees. Shred your chicken and then combine in a 13 x 9 inch glass baking dish with your Louisiana Hot Sauce. Place your cream cheese and dressing into a sauce pan over medium heat until the texture is smooth. Pour this mixture over your chicken and hot sauce mixture in the dish. Top with cheddar cheese and green onions.Bake un-covered for 30 minutes until bubbly. Let stand until slightly cooled, and then serve with tortilla chips of our choice!',45,45,0);
INSERT INTO "Recipe" VALUES(270,'Peanut Butter Sriracha Cookies','https://img.spoonacular.com/recipes/655335-556x370.jpg','1 cup butter, 1.5 cups crunchy peanut butter, 1 cup sugar, 1 cup brown sugar, 0.25 c sriracha, 2  eggs, 1 tsp vanilla extract, 2.75 cups flour, 1 teaspoon baking powder, 0.5 teaspoon salt, 1.5 teaspoons baking soda, 60 servings granulated sugar, 1 cups add a hershey''s chocolate kiss on top as done',replace('Cream together butter, peanut butter and sugars.\nSlowly add in sriracha, eggs and vanilla. Beat until combined.\nIn another bowl mix together flour, baking powder, baking soda and salt.\nGently mix flour into peanut butter mixture until well combined. Place batter into refrigerator for 1 hour to chill.\nPre-heat oven to 375 degrees.\nRoll dough into approx 1 sized balls or use a Medium sized cookie scoop/Size 40  1tbs portion. Dip the top of dough ball into granulated sugar and place onto cookie sheet.\nFlatten each ball with a fork, making a criss-cross pattern. Bake for 8-10 minutes or just until the cookies begin to brown. Do NOT over-bake!\nCool on wire racks and enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(271,'Peanut Butter and Apple Oatmeal Breakfast Bars','https://img.spoonacular.com/recipes/655212-556x370.jpg','2 cups quaker oats, 0.25 cup smooth peanut butter, 1 tbsp butter, 2 tbsp vegetable oil, 1 cup flour, 2 tbsp honey, 0.33333334 cup brown sugar, 1 tbsp vanilla extract, 1 tbsp cinnamon, 1  apple',replace('Preheat oven to 350 degrees F.\nGrease an 11x7 inch baking pan. If you don''t have one, you can use an 8x8, 9x9, or if neceessary an 11x13.\nPlace peanut butter and butter in a microwave safe dish. Heat in the microwave for 30-45 seconds or until butter is melted. Stir together.\nPlace all ingredients, except fruit, into a bowl. Using an electric beater or KitchenAid mixer, beat ingredients together for approximately 1 minutes.\nPeel a whole apple and thinly chop into pinky nail size pieces.\nStir the apples into the oatmeal mixture.\nPour the mixture into greased pan and press entire mixture down firmly with your fingers.\nPlace pan into the oven and cook for 25 minutes or until edges are golden brown. If you are using an 11x13 pan, it will take a bit less time because the mixture will be much thinner.\nLet cool for 10 minutes before slicing into strips. Let the remaining bars cool entirely before you place in tupperware or wrap them in foil.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(272,'Scotch Eggs','https://img.spoonacular.com/recipes/659581-556x370.jpg','1 pound bulk sausage, 1 cup corn meal, 9  eggs','Divide sausage into 8 portions. On a lightly crumb sprinkled surface, pat out each portion to about 1/8 inch thickness. Wrap 1 sausage portion completely around 1 hard boiled egg, pressing edges together to seal. Repeat with remaining sausage and hard boiled eggs.Dip sausage-covered eggs in 1 beaten egg and then roll in breadcrumbs.Deep fry or place on baking sheet and bake in a 375 degree oven for 20 minutes until lightly browned.',45,45,0);
INSERT INTO "Recipe" VALUES(273,'4 Ingredient Raw Peanut Butter Chocolate Cups','https://img.spoonacular.com/recipes/792705-556x370.jpg','2 tablespoons coconut flour, 200 g chocolate, 2 tablespoons maple syrup, 1.3333334 cups smooth peanut butter, 1 dash vanilla','Line a baking sheet with parchment paper.In a medium bowl, combine the peanut butter, maple syrup, vanilla and 2 tablespoons of the coconut flour until well blended. Add additional coconut flour if the peanut mixture is too soft  it should be pliable and easy to form into shapes with your hands.Using a tablespoon or ice cream scoop, drop spoonfuls of the mixture onto the prepared baking sheet. Form into balls and flatten each ball slightly with your fingers. Place in the freezer for 20 to 30 minutes until firm.Melt the chocolate in a small saucepan over low heat, stirring often, until melted. Let cool for a few minutes and then dip each of the frozen peanut butter pieces into the chocolate to coat completely. Using a fork is a good way to do this and be sure to work quickly.Transfer each peanut butter cup back to the baking sheet and return to the freezer. Sprinkle with a little coarse sea salt if desired. Chill until set, about 1 hour or more. These will keep well in the freezer for several days, if they last that long.Note: You can make a half batch instead, but these are so good, you won''t want to do that, especially as they keep so well.',45,45,0);
INSERT INTO "Recipe" VALUES(274,'Fried String Cheese Sticks','https://img.spoonacular.com/recipes/643809-556x370.jpg','4  individual string cheese sticks, 0.25 cup flour, 1 tablespoon egg +2 water, 0.5 cup seasoned bread crumbs, 1 serving vegetable oil',replace('Dredge individual cheese sticks in flour. shake off excess.\nRoll sticks in egg wash,\nThen coat with bread crumbs.\nFry in hot oil for 20 seconds, then flip and fry another 20 seconds.\nServe with Pizza sauce or marinara!!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(275,'Tomato and lentil soup','https://img.spoonacular.com/recipes/663559-556x370.jpg','2 Tbs olive oil, 1  onion, 2 cloves garlic, 3  carrots, 480 g tomatoes, 1  bay leaf, 1.3 l water, 250 g lentils, 0.25 tsp salt, 1 bunch parsley',replace('Saut onion and garlic in olive oil for 5 minutes.\nAdd the carrot, saut for another 2 minutes.\nAdd tomatoes, bay leaf and water, stir and bring to the boil.\nStir in lentils, season with salt and cook for 5 minutes.\nBefore serving sprinkle with chopped parsley.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(276,'Pittata - Pizza Frittata','https://img.spoonacular.com/recipes/622598-556x370.jpg','8  eggs, 2 servings basil, 0.5 cup milk, 2 servings parmesan cheese, 2 servings pepperoni, 0.25 cup mozzarella cheese','1. Pre-heat oven to ~450°F (230°C), top heat only.2. On the stove, heat cooking fat in a large oven-safe skillet over medium heat.3. Beat the eggs with the milk (again milk is optional), salt, pepper, and any herbs or spices desired.4. Add any desired add-ins (other than cheese) to the skillet. For the pittata, we didn''t use anything, but this is when you would add your cooked vegetables or raw vegetables that don''t require much cooking (e.g. bell pepper). Pour in the egg mixture and tilt the skillet to ensure it evenly surrounds any add-ins. Now distribute the shredded cheese and pepperoni slices (if using).5. Allow the eggs to cook on the stove until the edges of the eggs are set. The center will still be a bit jiggly. Now is a good time to top with Parmesan cheese (be generous!)6. Transfer the pan to the hot oven and bake until the eggs are puffed and browned with a firm center. Remove from oven and let cool for a couple minutes before cutting into wedges.',30,30,0);
INSERT INTO "Recipe" VALUES(277,'Boneless Buffalo Strips','https://img.spoonacular.com/recipes/635657-556x370.jpg','8 servings gorgonzola dip, 0.5 cup cream, 0.25 cup greek yogurt, 0.5 cup gorgonzola, 1 teaspoon garlic pepper, 0.5 teaspoon salt, 1 tablespoon apple cider vinegar, 8 servings buffalo strips, 1 pound chicken breasts, 2 teaspoons salt, 2 teaspoons chili garlic sauce, 2 tablespoons frank''s, 1 cup buttermilk, 1.5 cups panko crumbs, 8 tablespoons flour, 1.5 teaspoons paprika, 1 teaspoon cayenne, 1.5 teaspoons salt, 0.25 cup frank''s',replace('Whisk together buttermilk, chili-garlic sauce, Franks, buttermilk, vinegar and salt.  Add chicken and marinate overnight.\nPreheat oven to 450 degrees.  Spray wire rack with cooking spray.\nCombine panko, flour, paprika, cayenne and salt in a large bowl.\nDredge chicken in flour mixture, shake of access and place on wire rack.  Repeat with all chicken  pieces.\nSpray chicken breasts with cooking spray, making sure to hit all parts of the chicken.\nCook for 10 minutes.  Take out, turn chicken pieces over, spray again, and return to oven for another 5 minutes, or until all pieces are golden brown and chicken reaches 155 degrees.\nMeanwhile, in a small food processor add ingredients for gorgonzola dip.  Process until smooth.\nWhen chicken strips are done, with a pastry brush, brush strips with Franks Red Hot.  Serve with gorgonzola sauce and carrot and celery sticks.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(278,'Beef Teriyaki Stir Fry','https://img.spoonacular.com/recipes/634710-556x370.jpg','2 cups broccoli florets, 1 tablespoon brown sugar, 1 tablespoon cornstarch, 1 teaspoon sesame oil, 0.5 pound flank steak, 1 teaspoon garlic, 1 tablespoon ginger, 1 cup mushrooms, 6 teaspoons oil, 1 cup bell pepper, 2 tablespoons scallions, 2 teaspoons sesame seeds, 0.25 cup soy sauce','Whisk ingredients together in a small bowl and refrigerate for at least 30 minutes.Heat oil in a large frying pan over medium heat. Add beef and saut for 3-4 minutes just to brown it on all sides.Remove from pan and set aside.Add vegetables and saut for 5 minutes more, until beginning to soften.Stir in teriyaki sauce and allow mixture to come to a simmer.Add beef and any drippings that have accumulated on the plate. Cook for 5 minutes, stirring occasionally.In a small bowl, combine cornstarch with 2 tsp cold water to dissolve. Stir into the pan of beef and vegetables. Allow the mixture to simmer and thicken for 2 minutes. Toss to evenly coat vegetables and beef in teriyaki sauce. Serve.',45,45,0);
INSERT INTO "Recipe" VALUES(279,'khichdi "Recipe"','https://img.spoonacular.com/recipes/765725-556x370.jpg','1  bay leaf, 2 servings chili slit, 0.5 tsp cumin, 1 tbsp ghee, 1 tsp ginger, 0.75  lentils, 1 slices very few onion, 0.5 tsp chili powder, 0.75 cup rice, 2 servings salt, 0.5 cup tomato, 2 servings turmeric little, 2.5 cups water','find complete "Recipe" at swasthi''s blog',30,30,0);
INSERT INTO "Recipe" VALUES(280,'Endive Appetizer With Blue Cheese, Dried Cranberries and Walnuts','https://img.spoonacular.com/recipes/642406-556x370.jpg','2 large apples, 2 tablespoons balsamic vinaigrette, 1  belgian endive, 0.75 cup cheese, 1 cup cranberries, 0.5 cup walnut pieces','Toast walnuts in a dry skillet over medium heat for two minutes until fragrant. Set aside and cool.Arrange apple slices on one platter, and endive leaves on other platter.In a medium bowl combine cooled walnuts, dried cranberries and blue cheese.Top endive leaves with 1 tablespoon cheese mix and a drop or two of balsamic dressing.Put remaining cheese, nuts and blue cheese in a bowl to serve with apple slices.',20,20,0);
INSERT INTO "Recipe" VALUES(281,'Julia Child''s Vichyssoise','https://img.spoonacular.com/recipes/648643-556x370.jpg','4 cups leeks, 4 cups baking potatoes recommended, 6 cups water, 1.5 teaspoons salt or, 0.5 cup crème fraîche, 1 Tablespoon chives',replace('Bring the leeks, potatoes and water to the boil in the saucepan. Salt lightly, cover partially, and simmer 20-30 minutes, or until the vegetables are tender.\nPure the soup if you wish. Taste, and correct seasoning.\nAfter chilling the soup, you may wish to stir in a little more cream. Taste carefully again, and correct the seasoning.\nTop each serving with a sprinkle of chives or parsley and a drizzle or dollop of crme frache.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(282,'Chicken Cordon Bleu','https://img.spoonacular.com/recipes/638035-556x370.jpg','6 slices deli ham, 2  eggs, 0.25 cup flour, 2 teaspoons thyme leaves, 6 servings kosher salt and pepper, 1 teaspoon olive oil, 1 cup panko bread crumbs, 6  chicken breasts, 12 slices swiss cheese, 2 tsps water','Preheat oven to 350 degrees F.Butterfly the chicken breasts by slicing half lengthwise but not cutting all the way through. Lay the halved breasts between 2 pieces of plastic wrap. Using the flat side of a meat mallet, gently pound the chicken to 1/4-inch thickness, taking care to not tear or create holes in the meat.Lay 2 slices of cheese on each breast, followed by 2 slices of ham, and 2 more of cheese; leaving a 1/2-inch margin on all sides to help seal the roll. Tuck in the sides of the breast and roll up tight like a jellyroll. Squeeze the log gently to seal.Season the flour with salt and pepper; spread out on waxed paper or in a flat dish. Mix the breadcrumbs with thyme, kosher salt, pepper, and oil. The oil will help the crust brown. Beat together the eggs and water, the mixture should be fluid. Lightly dust the chicken with flour, then dip in the egg mixture. Gently coat in the bread crumbs.Carefully transfer the roulades to a baking pan and bake for 20 minutes until browned and cooked through.Serve whole or cut into pinwheels.',45,45,0);
INSERT INTO "Recipe" VALUES(283,'Moroccan Carrot Soup','https://img.spoonacular.com/recipes/652413-556x370.jpg','2 tablespoons butter, 1 cup onion, 1 pound carrots, 2.5 cups chicken stock, 1.5 teaspoons cumin seeds, 1 tablespoon honey, 1 tablespoon lemon juice, 0.125 teaspoon allspice, 2 servings salt and pepper, 0.5 cup yogurt',replace('Melt butter in a large sauce pan over medium-high heat. Add onion; saute for 2 minutes. Mix in carrots and broth. Bring to boil. Reduce heat, cover and simmer until carrots are very tender, about 20 minutes.\nStir cumin seeds in a small skillet over medium-high heat until fragrant, about 4  5 minutes. Finely grind in a spice mill.\nRemove soup from heat. Puree in batches in a blender until smooth. Return to sauce pan. Whisk in honey, lemon juice and allspice. Season with salt and pepper.\nLadle soup into bowl. Sprinkle with toasted cumin, or mix cumin and sour cream in a small bowl and dollop on top. Serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(284,'Mini-Cherry Pies','https://img.spoonacular.com/recipes/651990-556x370.jpg','2 pounds cherries, 2 tablespoons cornstarch, 4 cups flour, 0.75 cup granulated sugar, 3 tablespoons heavy whipping cream, 1 tablespoon lemon juice, 0.5 cup pecans, 0.25 cup turbinado sugar, 1 cup butter, 1 teaspoon vanilla extract, 0.6666667 tablespoon plus 2 water','Directions:In the work bowl of a food processor, combine flour, 1/2 cup granulated sugar, pecans, and 1/2 teaspoon salt, pulsing to blend. Add butter to flour mixture, pulsing until mixture is crumbly, approximately 30 seconds.With the food processor running,gradually add 2/3 cup cold water, in a slow steady stream, through lid opening until mixture forms a ball. Flatten dough into 2 disks, wrap in plastic wrap and refrigerate for 1 hour.Preheat oven to 350 degrees.On a lightly floured surface, roll 1 pastry disk to a 1/8-inch thickness. Fit dough into 12 (2-1/2-inch) mini pie plates. Trim dough around the edges. Freeze until dough is firm, approximately 10 minutes.Prick the bottoms and sides of dough with a fork. Bake until golden, 6 to 8 minutes.In a small bowl, combine cornstarch and remaining 2 tablespoons cold water, stirring until mixture is blended.In a large saucepan, combine cherries, cornstarch mixture, remaining 1/4 cup granulated sugar, and remaining 1/2 teaspoon salt. Cook over medium heat until cherries are soft and mixture is thick. Add lemon juice and vanilla, stirring to combine.On a lightly floured surface, roll remaining pastry disk to a 1/8-inch thickness. Cut dough into very thin (1/8 to 1/4-inch-wide) strips. Arrange enough dough strips vertically side by side to achieve at least a 2-1/2-inch width. Pull back halfway every other vertical strip, and place a strip horizontally across remaining vertical strips. Return to their original positions the vertical strips that were pulled back, and pull back the other vertical strips. Place another strip horizontally across remaining vertical strips as close as possible to first horizontal strip. Continue to tightly weave 1 horizontal strip at a time into the vertical strips, working out form the center to make at least a 2-1/2-x-2-1/2-inch lattice top for each mini pie. Using a spatula, carefully transfer lattice tops to prepared pie plates.Using a knife, trim the edges. Gently press edge of lattice tops to seal. Brush top and edges of dough with cream. Sprinkle the top of each pie with 1 teaspoon turbinado sugar. Bake until crusts are golden, 18 to 24 minutes. Serve warm with a scoop of vanilla ice cream, if desired.',45,45,0);
INSERT INTO "Recipe" VALUES(285,'Trinidadian Chicken Potato Curry','https://img.spoonacular.com/recipes/663824-556x370.jpg','2 lbs chicken thighs, 0.5  onion, 3  garlic cloves, 1 Tsp thyme, 1 Tsp hot sauce, 0.25 Tsp powdered ginger, 0.25 tsp curry powder, 1 Tsp coconut oil, 1 Tsp cilantro, 1  scallion, 1 Tbsp vegetable oil, 0.5  onion, 3  garlic cloves, 1.5 Tbsp curry powder, 1 Tsp amchar masala, 0.5 Tsp cumin, 0.5 Tsp salt, 1 cup water, 2  potatoes','Wash and pat dry chicken thighs. In a sealable container, combine all marinade ingredients. Toss chicken in marinade, cover and refrigerate for at least 2 hours.In a Dutch oven, heat vegetable oil over medium high heat. Add onions and saut until tender. Add garlic and continue to saut until fragrant.Sprinkle onions and garlic with curry powder and stir to evenly coat. Add 1 tablespoon of water and cook for one minute, stirring constantly.Add chicken and marinade. Saut until lightly browned, about 5 minutes.If you want a thick curry add potatoes now, otherwise set aside.Sprinkle chicken with amchar masala, cumin and salt. Toss to coat. Pour in one cup of water and bring to a boil.Reduce heat, cover pot and simmer for 20 minutes. If you reserved the potatoes for a thinner curry, add them to the pot after twenty minutes.Continue to simmer for an additional twenty minutes until chicken reaches an internal temperature of 165 F and potatoes are cooked through.Serve warm with roti or rice.',150,150,0);
INSERT INTO "Recipe" VALUES(286,'Caramelized Onion Dip','https://img.spoonacular.com/recipes/716422-556x370.jpg','0.6666667 c caramelized onions, 2 T chives, 1 c greek yogurt, 2 servings salt','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(287,'Savory Cheese Dill Scones','https://img.spoonacular.com/recipes/659463-556x370.jpg','0.75 teaspoon baking powder, 0.5 teaspoon a pinch of baking soda, 0.5 teaspoon pepper, 0.5 cup tablespoons butter, 1 cup buttermilk, 0.5 cup coarsely cheddar cheese, 0.5 cup cottage cheese, 1 tablespoon dill, 1 large shallot, 1 tablespoon sugar, 2.25 cups unbleached flour, 0.5 cup flour','Preheat oven to 375F with the rack in middle position.Make the Scone Mix.Using a Food Processor fitted with a steel knife blade: Place half the butter and half the dry ingredients in the bowl. Pulse until the butter is reduced to pea-sized pieces, with dough still dry. Transfer first half of the mix into a large bowl. Repeat process with the other half of the ingredients and add to the large bowl.By hand: Place all the ingredients in a large bowl and use a pastry cutter to incorporate the butter into the dough. Cut by pressing on butter, then gathering flour onto it in two quick strokes.  Cut until butter slices become pea-sized.Dont over process or mix. Dough will be dry. Break large lumps of butter by hand, and toss dry dough with your fingers.Blend the cheeses, dill, shallot and pepper with the Scone Mix using a wooden spoon. Drizzle the buttermilk over the dough and drop the cottage cheese in the middle, and stir until mixed. Add more buttermilk if dough is too dry to hold together.Place dough on a lightly floured surface and divide into two. Form 2 discs and flatten each to a thickness of about 1-1/2 inches, cut into 6 wedges for a total of 12. Arrange an inch apart on a cookie sheet.Bake for 15 minutes, rotate the pan, and bake another 10 to 15 minutes, until scones are light brown on top and darker at the bottom. Bread should no longer be soft and doughy in the center. Bake in 2 batches if scones dont fit in one cookie sheet.Serve warm or cool in a wire rack before wrapping in foil or plastic wrap/bag. Freshly baked scones can be kept at room temperature for up to 2 days, and in the refrigerator for a week.',45,45,0);
INSERT INTO "Recipe" VALUES(288,'Braised Oxtail','https://img.spoonacular.com/recipes/635846-556x370.jpg','3  bay leaves, 1  carrot, 1 tablespoon celery, 2 servings noodles, 2 tablespoons fat, 2 tablespoons flour, 2  onions, 1  oxtail, 2 servings bell pepper, 2 servings salt, 1 cup tomatoes, 1 cup water','Brown pieces of oxtail in fat. Add onion, carrot and celery and cook until brown. Sprinkle with browned flour. Add hot water, tomatoes, bay leaves, cloves, salt and pepper. Place in casserole and cook in moderate oven (350 degrees) until tender (a minimum of 3 hours). Serve over cooked noodles.',45,45,0);
INSERT INTO "Recipe" VALUES(289,'SLOW COOKER CHICKEN GUMBO SOUP','https://img.spoonacular.com/recipes/660283-556x370.jpg','3 cups chicken, 14 ounce can chicken broth, 1  carrot, 1  bell pepper, 1  onion, 14.5 ounce canned tomatoes, 16 ounce okra, 1.5 cups water, 1 teaspoon cajun seasoning, 0.5 teaspoon pepper, 1 teaspoon salt, 6 servings hot sauce, 1 cup rice','Put all ingredients in crockpot and cook on high for 4 hours or low for 6 to 7 hours.',45,45,0);
INSERT INTO "Recipe" VALUES(290,'Perch Fillets With Shrimp and Vermouth Sauce','https://img.spoonacular.com/recipes/655716-556x370.jpg','250 grams baby shrimp, 1 cup bread crumbs, 3 tablespoons butter, 0.5 cup chicken stock from, 1  egg, 1 cup flour, 3 tablespoons flour, 1 cup heavy cream, 0.5 cup milk, 1 cup peanut oil, 450 grams perch fillets, 1 tablespoon salt, 0.25 cup vermouth rosso','Wash and dry fillets, dust with flour.Mix egg with milk, add salt.Dip fish into egg and milk mixture.Dredge in crumbs. Reserve.Heat butter in pan. Add flour and stir into paste (roux). Cook for 2 minutes (do not allow to brown).Add cream, stock and vermouth. Simmer until thick.Add shrimp. Simmer for 5 minutes on low heat.Heat oil in skillet. Fry fish in oil for 1 -2 minutes each side.Place fried fillets on platter. Pour half the sauce over fish. Serve remainder separately.',45,45,0);
INSERT INTO "Recipe" VALUES(291,'Baked Oatmeal with Dried Cranberries','https://img.spoonacular.com/recipes/633692-556x370.jpg','1 cup almond milk, 2 tsp baking powder, 2  bananas, 1.5 tsp cinnamon, 1 cup cranberries, 2  eggs, 1 tbsp flaxseeds, 3 cups oats, 0.25 teaspoon salt, 1 tsp vanilla extract','1.Preheat oven to 350F2.Mix dry ingredients until well combined.3. Mix liquid ingredients separately.4.Add the liquid ingredients to the dry mix.5.Mix well.5.Spray a pan with a non-stick spray - the smaller the pan, the thicker the bars will be.6.Pour the mix into the pan.7.Bake for 45 minutes.8.Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(292,'Stuffed Lemons in the Oven','https://img.spoonacular.com/recipes/662038-556x370.jpg','2  unwaxed lemons, 4  basil leaves, 2 fillet anchovy, 2  cherry tomatoes, 4 servings salt & pepper',replace('Preheat your oven to 400 F / 215 C\nRemove the ends of the lemons & discard them (dont cut in to deep - you want to keep a closed bottom). Then cut the lemons in half crossways, giving you little lemon bowls.\nUsing a small knife, remove the lemon flesh, leaving you with 4 hollow lemon rind bowls. (Again you dont want to break-into the rind)\nCut a piece of mozzarella to fit inside, then lay a basil leaf, half an anchovy fillet and half a cherry tomato on top with a pinch of salt & pepper and a little drizzle of good olive oil. Put another slice of mozzarella on top - the lemon should now be filled up. Do the same to the rest of the lemon bowls.\nPlace on a baking sheet & cook in a preheated oven for 10 - 15 minutes, until golden & bubbling.\nRemove from the oven and serve immediately. To eat: scoop the mozzarella out and eat with the bread to soak up any juices!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(293,'Simit (Turkish Circular Bread)','https://img.spoonacular.com/recipes/631759-556x370.jpg','400 g flour, 1.3333334 tsp yeast, 40 g molasses, 8 servings olive oil, 1 tsp salt, 150 g sesame seeds, 1 tablespoon water','1. In a medium bowl combine the dry ingredients.2. Make a well in the center and pour the olive oil and lukewarm water into the well.3. Knead the dough with your hands for 5-10 minutes.4. Divide the dough into 16 equal pieces.5. Take two pieces and stretch the dough into thin strips (about 30-35 cm long).6. Cover the rest of the dough to prevent it from drying out.7. Place 2 strips side-by-side, pinch the ends. Twist them together and pinch to join the ends.8. Place the rings on baking sheets lined with parchment paper.9. Let the dough sit in a warm place for 20-30 minutes.10. Preheat the oven to 200C.11. Pour the sesame seeds into the pan and turn the fire on medium heat.12. Stir the seeds every 4-5 minutes until golden. Set aside.13. Pour molasses and boiling water into a bowl big enough to fit your rings.14. Whisk to dissolve the molasses completely.15. Put the sesame seeds in another bowl.16. Dip both sides of the rings in the liquid, drain excess moisture, then coat both sides in the sesame seeds.17. Transfer them to the baking sheets.18. Bake in preheated oven for about 17 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(294,'Mushroom-Pea Risotto','https://img.spoonacular.com/recipes/652722-556x370.jpg','1.5 cups arborio rice, 6 cups chicken broth, 2 cloves garlic, 1 teaspoon olive oil, 2 cups onions, 0.6666667 cup parmesan, 1 cup peas, 8 servings salt and pepper, 8 ounces mushrooms','Bring broth to a simmer, remove from heat and cover.Heat oil in a large skillet over medium heat. Add onions and saute until tender, about 10 minutes. Add mushrooms and garlic and continue to cook until mushrooms are tender. Stir in rice and saute until it become translucent.Reduce heat to medium-low. Add vermouth and cook until the liquid is absorbed. Add broth, 1 cup at a time, stirring often. Be sure all liquid is absorbed before adding the next cup of broth. Continue until rice is tender and creamy.Add peas and Parmesan, season to taste with salt and pepper.',45,45,0);
INSERT INTO "Recipe" VALUES(295,'Spinach Cheese Tortellini',NULL,'2 Tbs butter, 1 large can tomato, 1 package cheese tortellini - prepare, 1 tsp cumin, 1 tsp basil, 2 Tbs flour, 2 cloves garlic, 1 tsp garlic powder, 0.75 cup heavy cream, 0.75 C milk, 2 Tbs olive oil, 1 small onion, 1 tsp onion powder, 1 tsp oregano, 0.25 c parmesan cheese, 2 tsp sugar, 0.25 tsp pepper flakes, 8 servings pepper and salt, 4 cups spinach, 1 tsp thyme','Prepare tortellini per package instructions.In a large stainless steel pan, heat onions in olive oil and butter over medium heat until onions are soft and translucent (about 3-4 minutes). Add the garlic and allow to cook x 1 minutes. Add the tomatoes (juice and all), salt and pepper, garlic powder, onion powder, red pepper flakes, thyme, oregano, cumin and dried basil and raw sugar and allow to simmer for 5 minutes. Add spinach leaves all at once and place lid on the pan so that spinach can wilt. Stir occasionally until leaves are wilted. If tomato mixture becomes to dry  you can add water  cup at a time as needed to wilt the spinach. Continue to allow the tomato mixture to simmer.Once the spinach is wilted, in a small bowl, mix flour, milk and cream together and whisk together with a fork or a whisk. Once well blended, add to the tomato/spinach mixture. Add the Parmesan Cheese.Using a slotted spoon, remove the tortellini from its cooking water and place into the tomato mixture. Gently mix with a wooden spoon being careful not to tear up the tortellini. Heat on stove top until all is heated through. Serve immediately. Garnish with parmesan cheese and fresh basil',45,45,0);
INSERT INTO "Recipe" VALUES(296,'Guinness Braised Corned Beef and Cabbage','https://img.spoonacular.com/recipes/646034-556x370.jpg','2 pounds corned beef brisket, 1 pound carrots, 1 pound parsnips, 3 large potatoes, 2 cloves garlic, 2 cups guinness, 2 cups beef broth, 2 tablespoons pickling spice, 1 tablespoon brown sugar, 1  bay leaf, 3  spicy honey mustard',replace('Season both sides of the corned beef liberally with pepper. The corning of the beef makes the beef salty enough, so no need to add more.\nHeat 1 TBSP oil in a large, shallow oven-safe pot over medium-high heat. Add beef and sear each side for about 3 minutes, just to develop a nice brown crust. This will seal in the beef''s juices.\nRemove beef to a plate. Pour guinness into the pot to deglaze. Scrape up any browned bits. Add beef broth, pickling spice, brown sugar, bay leaf, and minced garlic. Bring mixture up to a simmer.\nReturn the beef to the pot with any additional juices that have accumulated on the plate.\nCover the pot and place on the bottom rack in your oven. Bake for 2 1/2 - 3 hours, or until a fork can easily be inserted into the meat.\nBaste the meat with the surrounding juices every 30 minutes or so.\nAfter 2 hours, add carrots, parsnips, and potatoes to the pot. They will only take about 25-30 minutes of simmering to cook.\nRemove pot from the oven. Place beef on a cutting board and let it rest for 15 minutes before carving into thin slices (cut against the grain of the meat). Remove vegetables and arrange them on a serving platter. Cover with foil. Place the pot on the burner and bring sauce to a boil. Add cabbage and cook for about 7 minutes, until it has softened. Place the cabbage on the serving platter with the other vegetables.\nStrain the sauce in the pot and stir in 2 or 3 TBSP of spicy honey mustard until dissolved. Place in a small dish or gravy boat with a ladle and serve alongside the beef.\nAfter slicing the beef and arranging it on the serving platter, ladle the guinness mustard sauce over the top to rehydrate and glaze the beef and vegetables.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(297,'Strawberry Shortcake Pancakes','https://img.spoonacular.com/recipes/661886-556x370.jpg','0.75 cup greek yogurt, 0.5 cup egg whites, 0.5 cup flour, 0.5 tsp baking soda, 1 tsp almond extract, 0.5 tsp sugar, 1 Dash salt, 0.33333334 cup freeze strawberries, 1 cup strawberries, 1 tsp sugar, 2 Tbsp whip cream',replace('Mix Greek Yogurt, Egg Whites & Almond Extract into a small bowl\nIn a separate bowl combine Flour, Baking Soda, Sugar, & Salt\nCombine and whisk till evenly mixed\nFold in Dried Strawberries\nIn a sauce pan or small pot add frozen or fresh strawberries and 1tsp. sugar and cook until thawed and juicy about 5-7 minutes, stirring occasionally.\nSpray Skillet with cooking spray and place 1/4-cup batter onto skillet and cook till bubbles start appearing through the top of the pancake and then flip. NOTE: Cook on medium heat and I flattened out my batter with the spatula to cook more evenly.\nAbout 1-2 minutes on each side\nTop with strawberry Sauce and Maple Syrup, and add a dollop of fat free whip cream.\nMakes 2 servings, 8 pancakes total, 4 pancakes each.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(298,'Crab Cake Stuffed Shrimp','https://img.spoonacular.com/recipes/640273-556x370.jpg','10 tablespoons butter, 1 cup onion, 1 cup bell pepper, 1 cup bell pepper, 0.5 cup wine, 2 cloves garlic, 8 ounce crab meat, 30  round buttery crackers, 0.5 cup panko bread crumbs, 0.5 teaspoon ground pepper, 1 teaspoon old bay seasoning, 1 teaspoon salt, 1 teaspoon ground pepper, 24 large shrimp, 1  optional: lemon',replace('Line a baking sheet with parchment paper.\nHeat 5 tablespoons butter until melted.\nAdd onion and saute until translucent.\nAdd bell pepper, remaining 5 tablespoons butter, wine and garlic.\nCook until tender (about 4 minutes).\nIn a large bowl, add crab meat, onion mixture, cracker crumbs, panko, red pepper, Old Bay, salt and pepper.\nStir to combine.\nCover and refrigerate for at least 1 hour to 24 hours.\nPreheat oven to 350 degrees.\nUsing a sharp knife and staring at the tail end, butterfly each shrimp.\nPlace each butterflied shrimp on prepared pan, pressing to flatten.\nForm about 3 tablespoons crab mixture into an ball.\nPlace on top of shrimp, pressing the shrimp tail over the crab.\nRepeat with remaining shrimp and crab mixture.\nBake 10 to 15 minutes.\nOPTIONAL:  Squeeze fresh lemon juice over cooked appetizer.\nServe immediately.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(299,'Sweet Potato, Kale & White Bean Soup','https://img.spoonacular.com/recipes/662604-556x370.jpg','1 tablespoon grapeseed oil, 1 medium sweet potato, 1  onion, 1 head kale, 1 quart chicken broth, 0.5 cup white wine, 15 ounces cannellini beans, 1 teaspoon oregano, 0.25 teaspoon thyme, 4 servings salt & ground pepper',replace('In a large pot, heat the grapeseed oil over medium high and add the sweet potato. Saut the sweet potato, stirring consistently about 5 minutes before adding the onion. Saut about 8 minutes then add a splash of chicken broth to help steam the sweet potato and onion (the chicken broth should sizzle when it hits the pot). Continue cooking until sweet potato is softened but still al dente, another 5 minutes or so.\nAdd all of the chicken broth, white wine, cannellini beans and the oregano and thyme. Stir well and bring to a boil. Reduce heat to medium low and simmer covered about 10 minutes. Add the chopped kale leaves, stir, cover again and cook another 5 minutes until kale leaves are softened. Taste the soup and add salt and ground black pepper to taste.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(300,'La Bella Italian Turkey Burger','https://img.spoonacular.com/recipes/649141-556x370.jpg','1 pinch pepper, 4  burger buns, 1  egg, 1 tablespoon extra virgin olive oil, 4 tablespoons extra virgin olive oil, 1 cup basil, 1 cup basil, 8 ounces mozzarella, 1 tablespoon rosemary, 1 tablespoon garlic, 1 pound ground turkey, 1 pound turkey sausage, 1 tablespoon mayonnaise, 1 tablespoon oregano, 0.5 tsp pepper, 2 tablespoons pine nuts, 1  bell pepper, 0.25 teaspoon salt, 1 teaspoon salt, 1 cup spinach leaves, 1 tablespoon thyme','Mix first 8 ingredients together thoroughly then add salt &amp; pepper and olive oil. Form 8 thin patties with the meat mixture. Cut mozzarella into 1/4 inch pieces. On top of one patty, scatter 4-5 mozzarella pieces throughout the center of the meat leaving a little space between each cube. Be careful not to put cheese too close to the edges or it will leak out during grilling. Place another patty on top and seal edges together until cheese is completely buried.Cut off the top of the red bell pepper and remove seeds and core. Then slice into 1/4 rings and brush lightly with olive oil.Pesto Sauce:  In a dry frying pan, quickly toast the pine nuts. Should take less than 3 minutes. In a food processor, pulse basil leaves, toasted pine nuts and salt &amp; pepper. simultaneously adding olive oil through the feed tube. Once good puree is achieved, add the mayo and pulse 2-3 more times, scraping sides to make sure its thoroughly mixed. Cook burgers meat over low to medium heat. Be sure to coat grill with non-stick spray. Cook about 8-10 minutes on each side. Try not to flip the burger too often as it tends to crumble. If the mozzarella starts to ooze out, don''t worry... that''s a sign that your burger is almost done.Place red pepper rings on the upper or outer edges of grill. Cook 2-3 minutes on each side. Brush olive oil on the insides of both halves of the sourdough buns and also place on the upper or outer edges of grill. Remove when lightly toasted.Spread pesto sauce on top &amp; bottom bun. place spinach leaves on bottom bun and place meat on top of spinach leaves. Garnish top of meat with grilled red bell pepper, fold the halves together and you have La Bella Burger!',30,30,0);
INSERT INTO "Recipe" VALUES(301,'Lemon Squares','https://img.spoonacular.com/recipes/649795-556x370.jpg','0.5 teaspoon baking powder, 2  eggs, 2  lemon juice, 1 teaspoon lemon peel, 0.25 cup powdered sugar, 0.25 teaspoon salt, 2 tablespoons sugar, 0.5 cup butter','Sift flour and powdered sugar together. Cut in butter until well blended. Press mixture over bottom of a 9 by 13 by 2-inch pan. Bake about 25 minutes at 300 until lightly browned. Combine remaining ingredients and spread on top of the baked crust. Bake at 350 for 25 to 30 minutes. Sprinkle with powdered sugar.',45,45,0);
INSERT INTO "Recipe" VALUES(302,'Pittata - Pizza Frittata','https://img.spoonacular.com/recipes/622598-556x370.jpg','8  eggs, 2 servings basil, 0.5 cup milk, 2 servings parmesan cheese, 2 servings pepperoni, 0.25 cup mozzarella cheese','1. Pre-heat oven to ~450°F (230°C), top heat only.2. On the stove, heat cooking fat in a large oven-safe skillet over medium heat.3. Beat the eggs with the milk (again milk is optional), salt, pepper, and any herbs or spices desired.4. Add any desired add-ins (other than cheese) to the skillet. For the pittata, we didn''t use anything, but this is when you would add your cooked vegetables or raw vegetables that don''t require much cooking (e.g. bell pepper). Pour in the egg mixture and tilt the skillet to ensure it evenly surrounds any add-ins. Now distribute the shredded cheese and pepperoni slices (if using).5. Allow the eggs to cook on the stove until the edges of the eggs are set. The center will still be a bit jiggly. Now is a good time to top with Parmesan cheese (be generous!)6. Transfer the pan to the hot oven and bake until the eggs are puffed and browned with a firm center. Remove from oven and let cool for a couple minutes before cutting into wedges.',30,30,0);
INSERT INTO "Recipe" VALUES(303,'Loaded Baked Potato Soup with Crispy-Fried Potato Skins','https://img.spoonacular.com/recipes/650231-556x370.jpg','8 slices bacon, 3 lbs russet potatoes, 1  onion, 2 t thyme, 2 T flour, 4 c chicken broth, 1 c half n half, 8 servings salt & pepper, 2 c sharp cheddar cheese, 1 c cream, 8 servings thin- scallion',replace('Using a vegetable peeler, remove wide, long strips of potato peel and set aside. Finish peeling the potatoes. ( I had probably around a 1 1/2 c. peels.)\nHeat a large Dutch oven over medium heat. Add chopped bacon and cook until crisp, about 10 minutes. Remove bacon to a paper towel-lined plate.\nTo the fat in the pan, add the potato skins and cook until crisp about 10 min. (You want to be sure they are crisp, or else they''ll just be soggy and greasy, I took mine out at just the 10 minute mark and they weren''t truly crisp, so I just spread them out on a cookie sheet and baked them in a 400 degree oven for around 5 minutes and they were very crisp after that.)\nRemove the crisped potato skins to the paper-lined plate with the bacon. Add the onion to the fat remaining in the pan, cook until tender and lightly browned, about 6 minutes. Add the thyme and flour, cook and stir for about a minute. Slowly whisk in the chicken broth and the half n half. Add the potatoes and bring to a boil over high heat. Reduce heat to medium-low, cover and cook until the potatoes are very tender, (you should be able to easly crush a piece of potato against the side of the pot with the back of a wooden spoon) about 10-15 minutes.\nUsing a blender, puree (in small batches) all but about 3 cups of the soup. Using a potato masher or your wooden spoon, lightly crush the potato chunks in the reserved potion of the soup. Add the pureed soup back to the pot and return to a low burner to keep the soup hot. Add in the 2 c. cheese, stir until melted, then add in the sour cream, stir well. Season to taste with salt & pepper. (Sometimes I like to add some of the crisped bacon into the soup mixture at this point, but that''s optional.)\nTo serve, top bowls of soup with crisped bacon and potato skins, additional cheddar, sour cream and sliced scallion.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(304,'Basic Hummus','https://img.spoonacular.com/recipes/634389-556x370.jpg','19 oz chickpeas, 1 tablespoon olive oil, 1  juice of lemon, 2 large cloves garlic, 2 tablespoons tahini, 2 tablespoons water, 1 pinch cumin, 1 pinch salt',replace('Puree the tahini in the food processor for about a minute until it becomes a paste.  Then add the olive oil, garlic lemon juice, cumin and salt and pulse until the ingrdients are well incorporated.  Add the chickpeas (skinned or not) in two batches.  Wait for the first batch to be completely smooth until the next one is added.\nThe taste will vary.  If you want the hummus to be smoother it is up to you to add more lemon juice or water to reach your level of smoothness.\nPour hummus into a bowl.  Garnish with  garbanzo beans in the middle of the bowl, paprika (hot or mild), and add your best extra virgin olive oil on top. Serve with warm pita bread (whole wheat preferred).','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(305,'Pasta with Spicy Sausage & Rapini','https://img.spoonacular.com/recipes/654953-556x370.jpg','12 ounces bow tie pasta, 1 tablespoon olive oil, 1 pound spicy sausage, 2 cloves garlic, 4 cups rapini leaves, 0.5 cup chicken broth, 1 cup cream, 0.5 cup milk, 1 cup fontina cheese, 0.5 cup parmesan cheese, 8 servings salt and pepper','Cook pasta according to package directions; drain.  Meanwhile, heat olive oil in a large skillet over medium-high heat.  Add garlic and cook for 1-2 minutes, or until fragrant.  Remove sausage from casings, if necessary, and add to the pan.  Cook the sausage, breaking it up as you go, until no longer pink.  Add the rapini to the skillet and saut until it begins to wilt, about one minute more.  Transfer the sausage and rapini mixture to a plate and keep warm.  Drain excess grease from the pan and return to stove over medium heat.  Add the chicken broth to the skillet and bring to a simmer, scraping any browned bits from the bottom of the pan.  Stir in the sour cream and milk.  Add the cheeses and stir until melted and smooth.  Return the sausage/rapini mixture to the skillet, along with the cooked pasta, and toss to coat.  Garnish with additional Parmesan cheese, if desired.',45,45,0);
INSERT INTO "Recipe" VALUES(306,'Rustic Brie Toasts with Wild Mushroom, Cranberry and Shallot','https://img.spoonacular.com/recipes/658914-556x370.jpg','2 cups mushrooms, 1  shallot, 0.25  1/4 cup dried cranberry (juice sweetened if possible), 1 tsp thyme, 1  rustic baguette, 1 tbsp olive oil, 1  wedge of beautiful brie cheese, 1 pinch salt and pepper',replace('Start by pre-heating your oven to 350 degrees.  While the oven is pre-heating, heat the olive oil in a saut pan and add the shallot, diced mushroom, cranberry and thyme.  Saut for a few minutes until the shallot begins to wilt and then season with salt and pepper and set aside to cool.\nSlice 12 pieces of brie and place each piece on the bread.  Follow with a spoonful of the cranberry, mushroom and shallot mixture and place on an oiled cookie sheet. Bake the toasts for 15 minutes or just until the brie melts.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(307,'Red, White & Blue Crepes: Happy July 4th! @driscollsberry','https://img.spoonacular.com/recipes/716414-556x370.jpg','1 serving blueberries, 1 serving crêpes, 1 serving feta cheese, 1 serving raspberries, 1 serving raspberry fruit spread','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(308,'Lemon Thumbprint Cookies','https://img.spoonacular.com/recipes/649808-556x370.jpg','3 ounces butter, 4  egg yolks, 2.5 cups flour, 0.5 cup granulated sugar, 0.5 teaspoon kosher salt, 1 cup lemon curd, 1 tablespoon lemon juice, 1  lemon zest','Pre heat oven to 350 degrees. Line 2 baking sheets with parchment paper and set aside.With a mixer, beat butter and sugar together in a large bowl until well combined. Beat in yolks, lemon zest, lemon juice, and salt.On low speed, beat in flour just until large moist clumps form. You may need to use your hands at this point to form one large ball.Roll tablespoons of dough into balls. Place balls on prepared baking sheets about 1 inch apart. Make a deep indentation in center of each ball. Bake cookies until firm and lightly golden on bottom, about 18 to 20 minutes.Remove cookies from oven and immediately fill indentations with curd.Sprinkle with confectioners sugar before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(309,'Buffalo Ranch Chicken Dip','https://img.spoonacular.com/recipes/715432-556x370.jpg','4  chicken breasts, 16 oz cream cheese, 0.5 cup green onions, 12 oz louisiana hot sauce, 7 servings paul prudhommes poultry seasoning, 16 oz ranch dressing, 8 oz sharp cheddar cheese','Take your chicken breasts and give them a light coat of the Poultry Magic seasoning, and then coat them with Pam cooking spray. (The Pam keeps the chicken from drying out while cooking.) Grill your chicken breasts and then allow to cool slightly.Preheat your oven to 350 degrees. Shred your chicken and then combine in a 13 x 9 inch glass baking dish with your Louisiana Hot Sauce. Place your cream cheese and dressing into a sauce pan over medium heat until the texture is smooth. Pour this mixture over your chicken and hot sauce mixture in the dish. Top with cheddar cheese and green onions.Bake un-covered for 30 minutes until bubbly. Let stand until slightly cooled, and then serve with tortilla chips of our choice!',45,45,0);
INSERT INTO "Recipe" VALUES(310,'Chocolate Pavlova with Winter Fruit','https://img.spoonacular.com/recipes/639137-556x370.jpg','2 ounces 70% chocolate, 0.25 teaspoon cream of tartar, 2 tablespoons dutch process cocoa powder, 4 large egg whites, 2 cups winter fruit, 1 cup granulated sugar, 2 cups heavy cream, 6 tablespoons confectioner''s sugar, 1 teaspoon tapioca starch, 1 teaspoon vanilla bean paste, 1 teaspoon vanilla extract, 1 teaspoon vinegar','To make the chocolate meringue: Preheat the oven to 225F convection or 250F conventional. Line a rimmed baking sheet with a Silpat or parchment paper.In the bowl of a stand mixer fitted with a whisk attachment, whip the egg whites, vanilla bean paste, and cream of tartar until soft peaks begin to form.Sift together the sugar, cocoa powder, and cornstarch. With the motor running at low speed, add the sugar mixture 1 tablespoon at a time to the egg whites. Add the vinegar and dark chocolate. Whip until fully incorporated and the egg whites hold a stiff peak (the whip attachment will have a sturdy egg white tail when removed).Scoop the mixture onto the prepared baking sheet. Shape into a 9- to 10-inch circle with a slightly higher edge. Bake until the outside is dry and starting to crack slightly, 1 to 1 hours. Turn the heat off and leave the meringue in the oven to cool, about 1 hour.To make the whipped cream: Add the cream, confectioners sugar, and vanilla to the bowl of a stand mixer fitted with a whisk attachment.Whip until the cream holds soft peaks.To assemble: Place the baked meringue onto a serving platter or cake stand. Spread the whipped cream in the center leaving a 2-inch gap around the edge.Arrange the fruit on top and serve immediately.',150,150,0);
INSERT INTO "Recipe" VALUES(311,'Sun-dried Tomato & Artichoke Tuna Casserole','https://img.spoonacular.com/recipes/662287-556x370.png','4  sundried tomato & artichoke tuna casserole: serves, 375 g macaroni, 4  artichoke hearts, 0.5 cup sundried tomatoes, 2 cloves garlic, 1 medium onion, 1 cup milk, 2 tbsp butter, 2 tbsp flour, 0.25 cup marsala, 1.5 cup parmesan, 1 can tuna, 2 tbsp grain mustard, 1 cup panko breadcrumbs, 2 tbsp olive oil, 4 servings salt and pepper',replace('Preheat oven to 375\nPlace six cups of water in a large pot and bring to a boil over high heat.\nLiberally salt the water and add the macaroni.  Cook for approximately nine minutes or until al dente.\nDrain, reserving one cup of the pasta water and set aside.\nSqueeze excess moisture from the artichoke hearts and place them in a food processor along with the tomatoes, onion and garlic.\nPulse until the mixture is finely minced and evenly distributed.  Set aside.\nIn a small saucepan melt butter over medium heat.\nAdd flour whisking constantly until it forms a paste.\nAdd marsala and whisk until incorporated.\nAdd the milk in increments whisking constantly until it forms a thin sauce.\nWhisk in one of Parmesan and the artichoke mixture.  Reduce and bring to a simmer until the cheese is completely melted.\nAdd mustard and tuna and stir to combine.\nSeason with salt and pepper to taste.\nRemove sauce from heat and pour over macaroni, adding as much pasta water as you need to thin the sauce enough to coat the pasta.\nPour macaroni into a prepared nine-inch casserole dish, approximately three inches deep.  Set aside.\nIn a small bowl combine breadcrumbs, the rest of the cheese and olive oil.\nCover macaroni with breadcrumb mixture and garnish with strips of Parmesan if desired.\nBake for 20-25 minutes or until golden brown and bubbly.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(312,'Homemade Oatmeal Cream Pies','https://img.spoonacular.com/recipes/647046-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 1 cup brown sugar, 0.5 cup butter, 0.5 teaspoon cinnamon, 1 teaspoon cocoa powder, 1  egg, 1 cup flour, 7.5 ounces marshmallow fluff, 1 cup powdered sugar, 1 cup rolled oats, 0.25 teaspoon salt, 2 teaspoons vanilla, 1 cup vegetable shortening','Preheat the oven to 350 degrees F. Line cookie sheets with parchment paper. Sift the dry ingredients into a medium bowl and set aside.Use an electric mixer to cream the brown sugar, butter, egg and vanilla. Once smooth, slowly add the dry mixture to the wet until well combined. Stir in the oats.Use a tablespoon-sized scoop to form equal dough balls. Allow them plenty of space to spread. Bake for 7-9 minutes. Allow the cookies to cool completely before moving off the parchment paper.Cream the shortening, powdered sugar, and vanilla together until smooth. Mix in the marshmallow fluff.To assemble: Match up two cookies that are of equal size and shape. Turn the bottom cookies over. Use a piping bag (or zip-bag with the corner cut off) to pipe the filling onto the bottom cookie. This is much easier than trying to spread it. Then add the top cookie of each cream pie and press down.I found I liked a thin layer of cream filling better than a thick layer--but you should have plenty if you want to pile it on!Makes approximately 10 cream pies. (20 cookies)',45,45,0);
INSERT INTO "Recipe" VALUES(313,'Chocolate Pudding - Rave Diet','https://img.spoonacular.com/recipes/639177-556x370.jpg','2 cups water, 0.5 cup maple syrup, 4 tablespoons corn flour, 3 tablespoons cocoa powder, 1 teaspoon vanilla, 3 servings roasted hazelnuts',replace('Combine water, maple syrup, cocoa, cornstarch or corn flour and vanilla together in a saucepan.\nWhisk smooth with a spoon or hand whisker.\nCook over medium heat and stir constantly until pudding is very thick.\nPour into dessert dishes and top with chopped hazelnuts.\nCool and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(314,'Orange & Ginger Chicken','https://img.spoonacular.com/recipes/653785-556x370.jpg','1 cup brown sugar, 1 cup flour, 0.5 teaspoon ginger root, 0.5 teaspoon garlic, 2 tablespoons green onion, 0.25 cup lemon juice, 3 tablespoons olive oil, 1  orange, 0.25 teaspoon pepper, 0.25 teaspoon pepper flakes, 1 cup rice vinegar, 0.5 teaspoon salt, 2  chicken breasts, 2.5 tablespoons soy sauce, 2 tablespoons water','Pour 1 1/2 cups water, orange juice (about 1/4 cup from the fresh orange), lemon juice, rice vinegar, and soy sauce into a saucepan and set over medium-high heat.Stir in the tablespoon orange zest, brown sugar, ginger, garlic, chopped onion, and red pepper flakes. Bring to a boil.Remove from heat, and cool 10 to 15 minutes.Place the chicken pieces into a resealable plastic bag. When contents of saucepan have cooled, pour 1 cup of sauce into bag.Reserve the remaining sauce. Seal the bag, and refrigerate at least 2 hours.In another resealable plastic bag, mix the flour, salt, and pepper. Add the marinated chicken pieces, seal the bag, and shake to coat.Heat the olive oil in a large skillet over medium heat. Place chicken into the skillet, and brown on both sides. Drain on a plate lined with paper towels, and cover with aluminum foil.Wipe out the skillet, and add the sauce. Bring to a boil over medium-high heat. Mix together the cornstarch and 2 tablespoons water; stir into the sauce. Reduce heat to medium low, add the chicken pieces, and simmer, about 5 minutes, stirring occasionally.',180,180,0);
INSERT INTO "Recipe" VALUES(315,'Cheesy Chicken Enchilada Quinoa Casserole','https://img.spoonacular.com/recipes/715421-556x370.jpg','1 small avocado, 0.5 tsp pepper, 15 oz black beans, 10 oz canned tomatoes, 0.5 tsp chili powder, 1 cup quinoa, 0.5 tsp cumin, 10 oz verde enchilada sauce, 2 Tbsp cilantro, 4 servings green onion tops, 1  roma tomato, 4 servings salt, 2 cups cheese, 1  chicken breast, 15 oz corn, 0.5 tsp pepper','To get started, heat your oven to 350 and prepare an 8x8 baking dish. Cook the quinoa according to the instructions. If you haven''t already, boil and shred your chicken breast.In a medium sized mixing bowl add 2 Tbsp cilantro, 1 cup shredded cheese, quinoa, tomatoes with chilis, black beans, half of the can of sweet corn, verde enchilada sauce, cumin, chili powder, white pepper, black pepper, and salt to taste. Mix everything well, and then pour into the 8 x8 baking dish. Cover with the last cup of cheese and then bake in the oven for 15 minutes.Remove from oven and allow to cool for 5 minutes. Then top with chopped Roma tomato, chopped avocado, green onion tops, and remaining 2 tsp of cilantro. Serve immediately.',30,30,0);
INSERT INTO "Recipe" VALUES(316,'Salmon with roasted vegetables','https://img.spoonacular.com/recipes/659135-556x370.jpg','1  potato, 1  parsnip, 1  carrot, 1  onion, 150 g cherry tomatoes, 2 fillet salmon, 1 tbsp olive oil, 1 tsp lemon juice, 2 servings salt, 2 tsp rosemary and thyme',replace('Season the salmon fillets with some salt, pepper and a pinch of paprika and keep aside.\nPreheat the oven to 200 C.  Roughly dice the potatoes, parsnips and carrots and add to a roasting tray. Drizzle over the olive oil and season with salt and pepper. Mix well and roast for 15 minutes. Add in the onion and roast for a further 10-15 minutes\nPlace the salmon fillets and tomatoes between the veg. Drizzle the lemon juice and sprinkle over the rosemary and thyme. Season lightly with salt and pepper and roast for 10-15 minutes or until the salmon and veg is cooked through.\nServe with some green salad.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(317,'One Soup, Two Ways: Chunky Vegetables and Cream Of Vegetables','https://img.spoonacular.com/recipes/653687-556x370.jpg','1 tablespoon olive oil, 3 cloves garlic, 1 small onion, 2 medium carrots, 2 stalks celery, 1 pinch salt, 1 cup tomato puree, 1 can corn, 1 liter chicken broth, 1 can beans, 1 pinch herbs like: thym, 0.5 cup cooking cream, 3 pinches turmeric',replace('For chunky vegetable soup: Heat olive oil over medium low heat in a soup pot (big enough to hold everything you have) and throw in garlic, onions, carrots and celery.\nStir around a bit, add the salt and cover. Let sweat for about 10 minutes.\nAdd the tomato puree and corn, stir, let cook for a few minutes.\nThen add the broth, turn heat up to maximum and bring to a boil.\nAdd the beans. Season with dried herbs.\nFor the Cream of Vegetables: Transfer half of the chunky soup into another soup pot.\nWhiz everything up with a hand-held blender, or in a blender. Then use a sieve, and "filter" the soup.\nBring back to a boil, add  cream, turmeric, curry powder, cayenne pepper and stir well.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(318,'Meatball Sliders','https://img.spoonacular.com/recipes/651341-556x370.jpg','0.5  california bay leaf, 3 cups coarse bread crumbs, 0.5 teaspoon marjoram, 2 large eggs, 0.5 cup flat-leaf parsley, 4  garlic cloves, 5  garlic cloves, 1 pound ground pork, 1 pound ground beef, 0.25 cup olive oil, 0.5 teaspoon oregano, 1.5 cups parmesan, 20 small slider buns, 1 teaspoon sugar, 56 ounce tomatoes in juice, 2 cups vegetable oil, 0.6666667 cup milk, 1 medium onion','To make the tomato sauce:Pure tomatoes with their juice in a blender and transfer to a bowl.Heat oil in a large heavy pot over medium-high heat and saut onion until golden, about 6 minutes. Add garlic and saut, stirring, 1 minute. Add tomato pure, sugar, bay leaf, and 1 1/2 teaspoons salt and simmer, uncovered, stirring occasionally, until thickened, 40 to 50 minutes. Discard bay leaf.Make meatballs while sauce simmers:Stir together bread crumbs and milk in a large bowl and let stand 10 minutes. Add meat, garlic, cheese, eggs, parsley, oregano, marjoram, 1/2 teaspoon salt, and 1/2 teaspoon pepper and blend until just combined well (do not overmix). Form level 1/4-cup portions into meatballs.Heat oil in a 10-inch heavy skillet over medium-high heat hot and fry meatballs, about 6 at a time, turning occasionally, until well browned and cooked through, 4 to 6 minutes per batch. Transfer to paper towels with a slotted spoon.Simmer meatballs in sauce and assemble sliders:Add drained meatballs to tomato sauce and simmer, stirring occasionally, until meatballs are heated through.Assemble sliders with a meatball and 1 tablespoon sauce per bun. Garnish with baby greens and secure each with a wooden pick.',45,45,0);
INSERT INTO "Recipe" VALUES(319,'Potato Soup With Peppers and Olives','https://img.spoonacular.com/recipes/657000-556x370.jpg','300 g potatoes, 2 cloves garlic, 4 servings olive oil, 2 tablespoons roasted and marinated peppers, 12  blacks olives, 4 servings oregano, 4 servings salt and pepper',replace('In a saucepan, fry  garlic in olive oil until tender.\nAdd potatoes, oregano and a pinch of salt.\nCover with water (300 ml-400ml) and cook for 30 minutes or until potatoes are soft OR\nTo speed up cooking, cook the potatoes, with some water, in a microwave oven for 15 minutes on MAX.\nPuree potatoes, peppers or pepper sauce and  4 olives in a blender.\nAdd water if too thick, season with pepper and salt.\nServe warm or hot, decorated with remaining olives.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(320,'Blackberry Pie Cobbler','https://img.spoonacular.com/recipes/635233-556x370.jpg','3  pie crusts, 1 cup sugar, 2 Tbs flour, 2 tsp real vanilla extract, 1.5 lbs blackberries - preferred - is ok too, 2 Tbs butter into pieces, 1  egg, 1 Tbs sugar',replace('Preheat oven to 450. Unroll one pie crust onto a lightly floured surface and set your pie plate onto the crust. Using the pie plate as a pattern, cut around the bottom of the pie plate with a butter knife. (This will form the middle crust in your pie/cobbler). Place this circle onto a baking sheet lined with parchment paper, waxed paper or aluminum foil. Place this on the center rack of the oven and bake until the pastry is dry and lightly browned and developing small bubbles on the surface  about 10 minutes. Set this pie crust aside to cool.\nInto a pie plate, place one refrigerated pie crust and allow the extra to hang over the edges.\nUnroll the final pie crust onto a lightly floured surface and cut into 1  inch wide strips.\nIn a small bowl, combine the sugar and the flour and set aside. Stir the vanilla into a  Cup of water.\nScatter  of the blackberries into the the bottom pie crust that is in the pie plate. Sprinkle half of the sugar mix over the berries and half of the water mix over the berries. Scatter  of the butter chunks onto the berries as well.\nPlaced the prebaked pie crust on top of the berries and repeat step 5 above, scattering the remaining berries, sugar, water and butter.\nUsing the strips of cut pie crust, weave the top of the pie crust. Wetting your fingers with water, dampen the underside of each strip where it will attach to the bottom pie crust and pinch together. Going around the pie plate  crimp the bottom edge and top edge together. Using a pastry brush, brush the top of the pie with the beaten egg. Sprinkle with the Raw Sugar.\nPlace the pie on a baking sheet to catch any drips and place on the bottom rack of the oven. Bake for 10 minutes at 450 and then reduce heat to 350 for another 45 minutes or until the filling is juicy and bubbling up through the pastry strips. Place on a cooling rack or folded kitchen towel and let cool for at least 20 minutes. Serve warm or at room temperature.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(321,'Berry & Ricotta Danishes','https://img.spoonacular.com/recipes/634846-556x370.jpg','5 servings glaze, 5 servings poached berries, 0.5 cup blueberries, 1  egg yolk, 5 servings pastry, 2 tablespoons flour, 4 tablespoons icing sugar, 3 tablespoons lemon juice, 0.5 teaspoon lemon zest, 3 sheets puff pastry, 1 cup ricotta cheese, 12  strawberries, 0.25 cup castor sugar, 2 tablespoons castor sugar, 1 teaspoon vanilla extract, 0.125 cup water','Method:Thaw puff pastry according to packet instructions. Once thawed, place pastry in the fridge to keep cool while you prepare the other ingredients.Place the berries in a saucepan over a medium-low heat. Sprinkle on castor sugar and add water. Cover saucepan with a lid and shake the saucepan around to coat the berries. Poach berries for about 5 minutes or until they soften but still retain their shape. Set aside to cool.Pre-heat the oven to 180C (350F).Make the ricotta filling by combining all ingredients in a mixing bowl. Mix well with a wooden spoon to thoroughly combine. Set aside.Prepare the glaze by mixing icing sugar and lemon juice together in a small bowl. Mix well and set aside.Remove the pastry from the refrigerator and place sheets on a clean, dry surface. Use a small, sharp knife to cut 10 8cm x 6cm (3" x 2.5") rectangles. Place 5 of the pastry rectangles on the lined baking sheet, making sure there is space in between them as they will expand. Lightly brush edges with a little water. We will call these the "pastry rectangle bases".Cut smaller rectangles out of the remaining 5 pastry rectangles so that you have small frames of about 1.5cm (1/2") in width.Danish1Place the frames on top of the pastry bases on the baking sheet. See the diagram below.Danish2Fill the middle of the frame with about 3-4 tablespoons of ricotta mixture. Top with several berries (reserve some for topping once the danishes are baked).  Repeat process with remaining pastry frames.Place in the oven and bake for 15 to 18 minutes or until the pastry puffs up and is golden. Remove from oven and cool on a wire rack. Top with remaining poached berries and sprinkle on a little icing sugar just before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(322,'Slow Cooked Applesauce','https://img.spoonacular.com/recipes/660261-556x370.jpg','5  apples from a local tree if possible, 1 cup water, 3 tablespoons brown sugar, 0.5 teaspoon cinnamon, 1 pinch nutmeg, 1 pinch salt','Peel and core apples. Thinly slice and rough chop them. Add them to a medium-to large pot over medium-high heat on the stove. Add water and stir. Once the water starts to simmer, reduce heat to med-low and stir. Add cinnamon, nutmeg and salt and stir. Cook over medium low heat for 2 hours, stirring occasionally. Depending on how you like the consistency of your applesauce, cook another hour for softer sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(323,'Simit (Turkish Circular Bread)','https://img.spoonacular.com/recipes/631759-556x370.jpg','400 g flour, 1.3333334 tsp yeast, 40 g molasses, 8 servings olive oil, 1 tsp salt, 150 g sesame seeds, 1 tablespoon water','1. In a medium bowl combine the dry ingredients.2. Make a well in the center and pour the olive oil and lukewarm water into the well.3. Knead the dough with your hands for 5-10 minutes.4. Divide the dough into 16 equal pieces.5. Take two pieces and stretch the dough into thin strips (about 30-35 cm long).6. Cover the rest of the dough to prevent it from drying out.7. Place 2 strips side-by-side, pinch the ends. Twist them together and pinch to join the ends.8. Place the rings on baking sheets lined with parchment paper.9. Let the dough sit in a warm place for 20-30 minutes.10. Preheat the oven to 200C.11. Pour the sesame seeds into the pan and turn the fire on medium heat.12. Stir the seeds every 4-5 minutes until golden. Set aside.13. Pour molasses and boiling water into a bowl big enough to fit your rings.14. Whisk to dissolve the molasses completely.15. Put the sesame seeds in another bowl.16. Dip both sides of the rings in the liquid, drain excess moisture, then coat both sides in the sesame seeds.17. Transfer them to the baking sheets.18. Bake in preheated oven for about 17 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(324,'Chocolate Coconut Banana Bread','https://img.spoonacular.com/recipes/716379-556x370.jpg','2.6666667 cups all purpose flour, 0.5 teaspoon baking powder, 0.25 teaspoon baking soda, 4  bananas, 9 tablespoon butter, 0.5 cup coconut flakes, 4  eggs, 1 pinch salt, 0.5 cup semi-sweet chocolate chips, 3.6666667 cups sugar','Combine the wet ingredients in a bowl.Combine the dry ingredients in a separate bowl except the coconut flakes and chocolate chips.Pre-heat your oven to 375F.Combine both wet and dry ingredients and beat till the mixture is smooth.Grease your baking pans with some oil and pour in mixture into baking pans (this "Recipe" makes enough for two loaves). Top it with the chocolate chips and coconut flakes.Place in the oven and bake for 30-35 minutes.Serve warm with tea or coffee',45,45,0);
INSERT INTO "Recipe" VALUES(325,'Sweet Florida Orange Breakfast Bread','https://img.spoonacular.com/recipes/662515-556x370.jpg','3 cups flour, 0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 0.5 teaspoon salt, 0.75 cup buttermilk, 0.5 cup orange juice, 2 teaspoons vanilla extract, 0.5 pound butter, 2 cups sugar, 4  eggs, 0.25 cup orange zest, 0.5 cup brown sugar, 4  note: i used oranges',replace('Preheat oven to 350F.\nGrease and lightly flour loaf pans.\nIn a medium bowl, whisk together flour, baking powder, baking soda, and salt. Set aside.\nMeasure buttermilk, orange juice, and vanilla into a measuring cup. Set aside.\nIn a large bowl, use a mixer to beat the butter until creamy.\nBlend in sugar and beat for a few minutes until light and fluffy.\nMix in eggs, one at a time, and orange zest, and beat until well incorporated.\nWith mixer on low, slowly pour in 1/3 of the flour mixture.\nMix in half of the buttermilk mixture.\nBlend in another 1/3 of the flour mixture and remaining buttermilk mixture.\nAdd remaining flour mixture and mix until just blended.\nDivide batter between prepared pans, filling about 3/4 full, and bake for 30 to 35 minutes (45 minutes if using a large loaf pan) or until a toothpick inserted in center comes out clean.\nWhile loaves bake, prepare orange simple syrup.\nStir together 1/2 cup orange juice and 1/2 cup brown sugar in a small pot. Bring to a boil over medium heat while occasionally stirring, then reduce heat and simmer for a few minutes. Remove pot from heat and set aside to cool.\nWhen cakes are done, cool for 10 minutes before turning out onto wire rack. Set rack over a sheet pan or piece of foil, and using a brush or a spoon, soak each cake with simple syrup. Allow to cool completely.\nStore in an airtight container or wrap tightly.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(326,'Spicy Salmon Patties','https://img.spoonacular.com/recipes/661186-556x370.jpg','16 oz pink salmon, 2  eggs, 0.25 cup parsley flakes, 2 tbsp scallions, 0.25 cup bread crumbs, 0.5  juice of lemon, 4 servings pepper flakes, 2 tbsp mayonnaise, 1 tbsp lemon juice',replace('Prep salmon: remove skin; crush bones with thumb and index finger leaving them in for added calcium.\nKnead together salmon with eggs, parsley, scallions, bread crumbs, lemon juice and red pepper flakes.\nCook in a lightly-oiled cast-iron pan over medium heat until golden brown. Serve warm, with sauce.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(327,'Gluten Free Waffles','https://img.spoonacular.com/recipes/644860-556x370.jpg','3 teaspoons baking powder, 0.5 tsp himalania pink salt, 1 cup brown rice, 0.5 cup potato starch, 0.25 cup tapioca flour, 0.5 cup coconut oil, 1.5 cup coconut milk, 2 tsp honey, 0.5 teaspoon baking soda, 3  eggs','Mix all dry ingredients in a large bowl, and slowly mix in wet ingredients. Cook on low in waffle machine.',45,45,0);
INSERT INTO "Recipe" VALUES(328,'Cheesy Ham and Shrimp Macaroni Au Gratin','https://img.spoonacular.com/recipes/637658-556x370.jpg','150 g broccoli, 300 g cream sauce, 250 g elbow pasta, 3 slices ham, 3  big shitake mushrooms, 2 tablespoons olive oil, 1 oz parmesan and m zarella cheese, 10 medium shrimps, 1 cup water','Cut off base of broccoli stem. Cut broccoli into florets. Remove skin from stem using a peeler and dice it. Wash broccoli thoroughly.Blanch broccoli and butter them.Rinse and dice mushrooms and ham. Add into sauce and mix well.Remove shells from shrimps and devein. Dice and set aside.Preheat oven at 250C. Cook pasta accordingly to instructions. Drain.Grease tin foils. Put pastas into foils and distribute sauce mixture evenly. Stir well.From Step 1 until the above, you can actually prepare ahead of time and refrigerate them with covers if youve guests coming over. Then follow by the rest of the steps below.Mix shrimps and broccoli stems evenly. Place broccoli florets, and top with cheese.Bake the gratin at 250C till golden brown. My oven took about 7 mins to brown. Look at how cheesy it turned out! Crispy on the outside and creamy inside. Enjoy your Cheesy Ham and Shrimp Macaroni Au Gratin!',45,45,0);
INSERT INTO "Recipe" VALUES(329,'Macaroni and Cheese Gratin','https://img.spoonacular.com/recipes/650546-556x370.jpg','1.5 cups herbed bread crumbs, 1 tablespoon butter, 2 cups cheddar, 1 pound elbow macaroni, 1 tablespoon flour, 2 cups gruyere, 4 cups milk, 0.25 teaspoon nutmeg, 0.25 cup parmesan, 0.33333334 cup parsley, 3 drops pepper sauce, 0.5 teaspoon salt','Bring a pot of water to a boil. Add salt and add macaroni and cook until not quite al dente (macaroni will continue to cook in the oven).In another pot melt the butter, add the flour and stir with a whisk or a wooden spoon for a couple of minutes to cook the flour.Add the milk, 1/2 cup at a time whisking until the mixture thickens, then add remaining milk and let cook over low heat until the sauce thickens, stirring constantly, scraping from the bottom of the pan and being careful not to burn it at the bottom.When the sauce is thick add the grated cheeses and stir until melted. Stir in the nutmeg, hot pepper sauce and salt, remove from heat and set aside.When the macaroni is cooked drain into colander and return to the pot. Pour the cheese sauce over the macaroni and stir with a wooden spoon.Pour the macaroni into individual gratins or a large buttered baking dish. You can add a few tomato slices into the macaroni either half way through pouring it into the pan or at the end, tucking them in with a knife. Don''t smooth out the top, allow a few peaks here and there, they will become crisp and delicious as you bake it.To make the topping:Melt the butter, pour over the bread crumbs in a bowl and mix to combine. Add the Parmesan and parsley.To bake:Sprinkle topping over macaroni, bake in 400 oven 10-15 minutes or until crumbs are nicely golden. Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(330,'Caramel Peanut Fudge Cake','https://img.spoonacular.com/recipes/637016-556x370.jpg','100 g almonds, 25 g cocoa, 300 g chocolate of at least cocoa parts, 500 ml cream, 6  eggs, 150 g peanuts, 1 Tbs rum, 150 g sugar, 2 Tbs water','For the sponge, beat egg yolks with sugar for 3-4 minutes until the mixture doubles in volume and becomes pale yellow.Whisk the egg whites until soft peaks form.Fold the egg whites gently into the egg yolks cream.Gently stir in almonds and cocoa.Lightly butter and flour a 20 round cake pan, line with parchment paper. Pour in the sponge mixture Bake in preheated oven at 180C for about 20 minutes or until done (the trick with a toothpick).Leave the cake to cool completely in the cake pan, then carefully remove it and split into two layers.For the caramel cream heat sugar and water over medium heat and cook, stirring occasionally, until the sugar dissolves and comes to a boil. Continue cooking, but without stirring, until mixture becomes golden amber in color. Remove from flame and set aside.Whip the cream, gradually stir in the caramel syrup.Add peanuts, stir and combine. Mixture must be smooth (at first it will foam up a little). Transfer the cream to a bowl to cool down to room temperature and thicken.For the ganache bring the cream just to a boil over medium-high heat; pour over chocolate. Let stand 10 minutes. Stir very gently for 3-4 minutes until smooth and glossy, incorporating the cream steadily, without overworking.Cool ganache for an hour or until completely chilled, then beat for 2-3 minutes or until it becomes fluffy and lighter in color. Do not overbeat because it will become too thick and not spreadable.To assemble the cake, first sprinkle each cake layer with half of the rum and water syrup.Spread the caramel cream over the bottom layer, cover with the top layer (wet side down).Immediately spread ganache over top and sides of cake.',45,45,0);
INSERT INTO "Recipe" VALUES(331,'Lemon Fish with Sweet Potatoes','https://img.spoonacular.com/recipes/716369-556x370.jpg','1 tablespoon butter, 1  chili pepper, 1 serving coconut sauce, 0.5 cup coconut milk, 2 fillet croaker fish, 1  garlic clove, 1  seasoning cube, 1 serving half of a seasoning cube, 0.25  lemon, 0.5  bulb of onion, 1 serving sprinkle of parsley, 1 tablespoon pepper soup spice, 1 large sweet potato, 1 teaspoon vegetable oil','Wash and place your potatoes in a pot and bring to boil till soft. Peel, slice and set aside.Season your fish with pepper soup spice and set aside.Preheat your butter and vegetable oil and fry your onions and pepper on medium heat for one minute.Add your fish and squeeze your lemon over the fish and sprinkle the seasoning cube and allow to cook on low heat. When brown, flip over so it can brown on the other side.For your sauce, heat up your coconut milk, garlic, seasoning cube and parsley and allow to thicken a bit.Serve the fish and potato with the sauce drizzled over it and garnish with extra chili. ',45,45,0);
INSERT INTO "Recipe" VALUES(332,'All American Sloppy Joes','https://img.spoonacular.com/recipes/632071-556x370.jpg','100 grams american barbecue sauce, 4  burger buns, 2  garlic cloves, 0.5  bell pepper, 450 grams ground beef, 1 teaspoon hot sauce, 1 tablespoon olive oil, 4 servings salt and pepper, 2  shallots, 180 grams tomato sauce, 0.6666667 tablespoon worcestershire sauce','Heat the olive oil in a large skillet. Add in minced garlic, shallots, and green bell pepper.  Stir until fragrant and tender, about 3 minutes. Season it with salt and black pepper.Add the ground beef to the vegetables. Stir and cook about 5 minutes, until the meat is no longer pink and fully cooked. Add tomato sauce, barbecue sauce, Worcestershire, and hot sauce into the skillet. Stir to combine. Simmer until thickened.To serve, spoon and pile sloppy meat onto the toasted, buttered bun bottoms and cover with bun tops with your favourite side dish or pickles.',45,45,0);
INSERT INTO "Recipe" VALUES(333,'khichdi "Recipe"','https://img.spoonacular.com/recipes/765725-556x370.jpg','1  bay leaf, 2 servings chili slit, 0.5 tsp cumin, 1 tbsp ghee, 1 tsp ginger, 0.75  lentils, 1 slices very few onion, 0.5 tsp chili powder, 0.75 cup rice, 2 servings salt, 0.5 cup tomato, 2 servings turmeric little, 2.5 cups water','find complete "Recipe" at swasthi''s blog',30,30,0);
INSERT INTO "Recipe" VALUES(334,'Cod with tomatoes, olives and polenta','https://img.spoonacular.com/recipes/639850-556x370.jpg','0.75 cup olives, 500 g cod fillets, 0.5 cup corn polenta, 3 Tbs corn flour, 0.25 cup wine, 4 servings parsley, 0.25 cup olive oil, 1 pinch oregano, 4 servings oregano, 1 pinch salt, 1 pinch salt, 1 pound tomatoes, 2 Tbsp water, 0.5 tsp pepper, 0.25 cup white wine','If the fillets are frozen, thaw them.Mix corn flour, salt and white pepper.Dredge the fillets through the flour mixture, and saut them in the oil for 3 minutes on each side.Sprinkle the fillets with white wine.Add tomatoes and olives, cook for about 5 minutes.Before serving, season the fillets with  oregano and parsley.To make polenta, bring the water to the boil, add wine, oregano and the salt. Gradually stir in the instant polenta and cook, stirring constantly, about 5 minutes or until done. Add some boiling water if needed. Cool slightly and serv with the fish.',45,45,0);
INSERT INTO "Recipe" VALUES(335,'Bacon-Wrapped Meatloaf','https://img.spoonacular.com/recipes/633372-556x370.jpg','3 tablespoons apple cider vinegar, 1 tablespoon butter, 2 teaspoons mustard, 2 large eggs, 1 tablespoon thyme, 2  garlic cloves, 0.5 teaspoon ground pepper, 2 pounds a mixture of 1 pound ground chuck and 1 ground pork, 3 tablespoons honey, 0.25 cup milk, 1 teaspoon mustard, 1 medium onion, 0.5 teaspoon salt, 1 teaspoon salt, 8 slices bacon, 6 oz tomato paste, 3 tablespoons water','Preheat the oven to 350 F.Melt the butter in a small skillet over medium-low heat; cook the onion until soft but not brown, about 5 minutes.  Add the garlic and cook for another minute.  Remove from heat and set aside.Place a rack on or in a large, glass baking dish.  Alternating slightly, lay the strips of bacon across the rack, one end in the middle and allowing the other end to hang over the side of the dish.  Set aside.In a small bowl, mix 3 tablespoons of the tomato paste with the water, apple cider vinegar, honey, prepared mustard and 1/2 teaspoon of salt.  Set aside.In a large mixing bowl, combine the remaining ingredients with the onion/garlic mixture and the remaining tomato paste and gently but thoroughly mix with your hands.  Form into a loaf directly on top of the bacon, leaving enough of the bacon uncovered to wrap the top of the meatloaf.  Spoon the glaze over the top of the meatloaf and spread down the sides, covering it completely.  Lift the ends of the bacon hanging down the sides and place over the top of the meatloaf.Bake for an hour, or until the meatloaf is cooked through and the bacon is brown and crisp.  Allow to rest for 10 minutes before serving.',90,90,0);
INSERT INTO "Recipe" VALUES(336,'Zabaglione with Roasted Plums','https://img.spoonacular.com/recipes/665620-556x370.jpg','12  plums, 6 tablespoons sugar, 4 large egg yolks, 0.25 cup plum brandy, 4 servings kosher salt',replace('1.Heat the oven the to 400F. Place the plums on a rimmed cookie sheet (lined with parchment paper for easier cleanup) and sprinkle with 2 tablespoons of the sugar. Roast until the plums are browning and tender but not falling apart, about 15 minutes.\n2.Bring about 2 inches of water to a bare simmer in a saucepan over medium-high heat. Reduce the heat to maintain a bare simmer. Combine the egg yolks, the remaining 4 tablespoons sugar, the plum brandy mixture, and a pinch of salt in a round-bottomed metal mixing bowl; whisk thoroughly.\n3.Set the bowl over the simmering waterthe base of the bowl should not touch the waterand whisk continuously. The egg yolks will begin to froth, lighten, and grow greatly in volume. If you sense that the yolks are at risk of scrambling, quickly remove the bowl from the heat and whisk to cool slightly, then continue. When soft peaks form, after 5 to10 minutes, the zabaglione is done. Transfer to a clean bowl, cover, and refrigerate.\n4.To serve, place 6 plum halves in the bottom of each of 4 glasses. Give the zabaglione a quick whisk and spoon it on top of the plums. Serve immediately.','\n',chr(10)),20,20,0);
INSERT INTO "Recipe" VALUES(337,'Chinese Potstickers','https://img.spoonacular.com/recipes/638693-556x370.jpg','200 g ground pork, 100 g water chestnuts, 1 teaspoon sea salt, 1 teaspoon sugar, 0.5 teaspoon ground pepper, 2 teaspoons soy sauce, 2 teaspoons sesame oil, 1 tablespoon shaoxing huatiao wine, 2 tablespoons scallions, 25  dumpling wrappers, 24 servings flour to dust, 4 tablespoons vegetable oil, 0.6666667 cups water',replace('Place 200g of ground pork in a large mixing bowl. If preferred, pork may be substituted with ground chicken.\nAdd 1 teaspoon of sea salt, 1 teaspoon of fine sugar, add 1/2 teaspoon of ground black pepper, 2 teaspoons of light soy sauce, 2 teaspoons of sesame oil and 1 tablespoon of Shaoxing Huatiao wine.\nPlace 100g of canned water chestnuts in a chopper/blender. Chop the water chestnuts to small pieces. Add the chopped water chestnuts to the pork mixture. If preferred, use spinach or cabbage in place of water chestnuts.\nAdd 2 to 3 tablespoons of finely chopped scallions or spring onions to the pork mixture. Combine all the filling ingredients well.\nThaw the dumpling wrappers if they are frozen. Keep them well covered until they are ready to be used.\nDust a dish generously with flour. This will hold the dumplings once they are made.\nDust the table generously with flour. Carefully separate the sheets of dumpling wrappers and lay them on the table. Fill each wrapper with about 1.5 teaspoons of the prepared pork filling.\nPrepare a bowl of water. Dip finger into the water and lightly wet the rim of each dumpling wrapper.\nBring the dumpling wrapper together till the opposite ends meet. Gently push the filling into the wrapper and pinch the top tip of the dumpling wrapper to seal it.\nFrom the centre of the dumpling, fold a pleat on ONE side and bring it to the other side of the dumpling. Fold towards the centre of the dumpling. Pinch to seal it.\nRepeat and create a 2nd pleat. Be mindful to pinch tight to seal the dumpling well. Repeat and create a 3rd pleat. Each side should have 3 pleats.\nRepeat the same pleating on the other end of the dumpling. Always ensure that the pleats face the centre of the dumpling.\nPlace all prepared dumplings in a well floured dish ensuring that they do not touch each other. Set aside till ready to cook. They can also be frozen at this stage.\nTo cook the potstickers, add 2 to 3 tablespoons of vegetable oil to a very hot frying pan. The potstickers should be cooked in at least 2 batches.\nWhen the oil is hot, add the dumplings ensuring that the flat surfaces face down. Pan fry till the bottoms of the dumplings are a nice golden brown.\nAdd 1/3 cup of water to the pan. Cover the pan immediately and let the steam cook the dumplings for 4 to 5 minutes.\nOnce the water has evaporated, remove the cover and let the dumplings sit in the hot pan for another minute for its base to crisp up again. These are now Chinese potstickers.\nGently transfer the potstickers to a plate. Serve immediately.\nThese Chinese potstickers are best served with a vinegar dip made with balsamic or black chinese vinegar and thinly sliced ginger. Soy sauce, chili oil or sesame oil may also be added to the dipping sauce.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(338,'Easy Chicken Tikka Masala',NULL,'3  chicken breasts, 4 tablespoons grape seed oil, 1 large onion, 2 cloves garlic, 1 teaspoon garam masala, 1 teaspoon cumin, 1 teaspoon coriander, 0.25 teaspoon turmeric, 0.125 teaspoon cardamon, 0.25 teaspoon cinnamon, 2 teaspoons ginger, 0.5 teaspoon cayenne, 1 tablespoon paprika, 1 teaspoon tomato paste, 1  tomato, 0.5 cup water, 0.5 cup yogurt, 4 servings coriander, 4 servings salt',replace('In a small bowl mix all the spices including the ginger. Set aside.\nIn a large saucepan, heat the oil .\nAdd the onions and cook until golden brown.\nAdd the garlic and continue to cook for a minute.\nStir in the spices and allow the flavours to infuse.\nStir in the tomato paste.\nAdd the chopped tomato and pour in the water. Simmer and season with salt to taste.\nAdd the chicken pieces stirring well to coat the meat with the sauce. Continue to simmer until the chicken is cooked and the sauce has thickened, about 12 minutes.\nStir in the yogurt and continue to simmer 5 minutes.\nGarnish with chopped fresh cilantro\nServe with bismati rice.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(339,'Greek Inspired Spring Omelet','https://img.spoonacular.com/recipes/645315-556x370.jpg','3  asparagus spears, 0.33333334 cup egg whites, 1 Tbsp feta cheese, 1 serving green onions, 1 serving salt and pepper, 1 Tbsp tzatziki, 4  cherry tomatoes','In a medium skillet saute asparagus until tender, about 7 minutes. Set aside.In a small bowl combine egg whites and tzatziki; stir to combine.Spray non stick skillet with cooking spray and bring to medium heat. Pour in egg white and allow it to spread over the skillet surface. Cook until egg turns white; about 2 minutes.Slide omelette onto a plate and place asparagus, tomatoes, green onions and feta in the middle. Fold the omelette into thirds to cover the fillings.Serve hot with additional tzatziki. Salt and pepper to taste.',20,20,0);
INSERT INTO "Recipe" VALUES(340,'Irish Whiskey Pie','https://img.spoonacular.com/recipes/648010-556x370.png','0.5 cup condensed milk, 0.25 cup cornstarch, 5  egg yolks, 1 cup brown sugar, 2 cups homogenized milk, 2.5 cups pastry flour, 10 servings salt, 6 tbsp butter, 0.25 cup vodka, 0.25 cup water, 1 oz irish whiskey','For the crust:Sift flour and salt together into a large bowl.Using a food processor, a pastry blender or two knives and a good amount of patience, cut the butter into the flour.Add water and vodka stirring after each addition until the dough comes together.Form into a ball and cut it in half.Flatten each half into a disc, wrap them in wax paper and refrigerate for at least half an hour before baking.You will only need one half for this "Recipe", so feel free to freeze the other half for future pie emergencies.When ready to bake, preheat oven to 375Place pastry on a well-floured surface and using a well-floured rolling pin, roll out the pastry to fit a 9-inch pie plate.Place pastry into the pie plate and trim and crimp the edges.Prick the dough several times with a fork.Wrap tin foil around the pastry and fill the center with pie weights or dried beans.Place in the center of the oven and bake for 25 minutes.Remove weights and tin foil and bake for an additional nine minutes or until golden brown.Remove from the oven and let cool.For the Filling:In a medium sized bowl whisk together condensed milk, cornstarch and salt.Add egg yolks one at a time, whisking until combined after each addition.  Set aside.In a medium sized saucepan melt butter over moderate heat.Add brown sugar and allow to bubble slightly.Slowly whisk in milk.Add egg mixture slowly, whisking constantly.Bring back to a boil while whisking the mixture.Once the mixture is boiling, let it cook while stirring for approximately one minute or until thick.Remove from heat and stir in whiskey.Pour into a cooled pie shell and cover with plastic wrap.Place in the fridge and let set for four hours.You may serve the pie with whipped cream if you wish, but I find it so rich that I like to eat it au naturale.',45,45,0);
INSERT INTO "Recipe" VALUES(341,'Kohlrabi Salad With Apple, Bacon, and Snow Peas','https://img.spoonacular.com/recipes/649004-556x370.jpg','1 small kohlrabi bulb, 0.25 cup fuji apple, 10  snow peas, 1 tablespoon sunflower seeds, 2 slices bacon, 0.25 cup heavy cream, 1 teaspoon apple cider vinegar, 1 tablespoon honey',replace('Slice the kohlrabi paper thin with a mandolin\nMix with chopped apple\nShell the snow peas (I just eat the shell!)\nToss them in along with the sunflower seeds\nCrumble the bacon finely and mix it in\nRefrigerate while making the dressing.\nMix vinegar into the cream and let it sit out for 10 minutes until thick\nAdd honey and mix well\nAdd the dressing to the salad a little bit at a time until thinly coated.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(342,'Pear-ginger upside-down cake','https://img.spoonacular.com/recipes/655455-556x370.jpg','1.5 tsp baking powder, 1.5 tsp baking soda, 1.5 cups buttermilk, 0.25 cup muscovado sugar, 0.5 cup demerara sugar, 3  eggs, 3 cups flour, 2 Tbs ginger, 1.5 tsp ground cinnamon, 5 Tbs maple syrup, 4  pears, 1 cup salt, 1 stick butter','Oil a 9-inch spring form pan, and line the bottom with a 10-inch circle of parchment paper.Combine butter, brown sugar, and cinnamon in a medium saucepan. Melt the butter over medium heat for about 1 minute.Pour the mixture into the prepared spring form pan, completely coating the parchment paper.Place the quartered pears on top of the butter-sugar mixture, lining the pieces up tightly in a decorative circle.In a large mixing bowl cream butter (cut into smaller pieces) and brown sugar for 3-5 minutes, until smooth.Add the grated ginger, and beat 1 minute more.Add the eggs one at a time,making sure that each egg is fully incorporated before adding another.Add in the maple syrup or honey and beat to fully mix. The mixture will look as though it is breaking or curdling, but it will come together when the dry ingredients are added.In a separate bowl, sift together the flour, baking powder, baking soda, and salt. Whisk to fully combine.Alternately add small amounts of flour and buttermilk to the batter, stirring and folding with a rubber spatula until the dry ingredients are just absorbed. Do not overmix the batter.Pour and scrape the batter into the pear-lined pan, smoothing the top with a rubber spatula.Bake the cake at 325F for about 1 hour and 45 minutes, until a skewer inserted in the cakes centre comes out clean.Let the cake cool in the pan for 10 minutes on a wire rack.Cover the pan with a serving plate; then carefully invert them together. Release the sides of the pan, and lift it away. Gently lift the pans base off the cake, and peel away the parchment paper.Allow the cake to cool, and serve warm.',45,45,0);
INSERT INTO "Recipe" VALUES(343,'Garlic and Herb Pork Roast With Potatoes, Wilted Spinach, and Cooling Cucumber Cream','https://img.spoonacular.com/recipes/644227-556x370.jpg','2.5 pounds butterflies pork butt, 10 servings oregano, 10 servings rosemary, 10 servings garlic, 1 pound baby spinach, 1 pound potatoes, 3 medium onions, 10 servings evoo, 10 servings balsamic vinegar, 10 servings greek yoghurt, 1 medium cucumber, 1  lemon, 10 servings sea salt',replace('I pull the leaves off two sprigs of rosemary and two sprigs of oregano (about a loose 1/2 cup of herbage).  I peel and mince 4 cloves of garlic.\nAlong with a few glugs of EVOO, some sea salt, and some cracked black pepper, I mix all this savory yumyum into a paste in a bowl.\nThen I spread it liberally along what will be the inside of my meat-wad.  See the strings laid out below?  Im going to fold this slab in half, encasing my herbaliciousness in the inside.\nSee?  I slide this baby into a ziplock bag and set it in the fridge to marinate for a few hours (overnight will work, too).  Its going to take at least 2 hours to roast, so I take it out around 4:00 pm\nAnd get my roasting pan set to high heat with a few glugs of EVOO shimmering on the surface.\nIm going to sear every surface of my luscious wrapped pink pig, which will help it cook through to tender later.  I leave the fat-cap for last.  Bottoms down!\nThen cut side, using tongs to flip when the surface has caramelized to a lovely golden brown.\nI even brown each tip, like so.\nFinally, I press the sweet sweet slice of quivering pork skin onto the searing hot oiled surface of my pan. After a few moments, I flip it the final time.\nThe house has already started to spell amazing, and the beautiful bacony aromas released once fat hits heat is almost more than I can handle.  Almost.  The promise of porcine perfection to come keeps me in check.\nOh, Ive nestled a few thick slices of white onion under my pork roast, because I dont want the bottom to oversear before the meat can release some juices, and then I dont want the bottom to stew in those juices too much.  The onion elevates the roast while adding flavor.  I wrap this in foil paper, and set into a\nOven.  It will bake for at least 2 hours; larger roasts will take longer, but for 2 people this is just the right size, and just the right amount of time to inhale the noxious tantalizing aromas before some sort of crazy sets in.\nI make my cucumber yoghurt right away, because I want the flavors to blend.  I start my peeling, then slicing\nThen chopping my cucumber.\nI throw it into a bowl, along with my yoghurt, 2 cloves of minced garlic, some lemon zest, the juice of 1/2 that lemon, some sea salt, cracked black pepper\nAnd I mix it all well.  I set this in the fridge, so all the flavors can come together.  Which they do oh, baby they do.\nWhen my roast is almost done (pretty much right at the 1:45 mark), I prep my spuds by splitting them into quarters, and tossing them with lots of EVOO, sea salt, cracked black pepper, and another 1/2 cup of chopped fresh rosemary and oregano.  Were bringing the scent and savory of the pork and potatoes together by lacing them both with the same herb blend.\nI spread these out on a sheet pan, and give them another healthy dose of EVOO, just to be sure theyre very heartily coated.  I set this into the bottom shelf of my oven, right above the heating element, so that my edges will crust up nicely. Youll see.\nWe purchased this lovely bottle of oregano scented white balsamic vinegar at O&Co. on Newbury Street.  Tonight was the perfect time to break it out.  Have you ever had french fries with vinegar?  If not, I highly recommend it.  This is the same concept.\nI had set aside the large bowl in which Id tossed my spuds; it was still coated with residual herbed EVOO, salt, and pepper.  Ive sliced my white onions into strips, and I toss them into this reservoir with another few healthy glugs of oil, and another handful of oregano leaves.  Heres where my vinegar comes in; I douse a healthy serving over this beautiful blend, stirring it all up very very well, soaking each each crisp slice of white root with dressing.  Every few minutes or so, I toss it afresh; this reactive base quick-pickles my onion slices transforming the flavor from pungent to perky sweet.\nFor the last 10 minutes of cooking my roast, I remove the foil from the top to expose the skin to the heat.  I can easily twist a wee bit of meat off with my fork, letting me know it is tender and perfectly ready to serve. I set the heat to 425, then stick my roast back in the oven so the skin can crisp.\nMeanwhile, my onions have pickled\nAnd Ive layered my baby spinach over them\nBefore I pour my spuds, sizzling oil and seared spices and all, over the whole pan.\nI toss this very well, letting the hot potatoes and oil wilt my spinach, and blending the pickled onions over the whole batch.\nMy pork is ready to go: the fat cap is crisped and blistered, and the meat is fork-tender.\nThis hunk of lovemeat almost slices itself, and the herbage cleavage is like a vein of precious green flavor gold.\nTopped with a cool cucumber cream, my thick, tender  slabs of herbed rolled pork roast with crispy, savory skin are perfectly partnered with my snappy spuds and buttery greens.  This is an elegant, delicious dinner that welcomes the first breezes of early spring  through freshly re-opened windows.  Light, fresh, and fantastic: I wish I could have you all over for dinner, because this was a company meal!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(344,'Quinoa, Tomato, Green Onion Side Salad','https://img.spoonacular.com/recipes/657698-556x370.jpg','0.5 cup green onions, 0.5  lemon, 2 Tbs olive oil, 0.75 cup quinoa, 2 servings salt and pepper, 2 medium size tomatoes, 1.5 cups water','Put your quinoa and your water in a pan. Heat over medium heat until bubbling, then cover and reduce heat to low. Cook for about 15 minutes or until all the water is absorbed.While your quinoa is cooking, get out and wash your green onions and tomatoes. Chop them roughly.Chop a lemon in half and squeeze one half''s juice into a bowl, picking out the seeds.Let your quinoa cool. A little warm is fine.Add olive oil, lemon juice, and tomatoes and green onions to the pan. Stir.Add salt and pepper to your liking.Serve chilled',45,45,0);
INSERT INTO "Recipe" VALUES(345,'Homemade Muesli Breakfast Cereal','https://img.spoonacular.com/recipes/647043-556x370.jpg','1 handful apple chunks, 0.25 cup corn flakes/bran flakes, 1 handful cashews, 1 handful craisins, 1 tablespoon honey, 1 tablespoon olive oil, 0.25 cup rolled oats, 1 teaspoon sesame seeds, 1 tablespoon wheat bran, 1 tablespoon wheat germ','Preheat the oven to 250 degrees F.Mix the olive oil and honey in a bowl and warm slightlyIn a oven-proof dish, mix all the other ingredients and pour in the warmed oil-honey mixture.Give it a brisk stir and pop into the oven for 30 minutes, stirring now and then.Remove from the oven and cool for an hour.',90,90,0);
INSERT INTO "Recipe" VALUES(346,'Fresh Strawberry Yogurt Cake','https://img.spoonacular.com/recipes/643615-556x370.jpg','0.5 teaspoon baking soda, 1 cup butter, 3  eggs, 2.5 cups flour, 1  lemon, 1 cup powdered sugar, 12 servings salt, 12 ounces strawberries, 1 teaspoon sugar, 8 ounces vanilla','Preheat oven to 325*. Grease and flour a 10 inch Bundt pan. Sift together the 2  cups of flour, baking soda and salt. Mix in the zest of 1 lemon and set aside.With an electric mixer, cream together the butter and sugar until light and fluffy. Beat in the eggs one at a time, then stir in 1 Tb. lemon juice. Alternate beating in the flour mixture and the yogurt, mixing just until incorporated.Toss the strawberries with the remaining  cup of flour. Gently mix them into the batter.Pour the batter into the Bundt pan. Bake in the preheated oven for 60 minutes, or until a toothpick inserted into the center of the cake comes out clean.Allow to cool 10 minutes in the pan, then turn out onto a wire rack and cool completely. Once cooled whisk together the remaining 2 Tb. of lemon juice and the powdered sugar. Drizzle over the top of the cake.Serves 12+.',45,45,0);
INSERT INTO "Recipe" VALUES(347,'Tomato and Bacon Pizza With Rice Crust','https://img.spoonacular.com/recipes/663553-556x370.jpg','2  bell pepper, 2 cups rice, 1  egg, 1 teaspoon seasoning, 2 cups mozzarella cheese, 3  tomatoes, 6 strips at least of turkey bacon','Preheat oven to 400F.To make rice crust, mix ingredients in a bowl. Press onto greased pizza pan (10 inch) evenly.Spread bacon, tomatoes, pepper and mozzarella cheese on top of rice crust.Bake for 20 minutes or until cheese melts.Slice and serve warm.',45,45,0);
INSERT INTO "Recipe" VALUES(348,'Chinese Chicken Salad With Chipotle Dressing','https://img.spoonacular.com/recipes/638642-556x370.jpg','4 servings pea-mond dressing, 0.25 cup rice wine vinegar, 1 tablespoon smooth peanut butter, 1 tablespoon smooth almond butter, 1 tablespoon ginger, 2 teaspoons adobo chipotle pepper juice, 1 teaspoon adobo chipotle pepper puree, 1 tablespoon soy sauce, 2 tablespoons honey, 2 teaspoons sesame oil, 0.5 cup canola oil, 4 servings salt and pepper, 4 servings salad, 0.5 head napa cabbage, 0.5 head romaine lettuce, 2  carrots, 0.25 pound snow peas, 0.25 cup cilantro leaves, 0.25 cup green onion, 2 cups rotisserie chicken, 0.5 cup roasted peanuts, 0.25 cup mint leaves, 4 servings chili oil, 1 halves lime',replace('Dressing:\nWhisk together the vinegar, peanut & almond butters, ginger, chipotle pepper puree, soy sauce, honey, sesame oil, and canola oil in a medium bowl. Season with salt and pepper, to taste.\nSalad:\nCombine cabbage, lettuce, carrots, snow peas, cilantro, and green onion in a large bowl. Add the dressing and toss to combine.\nTransfer to a serving platter and top with the shredded chicken, chopped peanuts, and mint. Drizzle with chili oil, if desired.  Garnish with lime halves.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(349,'Lemon Pilaf Chicken','https://img.spoonacular.com/recipes/649733-556x370.jpg','2 cups broccoli flowerets, 1.5 cups chicken, 3 tablespoons lemon juice, 1 teaspoon lemon peel, 1 tablespoon olive oil, 1  pkt near east rice pilaf see note','In large skillet bring 2 cups water, olive oil, lemon juice and spice sack to a boil. Stir in chicken and rice pilaf. Reduce heat and simmer for 10 minutes. Add broccoli and grated lemon peel. Simmer for 8 to 10 minutes, or until all water is absorbed.NOTES : For a colorful twist, substitute Near East Chicken Flavor Pilaf.',45,45,0);
INSERT INTO "Recipe" VALUES(350,'Blackberry Clafoutis','https://img.spoonacular.com/recipes/635195-556x370.jpg','1 cup blackberries, 0.25 cup almond meal, 2 tablespoons flour, 0.75 cup milk, 0.5 cup caster sugar, 2 large eggs, 0.5 teaspoon vanilla extract, 0.25 teaspoon salt',replace('Preheat oven to 200C and butter two ramekins.\nDivide the blackberries between the prepared ramekins, leaving some for later (optional).\nIn a bowl add the almond meal, flour, milk, sugar, eggs, vanilla and salt. Mix well until you have a smooth batter.\nPour the batter over the fruit (dotting the tops with the leftover blackberries).\nPlace the dishes on a baking tray and bake in the middle of the oven for 30 minutes, or until the tops are golden.\nTransfer to a wire rack and allow to cool for a few minutes.\nServe warm with whipped cream.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(351,'Crispy Rhubarb Pockets','https://img.spoonacular.com/recipes/640832-556x370.jpg','0.5 pound rhubarb, 0.25 cup granulated sugar, 0.25 cup cornstarch, 0.25 teaspoon salt, 0.25 teaspoon vanilla extract',replace('Combine the diced rhubarb,sugar, the cornstarch and salt in a medium saucepan and place over medium-low heat.\nCook, stirring occasionally, until the rhubarb releases its liquid and begins to breakdown, creating a thick, chunky sauce, about 10 minutes.\nRemove the pan from the heat and stir in the vanilla extract.\nSet aside to cool to room temperature.\nLayer 4 phyllo sheets, brushing each with melted butter.\nMeanwhile, preheat the oven to 350 degrees F.\nNow let us cut four 4-inch squares from phyllo stack.\nPlace 2 teaspoons of filling in center of square.\nBrush phyllo from edge of filling to each point of square lightly with water.\nGather points of square and pinch together just above filling.\nBrush pouch with butter. Repeat process for all 4 pouches.\nPlace filled pouches at least 1" apart on ungreased cookie sheet or baking pan.\nBake in preheated 350F oven for 12 to 15 minutes or until golden brown.\nTake the pouches out and let them cool on wire rack for ~5 minutes.\nServe warm or at room temperature.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(352,'Blueberry Basil Galette','https://img.spoonacular.com/recipes/635414-556x370.jpg','3 cups blueberries, 2 teaspoons virgin coconut oil oil, 0.25 cup basil leaves, 0.5 tablespoon lemon juice, 1 teaspoon lemon zest, 0.25 cup maple syrup, 2 tablespoons quick-cooking tapioca, 0.125 teaspoon sea salt, 1.5 cups spelt flour, 0.25 cup sugar, 1 cup up to ¼ water','To make sweet tart dough:Mix flour and salt.Melt coconut oil, then stir with flour and salt until mixture resembles coarse meal.Add maple syrup gradually (if dough does not hold together on its own, add just enough ice water to hold dough together).Mix until a soft workable ball forms in the bowl; do not overmix.Add a small amount of flour if necessary.Shape the dough with your hands into a flattened disc.Roll dough out between two sheets of parchment paper; dust flour over the bottom sheet and on top of the dough.Use quick gentle strokes to start rolling from the center outward in each direction, like a compass.Transfer the parchment covered dough onto a baking sheet.Refrigerate the dough on the baking sheet while preparing the blueberry filling.To make blueberry basil filling:Preheat oven to 350 F.In a medium bowl, whisk 1/4 cup of the sugar, arrowroot powder, and sea salt together.Rinse and drain blueberries in a strainer, then transfer to a towel and blot dry.Gently stir in blueberries, basil, lemon zest, and lemon juice; set aside.Remove dough from refrigerator.Peel off top layer of parchment paper.Pour blueberry filling over tart dough, leaving a 2-inch border.Fold the dough border over the blueberry filling to form a pleated ruffle.Brush the folded dough border with 2 teaspoons oil, then pat the berries with the rest.Sprinkle the crust with 2 teaspoons of sugar.Bake about 45-55 minutes, or until the galette is golden and thick juices bubble on top.Cool completely before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(353,'Chocolate-Date Cake with Chocolate Sticky Toffee Glaze',NULL,'1 cup water, 330 gr medjool dates, 100 gr medjool dates, 3 tablespoons brandy, 2 tablespoons strong-brewed coffee, 4 tablespoons dutch-process cocoa powder, 1.5 cups flour, 0.75 teaspoon salt, 1 teaspoon ground cinnamon, 9 tablespoons butter, 120 gr dark-brown sugar, 3 large eggs, 1 teaspoons baking soda, 5 ounces bittersweet chocolate, 3.5 tablespoons butter, 60 gr dark-brown sugar, 1 tablespoon water, 1 pinch salt, 0.33333334 cup cream, 100 gr bittersweet chocolate, 2 tablespoons brandy',replace('Make the cake:\nPreheat oven to 180 C (350 F) degrees. Butter a 21 cm (8,3 or 9 inch) round cake pan. Line with parchment, and butter.\nBring water to a boil in a saucepan. Meanwhile, combine dates, brandy, coffee, and 2 tablespoons cocoa in a heatproof bowl. Stir in boiling water. Let cool, stirring occasionally. Puree cooled date mixture in a food processor (you should have about 2 1/2 cups). Place puree in a large bowl.\nWhisk flour, salt, cinnamon, and remaining 2 tablespoons cocoa in a bowl. Beat butter and dark-brown sugar with a mixer on medium speed until fluffy. Add eggs, one at a time, beating after each addition (batter will look curdled). Stir baking soda into reserved uncovered date puree. On low speed, beat flour mixture into egg mixture in 2 additions, alternating with the date mixture.\nBeat in chocolate and chopped dates. Transfer batter to prepared pan, and smooth top.\nBake until a toothpick inserted into center of cake comes out clean, about 1 hour. Let cool in pan on a wire rack for 30 minutes. Run a knife around edge of pan to loosen, and invert cake onto rack.\nRemove parchment, turn cake right side up, and let cool completely. (Cake can be wrapped in plastic and stored at room temperature for up to 2 days.)\nMake the glaze:\nBring butter, dark-brown sugar, water, and salt to a boil in a saucepan over medium-low heat, stirring occasionally. Boil 3 minutes. Remove from heat. Whisk in cream. Add chocolate, and whisk until smooth. Whisk in brandy. Let cool until thickened, 15 to 20 minutes.\nPlace cake on stand and pour glaze over top, letting some drip down sides. Garnish with halved dates.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(354,'Pb, Banana, Chocolate Chip Muffins','https://img.spoonacular.com/recipes/655046-556x370.jpg','1 tablespoon baking powder, 2  banana, 0.25 teaspoon cinnamon, 1 large egg, 0.5 cup yogurt, 2.5 cups flour, 0.5 cup golden brown sugar, 0.75 teaspoon salt, 1 cup semi-sweet chocolate chips, 0.5 cup skim milk, 0.75 cup smooth peanut butter, 24 servings sugar, 1 teaspoon vanilla extract, 3 tablespoons vegetable oil','Preheat oven to 350In a large bowl sift together flour, sugar, brown sugar, baking powder, salt and cinnamon until combined. Set aside.In a food processor combine bananas, yogurt, milk, peanut butter, egg, oil and vanilla. Pulse until it is smooth.Pour the wet ingredients into the flour mixture and fold until just combined. Stir in chocolate chips.Spray muffin tins with cooking spray and fill until  full. Bake on middle rack for 20-25 minutes or until a toothpick comes out clean.',45,45,0);
INSERT INTO "Recipe" VALUES(355,'Easy Chicken, Kielbasa and Shrimp Paella','https://img.spoonacular.com/recipes/641911-556x370.jpg','10 ounces chicken breast strips, 4 cups chicken stock, 1 teaspoon ground turmeric, 1 cup picante sauce, 2 cups regular rice, 0.75 pound shrimp, 16 ounces turkey kielbasa, 1 tablespoon vegetable oil','Heat the oil in a 12-inch skillet over medium heat. Add the rice and cook for 30 seconds, stirring constantly. Stir the broth, picante sauce and turmeric in the skillet and heat to a boil. Reduce the heat to low. Cover and cook for 15 minutes.Stir the kielbasa, shrimp and chicken in the skillet. Cover and cook for 5 minutes or until the rice is tender.',45,45,0);
INSERT INTO "Recipe" VALUES(356,'Easy Instant Pot Beef Tips and Rice','https://img.spoonacular.com/recipes/1000566-556x370.jpg','2 pounds sirloin beef tips, 1 large can cream of mushroom soup, 1 tbsp garlic powder, 0.33333334 cup dale''s seasoning sauce, 1 tsp olive oil, 0.5 medium onion, 0.5 cup water',replace('Set Instant Pot to the saute setting. Once warm, add olive oil, beef tips, and onion. Stir and saut for 5 minutes or until meat starts to brown.\nAdd water, Dales, and cream of mushroom soup, and garlic powder. Stir to mix well, and then cover with lid.\nCook on Manual Setting on High Pressure for 25 minutes. It will take a few minutes to come to pressure.\nOnce done, allow to naturally release for 20 minutes.\nServe over rice (or sub noodles or mashed potatoes) and serve with french bread to sop up the gravy.','\n',chr(10)),30,30,0);
INSERT INTO "Recipe" VALUES(357,'Asian Salmon Burgers With Tangy Ginger Lime Sauce','https://img.spoonacular.com/recipes/632874-556x370.jpg','4  burger buns, 1 tablespoon basil, 1 clove garlic, 1  green onion, 0.25  juice of lime, 0.25 cup mayonnaise, 1 teaspoon oyster sauce, 0.5 teaspoon powdered ginger, 1 pound salmon, 5.5 tablespoons sesame oil, 2 tablespoons cream, 1 tablespoon soy sauce','Cut the salmon into large hunks and run it through a food processor until no large pieces remain.Add to the salmon the soy sauce, garlic, ginger, oyster sauce, green onion, and basil.Combine ingredients well and form 4 large patties from mixture.Heat up the sesame oil in a large frying pan on medium high heat and add in the patties. Cook for about 10 minutes flipping once half way through.To make the sauce, add together all the above listed ingredients and stir to combine.Pour a spoonful of sauce over the top of the finished salmon burger and serve inside a toasted bun.',30,30,0);
INSERT INTO "Recipe" VALUES(358,'Green Tea Fruit Medley Smoothie','https://img.spoonacular.com/recipes/645530-556x370.jpg','1 cup water, 3  tea bags, 1 cup berries, 0.25 cup pineapple juice, 0.5 cup vanilla yogurt, 0.5 cup ice cubes',replace('Prepare tea by steeping 3 Bigelow Green tea bags in 1 cup of boiling water for 5 minutes. Squeeze out bags and discard.\nCombine tea and remaining ingredients in blender and blend until smooth.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(359,'Triple Chocolate Whoppers','https://img.spoonacular.com/recipes/663833-556x370.jpg','6 ounces semisweet baking chocolate, 2 teaspoons baking powder, 0.75 cup brown sugar, 2 oz chocolate into chunks, 2  eggs, 1 teaspoon plus 2 espresso powder, 0.5 cup pecans, 0.5 teaspoon sea salt, 1 cup semisweet chocolate chips, 0.5 cup unbleached flour, 0.5 cup butter, 1 teaspoon vanilla extract, 1 cup walnuts','Preheat the oven to 325 degrees F (163 degrees C).Lightly grease 2 baking sheets. Set aside.Combine semisweet chocolate, unsweetened chocolate chunks, and  butter in a double boiler. Melt the chocolate over low heat until just melted, stirring occasionally. Be careful, not to burn the chocolate. Remove immediately. Stir to blend the butter and chocolate off the heat, and set aside.Combine the eggs, espresso powder, and vanilla extract in a large bowl and cream together using an electric mixer. Add the brown sugar and mix until creamy.In a separate bowl, sift together the flour, baking powder, and sea salt. Set aside.Add the melted chocolate and butter to the egg mixture and blend together using an electric mixture. Then add the flour mixture and stir by hand just until the dry ingredients and are moist.Add the chopped nuts and the chocolate chips to the chocolate and flour mixture folding them in gently. Note:  The dough will be relatively soft.Drop by large tablespoonfuls onto the greased baking sheets at least 3 inches apart. If you want your cookies to look uniform in size then use a 2 oz. cookie or ice cream scoop.  Bake immediately to prevent the chocolate from hardening for 10 to 12 minutes. Rotate the pan halfway through the baking time. The cookies will still be very soft and sticky inside, but do not overcook the cookies or they will be crispy, rather than chewy. Cool for 10 minutes on the baking sheets before gently removing the whoppers to a baking rack to cool completely.Store the cookies in an airtight container separating the layers with wax paper.Makes about 1 dozen 3-inch cookies',45,45,0);
INSERT INTO "Recipe" VALUES(360,'Fava Crostini','https://img.spoonacular.com/recipes/642638-556x370.jpg','1 cup broad bean, 4 servings glugs of olive oil, 1 clove garlic, 1 tablespoon lemon, 4 servings water, 4 servings parmesan, 4 servings salt & pepper, 4 servings crusty bread',replace('Throw the fava in a pan & cover with water & a little salt. Bring to a boil & lower to a simmer. Cook a couple of minutes until the fava are tender. Drain.\nReturn the pan to the heat. Pour in a couple glugs of olive oil and the garlic clove. Fry the garlic until browned. Then discard garlic.\nToss the fava into the pan & saute for a minute or two. Then begin mashing with the back of a wooden spoon until you form a paste. If you need to add a bit of water, do so.\nRemove fava paste from heat & season with salt & pepper add a squeeze of lemon.\nToast slices of good bread & rub warm fava mixture & top with shaved parmesan. You can drizzle a little really good quality extra virgin olive oil as well if you like.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(361,'Salmon Butternut Squash Corn Chowder','https://img.spoonacular.com/recipes/659056-556x370.jpg','1  butternut squash, 1 large carrot, 3  ears of corn, 1 bunch dill, 0.25 cup heavy cream, 2 tablespoons onion, 12 ounces salmon, 4 servings salt and pepper, 3 sprigs scallions, 0.25 cup water','Pour water into a medium-size soup pot and start boiling on a low flame. Chop up the onions, butternut squash, carrots, corn, along with the scallions and dill and add them to the pot. Cover and let cook on a low flame for 30 minutes. Taste and add salt and pepper. Cut up the salmon and add it to the soup, along with the cream. Let cook for another 20 minutes, taste again and enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(362,'Brownie Cupcakes','https://img.spoonacular.com/recipes/636331-556x370.jpg','120 grams chocolate, 113 grams butter, 250 grams granulated sugar, 1 teaspoon vanilla extract, 3 large eggs, 95 grams all purpose flour, 0.25 teaspoon salt',replace('Preheat oven to 325 degrees F (170 degrees C). Turbo broiler 150 Degrees\nMelt the chopped chocolate and butter in a stainless steel bowl placed over a saucepan of simmering water. Once the chocolate is melted and smooth, remove from heat and let cool for a few minutes\nThen stir (can also use a hand mixer) in the sugar. Add the vanilla and then add the eggs, one at a time, mixing well after each addition. Mix in the flour and salt until well blended.\nEvenly divide the batter between the muffin cups. Place in the preheated oven and bake for about 20 - 25 minutes. For turbo broiler 150 Degrees for 13-15 minutes.\nRemove from oven and let cool on a wire rack. Once the cupcakes have completely cooled, frost with icing.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(363,'Simple Squash Salad','https://img.spoonacular.com/recipes/660146-556x370.jpg','1  bell pepper, 0.25 tsp pepper, 0.25 cup parsley, 3 cloves garlic, 0.5 tsp garlic powder, 1 tablespoon capers plus 2 tablespoons caper juice, 3 slices lemon, 0.5  onion, 1 tsp oregano, 0.25 tsp pepper flakes, 1 tsp salt, 1 tablespoon sugar, 0.75 cup vinegar, 3 cups zucchini','Combine all of the ingredients the salad ingredients in a bowl.Combine all of the dressing ingredients in a cup and stir, adjust the ingredients to taste.  Pour this over the salad and toss.  Let the salad sit in the refrigerator for a few hours before serving.',180,180,0);
INSERT INTO "Recipe" VALUES(364,'Cucumber and Cannellini Bean Side Salad','https://img.spoonacular.com/recipes/641005-556x370.jpg','14 oz artichokes, 0.25 tsp pepper, 15 oz cannellini beans, 5  cucumbers, 0.5 cup basil, 1 Tbs capers - plus caper juice, 1  juice of lemon, 3 tablespoons olive oil, 0.5  onion, 0.25  pepper flakes, 0.5 tsp salt, 1 tablespoon sugar, 2  sun tomatoes, 2 tablespoons vinegar','Combine all of the ingredients for the salad in a bowl.Combine all of the ingredients for the dressing in a small bowl and mix.  Pour the dressing over the salad and give a toss.Refrigerate to chill before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(365,'Simple Poached Egg Dinner','https://img.spoonacular.com/recipes/639306-556x370.jpg','1 package full baby spinach, 4 slices bacon, 4 large pasteurized eggs, 2 tablespoons olive oil, 1 small onion or, 2 servings salt & pepper, 2 tablespoons vinegar','Method:Thinly slice the onion and saut over medium in the olive oil.While onions are sauting remove the fat from the bacon and chop into pieces; discard the fat or reserve for another use.Add bacon to onions and saut for about 10 minutes or until the onions are translucent and the bacon is almost cooked.While bacon and onions are cooking bring about 3 inches of water to a boil and add the vinegar. Once boiling reduce heat to just barely simmer.Add the spinach and turn with tongs until completely wilted and mixed with the bacon and onions.  Saute for 2  minutes; just until spinach is cooked.  Do not overcook!Give the water a gentle stir and just after you add the spinach to the onions and bacon,  drop the eggs in one at a time to poach. (first break the eggs into a cup) 3 minutes will give you medium firm egg; runny yolk and solid whites.Divide the spinach evenly between two dinner plates and top with two poached eggs.  Sprinkle black lava salt (if you have another kind of salt like truffle salt, that is great too!) and fresh ground black pepper.  Serve with a large chunk of toasted baguette.',20,20,0);
INSERT INTO "Recipe" VALUES(366,'Alouette Crème De Brie Shrimp Cups','https://img.spoonacular.com/recipes/632241-556x370.jpg','5 oz alouette crème de brie, 1 tablespoon chives, 2 tablespoons extra virgin olive oil, 0.125 teaspoon garlic, 1 tablespoon orange juice, 0.5 teaspoon orange peel, 4.2 oz phyllo tartlet shells, 0.25 teaspoon pepper flakes','Arrange tartlet shells on 2 serving plates. Spoon a scant teaspoon Alouette Crme de Brie in each.In medium bowl, combine shrimp and all remaining ingredients. Toss to coat shrimp.Place 1 shrimp over cheese in each shell. Spoon a little orange juice-chive mixture over shrimp. Serve immediately.Variation:For a slightly salty flavor, substitute 30 cup-shaped tortilla chips for the phyllo tartlet shells.If using phyllo tartlet shells, these can be served cold or warm (warm for 5 minutes at 350 F).',45,45,0);
INSERT INTO "Recipe" VALUES(367,'Lemon Delicious','https://img.spoonacular.com/recipes/649611-556x370.jpg','0.25 cup self raising flour, 0.33333334 cup caster sugar, 40 g butter, 2  lemon zest, 40 ml lemon juice, 2  egg yolks, 0.75 cup milk, 2  egg whites',replace('Preheat oven to 180C. Lightly grease 4 ramekins (you can use a smaller ramekins)\nPlace flour, sugar and lemon zest in a large mixing bowl and whisk to combine. Make a well in the centre and pour in lemon juice and melted butter. Stir to combine, add egg yolks and mix well. Stir in milk.\nIn a separate clean small  bowl of an electric mixer (I used my Kitchen Aid mixer), whisk egg whites until stiff. Fold egg whites into batter and divide mixture evenly between ramekins. Place ramekins in a large roasting dish (I used a square cake pan), filled with cold water to come halfway up the sides of the ramekins and bake for 30-35 minutes until golden.\nGood to serve warm.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(368,'Protein Strawberry Smoothie','https://img.spoonacular.com/recipes/644044-556x370.jpg','0.5 cup almond milk, 0.5 medium banana, 1.5 cups greek yogurt, 2 teaspoons honey, 1 cup ice, 2 cups strawberries','Combine ingredients and blend!',5,5,0);
INSERT INTO "Recipe" VALUES(369,'Caramel Almond Berry Trifle','https://img.spoonacular.com/recipes/636970-556x370.jpg','1 teaspoon almond extract, 10 servings berries, 0.5 cup mrs richardson''s butterscotch caramel sauce, 1 large vanilla pudding, 3 cups milk, 1 tub cool whip, 1  pound cake','Mix large box of pudding and milk (according to directions)Add one cap full of almond extract, mix well, and set aside to set.After pudding has set, let''s start the layers. First a thick layer of pudding, a layer of the pound cake, add berries, drizzle caramel sauce over berries, add Cool Whip layer, then repeat layers.Top with additional berries and caramel.',30,30,0);
INSERT INTO "Recipe" VALUES(370,'Braised Chicken with Artichoke Hearts & Olives','https://img.spoonacular.com/recipes/635820-556x370.jpg','0.5 cup artichoke hearts, 2 cups chicken broth, 2 handfuls basil, 1  juice of lemon, 0.5 cup kalamata olives, 2 servings olive oil, 0.5  onion, 2 servings salt & pepper, 1 pound chicken breasts, 0.5 cup white wine','Season the chicken with salt and pepper. In a large saut pan, over medium low heat,  add a couple drizzles of olive oil. Place the chicken skin side down in the pan and cook until golden brown, flip and cook a few minutes on the other side. Remove the chicken and place on a dish.If the pan is dry add a small drizzle of olive oil again and the onion. Saut until slightly softened. Carefully add in the white wine and scrap all those delicious bits from the bottom of the pan. Allow the wine to reduce by half.Add in the artichoke hearts, olives and broth. Add the chicken back to the pot and simmer cover for about 20 minutes.Again remove the chicken from the pan. Add in the lemon juice and basil. Simmer for 5 minutes.Pour that fabulous sauce overtop the chicken and enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(371,'Stuffed Chicken Breast','https://img.spoonacular.com/recipes/1003670-556x370.jpg','2 Tbsp chicken seasoning, 8 oz cream cheese, 4 servings green onions, 3  chicken breast',replace('Wash and Pat dry chicken breast.\nCut chicken lengthwise, careful not to cut all the way through.\nStuff chicken breast with cream cheese and onion.\nFirmly press the chicken breast closed.\nSpray chicken with olive oil based cooking spray.\nRib chicken breast with your favorite chicken seasonings.','\n',chr(10)),27,27,0);
INSERT INTO "Recipe" VALUES(372,'Mixed Berry Yogurt with Almonds','https://img.spoonacular.com/recipes/652111-556x370.jpg','1 cup berries, 0.25 cup oats, 1 cup greek yogurt, 10  almonds','You can put this together a variety of ways. It looks great layered in a glass cup or bowl.Variations. This breakfast lends itself to endless variations. If this is for dessert and you want something more decadent, use a creamier vanilla yogurt or layer in a bit of maple syrup on top of the yogurt.  Any kind of nut will do (Toast them for maximum crunch and flavor). If you dont have berries on hand, this works well with just about any fruit.',45,45,0);
INSERT INTO "Recipe" VALUES(373,'Balsamic Marinated Lamb Chops','https://img.spoonacular.com/recipes/633932-556x370.jpg','4  lamb loin chops, 1 Clove garlic, 0.25 cup balsamic vinegar, 1 Tbs dijon mustard, 1 Sprig each; oregano, 2 servings all of these herbs, 1 Tbs red wine vinegar, 2 Tbs olive oil, 1 Tbs brown sugar, 2 servings kosher salt, 2 servings pepper',replace('In a mixing bowl, mix above ingredients, except salt and pepper. Set aside\nSalt and Pepper the Lamb Chops on both sides on a plate\nToss Lamb in bowl with marinade\nCover and refrigerate at least 1 to 2 hours, turning occaisionally\nGet your BBQ ready! Medium-High, indirect heat\nGrill Lamb Chops on the BBQ to a nice medium rare\n5 to 7 minutes per side, depending on thickness','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(374,'Lemon Squares','https://img.spoonacular.com/recipes/649795-556x370.jpg','0.5 teaspoon baking powder, 2  eggs, 2  lemon juice, 1 teaspoon lemon peel, 0.25 cup powdered sugar, 0.25 teaspoon salt, 2 tablespoons sugar, 0.5 cup butter','Sift flour and powdered sugar together. Cut in butter until well blended. Press mixture over bottom of a 9 by 13 by 2-inch pan. Bake about 25 minutes at 300 until lightly browned. Combine remaining ingredients and spread on top of the baked crust. Bake at 350 for 25 to 30 minutes. Sprinkle with powdered sugar.',45,45,0);
INSERT INTO "Recipe" VALUES(375,'Homemade Animal Crackers','https://img.spoonacular.com/recipes/646905-556x370.jpg','0.25 tsp allspice, 1 tsp baking powder, 1 cup brown sugar, 1 stick butter, 1 tsp cinnamon, 2 Tbsp cocoa powder, 1  egg, 1.5 cups flour, 0.5 cup oats, 0.125 tsp salt, 1 tsp vanilla','Cream together the butter and brown sugar.Add in the egg and vanilla and combine well.Mix in the cinnamon, allspice, and salt.Finally, add in the baking powder, oats, flour, and optional cocoa powder. Cocoa powder should be subbed for flour. Simply add the powder to your measuring cup and then fill the rest of the way up with flour.Mix it up good and form into a ball. Store in the fridge for a minimum of one hour and up to overnight.When ready, pull dough from fridge, grab off a hunk and roll it out to 1/4" thick.Cut out crackers and place on a cookie sheet lined with parchment.Bake for 5-7 minutes in an oven preheated to 350 degrees.',45,45,0);
INSERT INTO "Recipe" VALUES(376,'Home made coffee ice cream','https://img.spoonacular.com/recipes/646868-556x370.jpg','2 cups cream, 6  egg yolks, 2 Tbs coffee granules, 2 cups milk, 0.75 cup sugar, 1 Tbs vanilla extract','Combine the cream, milk, sugar, and coffee in a medium, heavy saucepanBring to a gentle boil over medium heat; remove from the heat and set aside.Beat the egg yolks in a medium bowl.Whisk 1 cup of the hot cream into the egg yolks.Add the vanilla extract.Gradually add the egg mixture in a slow, steady stream, to the hot creamCook over low heat, stirring constantly until slightly thickened, about 4-5 minutes.Remove from the heat and strain through a fine mesh strainer into a clean container.Cover with plastic wrap, pressing down against the surface to keep a skin from forming.Chill in the refrigerator for at least 2 hours.Pour the mixture into an ice cream machine and churn until frozen (according to the manufacturer''s instructions).Transfer to plastic container and place in the freezer for a few hours before serving.Serving: take it out of the freezer for 5-10 minutes before serving, or longer, so it comes to the right scooping temperature.Easy suggestion: ice cream is best served in chilled glass or porcelain bowls. Scoop it with a hot, but dry, ice-cream spoon (soak it in boiling water, then wipe dry).',45,45,0);
INSERT INTO "Recipe" VALUES(377,'Buckwheat Banana Pancakes','https://img.spoonacular.com/recipes/636385-556x370.jpg','5 tablespoons almond milk, 0.5 teaspoon baking powder, 0.25 teaspoon baking soda, 1 medium banana, 0.25 cup buckwheat flour, 0.5 teaspoon cinnamon, 0.5 tablespoon flax seed, 0.5 tablespoon maple syrup, 0.5 tablespoon oil, 3 tablespoons yogurt, 0.25 cup rolled oats, 0.125 teaspoon salt, 0.5 teaspoon vanilla','Preheat a large skillet over medium heat for 3-5 minutes while you make the batter.Whisk together the flours, flax seed, baking powder, baking soda and salt. Add the yogurt, milk, maple syrup, vanilla and oil, if using. Mix until smooth (there is no gluten in this batter, so no worries about over-mixing and creating tough pancakes). Batter should be thick, but if you like thinner pancakes, add an additional tablespoon or two of milk. Fold in sliced bananas.Grease with a few drops of oil and spread around the pan. Add batter,  cup at a time (batter should sizzle when it hits the pan). Cook for about 2 minutes on each side (the first pancakes will take the longest to cook) and serve warm, with lots of maple syrup, additional bananas, nuts, chocolate chips, etc.',30,30,0);
INSERT INTO "Recipe" VALUES(378,'Butternut Squash Souffle Side Dish','https://img.spoonacular.com/recipes/636598-556x370.jpg','4 servings butter to grease the ramekins, 0.5  butternut squash, 0.5 teaspoon cinnamon, 3  egg whites, 2  egg yolks, 0.5 teaspoon ground ginger, 0.5 cup heavy cream, 0.25 teaspoon nutmeg, 4 servings splash of vanilla extract, 0.25 cup milk','Puree butternut squash with blender and set aside to let cool.In a small saucepan, heat cream, milk, nutmeg, cinnamon, ginger and vanilla to a simmer.Meanwhile, in a separate bowl, whisk yolks and sugar until pale yellow.Add a cup of the hot cream mixture very slowly into yolks while continuing to whisk.Then add yolks and cream back to saucepan and keep stirring over low heat.Mixture should thicken in a few minutes, then turn off heat and incorporate into squash puree.Preheat oven to 375 degrees, making sure the rack is near the bottom.Place a baking sheet in the oven.Butter your ramekins and dust the insides and rims with sugar.Then take egg whites in a clean bowl and whisk until glossy. It should form stiff peaks when you remove your whisk from the bowl, and should be able to hold the weight of an egg.Use a spatula to combine the egg whites scoop by scoop into the squash mixture, making sure they form a fully homogeneous mixture, but do not overmix.Carefully scoop your mixture into the ramekins up to the rims.Bake on lower rack for about 25 minutes, or until tops are golden brown.They should rise, but with firm tops and jiggly centers.',45,45,0);
INSERT INTO "Recipe" VALUES(379,'Avocado Toast With Caramelized Sweet Onion, Grape Tomatoes, Fresh Garden Chives and Chive Blossoms','https://img.spoonacular.com/recipes/633160-556x370.jpg','2 tablespoons olive oil, 0.25  onion, 15  grape tomatoes, 0.5  avocado, 2 slices quality bread, 2  springs chives, 1 tablespoon chive blossoms, 2 servings salt, 2 servings ground pepper',replace('Saute sliced onions and tomatoes with olive oil over medium high heat for 5-8 minutes. Season with salt and pepper. Set aside.\nToast two slices of bread in a toaster.\nEvenly smear avocado onto each slice of toast. Sprinkle with salt and pepper.\nTop toast with onions and tomatoes.\nGarnish with fresh chives and chive blossoms.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(380,'German Rhubarb Cake with Meringue','https://img.spoonacular.com/recipes/644488-556x370.jpg','600 g rhubarb, 2 Tablespoons sugar, 130 g sugar, 5 ml vanilla extract, 0.125 teaspoon salt, 2 large eggs, 150 g flour, 50 g roasted almonds, 2 teaspoons baking powder, 3  egg whites, 150 g sugar, 12 servings almonds',replace('Preheat the oven to 350F Convection. Grease a round 26 cm Spring pan (9 1/2 inch).\nWash, dry and peel the rhubarb. Cut it in little pieces, mix with 2 tablespoon of sugar and let sit for at least 1/2 hour. It will extract a lot of water that needs to be drained. Pat rhubarb dry for further use.\nIn a kitchen machine beat together butter, sugar and vanilla extract until the butter is fluffy and the sugar is dissolved. Put in the eggs, one at a time and mix well.\nIn a separate bowl sift together flour, ground almonds, salt and baking powder, add slowly to the egg mixture. Dont over mix.\nFill dough into the spring pan, top with dried rhubarb and bake for 25 min.\nIn the mean time prepare the meringue/ baiser topping. Beat egg whites until stiff peaks form. Slowly add the sugar until meringue is firm and shiny.\nSpread the meringue evenly over the rhubarb and decorate with almond slices. Return to the oven for another 15 min. Cover the cake with aluminum foil after 5 min. in case the meringue does turn too dark.\nCool completely before removing the cake from the pan.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(381,'Grilled Portabella and Poblano Tacos','https://img.spoonacular.com/recipes/645812-556x370.jpg','1 tbsp canola oil, 0.5 tsp chipotle powder, 0.25 cup cilantro, 4 servings cilantro sprigs, 8 small corn tortillas, 0.5 head garlic, 4 servings guacamole, 1 tsp lime juice, 4 servings lime wedges, 0.25 cup olive oil, 1  poblano chile, 6  portabella mushrooms, 1 large onion, 2  roma tomatoes, 1 tablespoon salt, 4 servings salt and pepper, 4 servings cheddar cheese','Preheat a lightly oiled grill on medium-high heat.While the grill is heating up, prepare the pico de gallo. In a small mixing bowl, combine tomatoes, onion, cilantro, garlic, salt and lime juice. Set aside.Next, prepare the grilled portabella filling. Remove the stems from the portabellas, and discard. Using a spoon, scrape out the dark gills from the underside of the mushroom caps.Lightly brush the portabellas and the onions on both sides with canola oil, and sprinkle generously with salt and pepper.Arrange the mushrooms, onion, and poblano on the hot grill, and cook for 5-6 minutes per side or until the mushrooms are softened and the onion is lightly charred. Remove from heat and transfer to a cutting board.Remove the stem and seeds from the poblano, and discard. Cut the poblano and the portabellas into thin strips, and roughly chop the onion. Transfer to a mixing bowl and toss with lime juice and chipotle powder until well coated.To assemble, arrange 2 tortillas per plate, and divide the mushroom filling evenly between them.  Serve with pico de gallo and bowls of the different toppings so that everyone can garnish their tacos as they please.',45,45,0);
INSERT INTO "Recipe" VALUES(382,'Turkey Sausage, Chard & Sweet Potato Breakfast Scramble','https://img.spoonacular.com/recipes/664054-556x370.jpg','3  baby portabella mushrooms, 6 ounces diestel breakfast sausage, 2 stalks rainbow chard, 6  eggs, 2 stalks green onion, 2 teaspoons olive oil, 0.5  sweet potato, 0.25 cup water','In a medium-sized skillet, heat about two teaspoons of olive oil on medium heat. Add the chopped sweet potato and saut 3 or 4 minutes before adding a little liquid and covering. In about 2 minutes, check to see if the liquid has burned off. If it has, add a little more and cover again. Repeat this several times until the sweet potato is soften, but still al dente. Add the mushrooms and the chopped chard stems. Saut another 3 to 5 minutes and add additional liquid if necessary.Move the veggies to one side of the skillet with a wooden spoon and add the ground breakfast sausage. Brown the meat and using the wooden spoon break it apart. Continue sauting until the sausage is cooked all the way through.Immediately add the green onion and chard leaves. Allow to steam for about 30 seconds before pouring the scrambled egg mixture evenly over the meat and veggies. This is where the technique comes in. Avoid the temptation to stir. Simply allow the skillet to sit 2 to three minutes. Then, using a wooden spoon or spatula, begin flipping sections of egg and veggies (similar to how you would fold whipped egg whites into a cake batter, just gently fold the scramble onto itself). Once all sections have been flipped over, everything to sit and cook another 2 or 3 minutes. Repeat the flipping.  Continue doing this until the egg is no longer cooking to the skillet.Serve with your favorite toppings!',45,45,0);
INSERT INTO "Recipe" VALUES(383,'Apple Pie Bars','https://img.spoonacular.com/recipes/632573-556x370.jpg','3 large mcintosh apples, 2 teaspoons baking powder, 1 teaspoon baking soda, 6 ounces butterscotch chips, 2  eggs, 2 cups flour, 1 teaspoon ground cinnamon, 1 teaspoon ground nutmeg, 0.5 teaspoon salt, 1 cup sugar, 1 cup vegetable oil','Preheat the oven to 350 degrees F.  Spray a 9 by 13 inch baking dish with cooking spray.In the bowl of an electric mixer, thoroughly combine the oil, eggs, and sugar.  Sift the flour, baking powder, salt, soda, and spices together in a bowl, then add to the oil mixture in the mixer, beating until thoroughly mixed.  The batter will be thick.Use a sturdy spoon to stir in the apple pieces.  Scrape the mixture into the prepared pan, spreading it out evenly.  Sprinkle the butterscotch chips over the top, pressing them into the batter lightly.Bake for 45 minutes to 1 hour, until golden and pulling away from the sides of the pan slightly.Cool thoroughly and cut into squares.',75,75,0);
INSERT INTO "Recipe" VALUES(384,'Finger Lickin'' Good Stewed Quince Dessert','https://img.spoonacular.com/recipes/642878-556x370.jpg','3  quinces, 3 tbsp unrefined oil, 1 tbsp rice flour, 50 g sucanat, 0.5 tbsp cinnamon, 1 tsp ground cloves, 3 tbsp raisins, 0.5 tsp vanilla extract, 1 tsp rum extract, 1 pinch sea salt','Go to my blog for the full instructions: http://gourmandelle.com/finger-lickin-good-stewed-quince-dessert/',45,45,0);
INSERT INTO "Recipe" VALUES(385,'Broccoli with cheese soup','https://img.spoonacular.com/recipes/636230-556x370.jpg','400 g broccoli florets, 2 Tbs flour, 1 cup milk, 0.125 tsp garlic powder, 0.25 tsp salt, 0.25 tsp ground pepper, 50 g feta cheese, 50 g swiss chesee',replace('Add onions and carrots to the melted butter and saute for 5-6 minutes over medium heat, or until vegetables are tender.\nAdd 1 cup chicken broth and bring to the boil.\nAdd broccoli and cook, covered, 5 to 6 minutes or until the broccoli is tender. Using a spoon, break broccoli florets in small pieces.\nReduce heat to low and add remaining cup of chicken broth.\nMix flour and milk in a small bowl and whisk until smooth. Add mixture to the pot.\nAdd garlic powder, salt, and pepper. Continue cooking for about 5-6 minutes over low heat until soup thickens.\nAdd cheese, handfuls at a time, and stir constantly over low heat for 10 minutes until smooth and creamy. If soup becomes too thick, add additional chicken stock. Do not let soup boil.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(386,'Broccoli Tartar','https://img.spoonacular.com/recipes/636228-556x370.jpg','1 tablespoon apple vinegar, 0.5  broccoli, 2  peeled/ tomatoes, 2 handfuls parsley, 1 teaspoon herbs de provence, 1 tablespoon olive oil, 1  onion, 1  bell pepper, 1 small pinch chili powder, 12 servings sea salt, 12 servings sesame seeds to decorate, 1 dash soy sauce, 12 servings colorful tartar on a bed of vegetables. also an touch, 12 servings a hand blender, 1 cup soaked arame, 12 servings hand blender, 1 cup soaked arame','Soak arame (seaweed can be found in a health-food store) in a bowl of pure water.Put the grill of the oven and put a pot of water on the fire with a pinch of sea salt.Wash the pepper, broccoli, parsley and tomatoes. Carve a cross down the tomatoes, halve the peppers and remove the seeds and cut the broccoli into chunks.When the water boils you immerse the tomatoes and leave them for a swim, get them and let them scare in cold water. They are now ready to go out of their jackets.Meanwhile, the broccoli  can be swimming for 6 minutes in the boiling water. Note: The water will cool off and when back to a boil, then add 5 minutes. Get them dry and cool under cold water, then they stay nice and green.The pepper may be under the grill until it sees black. Let them cool and peel them.Chop the parsley.Put the cooled broccoli in a long narrow bowl and blend finely with a hand blender. Add the oil and vinegar with the salt. Add half the parsley and mix into a smooth puree. If too grainy (dry) put some extra oil.Cut the unseeded, peeled tomatoes and peppers into very small pieces.The shallot or onion may be chopped in mini pieces.Add the chopped vegetables to the puree and stir gently with a spoon. The rest of the chopped parsley may be added now. A little salt, soy sauce and chili powder. Start with a little bit and add some more later if desired. The herbs de Provence can now embellish the whole with its bright flavor.The seaweed may now well out of the water and squeeze out any excess moisture. Cut the seaweed finely and mix carefully with the puree.With an ice cream spoon you  create beautiful balls and sprinkle with toasted sesame seeds.bon apptit',45,45,0);
INSERT INTO "Recipe" VALUES(387,'Blackberry Cobbler','https://img.spoonacular.com/recipes/635200-556x370.jpg','2 teaspoons baking powder, 2.5 cups blackberry, 0.5 cup butter, 1 cup flour, 1 cup milk, 0.5 teaspoon salt, 1 tablespoon sugar','Preheat the oven to 375.In a bowl, add the blackberries and the sugar together.  Let the berries macerate or if you are like me, you wait until it''s halfway done. lol I couldn''t wait any longer.In a larger bowl, mix the flour, baking powder, salt and milk. Now add the melted butter and mix until it''s well blended.Now pour the batter into a ungreased baking dish (next time I''ll be greasing it). Now spoon the berries on top of the batter.Bake in the oven for 45-55 minutes. Serve warm with whip cream or some ice cream.  This lasted for about 15 minutes in my house. Yes, it was yummy. ''Nuff said.',45,45,0);
INSERT INTO "Recipe" VALUES(388,'Enchiladas Verdes (Green Enchiladas)','https://img.spoonacular.com/recipes/642403-556x370.jpg','1 pound chicken breast, 12  anaheim chili peppers, 0.5 cup canola oil, 1 quart buttermilk can be used as a substitute, 2 tablespoons flour, 1 medium onion, 12  corn tortillas, 1 cup cheese, 0.25  queso fresco, 0.5 cup crema, 6 servings salt, 6 servings water',replace('Roast Chili Peppers\nPreheat broiler. Select firm, meaty peppers without wrinkles for roasting. Wash thoroughly. Place peppers evenly in a single layer on a foil-lined cookie sheet. Place under broiler. Watch them closely as the skin will blister and turn black within minutes. Turn the peppers after 5 minutes to blister all sides evenly. When done, the pepper skins should be evenly blistered and mostly black. Place roasted peppers in a plastic bag, cover with a kitchen towel and when cool, rub off blackened skin. Tear open and pull out the seed pod and stem.\nSauce\nIn a blender combine the peppers, flour, and half of the suero or buttermilk and blend until creamy. Pour mixture into medium skillet and set over medium-low heat to warm. Add additional suero or buttermilk and stir. Taste and season with salt, usually about 2 teaspoons. If the sauce is too spicy, add  cup of crema or sour cream and stir. If the sauce is too thick, add water until desired consistency is reached.\nChicken (Optional)\nIn a pot with enough water to cover, boil chicken breasts 25 minutes or until juices run clear. Drain, cool, and shred. Optional time-saver: shred a store bought rotisserie chicken.\nStacked Style\nFry tortillas in hot oil until softened. Drain on paper towels. Soften tortillas by soaking in sauce one at a time. Place softened tortillas on individual serving plates. Layer with cooked chicken, cheese, and onion. Repeat process for a total of 3 tortillas for each serving.\nOven Style\nPreheat oven to 350 degrees. Spread 1 cup of the sauce in an ungreased 9-by-13-inch baking dish. Fry tortillas in hot oil just until softened. Drain on paper towels. Fill with cooked chicken, cheese, and onion. Roll, placing seam side down.\nPour 2 cups of the sauce over enchiladas. Sprinkle with crumbled queso fresco and bake until warm, about 15 minutes. Serve with a dollop of crema or sour cream and your favorite side dish.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(389,'Smokey Rainbow Chili','https://img.spoonacular.com/recipes/660395-556x370.jpg','2 tablespoons olive oil, 2 small zucchini, 1  bell pepper, 1  orange bell pepper, 1  jalapeno pepper, 4 cloves garlic, 1  onion, 28 ounce stewed tomatoes, 6 ounce tomato paste, 15 ounce black beans, 15 ounce kernel corn, 15 ounce kidney beans, 0.5 tablespoon paprika, 1 teaspoon chili powder, 0.5 teaspoon oregano, 0.5 teaspoon ground pepper, 0.25 teaspoon cayenne pepper',replace('(if using meat...brown the meat really well, remove and set aside.  Add the meat after sauteing the veggies)\nHeat oil in a large pot over medium-high heat. Stir in zucchini, red bell pepper, orange bell pepper, jalapeno, garlic, and onion. Cook 5 minutes, just until tender.\nAdd tomatoes with liquid, tomato paste, black beans, corn, and kidney beans into the pot. Season with smoked paprika, chili powder, oregano, black pepper, and cayenne pepper. Bring to a boil.\nReduce heat to low and simmer 1 hour, stirring occasionally.  (depending on how big you cut the veggies, you may want to let it simmer a little longer)','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(390,'How To Make Fried Chicken Without Frying','https://img.spoonacular.com/recipes/647577-556x370.jpg','4  chicken thighs, 2 Tbsp extra virgin olive oil, 2 servings rosemary, 2 servings sage, 2 servings tarragon, 2 servings salt, 2 servings bell pepper, 6 Tbsp bread crumbs, 2 Tbsp honey, 2 Tbsp vinegar',replace('Preheat the oven to 200C/400F.\nWash and dry the chicken thighs.\nMince the herbs.\nIn a bowl put the extra virgin olive oil, the minced herbs, salt and pepper.\nPut the chicken inside the bowl and gently massage the chicken with the oil and herbs mixture.\nPass each thigh on the breadcrumbs and put on an oven tray covered with parchment paper.\nCook until well done, from 50 minutes to one hour, depending on your oven and the weight of the chicken pieces.\nAt half cooking time, turn each piece to the other side.\nPrepare a sauce mixing the honey and vinegar.\nFive minutes before taking the chicken out of the oven, brush each piece with the sauce.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(391,'Breakfast Sticky Buns','https://img.spoonacular.com/recipes/636080-556x370.jpg','0.5 cup brown sugar, 1 tablespoon butter, 1 box butterscotch pudding, 0.5 cup pecans, 1 pkg rich''s rolls','Spray a 10-inch tube pan with a no-stick cooking spray. Spread pecans evenly on bottom of pan. Place rolls on pecans and then sprinkle pudding on top of rolls.Mix sugar into melted butter. Pour this mixture over nuts/rolls/pudding. Cover and let stand overnight. Bake at 350 degrees for 20-25 minutes. Turn over and out onto plate at once.',45,45,0);
INSERT INTO "Recipe" VALUES(392,'Cajun Potato Wedges','https://img.spoonacular.com/recipes/636733-556x370.jpg','1 tsp cayenne pepper, 1 tsp garlic powder, 1 tsp seasoning, 3 tbsp olive oil, 1 tsp onion powder, 2 tsp paprika, 0.5 tsp pepper, 2 large russet potatoes, 0.75 tsp salt','Preheat oven to 425 degrees Fahrenheit. Slice potatoes into  inch thick wedges that are half the length of the potato.Make spice mixture: combine all spices and mix together in a small bowl.Spray cookie sheet with olive oil cooking spray. Place potatoes on cookie sheet. Toss with olive oil. Sprinkle spice mixture over potatoes and toss.Cook for 25 minutes. Flip over and cook for another 5 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(393,'Shortbread Lemon Bars','https://img.spoonacular.com/recipes/1005367-556x370.jpg','0.25 cup all purpose flour, 0.75 cup all purpose flour, 3  eggs, 0.5 cup lemon juice, 2 tsp lemon zest, 3 Tbsp fat milk, 0.33333334 cup powdered sugar, 0.25 tsp salt, 1 cup sugar, 6 tbsp butter',replace('Preheat oven to 350.\nCoat a 8 inch square baking ban with no stick cooking spray or line with foil.\nCombine flour, confectioners sugar and salt in large mixing bowl.\nAdd butter and cut into flour with a fork or crumble with your fingers to combine until flour resembles coarse meal.\nPress mixture with fingers into even layer over the bottom of the pan.\nRefrigerate for 15 minutes, then bake about 20 minutes, or until golden brown.\nCombine sugar and flour for the filling in a medium mixing bowl. Whisk in the eggs.\nAdd lemon juice, milk, and salt; stir to combine.\nPour over baked crust. Sprinkle lemon zest over the filling.\nReturn to oven and bake 20 minutes, or until firmly set.\nCool on rack. Remove from pan and cut into 9 squares.\nDust with powdered sugar.','\n',chr(10)),70,70,0);
INSERT INTO "Recipe" VALUES(394,'Harvest Hash','https://img.spoonacular.com/recipes/646317-556x370.jpg','2  sweet potato, 6  bacon, 4 servings onion, 2  honey apples, 4 servings evoo, 4 servings kosher salt',replace('Preheat oven to 400 degrees.\nIn a large bowl add the yams then drizzle with oil and sprinkle with some salt. Toss to coat then arrange on a baking sheet. Roast the yams until tender but not mushy, 10-15 minutes. Take out of the oven and set aside. Coat a large frying pan with olive oil; add the bacon and cook over medium heat just until it starts to get crisp then add in the onion. Saut until the onions are soft and tender, add the apples and cook for another 3-4 minutes. Stir in the yams and cook just until they start to get a little crisp around the edges about 6-8 minutes. Serve along with the ham steak and enjoy all the flavors of fall!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(395,'Buttermilk Pound Cake','https://img.spoonacular.com/recipes/636560-556x370.jpg','3 cups flour, 0.25 teaspoon baking soda, 0.5 teaspoon salt, 1 cup butter, 3 cups sugar, 5  eggs, 1  lemon zest, 0.5 teaspoon nutmeg, 2 teaspoons vanilla extract, 1 cup buttermilk',replace('Preheat oven to 325 F. Butter one 9- or 10-inch tube pan. Line the bottom with parchment paper, and butter the bottom again. Optional: In addition to buttering the pan, coat the sides with sugar.\nSift flour, baking soda, and salt. Set aside.\nIn a large bowl, beat butter with sugar until creamy, 5 minutes. Mix in the eggs, one at time, beating well after each addition. Stir in the lemon zest, nutmeg and the vanilla extract. Add one-third of the flour mixture to the batter and mix well. Add one-half of the buttermilk into the batter and mix well. Continue to alternate the flour mixture and the buttermilk. Pour batter into the prepared pan. Optional: Garnish with chopped pecans/walnuts or sliced almonds.\nBake in a preheated oven for 70 to 90 minutes. Do not open oven door within the first hour of baking. The cake is done when it starts to pull away from the tube pans side, or use the toothpick trick. Insert a toothpick and when it comes out clean, the cake is done cooking. After removing the cake from the oven, cool in a pan for 10 minutes. Remove from the cake from the pan and place on a wire rack. Let cool completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(396,'Beer Can Chicken, Country Style Vegetables with Roasted Garlic','https://img.spoonacular.com/recipes/634753-556x370.jpg','12 oz beer, 1  cayenne pepper, 1 tbsp chilli flakes, 1 large corn on the cob, 1 tsp thyme, 1 lb garlic bu, 4 servings garlic powder, 100 g green beans, 1 teaspoon lemon juice, 4 servings olive oil, 2 teaspoons onion powder, 2  peppers, 2 teaspoons salt, 4 servings salt & pepper, 1 tbsp paprika, 1  chicken, 2 tbsp corriander, 2 tbsp corriander','METHOD:1. Pre-heat oven to 200C2. Rub chicken with olive oil and lemon juice. Cut a garlic clove in half and rub the open end all over the chicken. In a small bowl mix the paprika, crushed chilli, thyme, salt and pepper. Rub this mixture into the chicken.3. If injecting your chicken with marinade do this now. Mix all ingredient together until smooth so nothing clogs the injector. Inject into various points of the flesh.4.. To prepare for the oven. Open the can of beer and pour out 1/3 of the beer (better, drink it!). Place the beer can on a roasting tray and gently place the chicken on top of the can as far down as you can go.5.. Place chicken in the oven standing up and roast for approx. 25 minutes on 200C, then turn down to 180C and roast a further 25 minutes. (Depending on what type of oven you have you may need to adjust these times, and check on the progress of the bird as you go.)  In the final 20 minutes of roasting add your garlic bulb to the roasting pan.6. For the vegetables. Rub pepper in oil and place on some foil in the oven along with the chicken for approx. 15  20 minutes until soft and charred and skin is peeling off. When ready remove from oven, peel off skin and slice into strips.7. Boil or steam green beans.8. Boil, then char the corn in a griddle pan. When ready take a knife and from the top to the bottom cut off the corn kernels, slicing downwards. At this point you could also add your strips of red pepper and beans to the griddle pan to add some charred stripes. slicing downwards.7.. To plate the dish. Mix the pepper, beans and corn in a bowl with some olive oil, a squeeze of lemon juice, chopped coriander and salt and pepper. Serve this along with pieces of the paprika beer can chicken.',45,45,0);
INSERT INTO "Recipe" VALUES(397,'Dried Cherry-Almond Scones','https://img.spoonacular.com/recipes/641650-556x370.jpg','0.5 teaspoon almond extract, 0.5 cup almonds, 1 tablespoon baking powder, 0.5 teaspoon baking soda, 1 cup cherries, 2 large eggs, 500 g flour, 0.5 tsp salt, 2 tbsp sugar, 6 tablespoons butter, 0.6666667 cup buttermik, 0.6666667 cup buttermik','Preheat oven to 400 degree F.  Stir together flour, 1/4 cup sugar, and next 3 ingredients in a large bowl; cut int butter with a pastry blender or fork until crumbly.  Stir in cherries and almonds.Whisk together buttermilk, 1 egg, and almond extract; add to flour mixture, stirring with a fork just until dry ingredients are moistened and mixture forms a shaggy dough.Use floured hands to pat dough into a 1/2-inch thick, 10-x7-inch rectangle on a lightly floured surface; cut into 16 rectangles.  Place scone dough on a parchment paper-lined baking sheet.  Whisk together remaining egg and 1 teaspoon water.  Brush scones with egg wash; sprinkle with remaining 1/4 cup sugar.Bake in preheated oven for 12 to 15 minutes or until golden.',45,45,0);
INSERT INTO "Recipe" VALUES(398,'Cheddar Polenta With Bacon Wrapped Asparagus','https://img.spoonacular.com/recipes/637516-556x370.jpg','6  spears of asparagus, 2 slices bacon, 0.75 cup chicken broth, 0.25 cup coarse corn grits, 0.25 cup extra sharp cheddar cheese, 1 serving bell pepper, 1 serving salt','Preheat the oven to 400. Wrap 6 thick asparagus spears with two slices of raw bacon.Place on a small baking sheet and spritz the bundle with nonstick cooking spray, just to coat the asparagus lightly. Sprinkle with salt and pepper.Roast for 15-20 minutes, or until the bacon is crispy and the asparagus is tender.Make the cheddar polenta while the asparagus is roasting: Bring chicken broth to a boil in a small saucepan.Stir in polenta.Lower the heat and cook slowly for 5 minutes, stirring occasionally until the mixture has thickened.Stir in the cheese. I used extra sharp cheddar, but any kind would work. Add a dash of salt and pepper, or more to taste.Scoop the polenta in a dish and top with the bacon wrapped asparagus.',45,45,0);
INSERT INTO "Recipe" VALUES(399,'Tarte aux Pommes','https://img.spoonacular.com/recipes/662895-556x370.jpg','6  apples, 3 tablespoons brown sugar, 2  eggs, 1 cup heavy whipping cream, 1  pie crust already made and on your supermarket refrigerator section, 1 teaspoon vanilla extract','Preheat the oven to 350.  In a 9 inch pie pan, place the pie crust, pick slightly with a fork and place in the hot oven for 9 minutes. When done remove from the heat and let cool for a while. In a bowl mix together the eggs, whipping cream, vanilla. Place the apples all over the pie dough.  cover with the cream.  Place in a hot oven for 35 to 45 minutes, until the middle is firm and the tarte is a wonderful golden color.',45,45,0);
INSERT INTO "Recipe" VALUES(400,'Croissants With Sesame Seeds (Kifli)','https://img.spoonacular.com/recipes/640907-556x370.jpg','2 cups milk, 1 package active yeast, 6 teaspoons sugar, 2 tablespoons flour, 1 tablespoon baking powder, 2 teaspoons salt, 0.5 cup vegetable oil, 4  eggs, 6 cups flour, 1 stick margarine, 50 servings sesame seeds',replace('In a large, deep mixing bowl pour in lukewarm milk.\nStir in the sugar, 2 tablespoons of flour, and the yeast.\nLet stand for ten minutes.\nAdd in the baking powder, salt, vegetable oil, egg whites, and 6 cups of flour.\nStir with a wooden spoon until the mixture is well incorporated, you may need to get your hands in there towards the end, and then bring the dough to a lightly floured surface.\nKnead the dough for 10 minutes.\nPut the dough in a large bowl, cover it, and let it stand for one hour.\nPreheat oven at 375.\nBring the dough back to your working area and knead it again for another 5 minutes. You want to make sure that all those air bubbles are out.\nForm the dough into a log and cut it into 5 or 6 equal pieces.\nTake one piece (cover the rest with a kitchen towel), and roll it out to a size as big as a medium pizza.\nWith a knife, cut the rolled out dough into 8 equal slices.\nBeginning at the widest point of the slice start rolling it towards the narrowest point.\nPlace the croissants on a lightly greased baking sheet.\nContinue to do this with the rest of the dough.\nIn a small mixing bowl, whisk the 4 egg yolks.\nBrush each croissant with the egg yolk.\nTop each croissant with sesame seeds.\nPut 4 or 5 small pieces of margarine throughout the baking sheet.\nBake for  15 to 20 minutes, or until golden brown.\nCover with a kitchen towel while they are cooling.\nServe immediately or store in an airtight container.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(401,'Shortbread Lemon Bars','https://img.spoonacular.com/recipes/1005367-556x370.jpg','0.25 cup all purpose flour, 0.75 cup all purpose flour, 3  eggs, 0.5 cup lemon juice, 2 tsp lemon zest, 3 Tbsp fat milk, 0.33333334 cup powdered sugar, 0.25 tsp salt, 1 cup sugar, 6 tbsp butter',replace('Preheat oven to 350.\nCoat a 8 inch square baking ban with no stick cooking spray or line with foil.\nCombine flour, confectioners sugar and salt in large mixing bowl.\nAdd butter and cut into flour with a fork or crumble with your fingers to combine until flour resembles coarse meal.\nPress mixture with fingers into even layer over the bottom of the pan.\nRefrigerate for 15 minutes, then bake about 20 minutes, or until golden brown.\nCombine sugar and flour for the filling in a medium mixing bowl. Whisk in the eggs.\nAdd lemon juice, milk, and salt; stir to combine.\nPour over baked crust. Sprinkle lemon zest over the filling.\nReturn to oven and bake 20 minutes, or until firmly set.\nCool on rack. Remove from pan and cut into 9 squares.\nDust with powdered sugar.','\n',chr(10)),70,70,0);
INSERT INTO "Recipe" VALUES(402,'Caramelized Tofu & Gala Apple Salad','https://img.spoonacular.com/recipes/637067-556x370.jpg','2 tablespoons brown sugar, 1 tablespoon butter, 14 ounces extra-firm tofu, 1  gala apple, 2 cloves garlic, 3 cups lettuce, 12  wholes pecans, 0.25 cup water','First thing of action: bake your tofu. Preheat the oven to 350F. Let tofu sit on a kitchen towel for 15 minutes, turning once, to absorb moisture. Cut tofu into 1 inch cubes. Brush them lightly with vegetable oil (I always use olive oil, but I am certain that this "Recipe" would be best with a peanut oil). Place them on a baking sheet and bake for 35 minutes, turning once.In a small pan, heat butter and garlic on low until the butter has just almost melted. Add the apples, tofu, and salt. Bring heat up to medium, and cook for about 4 minutes. At this point you should add the water and stir every minute for the next 6-7 additional minutes, or until there is little moisture left in the pan. Turn off the heat, and add the brown sugar. Stir to incorporate all of the sugar. Place on top of salad lettuce.',45,45,0);
INSERT INTO "Recipe" VALUES(403,'Old Fashioned Vanilla Buttercream Frosting','https://img.spoonacular.com/recipes/715550-556x370.jpg','0.5 cup solid vegetable shortening, 0.5 cup butter, 1.5 tsp vanilla, 5 cups confectioners sugar, 3 Tbsp milk',replace('Instructions\n\nButtercream Icing "Recipe"\n\nIn a large mixing bowl cream butter and shortening with electric mixer. Add vanilla.\n\nGradually add in sifted confectioners sugar, one cup at a time beating on medium speed.\n\nScrape sides and bottom of bowl often. When all of the sugar has been mixed in, icing will appear dry. Add milk and beat at medium speed for 3 minutes.\n\nKeep icing covered with a damp cloth until ready to decorate. For best results, keep icing bowl in refrigerator when not using.\n\nIcing can be stored in an air tight container for up to a week. Just re-whip it in your mixer before using. Makes 3 1/2 cups.','\n',chr(10)),5,5,0);
INSERT INTO "Recipe" VALUES(404,'Coconut Cream Pie Vegan Milkshake','https://img.spoonacular.com/recipes/639749-556x370.jpg','1 cup coconut meat, 1 tablespoon lemon juice, 1 tablespoon coconut oil, 1 cup coconut milk, 1  banana, 1 teaspoon vanilla extract, 2 tablespoons graham cracker crumbs, 1 tablespoon coconut flakes, 3 servings ice cubes',replace('Combine coconut meat, lemon juice, coconut oil, coconut milk, banana, vanilla, agave nectar (optional) and graham cracker crumbs in a blender; pulse until smooth.\nTop with soy or dairy based whip cream, sprinkle with additional graham crackers and garnish with toasted coconut flakes.\nServes 2-3','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(405,'Tomato and lentil soup','https://img.spoonacular.com/recipes/663559-556x370.jpg','2 Tbs olive oil, 1  onion, 2 cloves garlic, 3  carrots, 480 g tomatoes, 1  bay leaf, 1.3 l water, 250 g lentils, 0.25 tsp salt, 1 bunch parsley',replace('Saut onion and garlic in olive oil for 5 minutes.\nAdd the carrot, saut for another 2 minutes.\nAdd tomatoes, bay leaf and water, stir and bring to the boil.\nStir in lentils, season with salt and cook for 5 minutes.\nBefore serving sprinkle with chopped parsley.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(406,'Almost Guilt Free Mac and Cheese','https://img.spoonacular.com/recipes/632213-556x370.jpg','0.5 pound cellantani pasta, 1 medium Head cauliflower, 1 pound chicken breast, 2 tablespoons olive oil, 5 tablespoons butter, 3 tablespoons flour, 1 tablespoon coleman''s mustard, 3 cups soy milk, 1 medium onion, 2  bay leaves, 0.5 teaspoon paprika, 0.5  juice of lemon, 0.25 teaspoon thyme, 0.5 teaspoon garlic powder, 0.125 teaspoon szechuan peppers, 2  eggs, 5 ounces goat cheese, 5 ounces parmesan cheese, 6 ounces emmental cheese, 1 cup panko bread crumbs, 8 servings kosher salt, 8 servings ground pepper',replace('Preheat oven to 425 degrees Farenheit.\nFor Roasted Cauliflower\nClean core and leaves from cauliflower (you do not have to have any precision when doing this).  Chop cauliflower into pieces.  Pieces should be roughly 1/2" - 3/4".\nPlace chopped cauliflower pieces onto a baking sheet.  Drizzle olive oil over top of cauliflower and mix to thoroughly coat pieces.\nAfter 20 minutes, toss cauliflower pieces to brown all sides.  Bake for another 20 minutes or until edges are browned.\nRemove from oven and lower temperature to 350 degrees Farenheit.\nFor Macaroni and Cheese\nIn a large pot of boiling and salted water, cook pasta until it is al dente.  Once done, drain.\nIn another large saucepan, over medium high heat, melt 3 tablespoons of butter.  Once melted, whisk in flour.  Keep whisking to ensure that there are no lumps.  After 5-7 minutes, the butter and flour mixture should be a light caramel color.\nAdd the soy milk, bay leaves, paprika, lemon juice, thyme, garlic powder and Szechuan pepper.  Stir occasionally for 10 - 15 minutes.  The mixture should thicken up.  Remove bay leaves.\nIn a medium size bowl thoroughly mix eggs.  Using a 1/4 cup measuring cup, slowly add milk mixture to eggs (temper the eggs).  While adding the hot mixture to the eggs, make sure that you keep whisking.  Once you have roughly 2 cups of the soy milk mixture in with the eggs, dump everything into the main saucepan and stir.  Add in 3/4 of the shredded cheeses, and all of the goat cheese, and stir to combine.\nAdd in the cooked, diced chicken and roasted cauliflower.  Once these are combined, add the cooked pasta and stir thoroughly.\nSeason with salt and pepper.\nPour into a 9"x13" baking pan.\nCover with remaining cheese.\nMelt 2 tablespoons of butter in a saute pan.  Add panko bread crumbs and stir to coat all of the crumbs with butter.\nTop the mac and cheese with the panko crumbs and bake for 30 minutes.\nLet rest for 15-20 minutes before serving.\nIf you really want to kick up the heat factor in this, you can add tablespoon of Sriracha hot sauce to the mix.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(407,'Corned Beef Ribs With Brown Sugar and Mustard Glaze','https://img.spoonacular.com/recipes/640141-556x370.jpg','4  bay leaves, 24  peppercorns, 1 small head cabbage, 4 medium carrots, 1 tablespoon cider vinegar, 2.5 pounds corned beef ribs, 2 tablespoons dijon mustard, 2 large cloves garlic, 0.25 cup beer, 0.5 cup brown sugar, 2 medium onions, 4 medium potatoes, 2 quarts water','Preheat an oven to 350Stud the rinsed and peeled rack of corned beef ribs with the three cloves, fairly evenly spaced along the top meaty side of the ribs.Place the ribs in a large, deep covered roasting pan or Dutch oven.Sprinkle the peppercorns on top of the ribs along with the slices of garlic and the bay leaves.Add enough water to just cover the ribs - this will vary depending on the size of your pan.Put the pan, covered, into the oven and cook for one hour.While the ribs are braising for the first hour, prepare the vegetables.After the first hour, add all the vegetables, except for the cabbage, into the pan. Re-cover and return to the oven for 45 minutes.After the 45 minutes, add the cabbage to the pan, re-cover and return to the oven for fifteen minutes.During the final braising of the ribs and vegetables, prepare the glaze.Combine the sugar, beer and vinegar in a small saucepan and heat to a boil over medium heat.Cook at a low boil for 5 minutes, stirring often.Remove the glaze from the heat, add the mustard and stir to combine.Set aside until ribs and vegetables are finished braising.Remove the vegetables and ribs from the oven when the cooking time is complete (about 2 hours).Remove the ribs and place on a baking rack set over a pan. Re-cover the vegetables to keep them warm while you glaze the ribs.Brush a light coat of glaze on the underside of the ribs and a thicker layer on the top side.  Use about 1/2 the glaze.Place the ribs into the oven and cook for 15 minutes.  This will give you a good base layer of glaze.After 15 minutes, remove the ribs for a final coating and turn the oven up to 425Brush the rest of the glaze on the ribs, return to the oven and cook for 10 to 15 minutes more, until the glaze is lightly browned and bubbly but not burned.When the glazed ribs are done, allow to cook for a couple of minutes (that sugar will be hot!).Remove the vegetables from the braising liquid and serve with the ribs on a platter to serve and cut at the table or cut the meat into rib sections. If you wish to forego the vegetables,  by the way, the ribs make a fantastic appetizer all on their own.',45,45,0);
INSERT INTO "Recipe" VALUES(408,'Blackberry Balsamic Drumsticks','https://img.spoonacular.com/recipes/635182-556x370.png','6  skin-on chicken drumsticks, 1 cup blackberries, 0.25 cup balsamic vinegar, 0.25 cup demerara sugar, 1.5 tbsp rosemary, 2 tbsp butter, 2 tbsp grain mustard, 2 servings salt and pepper',replace('Place blackberries, butter, water, rosemary, sugar and vinegar in a small saucepan.\nCook over medium high heat stirring occasionally until slightly reduced.  About 10 -15 minutes.\nRemove from heat and stir in mustard and salt and pepper.\nLeave marinade to cool.\nPlace drumsticks in a large zip lock bag,\nPour cooled marinade over top and seal.  Toss to coat.\nPlace mixture in the fridge and marinate for 24 hours.\nWhen ready to cook, preheat oven to 375\nArrange drumsticks on a cookie sheet coated in tin foil.\nCook for 25 minutes, turning once.\nServe hot with preferred side.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(409,'Chocolate Asparagus Bundt Cake','https://img.spoonacular.com/recipes/638819-556x370.jpg','1 pound asparagus, 1 teaspoon baking soda, 0.33333334 cup cocoa powder, 3  eggs, 2 cups flour, 1 teaspoon ground cinnamon, 1 tablespoons orange peel, 1 cup pecans, 0.5 teaspoon salt, 0.75 cup sugar, 2 teaspoons vanilla extract, 0.5 cup vegetable oil','Preheat oven to 350 F.In a large bowl, combine flour, sugar, baking soda, cinnamon, cocoa powder, and salt.Add oil, eggs, asparagus, orange peel and vanilla; mix well.Fold in pecans.Pour into a greased and floured 10-in. bundt pan. Bake for 1 hour or until a toothpick inserted comes out clean. Cool for 10 minutes; remove from pan to a wire rack to cool completely.',45,45,0);
INSERT INTO "Recipe" VALUES(410,'Brown Rice Vegetable Pulao','https://img.spoonacular.com/recipes/636295-556x370.jpg','175 grams brown basmati rice, 1  carrot, 2  celery stalks, 1 small chilly, 75 grams lentils, 1  onion, 2 tablespoons orange juice, 3 servings salt and pepper, 1  spring onion including the part, 4 tablespoons vegetable oil, 80 ml vegetable stock, 20 grams almonds, 1 leaves to garnish','Heat 2 tbsp of oil in a frying pan over medium heat. Add the chopped onion and saute well till softened.Add the celery, carrot, chilli, spring onions and almonds. Stir-fry for 2 minutes or until the vegetables are done. Transfer to a bowl and set aside.Add the remaining oil to the pan. Stir in the rice and lentils. Cook over medium heat, stirring for 2 minutes.Reduce the heat and stir in the veg stock and orange juice. Season with salt and pepper.Mix the already cooked vegetables to the pan. Toss with the rice for a few minutes until heated through.Transfer to a warmed dish, garnish with leaves and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(411,'Almond Butter Slices','https://img.spoonacular.com/recipes/632103-556x370.jpg','100 grams almond, 15 grams saffron baking powder, 125 grams kerrygold butter, 300 grams german #405 flour, 150 grams german quark, 90 ml safflower oil, 0.5 teaspoon salt, 1.5 cups sugar, 20 grams vanilla sugar, 0.5 cup milk','Preheat the oven to 180C/350F. Line a 30x40cm baking tray with paper. Combine the sugar, vanilla sugar and almond slices for the topping in a bowl. Set aside.Sift the flour and baking powder into a mixing bowl. Add in Quark, milk, oil, sugar and salt. Mix all the ingredients with a hand mixer fitted with dough hooks for 1 minute on high speed. Dont over stir the dough or it will become sticky.Place the dough onto the prepared tray and roll it out. Spread the softened butter all over the surface of the dough. Spead the topping mixture evenly onto the dough. Bake on the upper rack of the hot oven for about 20 minutes until golden crispy.',45,45,0);
INSERT INTO "Recipe" VALUES(412,'Mashed Cauliflower','https://img.spoonacular.com/recipes/651202-556x370.jpg','1 large head cauliflower, 2 cups chicken broth, 0.75 cup gruyere cheese, 2 tablespoons heavy cream, 1 dash nutmeg, 0.25 cup parmesan cheese, 6 servings bell pepper, 6 servings salt, 2 tablespoons butter','Wash and cut cauliflower into small pieces.Cover cauliflower in a pot with chicken broth.Boil until tender.Drain very well.Add butter, cream, cheeses, salt and pepper to taste, and nutmeg.Mix with electric hand mixer.',45,45,0);
INSERT INTO "Recipe" VALUES(413,'Moroccan Spiced Chicken Under A Brick','https://img.spoonacular.com/recipes/652442-556x370.jpg','3 lb chicken, 4  garlic cloves, 0.25 cup cilantro leaves, 2 teaspoons sea salt, 1 teaspoon lemon zest, 0.25 teaspoon saffron threads, 4 tablespoons olive oil, 1 tablespoon paprika, 1 teaspoon ground cumin, 0.5 teaspoon pepper, 0.25 teaspoon cayenne',replace('Make the paste:\nCombine garlic, cilantro, one teaspoon salt, lemon zest and saffron in a mortar with pestle.\nSmash to a paste.\nAdd 3 tablespoons olive oil and stir to combine.\nRub chicken all over with paste, including between skin and breast meat.\nPlace on tray or platter, skin side up and cover loosely with plastic wrap.\nRefrigerate at least 2 hours and up to 6 hours.\nRemove from refrigerator 30 minutes before roasting.\nPrepare chicken:\nPreheat oven to 450 F.\nMix one teaspoon salt, paprika, cumin, black pepper and cayenne together in a small bowl.\nSprinkle over all sides of chicken.\nHeat one tablespoon olive oil in oven-proof skillet over medium-high heat.\nPlace chicken, skin-side down, in skillet.\nPlace brick wrapped in foil (or heavy pan or Dutch-oven) over chicken.\nCook chicken over medium-high heat without moving brick or chicken, 10 minutes.\nRotate skillet occasionally, to ensure even cooking.\nRemove from heat.\nUsing a spatula, turn over chicken, skin-side up.\nPlace in oven (without brick) and continue cooking until done, 20-30 minutes, depending on size of chicken.\nLet rest 10 minutes before carving into serving pieces.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(414,'Arroz Con Leche','https://img.spoonacular.com/recipes/632737-556x370.jpg','3 cups heavy cream, 3 cups milk, 1 cup arborio rice, 2  cinnamon sticks, 1  lemon zest, 1 pinch salt, 1 cup sugar',replace('In a saucepan, place the 2 cups heavy cream, 2 cups milk, rice, cinnamon sticks, lemon zest and salt then bring to a boil.\nTurn down the heat and simmer until the rice is cooked, about 30 minutes. Add the rest of milk and heavy cream as needed (you don''t want the rice to become too thick).\nAdd the sugar off the heat and stir to combine.\nRemove the cinnamon sticks.\nSprinkle with cinnamon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(415,'Pumpkin Pecan Streusel Cake - gluten free, soy free, vegan','https://img.spoonacular.com/recipes/657341-556x370.jpg','0.5 teaspoon aluminum free baking soda, 2 teaspoons aluminum free baking powder, 1 teaspoon apple cider vinegar, 2 medium bananas, 0.25 cup brown rice flour, 0.75 cup firmly brown sugar, 1 bag enjoy life brand chocolate chips, 1 teaspoon ground ginger, 0.5 teaspoon ground nutmeg, 0.5 teaspoon kosher salt, 0.25 cup oat flour, 0.5 cup pecans, 1 cup roasted pumpkin puree, 0.75 cup rice flour, 0.25 cup sorghum flour, 0.25 cup earth balance soy free spread, 0.5 cup tapioca flour, 0.5 cup coconut yogurt','Preheat oven to 350F.Grease and flour a 9-inch spring form pan or a 9-inch cake pan with 3-inch sides (recommended by Williams Sonoma). I used an Angel Food Cake Pan.For the streusel:Combine the flours, brown sugar, cinnamon and kosher salt in a small bowl.Add Earth Balance Soy Free Spread into the dry ingredients.Work the spread into the mixture with your hands until the mixture looks like coarse crumbs.Add the pecans, combine. Set aside.For the batter:Measure your coconut milk and add the apple cider vinegar to it.Let it sit without mixing to become sour-creamy looking. Set aside.In a medium bowl, sift together, or whisk the flours, baking powder, baking soda, cinnamon, ginger, nutmeg and kosher salt.In the bowl of an electric mixer fitted with the flat beater, beat together the butter and brown sugar on medium-high speed until well combined.Add the mashed banana, scraping down the sides of the bowl with a rubber spatula when needed.Add the pumpkin puree and sour cream mixture and continue to mix on low speed.Add in the flour mixture.The batter will be quite thick which is how it should be.Note: If your batter is not thick for some reason add 1/4 cup of white rice flour.Spread half of the thick batter into the prepared pan.Sprinkle half of the streusel over the batter.Add the remaining batter over the streusel and spread the thick batter evenly.Evenly spread the remaining streusel over the batter.Bake 55-60 minutes, or until a toothpick inserted into the center of the cake comes out clean.Transfer the cake in the pan to your stovetop and let it cool for about 40 minutes.When cooled, remove the sides of the cake from the pan using a spreader type knife, or something that will not scratch your cake pan.Gently lift up the cake by pressing the removable bottom upwards.I then refrigerated the cake with the bottom part still holding the cake for about an hour.Transfer the chilled cake to a cake platter.Put pieces of wax or parchment paper under the edges of the cake to keep the glaze drips from making a mess of your platter.For the glaze:In a glass bowl set over a small saucepan with simmering water, combine mini chips with Earth Balance spread.Mix often to get a glossy sheen.When completely melted take off the saucepan and let it cool for 5 minutes before glazing the cake.Using a large spoon drizzle melted chocolate over the top of the cake.Slowly pull out the papers along the cake.Serve chilled, or room temperature.',45,45,0);
INSERT INTO "Recipe" VALUES(416,'Asian Salmon Burgers With Tangy Ginger Lime Sauce','https://img.spoonacular.com/recipes/632874-556x370.jpg','4  burger buns, 1 tablespoon basil, 1 clove garlic, 1  green onion, 0.25  juice of lime, 0.25 cup mayonnaise, 1 teaspoon oyster sauce, 0.5 teaspoon powdered ginger, 1 pound salmon, 5.5 tablespoons sesame oil, 2 tablespoons cream, 1 tablespoon soy sauce','Cut the salmon into large hunks and run it through a food processor until no large pieces remain.Add to the salmon the soy sauce, garlic, ginger, oyster sauce, green onion, and basil.Combine ingredients well and form 4 large patties from mixture.Heat up the sesame oil in a large frying pan on medium high heat and add in the patties. Cook for about 10 minutes flipping once half way through.To make the sauce, add together all the above listed ingredients and stir to combine.Pour a spoonful of sauce over the top of the finished salmon burger and serve inside a toasted bun.',30,30,0);
INSERT INTO "Recipe" VALUES(417,'Summer Veggie Bake','https://img.spoonacular.com/recipes/662263-556x370.jpg','2  ears of corn, 1 tsp garlic powder, 1  juice of lemon, 1 cup milk, 1.5 cups chicken broth, 1 tsp onion powder, 1 cup orzo, 0.5 cup panko, 1 tsp paprika, 0.25 cup parmesan cheese, 0.25 cup parsley, 1 tsp pepper, 1  rotisserie chicken, 0.25 cup mozzarella cheese, 3  tomatoes, 8 oz zucchini','Preheat the oven to 400 degrees Fahrenheit. In a medium saucepan, add milk and chicken broth and bring to a boil. Add orzo and reduce to medium heat. Cook orzo until tender and liquid is absorbed, about 15 min.Meanwhile, mix chicken, cheese, spices, lemon, corn and parsley. Add mixture to the orzo and stir until evenly distributed.Pour out orzo mixture into a 8 by 8 glass baking dish. For the topping, layer zucchini and tomato, alternating each veggie.Sprinkle panko, garlic powder and pepper over the veggies.Spray the panko evenly with olive oil cooking spray.Place in oven and cook for 40 minutes. Then broil for about 2 minutes to get the top really golden brown.Serve immediately. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(418,'Minted Pea & Spinach Soup','https://img.spoonacular.com/recipes/652038-556x370.jpg','1 cube chicken stock, 0.25 cup cream, 2 teaspoons mint, 0.25 cup milk, 1 lb peas, 2 medium potatoes, 6 servings salt & pepper, 0.5 pound spinach, 2 tablespoons sugar, 1 cup water, 2 tablespoons yoghurt','Place pototoes in a medium sized pot with a little bit of water and some salt & pepper. Place lid on and cook for 20 minutes until almost soft.Add peas and cook for a further 5 minutes until potatoes are soft and cooked through.Add spinach and cook a further 3 -5 minutes, until wilted.Take off the heat and let cool for a few minutes, then blend to a puree with an immersion blender.Place pot back on the stovetop, adding cream, milk, water and chicken stock. Re-heat for a few minutes until piping-hot. Add yoghurt, mint, sugar, salt and pepper to taste and stir through.Serve immediately, scattered with some crispy croutons or bacon bits (or if you''re like me and you just have some cheesegrillers on hand, fry them up in thin slices with a bit of sweet chilli sauce and use as topper).',45,45,0);
INSERT INTO "Recipe" VALUES(419,'Gluten Free Onion Rings','https://img.spoonacular.com/recipes/644846-556x370.jpg','1  egg, 0.25 cup vegetable oil, 1 cup milk, 1 cup bette hagan''s pizza/french bread flour mix, 0.5 teaspoon salt, 1 teaspoon baking powder, 2 large onions, 0.5 cup all purpose flour, 4 servings oil',replace('Mix egg, oil, and milk on low speed of mixer for 1 minute.\nAdd Bette''s Mix (or equivalent dry ingredients) and mix until smooth.\nPut 1/2 cup all purpose gf flour in a shallow dish. Coat onion rings in flour.\nDip floured onions in prepared batter.\nFry in hot oil (375 degrees, at least 1-inch deep) until desired shade of brown.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(420,'Chicken Cordon Bleu','https://img.spoonacular.com/recipes/638035-556x370.jpg','6 slices deli ham, 2  eggs, 0.25 cup flour, 2 teaspoons thyme leaves, 6 servings kosher salt and pepper, 1 teaspoon olive oil, 1 cup panko bread crumbs, 6  chicken breasts, 12 slices swiss cheese, 2 tsps water','Preheat oven to 350 degrees F.Butterfly the chicken breasts by slicing half lengthwise but not cutting all the way through. Lay the halved breasts between 2 pieces of plastic wrap. Using the flat side of a meat mallet, gently pound the chicken to 1/4-inch thickness, taking care to not tear or create holes in the meat.Lay 2 slices of cheese on each breast, followed by 2 slices of ham, and 2 more of cheese; leaving a 1/2-inch margin on all sides to help seal the roll. Tuck in the sides of the breast and roll up tight like a jellyroll. Squeeze the log gently to seal.Season the flour with salt and pepper; spread out on waxed paper or in a flat dish. Mix the breadcrumbs with thyme, kosher salt, pepper, and oil. The oil will help the crust brown. Beat together the eggs and water, the mixture should be fluid. Lightly dust the chicken with flour, then dip in the egg mixture. Gently coat in the bread crumbs.Carefully transfer the roulades to a baking pan and bake for 20 minutes until browned and cooked through.Serve whole or cut into pinwheels.',45,45,0);
INSERT INTO "Recipe" VALUES(421,'Quick and Easy Southwestern Corn Chowder','https://img.spoonacular.com/recipes/657556-556x370.png','2 Tb butter, 0.25 cup cheddar cheese, 1 tsp chili flakes, 32 oz corn kernels, 0.5 cup bell pepper, 0.25 cup half and half, 0.5 cup bell pepper, 6 servings salt and pepper, 2 cups chicken, 2 large onions, 4 cups vegetable stock','In a Dutch oven, sweat the onions and peppers with a pinch of salt until onions are translucent.Add the chili flakes.Add the chicken stock, corn and chicken.Simmer covered for 10 minutes.Add the butter, half and half, and cheese, if desired.Add salt and pepper to taste.',45,45,0);
INSERT INTO "Recipe" VALUES(422,'Strawberry Shortcake w. Mini Strawberry PopTarts','https://img.spoonacular.com/recipes/716417-556x370.jpg','1 Tbs cup heavy whipping cream, 1  pie crust dough, 1 pinch sea salt, 1 lb strawberries, 0.25 cup strawberry jam, 1 tsp tsp vanilla sugar','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(423,'Roasted Sweet Potato Salad','https://img.spoonacular.com/recipes/658680-556x370.jpg','3 pounds sweet potatoes, 0.25 cup extra virgin olive oil, 1 inch chipotle pepper adobo sauce, 1 teaspoon balsamic vinegar, 2 teaspoons salt, 0.25 teaspoon pepper, 1 cup cranberries, 0.5 cup pecans, 2 tablespoons chives',replace('Preheat oven to 400 degrees (convection works best).\nPeel and cut potatoes into 1 pieces.\nToss to coat with 2 tablespoon of olive oil.\nArrange in a single layer on two baking sheets\nRoast for 35 minutes\nMix 2 tablespoons oil, pepper puree, vinegar, salt and pepper to make a dressing\nCombine cranberries, pecans, chives and cooked sweet potatoes in a medium bowl, drizzle with dressing, cover. Refrigerate until chilled.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(424,'Homemade Oatmeal Cream Pies','https://img.spoonacular.com/recipes/647046-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 1 cup brown sugar, 0.5 cup butter, 0.5 teaspoon cinnamon, 1 teaspoon cocoa powder, 1  egg, 1 cup flour, 7.5 ounces marshmallow fluff, 1 cup powdered sugar, 1 cup rolled oats, 0.25 teaspoon salt, 2 teaspoons vanilla, 1 cup vegetable shortening','Preheat the oven to 350 degrees F. Line cookie sheets with parchment paper. Sift the dry ingredients into a medium bowl and set aside.Use an electric mixer to cream the brown sugar, butter, egg and vanilla. Once smooth, slowly add the dry mixture to the wet until well combined. Stir in the oats.Use a tablespoon-sized scoop to form equal dough balls. Allow them plenty of space to spread. Bake for 7-9 minutes. Allow the cookies to cool completely before moving off the parchment paper.Cream the shortening, powdered sugar, and vanilla together until smooth. Mix in the marshmallow fluff.To assemble: Match up two cookies that are of equal size and shape. Turn the bottom cookies over. Use a piping bag (or zip-bag with the corner cut off) to pipe the filling onto the bottom cookie. This is much easier than trying to spread it. Then add the top cookie of each cream pie and press down.I found I liked a thin layer of cream filling better than a thick layer--but you should have plenty if you want to pile it on!Makes approximately 10 cream pies. (20 cookies)',45,45,0);
INSERT INTO "Recipe" VALUES(425,'Roasted Sea Bream With Anchoiade','https://img.spoonacular.com/recipes/658661-556x370.jpg','12 fillet sea bream, 2  garlic cloves, 150 grams olives, 4  anchovies, 100 milliliters olive oil, 2  peppers, 150 grams sundried tomatoes',replace('Preheat the oven to 190 degrees C/gas 5.  Blend together the garlic, black olives, anchovies and olive oil.  Cut the peppers into large flat pieces, lay skin up on a baking sheet and bake in the oven for about 10 minutes or until the skin is blistering and blackened.  Remove from the oven and leave to cool.  Once cool, carefully remove the skin and then slice finely.\nAdd the peppers and sundried tomatoes to the olive and anchovy mix, combine well.  Increase the oven temperature to 200 degrees C/gas 6.\nLine a baking sheet with baking paper.  Lay 6 of the sea bream fillets, skin down on the baking sheet, spread each of them with the olive mixture, place the other 6 fillets on top, skin up, drizzle with the olive oil, bake for 8 minutes, serve immediately.  I served mine with broken roasted potatoes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(426,'Classic Boeuf Bourguignon','https://img.spoonacular.com/recipes/639571-556x370.jpg','0.5 lb bacon, 1 Tbsp olive oil, 2 lbs beef stew meat, 2 cloves garlic, 1  onion, 3 sprigs thyme, 3  bay leaves, 0.5 cup parsley, 2 cups pearl onions, 2 cups button mushrooms, 1  carrot, 1 cup red wine, 2 cups beef broth, 2 Tbsp all purpose flour, 4 servings salt and pepper',replace('Preheat oven to 400\nIn a large Dutch oven, heat olive oil over medium heat. Add bacon and saut for 2-3 minutes until cooked. Remove bacon with a slotted spoon and set aside.\nDry beef with a paper towel so it will brown better. Increase heat to medium high and add beef to the bacon fat. Cook for 4-5 minutes until the outside has browned. Remove beef with a slotted spoon and set aside in a separate dish.\nReturn heat to medium. Saut carrots, garlic, onions, parsley thyme and bay leaves for 2-3 minutes. Remove with a slotted spoon and set aside in a separate dish.\nAdd pearl onions and mushroom to Dutch oven and saut until onions begin to brown and mushrooms become tender. Remove with a slotted spoon and set aside in the reserved bacon dish.\nAdd beef back to the pot and dust with one tablespoon of flour. Toss to coat and sprinkle with salt and pepper. Place in the preheated oven for 4-5 minutes. This will add a nice coating to the beef.\nRemove pot from the oven and place back on the stove top. Add red wine and deglaze the pan. Pour in beef broth and bring to a simmer over medium heat. Add carrot, onion and spice mixture to the pot, reduce heat and simmer covered for one hour.\nAfter one hour add pearl onions, mushrooms and bacon to the pot. Continue to simmer until beef is tender, about an additional 30 minutes.\nWith a slotted spoon remove solids and set aside. Increase heat and bring sauce to a rapid boil. In a small bowl mix together remaining tablespoon of flour with two tablespoons of sauce. Stir until smooth and no lumps remain. Add mixture to the pot and stir constantly until sauce thickens.\nRemove bay leaves and thyme sprigs, discard. Add solids back to the pot and stir to coat evenly. Serve warm over a bed of egg noodles or rice.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(427,'Bacon Ice Cream','https://img.spoonacular.com/recipes/633314-556x370.jpg','1 pound bacon, 1 pint dulce de leche ice cream, 0.25 cup pecans','Mix bacon and nuts in bowl. Set aside a teaspoon of bacon and nuts for topping.Mix chopped bacon and nuts into ice cream, then place back in freezer.After Bacon Ice Cream is frozen, scoop into cup and top with bits of bacon and nuts. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(428,'Vanilla Pound Cake','https://img.spoonacular.com/recipes/716367-556x370.jpg','1 teaspoon baking powder, 160 g butter, 5 large eggs, 0.5 cup natural yogurt, 1 cup granulated sugar, 0.25 cup milk, 0.5 teaspoon nutmeg, 2 cups flour, 0.5 teaspoon salt, 3 tablespoon vanilla extract','Step 1: With the aid of a sifter, sift the dry ingredients (flour, baking powder, salt, nutmeg) into a bowl and set aside.Step 2: Grease the cake pan and dust with flour. Also pre-heat oven to 180 degrees CelsiusStep 3: Put the butter, sugar and yogurt into a mixer or bowl {if you are using hand mixer}, mix until fluffy; mix on a high speed.Step 4: Crack in the eggs, one at a time…mix for about a minute before adding next. Then add the vanilla extract and mix.Step 5: Add the flour in batches; reduce the speed to the lowest and mixed. Once the flour is combined (doesn’t have to be perfect), and then stop; so you don’t over work the batter.Step 6: At this point, add the milk and mix with a spatula until combined.Step 7: Pour batter into the greased cake pan and bake for approximately 50 minutes or until golden brown.',75,75,0);
INSERT INTO "Recipe" VALUES(429,'Bacon Wrapped Tofu Tacos','https://img.spoonacular.com/recipes/633352-556x370.jpg','12 oz tofu, 1 package fajita size, 8 oz cream cheese, 3 small jalapeno peppers, 2 cups monterey jack cheese, 1 pound bacon, 1 cup chicken broth, 1 bottle olive oil, 1 teaspoon cumin, 1 teaspoon chili powder, 1 teaspoon paprika, 2  garlic cloves',replace('In a small bowl combine the cumin, chili powder, paprika, 1 minced clove of garlic and 2 tbsp of olive oil.  Slice the tofu very thin, about 1/2 inch per slice, then rub each slice with the spice mixture.  Set aside.\nHeat about 1 tbsp olive oil over medium high heat in a large pan.  Add the tofu, a few slices at a time, watching carefully.  Flip after about 1-2 minutes.  Cook until done  I let mine cook about 2-3 minutes per side.   Half each piece, wrap with bacon, then set aside and cover with aluminum foil.\nDo NOT wash the pan out  now put it back on the stove, reduce heat to medium and add the remaining minced garlic clove, 1 tbsp olive oil and diced jalapeno.  Saute until the peppers are almost getting a little bit brown and everything is fragrant.   Add the cream cheese, 1/2 cup cheese and chicken broth.  Whisk and bring to a slight boil; reducing the heat if you have to, preventing it from scorching. Once its combined and a sauce consistency, salt and pepper to your taste and pour into a separate bowl; cover.\nBring the heat back up to medium-high, and add another tablespoon of olive oil to the pan.  When hot add one tortilla at a time, turning after about 15-20 seconds to the other side.  Your end result will be tortillas slightly brown around the edges and a little bubbly in the middle.\nSet aside and cover.\nTo serve, stuff a tortilla with bacon-wrapped tofu, and drizzle the jalapeno creme on top and some Monterey jack.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(430,'Nutella Crepes and Ice Cream','https://img.spoonacular.com/recipes/716272-556x370.jpg','6 servings strawberries/ bananas, 1 tablespoon butter, 1.25 cup butter milk, 0.5 teaspoon cinnamon, 2  eggs, 1 cup flour, 6 servings ice cream, 6 servings nutella, 6 servings oil, 0.25 cup sugar, 1  tea spoon of vanilla extract','In a dry clean bowl, mix together the dry ingredients (flour, sugar, cinnamon)In another bowl, break the eggs and whisk properly, add the milk, butter (or oil), vanilla extract and whisk properly.Add the wet ingredients to the dry ingredients and whisk, ensuring that there are no lumps (Tip: you can use a blender in order to prevent lumps , and if normal whisk is used and you notice lumps you can sieve out the lumps)Grease (with oil or butter) a crepe pan or a big frying panSet to medium to low heatPour batter in the middle of pan and move pan around to ensure that the batter covers the entire pan ( the idea is to make the crepe as thin as possible so avoid pouring a lot of batter into the pan at once)Fry each side of the crepe for 3-4 minutesScoop Nutella into a bowl and microwave for 45 secs to soften it up, so that it doesn’t rip the crepesSlice bananas or strawberrySpread Nutella on one half of the crepe, put the strawberries/bananas and fold over',45,45,0);
INSERT INTO "Recipe" VALUES(431,'Coffee-braised Short Ribs','https://img.spoonacular.com/recipes/639891-556x370.jpg','1.5 tablespoons ancho chile powder, 14  canned tomatoes, 2 tablespoons brown sugar, 5 servings cilantro, 6  garlic cloves, 1.25 teaspoons ground cumin, 1 large jalapeño, 2 tablespoons olive oil, 2 teaspoons oregano, 1 large bell pepper, 5 pounds short, 2 cups strong freshly coffee, 1 tablespoon tomato paste, 1 large onion','FoodPreheat oven to 300F. Heat oil in a large heavy stockpot over medium-high heat. Sprinkle short ribs with salt and pepper. Working in batches, add ribs to pot and cook until browned, about 4 minutes per side. Transfer to platter.Add onion, red bell pepper, and jalapeo to drippings in stockpot. Reduce heat to medium, cover, and cook until onion is tender, stirring occasionally, about 6 minutes.Stir in garlic and saut uncovered 1 minute.Add brown sugar, ancho chile powder, oregano, and cumin; stir 15 seconds. Stir in coffee, tomatoes with juice, and tomato paste. Bring to boil, scraping up browned bits. Return ribs and any juices to pot; bring to boil.Cover and bake until meat is very tender, about 1 hour 45 minutes. Spoon fat from surface of sauce. Season sauce to taste with salt and pepper.Transfer ribs to a platter and spoon sauce over top.Sprinkle with chopped cilantro.',45,45,0);
INSERT INTO "Recipe" VALUES(432,'Snickerdoodle Ice Cream','https://img.spoonacular.com/recipes/716411-556x370.jpg','0.5 teaspoon ground cinnamon, 0.125 teaspoon ground nutmeg, 1.5 cups half-and-half, 2 cups heavy whipping cream, 0.33333334 cup brown sugar, 2 teaspoons vanilla extract, 0.33333334 cup vanilla sugar','No instructions provided.',45,45,0);
INSERT INTO "Recipe" VALUES(433,'Baked Mushroom Caps','https://img.spoonacular.com/recipes/633678-556x370.jpg','8 oz cream cheese, 1.5 lbs mushrooms, 0.25 pkg pepperidge farm dressing, 0.25 cup enough to be able to handle easily','Fill sauteed caps with mixture of rest of ingredients and sprinkle generously with Parmesan cheese. Bake at 350 degrees for 10 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(434,'Cherry ice cream','https://img.spoonacular.com/recipes/637761-556x370.jpg','1.5 cups cherries, 1 tsp corn starch, 1.75 cups cream, 1 tsp lemon juice, 0.75 cup milk, 1 pinch salt, 0.5 cup sugar','Put cherries, milk, one cup of the cream, sugar, and salt into a medium saucepan. Heat on medium heat until the mixture is steamy, then lower the heat and let sit for about 15 minutes. Remove from heat.Pour mixture into a blender, and carefully pure ( because of the hot liquid).Put mixture into a large bowl and stir in the remaining  cup of cream. Chill for several hours in the refrigerator until completely cold.Stir in cornstarch, lemon juice and Amaretto.Pour the mixture into an ice cream machine and churn until frozen. Transfer to plastic container and place in the freezer for an hour before serving.Serving: take it out for 5-10 minutes before serving, or longer, so it comes to the right scooping temperature.',360,360,0);
INSERT INTO "Recipe" VALUES(435,'Cheddar Polenta with Sun-dried Tomatoes & Shrimp','https://img.spoonacular.com/recipes/637515-556x370.jpg','0.33333334 oz precooked polenta tube, 0.5 cup cheddar cheese, 0.25 cup onions, 12 large shrimp, 8  sun-dried tomatoes, 1 tablespoon olive oil, 2 teaspoon garlic powder, 2 servings chives, 1  lemon juice, 2 servings salt and pepper',replace('- Cook polenta according to the package directions and towards the end add cheddar cheese. Reduce heat and allow cheese to melt slowly then combine them together.\n- In a skillet heat oil over medium heat, sautee onion until translucent then add sun-dried tomatoes allowing it to soften for 2-3 minutes.\n- Add shrimps to the skillet, cook until it is no longer pink.\n- Season it generously with salt, pepper, garlic powder and stir everything together.\n- Remove from heat.\n- In a plate, put polenta then top it with sun-dried tomatoes & shrimp. Drizzle lemon juice.\n- Garnish with chives and serve it warm.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(436,'Braised Chicken with Artichoke Hearts & Olives','https://img.spoonacular.com/recipes/635820-556x370.jpg','0.5 cup artichoke hearts, 2 cups chicken broth, 2 handfuls basil, 1  juice of lemon, 0.5 cup kalamata olives, 2 servings olive oil, 0.5  onion, 2 servings salt & pepper, 1 pound chicken breasts, 0.5 cup white wine','Season the chicken with salt and pepper. In a large saut pan, over medium low heat,  add a couple drizzles of olive oil. Place the chicken skin side down in the pan and cook until golden brown, flip and cook a few minutes on the other side. Remove the chicken and place on a dish.If the pan is dry add a small drizzle of olive oil again and the onion. Saut until slightly softened. Carefully add in the white wine and scrap all those delicious bits from the bottom of the pan. Allow the wine to reduce by half.Add in the artichoke hearts, olives and broth. Add the chicken back to the pot and simmer cover for about 20 minutes.Again remove the chicken from the pan. Add in the lemon juice and basil. Simmer for 5 minutes.Pour that fabulous sauce overtop the chicken and enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(437,'Cheddar Polenta with Sun-dried Tomatoes & Shrimp','https://img.spoonacular.com/recipes/637515-556x370.jpg','0.33333334 oz precooked polenta tube, 0.5 cup cheddar cheese, 0.25 cup onions, 12 large shrimp, 8  sun-dried tomatoes, 1 tablespoon olive oil, 2 teaspoon garlic powder, 2 servings chives, 1  lemon juice, 2 servings salt and pepper',replace('- Cook polenta according to the package directions and towards the end add cheddar cheese. Reduce heat and allow cheese to melt slowly then combine them together.\n- In a skillet heat oil over medium heat, sautee onion until translucent then add sun-dried tomatoes allowing it to soften for 2-3 minutes.\n- Add shrimps to the skillet, cook until it is no longer pink.\n- Season it generously with salt, pepper, garlic powder and stir everything together.\n- Remove from heat.\n- In a plate, put polenta then top it with sun-dried tomatoes & shrimp. Drizzle lemon juice.\n- Garnish with chives and serve it warm.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(438,'Flank Steak with Mushroom Sauce','https://img.spoonacular.com/recipes/631750-556x370.jpg','2 packets flavor concentrated beef broth, 2 tablespoons butter, 1  flank steak, 1 tablespoon rosemary leaves, 4 cloves garlic, 3 cups mushrooms, 2 tablespoons olive oil, 1  shallot, 0.25 cup water','Heat 1 tablespoon oil in a 10-inch skillet over medium heat.  Add the beef and cook until well browned on both sides and until desired doneness, about 10 minutes for medium-rare.  Remove the beef from the skillet.Heat 1 tablespoon butter and the remaining oil in the skillet.  Add the mushrooms and cook for 5 minutes or until tender, stirring occasionally.  Add the shallot, garlic and rosemary and cook and stir for 30 seconds.   Stir in the concentrated broth, water and remaining butter and cook until the butter is melted.Cut the beef diagonally against the grain into thin slices.  Serve the mushroom mixture with the beef.',45,45,0);
INSERT INTO "Recipe" VALUES(439,'{No Bake} Cinnamon Butterscotch Energy Bites','https://img.spoonacular.com/recipes/665822-556x370.jpg','2 tbsp brown sugar, 0.25 cup butterscotch chips, 0.5 cup rice cereal, 2 tbsp ground flax seed, 0.25 cup honey, 1 cup oats, 14 servings peanut butter, 2 tbsp protein powder, 0.5 cup ground oats','Grind  cup oats in blender. Combine cereal, whole oats, ground oats, protein powder, and ground flax in a bowl. In a microwavable safe bowl, mix together brown sugar, peanut butter, and honey and heat in the microwave in 15 second intervals, stirring intermittently, until melted. Pour liquid mixture into dry mixture and stir to combine. Refrigerate 30 minutes. Remove from fridge and roll into balls, then press butterscotch chips into each ball.',45,45,0);
INSERT INTO "Recipe" VALUES(440,'How to Make an Amazing Chicken Salad with Apples and Celery','https://img.spoonacular.com/recipes/1160166-556x370.jpg','3 stalks celery, 2.5 cups rotisserie chicken cut, 2 tbsp reduced fat mayo, 0.5 cup non-fat greek yogurt, 1 cup apples i use 2 granny smith apples, 2 tsp lemon juice squeezed, 3 servings avocado',replace('Instructions\n\nMix chicken, celery, and apples. \n\nIn a separate bowl mix mayo, yogurt, and lemon juice. Mix well.\n\nCombine chicken mixture with mayo mixture and stir well. Add salt and pepper to taste.\n\nOPTIONAL: Slice an avocado, remove the pit, and serve the chicken salad with avocado. It''s so good! ','\n',chr(10)),10,10,0);
INSERT INTO "Recipe" VALUES(441,'Vegetable Coconut Sambar','https://img.spoonacular.com/recipes/716097-556x370.jpg','0.5 teaspoon asafetida, 1 teaspoon brown mustard seeds, 4  cayenne, 2 tablespoons chana dal, 2 tablespoons coconut oil, 3 tablespoons coriander seeds, 1 teaspoon cumin seeds, 1 teaspoon cumin seeds, 1 small handful curry leaves, 1  drumstick, 1 small eggplant, 0.5 teaspoon fenugreek seeds, 0.5 teaspoon fenugreek seeds, 1 handful fresh cilantro, 1 small potato, 2  red bell peppers, 1  red chili, 4 servings sea salt, 2 teaspoons sesame oil, 3  shallots, 0.25 cup tamarind pulp, 0.6666667 cup toor dal, 0.5 teaspoon turmeric, 5 tablespoons unsweetened shredded coconut, 0.25 cup water, 1.5 cups water, 2.5 cups water','To make the paste, heat the oil in frying pan over medium heat. When hot, add the fenugreek seeds, cayenne peppers, asafetida, cumin seeds, coriander seeds and chana dal. Stir and fry for a few minutes until the seeds have darkened a few shades. Remove from heat and transfer the mixture to a food processor or blender along with the coconut and 1/4 cup water. Blend into a paste, adding just a bit more water if necessary. Set aside.In a medium saucepan, combine the toor dal and 2 1/2 cups water. Bring to a boil, cover, reduce the heat to medium-low, and simmer gently for 1 hour until the dal is very soft. Stir occasionally. Do not drain.Meanwhile, soak the tamarind pulp in 1 1/2 cups hot water for 30 minutes. Strain the tamarind liquid into a bowl, squeezing out as much liquid from the pulp as possible. Discard the pulp and set the liquid aside.Heat the coconut oil in a large saucepan over medium heat. When hot, add the mustard seeds, cumin seeds, fenugreek seeds, chili and curry leaves. Stir for 30 to 60 seconds until the mustard seeds turn grey and begin to splutter and pop.Add the shallot and stir for another 2 minutes. Add the vegetables, tamarind juice and salt to taste. Cover and simmer for 10 minutes until the vegetables are tender. Stir in the cooked toor dal and the paste and simmer for another 5 minutes. Add 1/4 to 1/2 cup water if the sambar is too dry. Stir in the fresh cilantro or use as a garnish.',45,45,0);
INSERT INTO "Recipe" VALUES(442,'Roasted Mediterranean Vegetable Soup','https://img.spoonacular.com/recipes/658607-556x370.jpg','3 tablespoons oil, 1 lb tomatoes, 3 large bell peppers., 3  zucchini, 4  garlic cloves, 2  onion, 1 pinch thyme, 6 cups vegetable stock, 0.5 cup non-dairy creamer like mimiccreme, 6 servings salt and pepper, 6 servings basil leaves',replace('Preheat oven to 375 F.\nBrush a large shallow baking dish with olive oil. Laying them cut-sized down, arrange the tomatoes, bell peppers, zucchini and eggplant in one layer (use two dishes if necessary).\nTuck the garlic cloves and onion pieces into the gaps and drizzle the vegetables with the remaining olive oil.\nSeason lightly with salt and pepper and sprinkle with thyme.\nPlace in preheated oven and bake uncovered, for 30-35 minutes, or until soft and browned around the edges.\nLet cool, then scrape out the eggplant flesh and remove the skin from the bell peppers.\nWorking in batches, put the eggplant and bell pepper flesh, together with the tomatoes, zucchini, garlic and onion place into a bowl and chop together using a knife.\nCombine the stock and chopped vegetable mixture in a saucepan and simmer over medium heat for 20-30 minutes, until all the vegetables are tender and the flavors have completely blended.\nStir in the cream and simmer over low heat for about 5 minutes, stirring occasionally until hot.\nTaste and adjust the seasoning if needed. Ladle the soup into warm bowls, garnish with basil and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(443,'Brined Chicken Breast with Sautéed Onion Dipping Sauce','https://img.spoonacular.com/recipes/636118-556x370.jpg','6 servings pepper, 2 lbs chicken breast, 1 tsp cumin, 1  juice of lime, 1 tsp lemon juice, 1 Tbs oregano, 6 servings salt, 3 tablespoons sugar, 1  onion, 3 Tbs vinegar, 3.5 cups water','For the Dipping Sauce:Saut the onion in a tablespoon of olive oil until transparent.  Let the onion cool.Place the onion in a food processor and add the rest of the ingredients.  Give a few good chops until the desired consistency is reached.  Place in a container and refrigerate.For the Chicken Breast:Combine all of the above in a pot; add the chicken and cover in the refrigerator for a few hours or overnight.Remove from the brine and cut the chicken into desired sized pieces.Heat a 10 inch frying pan with 2 tablespoons of olive oil.If the chicken is cut into  to  inch thickness it should take about 6 to 10 minutes over medium heat; turning the chicken pieces occasionally to saut evenly.  Do not overcrowd the pan.Serve with the onion dipping sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(444,'Baked Caramel Custard','https://img.spoonacular.com/recipes/633492-556x370.jpeg','1 cup egg substitute, 1  egg yolk, 1.5 cups evaporated skim milk, 2 teaspoons port wine, 1.5 cups skim milk, 1 cup sugar plus, 2 tablespoons sugar, 2 teaspoons vanilla','Preheat the oven to 350 degrees. Scald the milks together in a heavy saucepan. Remove from the heat.Caramelize the sugar in a skillet over medium heat until it melts and turns brown. Slowly add the milks to the sugar, stirring constantly until the sugar dissolves.In a medium bowl, beat the egg substitute and egg yolk together until it is lemon-colored. Add the milk mixture, port, and vanilla and stir well.Pour the mixture into 6 custard cups and place them into a baking dish. Pour boiling water into the baking dish so that the water comes halfway up the sides of the cups. Place in the oven and bake until set, about 35 to 40 minutes.Remove the custard cups from the oven and cool completely in the refrigerator. When they are chilled, place a dessert plate on top of each custard cup and invert. Serve immediately.This "Recipe" yields 6 servings.Serving size: 1/2 cup.',45,45,0);
INSERT INTO "Recipe" VALUES(445,'Gluten Free Cinnamon Apple Muffins','https://img.spoonacular.com/recipes/644810-556x370.jpg','1 box betty crocker''s cake mix, 3  eggs, 0.5 cup water, 1 tablespoon cinnamon, 1 teaspoon nutmeg, 0.25 teaspoon ground cloves, 0.5 teaspoon lemon juice, 3  granny smith apples, 2 tablespoons agave nectar',replace('Preheat oven to to 350 degrees.\nCore, peel, and chop the apples into small pieces\nIn a medium bowl, combine the apples, cinnamon, nutmeg, cloves, lemon juice, and agave.\nIn a large bowl, add the yellow cake mix, eggs, water, and apples.  Now stir, stir, stir until very well combined.\nLine a muffin tin with baking cups and fill each cup with batter.\nBake 18-23 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(446,'Mini Stuffed Mexican Bell Peppers','https://img.spoonacular.com/recipes/651977-556x370.jpg','20 large bell peppers, 7 oz black beans, 1 TBSP chili powder, 3 oz chipotles in adobo, 7 oz canned tomatoes, 1 tablespoon garlic, 4 oz chilies, 1  tsp ground coriander, 1 TBSP ground cumin, 10 oz ground turkey, 1 TBSP paprika, 3  tomatillos, 0.5  onion','1. Roast the vegetables:  Preheat oven to 400 degrees.Cut the tomatillos in half, slice the onion into 1/2 in slices and remove garlic from covering. Place on baking sheet. Roast till tomatillos are tender and start to brown, about 20 minutes.2. Meanwhile,make the sauce: Add tomatillos, onion, garlic, tomatoes, green chilies, chipotles, chili powder, cumin, paprika, and coriander to blender or food processor. Blend until smooth.3. In a large bowel, add the turkey, beans, and sauce, Mix together until everything is evenly distributed.4. Cut tops off mini bell peppers and remove any seeds. Stuff turkey mixture into peppers until slightly overflowing. Place in 9 by 13 glass dish. Repeat for all bell peppers.5. Cook at 400 for 20 minutes. For the last 5 minutes, turn on the broiler and get some color on the peppers.6. Serve with your favorite salsa (used my Pico De Gallo from my tortilla soup), sour cream and avocado.ENJOY!',45,45,0);
INSERT INTO "Recipe" VALUES(447,'Ginger Snap and Pumpkin Ice Cream Sandwiches',NULL,'2 cups milk, 2.5 cups heavy cream, 1 cup granulated sugar, 0.5 tablespoon cinnamon, 0.5 tablespoon nutmeg, 1 teaspoon ground ginger, 1  cinnamon stick, 0.5 teaspoon kosher salt, 8 large egg yolks, 22.5 ounces pumpkin puree, 0.5 tablespoon vanilla, 2 cups all purpose flour, 1.5 teaspoons baking soda, 2 teaspoons ground cinnamon, 2 teaspoons ground ginger, 1 teaspoon ground nutmeg, 0.125 teaspoon ground pepper, 11 tablespoons butter, 0.6666667 cup granulated sugar, 1 teaspoon vanilla extract, 0.25 cup molasses, 1 large egg',replace('In a medium saucepan over medium heat, combine the milk, cream, granulated sugar, ginger, ground cinnamon, cinnamon stick, nutmeg and salt. Heat the mixture until steaming and it begins to foam.  Remove from the heat.\nIn a small bowl, whisk the egg yolks until pale yellow.  Gradually whisk in one cup of the warm cream mixture, whisking constantly.  Pour the yolks and cream mixture back into the saucepan and cook over low heat, stirring constantly being sure to scrape the bottom and sides of the pan.  Continue cooking until the mixture thickens and coats the back of a spoon.\nPlace some ice and water into a large bowl and place a smaller bowl inside. Pour the cream mixture through a mesh strainer into the bowl.  Stir in the pumpkin and vanilla, add the cinnamon stick back to the mixture. Chill thoroughly, preferably overnight.\nPour the mixture into the freezer can of an electric ice cream maker and freeze according to the manufacturers instructions.\nIn a small bowl, whisk together the dry ingredients.\nIn the bowl of an electric mixer, beat the butter untill soft.  Add the sugar and continue beating until smooth and creamy.  Stop the mixer occassionally to scrape down the sides of the bowl. Stir in the vanilla, molasses and egg, combine thoroughly.  Mix in the dry ingredients gradually until the dough is smooth.\nTurn the dough out onto a lightly floured surface and divide in half. Roll each half until its about 2 inches around, like a log.  Wrap each log in plastic wrap and then roll them lightly to smooth them out.  Refrigerate or freeze until firm.\nPreheat the oven to 350 degrees and line two baking sheets with parchment.\nSlice the dough into 1/4 inch rounds with a serrated knift being careful to keep their shape. Place the rounds on the baking sheet and sprinkle with granulated or course sugar.\nBake for 10-13 minutes, rotating the pans halfway through the baking time.  Let the cookies cool in the pan for about 2 minutes and then transfer to a wire cooling rack.\nDough can be refrigertaed for up to five days or frozen for up to three months.  Baked cookies can be stored in an air-tight container for approximately a week.\nTo assemble the sandwiches:\n(Im sure this is a no-brainer, but.you never know.)\nThaw the ice cream until soft enough to scoop.  Because of the high water content from the pumpkin puree it tends to freeze very firmly.\nTake one scoop of ice cream and place on top of one gingersnap, using a second cookie place on top of the ice cream and gently press down.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(448,'Gambas Al Ajillo','https://img.spoonacular.com/recipes/644140-556x370.jpg','3 slices bacon, 3 tablespoons butter, 0.5 teaspoon cayenne pepper, 1 tablespoon chili powder, 1 cup sherry, 2 tablespoons garlic, 4 servings lemon wedges, 2 tablespoons olive oil, 1 tablespoon paprika, 4 servings parsley, 1 slices rustic bread, 1 teaspoon salt, 1 pound shrimp, 0.5 cup tomato','In a saut pan over medium-high heat, add olive oil. When hot, add shrimp and seasonings, and saut until they are cooked halfway.Add garlic, tomatoes, bacon and saut a bit longer. Add sherry and cook until reduced by half. Add butter and stir in.Sprinkle with parsley and squeeze the lemon wedges over the shrimp. Serve with crusty bread and a crisp white wine like a Verdejo from Rueda or a bubbly Cava from Penedes.',45,45,0);
INSERT INTO "Recipe" VALUES(449,'Crab Cakes Rockefeller','https://img.spoonacular.com/recipes/640279-556x370.jpg','1 pound lump crab claw meat, 0.5  bell pepper, 4  green onions, 1 cup bread crumbs, 4 tablespoons honey, 1 teaspoon chili powder, 1 tablespoon butter, 2 slices bacon, 4 cups baby spinach, 0.25 cup watercress stems, 4 cloves garlic, 6 servings salt & pepper',replace('Preheat your oven to 375F and set the top rack to the middle position (BTW, this "Recipe" is a great toaster oven candidate).  Line a baking sheet with aluminum foil or a nonstick cooking mat.\nIn a large bowl, combine the crab meat, diced red bell pepper, half of the diced green onion (reserving the other half) and half of the bread crumbs (reserving the other half).  Mix in the honey and chili powder, then season to taste with salt and pepper.\nI like to form my crab cakes by pressing them into a 1/2 cup measure, squeezing tightly so theyll hold their shape.  You can mould them with your hands as well, but be sure to press them together tightly or they might fall apart in transit to the plates.  Arrange the crab cakes on the lined baking sheet, leaving at least 1 between each crab cake.\nUsing your olive oil sprayer (if you have one; or by drizzling olive oil) lightly coat the outside of each crab cake.  This will help with browning and to form an outer crust.  Bake at 375F for 25 minutes, or until golden brown.\nMeanwhile, fry the bacon or prosciutto in a large skillet until crispy.  Set aside to drain, then crumble into small pieces using a sharp knife.\nFinely chop the spinach and watercress stems.  In a large skillet, melt the butter over medium heat.  Add the garlic and saut 1 minute.  Then, add the remaining green onion, bread crumbs and watercress stems.  Saut 1 minute more.  Finally, add the chopped spinach and cook until wilted, 1-2 minutes.  Season to taste with salt and pepper.\nTo serve, plate a crab cake atop a smear of the spinach mixture, then sprinkle the whole plate with crumbled bacon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(450,'Buttered Plantain Fries and Seasoned Avocado','https://img.spoonacular.com/recipes/800754-556x370.jpg','1  avocado, 0.5 cup butter, 1 handful chili pepper, 1 clove garlic, 3 servings onions to garnish, 1  plantain, 3 servings salt, 2 tablespoons vegetable oil','Peel and Slice your plantain into thin stripes and set aside.In a pan, pour in your butter and oil and heat slowly.Toss in your plantain and allow to brown on all sides.Mash your avocado, season with salt and stir in your chopped pepper, garlic and onion.Serve as a starter.',45,45,0);
INSERT INTO "Recipe" VALUES(451,'5-Minute Rocky Road Fudge','https://img.spoonacular.com/recipes/631882-556x370.jpg','2 c semi-sweet chocolate chips, 14 oz condensed milk, 1 t vanilla extract, 0.125 t salt, 3 c mini-marshmallows, 1.5 c walnuts',replace('Line a 13x9-inch pan with foil, lightly spray with cooking spray. Set aside.\nIn a large, microwave safe bowl, add chocolate chips and condensed milk. Microwave for about 40 seconds, or until the chips are just melted when you stir them. If needed, continue to microwave in 15 second increments until melted. Do not overcook. Immediately stir in vanilla and salt. Then fold in the marshmallows and nuts.\nWorking quickly, spread and press fudge into the prepared pan. Refrigerate until completely cooled before cutting into squares.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(452,'Peppermint White Chocolate Fudge','https://img.spoonacular.com/recipes/655687-556x370.jpg','2 cups chocolate chips, 12 ounce vanilla frosting, 8 servings food coloring, 0.5 tsp peppermint flavoring, 1 handful peppermint candies',replace('Line an 8X8 pan with plastic wrap or wax paper\nIn a large bowl, melt white chocolate chips by microwaving 30 seconds at a time, stirring between sessions.\nAdd the container of vanilla frosting\nStir well\nAdd Peppermint flavoring and stir well\nReheat for 10 seconds if needed, so the mixture is still soft enough to pour\nPour mixture into lined pan\nPlace 6-8 drops of red food coloring on the top of the warm fudge\nWith a toothpick or knife, swirl the color into the top of the fudge\nSprinkle crushed candies over the top of the fudge\nCool in fridge until hard\nCut and enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(453,'Nachos Grande','https://img.spoonacular.com/recipes/652919-556x370.jpg','400 grams canned tomatoes, 1.5 cups cheddar cheese, 0.5 teaspoon chili powder, 2 tablespoons corn oil, 3  garlic cloves, 0.5  bell pepper, 1  chili, 0.25 teaspoon ground cumin, 1  onion, 1 teaspoon paprika, 4 servings paprika to garnish, 13 oz refried beans, 2 cups tortilla chips, 5 tablespoons water','Heat oil in a skillet, add the onion, green pepper, and garlic, and cook gently, stirring occasionally, for 5 minutes or until soft but not browned.Add the tomatoes and chili and cook over medium heat for 5 minutes, or until most of the liquid has evaporated.Stir in the chili powder and paprika and cook for 3 minutes, then add the refried beans, breaking them up with a fork. Add the measured water and cook, stirring occasionally, for 8-10 minutes, until the mixture thickens.Spoon the beans into the middle of a baking dish, arrange the tortilla chips around the edge and sprinkle with cumin. Sprinkle the cheese over the beans and tortilla chips.Bake at 400 degrees for 15-20 minutes, until the cheese has melted.Sprinkle the paprika for garnish in a lattice pattern on top and serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(454,'Masala-Tofu Burger','https://img.spoonacular.com/recipes/651190-556x370.jpg','1 medium onion- shopping list, 1  red/orange/green bell pepper- shopping list, 1 cup peas-carrots mix shopping list, 4 small chillies shopping list, 0.75 cup tofu - shopping list, 1 medium potato- boils, 2 cloves garlic- shopping list, 0.5 tablespoon mustard seeds shopping list, 5  curry leaves shopping list, 1 pinch hing shopping list, 1 teaspoon cumin powder shopping list, 1 teaspoon turmeric shopping list, 1  lemon shopping list, 1 teaspoon salt shopping list, 0.5 bunch cilantro- washed-finely shopping list, 0.75 cup indian breadcrumbs shopping list, 0.5 tablespoon vegetable oil shopping list, 4 servings pam original flavor shopping list, 1  red/white onion, 2  beefsteak tomatoes, 3 sprigs cilantro shopping list, 0.5 cup mint-cilantro chutney spread shopping list, 4  portugese rolls',replace('In a large skillet over medium-high heat, add spray with a generous amount of PAM and add oil. Add mustard seeds and saute for 30 seconds-till you hear popping noises. Add curry leaves- BE CAREFUL, they pop hot oil! Add onions and peppers- sweat for about 30 seconds. Add chopped garlic, chilies and turmeric. Saute for about 5-7 minutes, until the onions and peppers are soft. Add peas and carrots mixture, cumin powder and salt. Saute for about 7-10 minutes- you want all the veggies to be soft and cooked through.\nMeanwhile in a small bowl, add the cubed tofu, a pinch of turmeric, cumin powder, coarse black pepper and some cayenne pepper (totally optional!). Mix and set aside to marinate for a bit.\nOnce the veggies are cooked, add the tofu- saute until slightly brown and soft enough that it crumbles. Add juice form half a lemon and half of the chopped cilantro. Mix and add the diced boiled potato, and toss until everything is coated, soft and taste for salt/spices. Using a masher, mash the mixture until mushy and until the veggies are small. Set aside to cool. Once cooled, add a bit of the breadcrumbs and mix with your hands. Start forming into thick patties (mixture should make 4). If its still giving you a hard time, add more breadcrumbs. Make 4 patties, place on a plate and wrap with plastic wrap until ready to use.\nIn a small skillet sprayed with PAM over medium-high heat, add one patty at a time. Cook for about 2 minutes on each side- until browned and crispy.At the same time, saute the thick slices of onion, until charred and slightly soft. Spread a generous amount of the chutney spread on each side on the bread, place burger, onions tomato and cilantro leaves. Serve with a slice of lemon and reduced-fat chips on the side.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(455,'Salmon In Banana Leaf','https://img.spoonacular.com/recipes/659083-556x370.jpg','2 large banana leaves, 1 pinch cinnamon, 1 pinch fennel seed, 1 tablespoon fish sauce, 1 clove garlic, 1 piece ginger, 1.5 tablespoons peach preserves, 2 servings chiles, 0.25 cup rice, 0.75 teaspoon rice wine vinegar, 2  steaks salmon, 2  eachs scallions, 6  scallions, 0.75 teaspoon sesame oil, 1.25 teaspoons soy sauce, 1  star anise, 2 tablespoons tahini, 1 tablespoon vegetable oil','Begin by mixing all of your marinade ingredients together and pouring it over the salmon in a big baggy or container. Marinate under refrigeration for at least a half an hour or up to 2 hours.While salmon is marinating, put all of your scented rice powder ingredients into a spice grinder and pulse until everything is coarsely ground. Remember, you want a few larger crumbles of rice for mouth-feel!Remove the salmon from the marinade (discarding any leftover marinade) and coat it with some of the scented rice powder on each side. You won''t use it all with just the 2 pieces of salmon. Save some for another time.Lay your banana leaves out flat. Place one salmon fillet in the center of each leaf. Fold one side over the salmon.Fold the opposite side over that, then both ends to make a little package.Place salmon packets in a steamer basket over boiling water.Put all of the marinade ingredients into a small sauce pot or alternately, a microwave safe dish and bring to a heat. Whisk everything together and it''s ready to serve.After ~10-13 minutes, salmon will be finished. Flip the smooth side of the banana leaves up and make a slit through them to serve....they kinda look like tamales, huh!I served with chinese noodles, corn and the dipping sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(456,'Cheesy Spinach Stuffed Shells','https://img.spoonacular.com/recipes/637683-556x370.jpg','16 jumbo shells, 10 oz spinach, 0.5 cup wheat germ, 0.5 cup parmesan cheese, 0.5 cup pecans, 1 cup mexican cheese, 2  green onions, 8 servings salt, 0.25 teaspoon basil, 2  eggs, 0.33333334 c water, 16 oz alfredo sauce, 28 oz spaghetti sauce',replace('Start by pre-boiling your jumbo shells in a large pot of boiling salted water. You only need to cook them for about 9 minutes. They''ll finish cooking in the oven, later. After the 9 minutes, take them out and drain them face down on a paper towel. You don''t want an excess water in the shell!\nWhile the noodles are cooking, work on your filling. Cook some frozen spinach in the microwave until it''s no longer frozen. I''d recommend following the directions on the box, but don''t add in any water. Once the spinach is cooked, add to the spinach, wheat germ, parmesan cheese, Mexican (the original "Recipe" called for cheddar) shredded cheese, chopped pecans, and finely diced green onions. Mix until combined. Add in salt, a touch of pepper, and dried basil, to taste. I used about  teaspoon of dried basil, but feel free to use as much as you like. The sisters also suggest adding nutmeg, to taste, if you like!\nOnce the mixture is seasoned to your liking, add in two eggs and water and mix again until the eggs have been fully incorporated!\nNow stuff the mixture into each of the shells. You should have enough of the spinach filling to make about 16 - 20 shells. Set these aside.\nTake an 8 x 8 pan (you could also use a 9 x 13) and grease it with cooking spray. Now spread alfredo sauce on the bottom, you''ll use about  of a jar. Spread spaghetti sauce on top of that. Use a spatula to spread it evenly on the bottom of the pan. Top the sauces with the shells. Use the remaining sauce to top the shells.\nBake in a preheated 350 degree oven, uncovered, for about 30 - 35 minutes or until the sauce is bubbly and serve!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(457,'Brown Rice Mushroom Pilaf','https://img.spoonacular.com/recipes/636292-556x370.jpg','1 large onion, 1 cup brown rice, 1 cup mushrooms, 1 tbsp unrefined sunflower oil, 2 cups water, 4 servings sea salt, 0.33333334 tsp ground pepper',replace('Heat oil in a large saucepan over medium heat. Saut chopped onion and sliced mushrooms for 5 minutes.\nAdd brown rice and stir to coat in oil.\nAdd water.\nBring to a boil, then simmer for 30 minutes. Remove from heat and cover with a lid. Let it rest until all liquid is absorbed.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(458,'Vegetarian Chinese Pot Stickers','https://img.spoonacular.com/recipes/664650-556x370.jpg','24  won ton wrappers, 8 oz mushrooms, 1 Tbs soy sauce, 1 tsp sriracha hot sauce, 1 tsp ginger, 1 tsp garlic, 2  scallions, 24 servings little cornstarch, 24 servings little vegetable oil, 1 cup water',replace('Add all of the ingredients (except the wrappers, cornstarch, oil, and water) to the bowl of a food processor. Pulse until the mushrooms are finely minced and all of the ingredients are well combined. It will help if youve given the mushrooms a bit of a rough chop first, or if you use pre-sliced mushrooms.\nPlace a won ton wrapper on your work surface, turned so that it appears to be a diamond shape.\nPlace a teaspoon of filling in the middle of the wrapper.\nDip a fingertip into the bowl of water and trace along the two edges farthest from you. Bring up the end closest to you, fold over the filling, and pinch the edges together to seal. Make sure youve gently pressed the wrapper around the filling so there are no air pockets.\nStand up your little triangle pocket so that the filling side sits on your work surface. Fold the top point down, away from you, and pinch. Now, give the edges on either side of that fold 2 little pleats and pinch. Your pot sticker will now look like it has wings. Place it on a large plate thats been dusted with a bit of cornstarch, to prevent sticking.  (Traditionally, pot stickers are made with round dumpling wrappers, so if you have them, you can skip the part about folding the top point down.)\nHeat the skillet over medium-high heat. Brush just a few drops of oil onto the hot pan surface, and place 12 of the pot stickers, upright, into the pan. Allow the bottoms to brown. Carefully add 1/2 cup water to the pan and cover it quickly. Cook for about 3-4 minutes, or until all of the water has been absorbed. Remove the pot stickers immediately to another plate to keep warm, and repeat the procedure with the rest of the uncooked ones.\n*Feel like you have to have meat? Substitute 4 oz. of ground chicken (or pork, if you must) for half of the mushrooms, just dont run it through the food processor. Mix the processed ingredients with the ground chicken thoroughly and fill the wrappers as before. Add a full cup of water (instead of 1/2 cup) to the pan, and steam until the water evaporates, about 5-6 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(459,'Lentil Mango Salad','https://img.spoonacular.com/recipes/649944-556x370.jpg','1 bunch cilantro, 1 pound lentils, 1 clove garlic, 1  mango, 0.5 cup olive oil, 4 servings bell pepper, 1  bell pepper, 1  onion, 4 servings salt, 0.25 cup white wine vinegar','Clean and chop the onion, red pepper, garlic, CilantroPeel and chop mangoPlace all salad ingredients in a bowl, add the oil, vinegar, season with salt and pepperMix well and leave in the refrigerator for 1 / 2 hourThis salad is left to eat alone or to accompany meat and poultry dishes, enjoy ...',45,45,0);
INSERT INTO "Recipe" VALUES(460,'Brie Bundles with Homemade Fig Jam','https://img.spoonacular.com/recipes/636098-556x370.jpg','1 pkg sheets puff pastry, 6 oz brie log, 9 oz figs, 1  apple juice, 0.5 cup sugar, 1  juice of lemon',replace('Oven at 375 degrees.\nLets make the fabulous fig jam! Into a small saucepan, over low heat, add in the figs, apple juice, sugar and lemon juice. Simmer for 15-20 minutes, until the figs are softened and the mixture has thickened a bit.\nUsing either an immersion blender of food processor, puree the jam until the large pieces of fig are broken down and the jam is relatively smooth but the seeds still visible. Allow the jam to cool.\nUnroll the two sheets of puff pastry out on a piece of parchment and cut into 12 even squares. Place a piece of brie and a small spoonful of the fig jam to the center of each square.\nFold each corner to the center, don''t worry about them all looking exactly the same. Be sure to pinch the edges closed.\nPlace the bundles onto a parchment lined baking sheet. Bake for approx 15-18 minutes or until golden.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(461,'Maple & Curry Acorn Squash','https://img.spoonacular.com/recipes/650871-556x370.jpg','1 large acorn squash, 1 tsp curry powder, 1 Tbs maple syrup, 1 Tbs olive oil, 1 dash salt','Preheat oven to 400 F. Line a baking sheet with parchment paper or a silicone mat.Rinse the outside of the acorn squash and then chop it in half. Seed the squash and chop off the stem. Next, slice it into one-inch wedges. I like use the natural grooves on the squash as a guide for thickness.Place the sliced acorn squash in a medium-sized bowl. Add the rest of the ingredients to the bowl and stir until everything is well incorporated.Lay the acorn squash in a single layer on top of the lined baking sheet, cut side down.Bake for about 15 minutes. Flip the acorn squash slices to the other side so that both sides will be browned equally.Bake the squash for another 10 to 15 minutes or until the pieces can be easily pierced with a fork.',45,45,0);
INSERT INTO "Recipe" VALUES(462,'Appetizing Apple and Almond Soup','https://img.spoonacular.com/recipes/632449-556x370.jpg','8  almonds, 2  apples, 0.5 cup carrots, 0.5 teaspoon cinnamon, 1  gooseberry, 0.25 cup heavy cream, 2 teaspoons salt, 0.25 cup sugar, 2  tomatoes, 3 cups water','Wash and rinse the apples thoroughly. Cut the apples (with their skin) as well as the gooseberry, tomatoes, and carrots roughly into chunks. Soak almonds in warm water and peel off the skin.In a deep bottomed pan or pressure cooker, boil 3 cups of water.Add chopped fruits, veggies, almonds. Let it simmer or pressure cook until 4 whistles.Puree the boiled veggies/fruits in a mixer until smooth.Sieve the soup if desired.Season with salt and sugar to taste.To make the soup creamier, add cream to the soup and simmer for another 5 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(463,'Flax, Quinoa, and Almond Meal Bread','https://img.spoonacular.com/recipes/643091-556x370.jpg','1 cup milled flax seed, 0.6666667 cup blanched almond meal, 0.6666667 cup quinoa flour, 4 teaspoons baking powder, 0.25 teaspoon salt, 2 teaspoons baking soda, 0.25 cup olive oil, 4  eggs, 0.5 cup water to texture desired',replace('Preheat oven to 375F\nMix dry ingredients together.  Gently beat eggs together before adding to dry mixture.  Add oil.  (I had my coconut oil in a mixing cup and added the eggs to mix together but the coldness of the eggs turned the oil solid, it was difficult to mix the solid oil in the batter.\nAdd water a little at a time until you get the desired consistency to pour thickly into your loaf pan.\nI used a Pyrex bread pan with parchment paper, cooked at 375F for 40 mins.  If you use a metal pan you will have to adjust time.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(464,'Vegetarian Scotch Eggs','https://img.spoonacular.com/recipes/664697-556x370.jpg','4 handfuls breadcrumbs, 1  dessert spoon chives, 5 medium eggs, 1  dessert spoon flat leaf parsley, 4 servings salt and pepper, 4 servings vegetable oil','Preheat the oven to 325F/170C.Place 4 of the eggs in a pan and cover completely with cold water.Bring to the boil then reduce the heat and simmer for 4 minutes.Cool in cold water before peeling.Whisk the remaining egg.Combine the chopped herbs with the breadcrumbs and season.Gently roll each boiled egg in flour, then the egg mixture then the breadcrumbs.Put the oil in a pan to a depth of 2 inches/5 cm and heat.Fry the eggs until golden, turning occasionally so as not to burn - about 2-3 minutes.Remove the eggs with a slotted spoon and place in the oven in an ovenproof dish to heat through for about 3-4 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(465,'Crumbled Feta Couscous Salad','https://img.spoonacular.com/recipes/640927-556x370.jpg','1 cup couscous, 1 cup vegetable stock, 2 tablespoons quality olive oil, 0.25 teaspoon salt, 1  roma tomato, 0.5 cup onion, 1 teaspoon mint, 1 tablespoon parsley, 2 tablespoons balsamic vinegar, 4 oz feta cheese',replace('In a medium sauce pan bring water or vegetable stock to a boil then add couscous stirring quickly. Remove from the heat and cover, let stand for 4-5 minutes.\nRemove the lid and stir in the olive oil. Pour cooked couscous in a large bowl to chill, stir occasionally. When cooled stir in remaining ingredients and chill completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(466,'Lemon Drop Jello Shots','https://img.spoonacular.com/recipes/649625-556x370.jpg','6  lemons, 3 oz lemon jello, 3 tablespoons sugar, 1 cup water, 0.5 cup lemon juice, 0.5 cup lemon vodka',replace('Empty out the citrus to create a vessel.  Juice the citrus first as it makes it easier for pulp removal.  Reserve juice.\nHallow out the citrus by turning them inside out and take out the pith and membrane.\nMake jello according to "Recipe" above.\nPlace citrus cups into muffin pan holes.  Pour in jello.\nChill overnight - Use a sharp, straight edge knife to cut into wedges','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(467,'Navajo Fry Bread By Mommie Cooks','https://img.spoonacular.com/recipes/652980-556x370.jpg','1  pd sausage, 1 bunch cilantro, 0.5  onion, 1 teaspoon cumin, 1 teaspoon chili powder, 1 teaspoon oregano, 1 tablespoon water, 1 tablespoon tomato paste, 6 servings oil, 1 teaspoon corriander, 1 teaspoon corriander',replace('For the fry bread dough, mix together all the listed ingredients; the flour, milk, baking powder, and salt.\nAllow the bread to rest for at least 10 minutes.\nWhile the dough is resting, grab a frying pan and start cooking up the meat for a minute or two.\nAdd to the meat the garlic, cilantro, and onion.\nCook the meat all the way through and then add in the cumin, chili powder, and oregano\nMix it up well and then add in the water and tomato paste\nStir it all together and turn the heat down to low to keep warm\nGrab a clean frying pan and pour enough oil in the bottom to create about a 1" depth of oil. Turn the heat on medium high and allow it to heat up.\nWhile the oil is heating, take your rested dough ball, rip of a chunk and roll it out thin with a rolling pin.\nDrop the rolled bread into the hot oil and allow it to cook up for about a minute on each side or until gold brown.\nServe meat on top of bread along with additional desired toppings.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(468,'Alouette Sundried Tomato and Basil Bisque','https://img.spoonacular.com/recipes/632250-556x370.jpg','1 inch bacon, 1 can all natural tomato soup, 1 cup vegetable stock, 6.5 oz alouette all natural sundried tomato and basil spreadable cheese',replace('Saut bacon in heavy gauge sauce pot until crispy\nDrain fat from sauce pot\nAdd Tomato soup and vegetable stock and bring to a boil\nAdd Alouette Sundried Tomato and Basil soft cheese\nBring back to a boil and serve','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(469,'Butternut Squash Frittata','https://img.spoonacular.com/recipes/636589-556x370.jpg','1 large butternut squash, 0.5 oz goat cheese, 0.5 cup liquid egg substitute, 2 tbsp non-fat milk, 1 serving bell pepper','Preheat oven to 350Spray a 10 oz oven safe dish with cooking sprayAdd your butternut squashIn a measuring cup add your eggs and milk. Mix until combined. Pour over butternut squash.Sprinkle with pepper and top with cheese.Bake in oven for 30-35 minutes, until middle is slightly firmLet it cool for a few minutes',45,45,0);
INSERT INTO "Recipe" VALUES(470,'Crock Pot Chicken Pot Pie','https://img.spoonacular.com/recipes/640862-556x370.jpg','4  chicken breasts, 1 large can condensed cream of chicken soup, 4 medium potatoes, 2.5 cups vegetables - we prefer peas and carrots, 20 servings salt and pepper, 4  pie crusts, 1  egg white',replace('In Crock Pot, combine chicken breasts, potatoes, frozen vegetables, cream of chicken soup and mix well. Add additional salt and pepper if desired.\nCook on low for 6-8 hours until chicken is fully cooked. Use a sturdy spoon to break up the chicken after cooking. Preheat oven to 400. Prepare pie crusts. Spoon chicken filling into pie crust.\nTop with pie crust. Cut slits into the top crust to vent steam during baking. Cut excess crust from edges and pinch to seal.\nBrush with egg white or melted butter and bake for 20-30 minutes until crust is fully cooked and golden brown on top.\nAllow pies to cool for at least 10 minutes before cutting. Best served hot.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(471,'Hyderabadi baghara Baingan','https://img.spoonacular.com/recipes/647679-556x370.jpg','4 servings baby eggplants- 10-12, 4 servings kashmiri chilies- 3-4, 3 tbsp coconut, 1 tbsp coriander seeds, 1 tsp cumin seeds, 4 servings curry leaves- 8-10, 2 cloves garlic, 1 piece ginger- 1, 4 servings tamarind- a lime sized, 1 tsp oil, 1 large onion, 4 servings salt, 0.5 tsp nigella seeds, 1 tsp sesame seeds, 0.25 tsp turmeric, 2 tsp jaggeryns, 2 tbsp peanutsns, 2 tbsps cashewnuts, 2 tbsps cashewnuts','Wash the eggplants and pat them dry. Slit the eggplants length wise into fours but keep the stems intact. This way, the egg plants remain joined at the stem. Keep aside.Heat a tspn of oil in a separate pan and add the cumin seeds, peanuts and cashew nuts and fry for a few seconds. Add ginger, garlic and chopped onion and fry for a min. Add the turmeric, coriander seeds, coconut and Kashmiri red chilies and fry till the mixture is brown. Allow the mixture to cool completely and blend to a fine paste using a little water and keep aside.Heat oil in a thick bottomed pan and fry the egg plants till brown and tender, remove and keep aside.Add the nigella seeds to the same oil and allow them to crackle. Stir in the curry leaves and fry for a few seconds. Add the ground paste, tamarind pulp, salt and jaggery and mix well.Add the sauted egg plants and 1/2 cup of water and cook covered over low heat till the egg plants are cooked through and soft.Serve the curry hot with either rice or rot is.',45,45,0);
INSERT INTO "Recipe" VALUES(472,'Gluten Free Yellow Cake And Cupcakes','https://img.spoonacular.com/recipes/644861-556x370.jpg','0.5 cup coconut flour, 0.75 cup tapioca flour, 1 teaspoon salt, 1 teaspoon baking soda, 3 teaspoons baking powder, 1 teaspoon xanthan gum, 4  eggs, 1.25 cups sugar, 0.6666667 cup veganaise, 0.75 cup milk alternative, 2 teaspoons vanilla extract, 1 cup earth balance butter, 2 cups dairy free chocolate chips, 2 pinch salt, 4 tablespoons powdered sugar',replace('Preheat oven to 350 degrees. Grease two 8 or 9 inch round cake pans and sprinkle with tapioca flour if youre making a layer cake. Otherwise, line a muffin tin with baking cups.\nMix together the coconut flour, tapioca flour, salt, xanthan gum, baking soda, and baking powder. Set aside.\nBeat the eggs, sugar, and mayonnaise until fluffy.\nThen slowly add the vanilla, flour mixture, and milk. Alternating between the flour and milk to make a nice fluffy cake. Note- I usually use just barely under 3/4 C of the milk alternative.\nPour the batter into the greased cake pans or fill the baking cups 3/4 full (makes 24 cupcakes).\nBake for 20-25 minutes for the cakes or 12-15 minutes for the cupcakes. Cakes are done when they are nicely browned and spring back when lightly touched or when a toothpick inserted in center comes out clean. Let cool completely before icing.\nFor The Icing:\nBring a small saucepan of water to a boil. Place a heatproof bowl over the saucepan (make sure the water isnt touching the bottom) and add the chocolate and butter.\nStir until melted. Then, add the remaining ingredients.\nPlace uncovered in freezer for 15 minutes.\nBeat with hand mixer until light and fluffy. If its too runny, place back in freezer a few minutes and repeat process until the icing is a good consistency.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(473,'Roasted Beet Hummus','https://img.spoonacular.com/recipes/658503-556x370.jpg','1 medium roasted beets, 1 cup chickpeas, 2 cloves garlic, 1 teaspoon ground cumin, 1  juice of lemon, 10 servings olive oil, 10 servings salt, 0.25 cup tahini sesame seed paste','Place all ingredients except for the chickpeas and olive oil in a food processor or blender.Pulse until well blended.Add the chickpeas and olive oil and pulse until just incorporated.Add more olive oil as necessary for blending the chickpeas into a paste, or to thin out the hummus to a thinner consistency.Serve with warm pita or flat bread.',45,45,0);
INSERT INTO "Recipe" VALUES(474,'Smoked Salmon Eggs Benedict With Lemon Dill Hollandaise','https://img.spoonacular.com/recipes/660368-556x370.jpg','1 cup baby arugula, 1 cup baby spinach, 2 tablespoons butter, 3 large egg yolks, 4  eggs, 1 tablespoon dill, 1  lemon, 2 slices multigrain bread, 2 servings salt and pepper, 8 ounces salmon, 2 tablespoons water, 1 tsp worcestershire sauce','Make Lemon Dill Hollandaise:Fill a medium saucepan about halfway with water, and bring to a gentle simmer over medium heat. Put the egg yolks and water in a heatproof bowl, season with a pinch of dill (if using dried), salt, and pepper. Whisk the ingredients together and then place the bowl on top of the saucepan. Keep stirring the egg mixture for about 5 minutes or until it begins to thicken. Make sure you dont scramble your eggs! Once the eggs are thickened, take the bowl off the water and set aside.Poach the eggs:Fill a medium saucepan with water, add a splash of white vinegar (optional, but this helps hold the whites together which results in nicely shaped eggs) and bring to a gentle simmer. You want tiny bubbles only, not a rolling boil. Gently add eggs to water and poach until deisred doneness.Meanwhile, toast bread.Place toast on plates and top with arugula, spinach and salmon. Place eggs on top of salmon and spoon hollandaise over the top. Garnish with dill, salt and freshly cracked black pepper and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(475,'5-Minute Rocky Road Fudge','https://img.spoonacular.com/recipes/631882-556x370.jpg','2 c semi-sweet chocolate chips, 14 oz condensed milk, 1 t vanilla extract, 0.125 t salt, 3 c mini-marshmallows, 1.5 c walnuts',replace('Line a 13x9-inch pan with foil, lightly spray with cooking spray. Set aside.\nIn a large, microwave safe bowl, add chocolate chips and condensed milk. Microwave for about 40 seconds, or until the chips are just melted when you stir them. If needed, continue to microwave in 15 second increments until melted. Do not overcook. Immediately stir in vanilla and salt. Then fold in the marshmallows and nuts.\nWorking quickly, spread and press fudge into the prepared pan. Refrigerate until completely cooled before cutting into squares.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(476,'Easy Slow Cooker Artichoke Garlic Chicken','https://img.spoonacular.com/recipes/642093-556x370.jpg','1  bell pepper, 1  onion, 6  garlic cloves, 1 tsp rosemary, 1 tsp cooking tapioca, 0.5 tsp lemon zest, 0.25 Cup chicken broth, 1.5 Lbs chicken thighs, 14 oz cut artichoke hearts, 1 tsp lemon juice, 2 servings salt & pepper, 2 servings rigatoni pasta',replace('Chop, mince and dice all veggies & spices.\n Combine bell pepper, onion, garlic, tapioca, rosemary, lemon zest, artichokes, chicken thighs, salt and pepper in crockpot.\n Pour broth and lemon juice over mixture.\n Cover and cook on low for 5 hours- You really dont need to check on this but every once and a while maybe give it a little stir.\n Once chicken is cooked through, cook pasta.\n Serve over pasta top with fresh shaved parmesan\n ENJOY!!!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(477,'Magic Cookie Bars','https://img.spoonacular.com/recipes/650620-556x370.jpg','1 cup chocolate chips, 4.5 cups graham cracker crumbs, 42 oz condensed milk, 4.5 cups coconut, 1.5 cups butter, 2 cups walnuts','Preheat oven to 325 degreesIn a large bowl, combine the graham cracker crumbs with the melted butter. Press firmly into an ungreased 12 x 18" jelly roll panSprinkle the walnuts, chocolate chips, and shredded coconut over the graham cracker crustPour the three cans of condensed milk over everything evenly, making sure to completely cover the coconut. Use a spatula to spread if neededBake for 30-35 minutes, or until lightly goldenCool to room temperature, or overnight, before cutting and serving',45,45,0);
INSERT INTO "Recipe" VALUES(478,'Avocado Egg Salad','https://img.spoonacular.com/recipes/716245-556x370.jpg','0.25 teaspoons pepper, 2  eggs, 0.5  seasoning cube, 0.25  lemon, 1  avocado pear, 1  scotch bonnet pepper, 2 slices bread','Boil your eggs and immerse in water to cool.Peel your avocado and mash in a bowl.Squirt your lemon over the avocado.Peel the eggs, chop and mix with the avocado.Mix the black pepper, seasoning and scotch bonnet pepper and set aside.Toast your bread and roll out with a rolling pin, cut the edges off and serve the avocado egg salad on the bread.',45,45,0);
INSERT INTO "Recipe" VALUES(479,'Eggs Florentine','https://img.spoonacular.com/recipes/642332-556x370.jpg','0.25 cup butter, 4 servings cayenne pepper, 11  eggs, 4  muffins, 4 servings kosher salt, 2 Tablespoons lemon juice, 10 ounces spinach, 4 Tablespoons water','Saute spinach in a saute panPoach 8 eggs and toast muffins. Top each muffin with spinach, then a poached egg.To make the hollandaise sauce, melt the butter and keep it warm, but not hot. Heat the lemon juice until just warmed. Have small saucepan with boiling water and a measuring tablespoon ready.Place the top of a double boiler over hot water. Place 3 egg yolks in the top of a double boiler and whisk until they begin to thicken. Now add 1 tablespoon of the boiling water. Continue to beat the sauce until it begins to thicken. Repeat with the remaining water, one tablespoon at a time, beating the mixture after each addition.Now add the warmed lemon juice. Remove the double boiler from the heat. Beat the sauce briskly with a wire whisk. Continue to beat the mixture as you slowly pour in the melted butter. Add the salt and cayenne and beat the sauce until it is thick. Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(480,'Vanilla Bean Melting Moment Cookies With Caramel Filling','https://img.spoonacular.com/recipes/664288-556x370.jpg','6 ounces butter, 0.25 cup powdered sugar, 2 teaspoons vanilla bean paste, 1 cup ap flour, 0.25 cup cornstarch, 14 oz condensed milk, 3.5 ounces butter, 2 tablespoons golden syrup',replace('Preheat oven to 350 degrees\nPlace the butter, powdered sugar and vanilla in a bowl and beat with an electric mixer until light and fluffy.\nStir in the sifted flour and cornstarch until combined.\nPlace the mixture in a piping bag fitted with a fluted tip. Pipe 1in rounds onto a baking sheet linded with parchment paper, allowing room to spread.\nBake for 12 - 14 minutes or until golden. Cool on a tray (not on a rack, that will make it hard to pick up the delicate cookie).\nPlace all ingredients in a sauce pan and turn on very low heat.\nStir for 25-30 minutes or until thick and pale golden. Allow to cool. Eat with a big spoon.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(481,'Slow Cooker Ranch Chicken','https://img.spoonacular.com/recipes/1165783-556x370.jpg','2 large chicken breasts, 8 oz cream cheese, 2 cups chicken broth, 3 tbsp ranch seasoning',replace('Instructions\n\nAdd two cups of chicken broth to the bottom of the slow cooker.\n\nPlace chicken breasts in the bottom of the Crock Pot.\n\nCook on high for 3 hours.\n\nRemove chicken breasts and shred. Place back into the slow cooker.\n\nAdd cream cheese and mix until creamy.','\n',chr(10)),185,185,0);
INSERT INTO "Recipe" VALUES(482,'Easy Garlic Roast Leg Of Lamb With Rosemary and Parsley','https://img.spoonacular.com/recipes/641973-556x370.jpg','8 lbs leg of lamb, 5  garlic cloves, 8 servings extra virgin olive oil, 1 cup flat leaf parsley, 1 tablespoon rosemary, 1 tablespoon kosher salt, 8 servings pepper',replace('With the tip of a small sharp knife, poke holes in the leg of lamb about 1 1/2-inch deep. Into each hole, stuff one slice of garlic.\nRub the leg of lamb all over with olive oil, parsley and rosemary. Season well with Kosher salt and black pepper.\nHeat oven to 425 degrees. Place lamb in a roasting pan; roast 30 minutes. Reduce heat to 325 degrees, and baste the leg with any juices that have accumulated in the pan. Cook about 2 hours (total cooking time is about 20 minutes per pound), until an instant-read thermometer registers 130 degrees (medium) in the thickest part. Remove roast from oven and allow to rest 15 minutes.\nTransfer roast to a cutting board and let rest for 10 minutes.\nCarve in thin slices, parallel to the bone and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(483,'Strawberry-Mango Quinoa Salad','https://img.spoonacular.com/recipes/661925-556x370.jpg','0.75 cup cucumber, 2 tablespoons mint, 1 T honey, 2 T lime juice, 0.5 t lime zest, 0.5  mango, 0.25 c olive oil, 4 servings bell pepper, 1 c quinoa, 4 servings salt, 1 T cream, 1.5 cups strawberries, 1.5 c water','Prepare the quinoa: In a medium saucepan combine the quinoa, water and 1/4 t. salt. Bring to a boil, reduce heat to low, cover and simmer until the liquid is just absorbed, about 15 minutes. Spread the cooked quinoa out on a baking sheet to cool for about 20 minutes.In a large bowl whisk together lime juice, zest, honey, sour cream and olive oil. Add the cooled quinoa, strawberries, mango, cucumber and mint. Toss well to combine and season with salt &amp; pepper. Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(484,'Summer Veggie Bake','https://img.spoonacular.com/recipes/662263-556x370.jpg','2  ears of corn, 1 tsp garlic powder, 1  juice of lemon, 1 cup milk, 1.5 cups chicken broth, 1 tsp onion powder, 1 cup orzo, 0.5 cup panko, 1 tsp paprika, 0.25 cup parmesan cheese, 0.25 cup parsley, 1 tsp pepper, 1  rotisserie chicken, 0.25 cup mozzarella cheese, 3  tomatoes, 8 oz zucchini','Preheat the oven to 400 degrees Fahrenheit. In a medium saucepan, add milk and chicken broth and bring to a boil. Add orzo and reduce to medium heat. Cook orzo until tender and liquid is absorbed, about 15 min.Meanwhile, mix chicken, cheese, spices, lemon, corn and parsley. Add mixture to the orzo and stir until evenly distributed.Pour out orzo mixture into a 8 by 8 glass baking dish. For the topping, layer zucchini and tomato, alternating each veggie.Sprinkle panko, garlic powder and pepper over the veggies.Spray the panko evenly with olive oil cooking spray.Place in oven and cook for 40 minutes. Then broil for about 2 minutes to get the top really golden brown.Serve immediately. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(485,'Parmesan Polenta','https://img.spoonacular.com/recipes/654681-556x370.jpg','1 serving pepper, 1 cup chicken broth, 24 oz polenta, 1 cup parmesan cheese','Cut polenta into large pieces and heat with broth in medium saucepan over medium-low heat about 5 minutes, mashing and stirring polenta as it cooks until smooth. Add cheese and stir until melted, about 1 minute. Season to taste with pepper.This "Recipe" yields 6 servings.',45,45,0);
INSERT INTO "Recipe" VALUES(486,'Tomato Cucumber Salad','https://img.spoonacular.com/recipes/663587-556x370.jpg','250 grams cherry tomatoes, 150 grams cucumber, 1 clove garlic, 1 tablespoon lemon juice, 2 tablespoons olive oil, 2 servings salt and pepper, 1  shallot, 1 tablespoon parley, 1 tablespoon parley','Heat the olive oil in a skillet. Add in the chopped shallot and sliced garlic. Stir-fry for over medium heat until lightly golden. Remove from the heat and stir in lemon juice. Season with salt and pepper.Cut the cherry tomatoes into halves and the cucumber to 1cm dices.  Transfer them into a salad bowl. Pour in the dressing and parsley. Toss gently and chill for an hour before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(487,'Panna Cotta with Raspberry and Orange Sauce','https://img.spoonacular.com/recipes/654571-556x370.jpg','4 cups half and half, 0.5 cup mascarpone, 0.5 cup sugar, 1.5 teaspoons vanilla, 1 tablespoon powdered gelatin, 1  orange zest, 2 cups raspberries, 2 teaspoons orange juice, 1 tablespoons confectioners sugar',replace('Spray 6 ramekins or juice glasses with the nonstick cooking spray.\nAdd the half and half to a saucepan over low-medium heat (dont let the mixture get too hot or come to a boil).\nWhen warm, sprinkle the gelatin over the mixture, and stir it to dissolve it.\nAdd the mascarpone and stir until melted.\nAdd the sugar, orange zest and vanilla, and stir until the sugar is dissolved.\nRemove from the heat and let it stand for about 5 minutes.\nPour the mixture evenly into the ramekins or glasses.\nCover and refrigerate for at least four hours, but ideally overnight.\nMeanwhile, put the raspberries in a bowl and press them softly with a fork to produce some juice.\nAdd the orange juice and confectioners sugar and mix together. Keep the berry mixture refrigerated until youre ready to serve the panna cotta.\nWhen the panna cotta has set, move a knife around the edges of the ramekin or glasses to loosen it, and gently shake each onto individual plates.\nDrizzle the berry mixture over each serving.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(488,'Honeyed Bacon" Baklava','https://img.spoonacular.com/recipes/631783-556x370.jpg','16 ounce walnuts, 0.5 cup sugar, 1 teaspoon ground cinnamon, 16 ounce phyllo, 1 cup butter, 12 ounce honey, 16 ounce bacon',replace('In large bowl of food processor, add walnuts, bacon, sugar, and cinnamon. Pulse until walnuts and bacon are chopped; set aside. (Be sure to fry the bacon to a crispy stage. Then it will chop up finely and evenly.)\nCut phyllo into 13" by 9" rectangles. In greased 13" by 9" baking dish, place 1 phyllo sheet; brush with melted butter. Repeat with phyllo and butter to make 5 more layers, overlapping any small strips of phyllo to make rectangles, if necessary.\nOver phyllo in baking dish, sprinkle 1 cup walnut mixture.\nRepeat steps 2 and 3 to make 3 more layers (4 layers total). Place remaining phyllo on top of last walnut layer; brush with butter.\nWith sharp knife, cut just halfway through layers in triangle or diamond pattern.\nBake in 300 degree oven for 1 hour and 25 minutes or until top is golden brown.\nIn small saucepan over medium-low heat, heat honey until hot but not boiling. Evenly spoon hot honey over hot baklava.\nCool Baklava in dish on wire rack at least 1 hour; cover with foil and let stand at room temperature until serving.\nTo serve, finish cutting, with a sharp knife, through layers to make triangles or diamonds.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(489,'Cinnamon Rolls by Bing','https://img.spoonacular.com/recipes/639482-556x370.jpg','4 cups milk, 1 cup vegetable oil, 1 cup sugar, 16 g active yeast, 9 cups flour, 1 teaspoon baking powder, 1 teaspoon baking soda, 2 teaspoons salt, 3 cups butter, 1 cup caster sugar, 1 cup brown sugar, 0.25 cup ground cinnamon, 2 cups pecan nuts, 0.25 cup strong coffee, 1 tablespoon quality honey, 6 tablespoons butter, 1 pinch salt, 2 cups icing sugar, 2 tablespoons cream',replace('Begin by pouring 4 C of whole milk into a large cooking pot. Add 1 C of sugar. Add 1 C of vegetable oil. Heat it over a medium flame and stir till sugar has dissolved. Do NOT boil.\nSet the mixture aside to cool till lukewarm. About 38 deg C. Check with your finger right into the mixture. If its hot, then cool some more. I should be just very mildly comfortably warm to the touch.\nWhen the mixture is lukewarm, add 2 packets of instant dry yeast (about 16g, 4.5 teaspoons). Sprinkle the yeast on the surface of the mixture. Leave it for 3 to 5 minutes. If the yeast is fresh and alive, you will see it growing and poofing up.\nAdd 8 C of plain flour. Mix it all up together. Dont overmix.\nCover with a table cloth and set aside covered in a warm place for 1 hour.\nAfter an hour, the dough would have risen to twice its size. Punch the dough down. Add the last C of flour.\nAdd 1 heaping teaspoon of baking powder.\nAdd 1 scant teaspoon of baking soda.\nAdd 2 teaspoons of salt.\nMix it up. Cover the dough again. And this time, either leave it in a warm place again for 1 hour. Or leave it covered in the fridge for 3 hours to rise slowly.\nNote: I left it in the fridge for 3 hours. The dough may be easier to manage when left to rise this way instead as it will be colder and harder.\nAfter the mentioned time, the dough would have risen again. Punch it down.\nKnead the dough for a few moments and then transfer the dough to the working table that has been lightly floured.\nIf the dough is too wet at this stage. Chill it in the fridge for a while. Itll help.\nFlour a rolling pin. And roll out the dough into a huge long rectangle.\nCut the dough into 2 parts. So that there are two long pieces of dough.\nPour 2 cups of melted butter onto the rolled out dough.\nNote: Check your dough. If its VERY wet, reduce the amount of melted butter added at this stage. When the rolls are laid out in the pan later, pour the rest of the melted butter on them instead. I really prefer to add all the melted butter at this stage because the flavour goes right into the dough.\nUsing fingers, evenly distribute the butter.\nSprinkle 1/4 cup of cinnamon over the dough.\nSprinkle 1 cup of castor sugar over the dough.\nSprinkle 1 cup of brown sugar over the dough. As brown sugar gets clumpy. I scattered the sugar on the dough with my fingers.\nChop some pecan nuts to get about 2 cups worth of chopped pecans.\nSprinkle the chopped pecan nuts onto the rolled dough.\nRoll up the dough, lengthwise. It will be a really long roll. If the dough is very wet and you are struggling to roll it, add some flour to the surfaces to help you roll.\nCut into 1 inch thick rolls.\nRub pans or baking dishes generously with more melted butter. Place the cinnamon rolls comfortably in each pan/dish. Do not overcrowd as they will expand alot in the pan. Pour remaining butter over the rolls. Dont be afraid!\nSet them aside for 1 hour. If theres wind/draft in your kitchen, cover the rolls with table cloths. The rolls will rise some more.\nPop the rolls into a oven, preheated at 180 deg Celsius. Bake for 15 to 17 minutes.\nWhile the rolls are baking, make the icing. Dont get stressed about the proportions. Just mix the ingredients till you get a gooey consistency to pour over like syrup.\nMake a 1/4 cup of strong coffee with 1/4 cup water and one 3-in-1 coffee mix.\nAdd 1 tablespoon of the best honey you can get your hands on. Maple syrup works too.\nStir the honey into the coffee.\nAdd a pinch of salt.\nAdd 6 tablespoons of melted butter.\nAdd 2 cups of icing sugar.\nWhisk it all up.\nAdd 1 to 2 tablespoons of fresh cream.\nStir in the cream.\nPour the icing over the rolls while they are still hot.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(490,'Grilled Garlicky-Herbed Shrimp','https://img.spoonacular.com/recipes/645721-556x370.jpg','1 teaspoon chili pepper flakes, 0.33333334 cup extra virgin olive oil, 3 tablespoons coriander leaves, 4 servings garlic, 20 jumbo shrimp, 1 tablespoon lemon zest, 3 tablespoons parsley','Combine all ingredients except shrimp in a large bowl. Add shrimp and toss to combine making sure all parts of the shrimp is coated in the marinade. Refrigerate 4 hours or overnight. Preheat grill on medium heat. Place shrimp on grill and cook, turning once, until pink  about 5 minutes.The Culinary Chases Note: Want a Mediterranean feel?  Serve the shrimp with a roasted red pepper salad. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(491,'Mango Salsa','https://img.spoonacular.com/recipes/716290-556x370.jpg','1 handful cherry tomatoes, 0.5  bell pepper, 1 tablespoon lime juice, 2  mangoes, 3 leaves mint leaves, 0.5  bell pepper, 2 handfuls onions, 1 pinch sugar','Peel and chop your mango into small cubesCube your bell peppers and onions as well and mix in with the mangoes. Add the cherry tomatoes and mix in.sprinkle your sugar and lime juice over it.Chop your scent/mint leaves and mix in and refrigerate.Serve cool as a side dish or if you want something refreshing on a hot day.',45,45,0);
INSERT INTO "Recipe" VALUES(492,'Eggplant and Tomato Sauce','https://img.spoonacular.com/recipes/642276-556x370.jpg','1  eggplant, 28 oz canned tomatoes, 1  onion, 3 large cloves garlic, 1 pint grape tomatoes, 1 tablespoon lemon juice, 2 tsp salt, 1 tsp ground pepper, 0.25 tsp bell pepper, 1 tsp oregano, 0.5 cup basil, 0.25 cup red wine, 1 lb favorite macaroni, 6 servings romano cheese, 6 servings olive oil',replace('Place the cut eggplant, chopped garlic, sliced onion and halved tomatoes in a bowl.  Add 2 tablespoons of olive oil, lemon juice, 1 tsp. of salt and  tsp. of ground black pepper and toss.\nHeat a large frying pan with 2 tablespoons of olive oil add the eggplant mix to the frying pan.  Saut until the eggplant is softened. Add the crushed tomatoes, red pepper flakes, dried oregano,  tsp. ground black pepper and 1 tsp. salt and continue to simmer on low.\nAdd the wine and simmer on low for about 30-35 minutes. The longer it cooks the better.\nPrepare the macaroni as directed.\nDrizzle a little olive oil at the bottom of a large bowl.\nAdd a few dashes of red pepper flakes, dashes of dried oregano, grated Romano cheese and some fresh basil.\nAdd the cooked macaroni and toss.\nAdd the eggplant sauce and toss again; finish with more grated cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(493,'Elk Sliders With Pancetta Bacon and Smoked Mozzarella','https://img.spoonacular.com/recipes/642373-556x370.jpg','1 cup bread crumbs, 8 servings cherry tomatoes, 1  egg, 1 tablespoon garlic powder, 1 pound ground elk meat, 8 servings hawaiian rolls, 8 servings mozzarella, 8 servings pancetta, 8 servings salt and pepper, 1 tablespoon steak sauce, 2 tablespoons grain mustard, 1 tablespoon worcestershire','In a large bowl, add mustard, bread crumbs, egg, garlic powder, salt and pepper to ground elk meat. Mix all ingredients by hand and then form into small patties. Use a  cup measuring cup to size how much meat to use when forming your patties.  Place meat on tinfoil and press gently with your thumb creating a small indent in the center. This will help keep patties from shrinking when cooking.Pre-heat the barbecue to high temperature.I recommend leaving the elk burgers on the tinfoil while cooking on the BBQ. The elk meat is very lean and can have the tendency to dry out if overcooked. Cooking on tinfoil reduces the risk of overcooking.Cook 7 minutes or until brown and then flip patties. Continue cooking on other side until brown  7 minutes. Add smoked mozzarella cheese to the top of burgers during the last 2 minutes of cooking. Close lid and melt cheese.While cooking your burgers, place pancetta bacon slices on tinfoil and place on the barbeque for the last few minutes of cooking. Toast buns on grill.Place elk sliders on Hawaiian Sweet Rolls, top with a slice of pancetta bacon and a few cherry tomatoes and you are set! Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(494,'Lentil Salad With Vegetables','https://img.spoonacular.com/recipes/649931-556x370.jpg','2 teaspoons balsamic vinegar, 3 tablespoons extra virgin olive oil, 4  green onions, 1 cup lentils, 4 servings bell pepper, 1  bell pepper, 2 teaspoons red wine vinegar, 1 tablespoon rosemary, 4 servings salt, 2  tomatoes, 1  onion','Heat olive oil in a saucepan over medium high heat and add onion. Cook until just translucent and then add lentils. Add water and cook according to package directions. Drain and cool.Combine lentils with tomatoes, pepper, onions, rosemary, olive oil, and vinegars. Season with salt and pepper to taste and adjust oil or vinegar as desired.Serve cold or at room temperature.',45,45,0);
INSERT INTO "Recipe" VALUES(495,'The Best Mashed Potatoes','https://img.spoonacular.com/recipes/1022743-556x370.jpg','0.5 stick butter, 8 oz cream cheese, 1 bunch green onions, 0.5 cup milk, 1 bag potatoes, 8 servings salt and pepper, 0.5 cup cream, 2 cups water','InstructionsTake the uncooked red potatoes and place them into the Instant Pot. Cover with 2 cups of water, or more if needed. Place the lid securely into place, set the valve to "seal" and then put the Instant Pot on manual for 8 minutes.When the cooking time is finished, allow the Instant Pot to naturally release pressure for 10 minutes before moving the valve t0 "vent". I always cover mine with a hand towel just in case any thing decided to spurt out of the lid.Once the pressure has been released, remove the inner pot and drain the excess water.Place the potatoes into a bowl and add cream cheese, butter, milk, sour cream, and salt and pepper. Mash the potatoes really well and mix everything up good. Add in the chopped green onion and mix again. Serve immediately or save them for later.',20,20,0);
INSERT INTO "Recipe" VALUES(496,'Vanilla Panna Cotta with Chocolate Ganache','https://img.spoonacular.com/recipes/664327-556x370.jpg','3 sheets gelatin, 0.5 cup milk, 1  vanilla bean','Fill a bowl with water, add the gelatin and let is soak. Pour milk into a pan & bring to just below simmering, then remove the pan from the heat. Do NOT let it boil. Drain & squeeze out the gelatin & add it to the milk. Pour the cream into another pan, add the sugar and vanilla bean and bring to a boil over low heat, stirring constantly. Then remove the pan from the heat, remove the vanilla bean and stir in the milk mixture.You can put the mixture into any kind of ramekin, mold, cup, you like. Rinse your ''glass'' in ice-cold water, shaking out any excess water & fill with the milk mixture. Chill in the refrigerator for several hours until set (at least 3-4 hours). Turn out onto a serving dish & serve with fruit sauce or chocolate sauce.In a double boiler melt chocolate bar. Once the chocolate is completely melted, slowly whisk in cream until the desired consistancy is reached.Drizzle over the top of the panna cotta once on the serving plate.',45,45,0);
INSERT INTO "Recipe" VALUES(497,'Fluffy frittata with spinach','https://img.spoonacular.com/recipes/643150-556x370.jpg','8  eggs, 2 cloves garlic, 0.5 tsp ground pepper, 0.75 teaspoon nutmeg, 1.5 Tbs olive oil, 0.33333334 cup parmesan, 0.5 cup ricotta cheese, 0.25 teaspoon salt, 140 g spinach, 140 g spinach','In a medium oven-proof skillet heat the olive oil, add the garlic and cook until softened.In a glass or metal bowl, beat the egg whites until stiff peaks form. In another bowl, beat the egg yolks and stir in the spinach and ricotta cheese; season with the salt, pepper and nutmeg. Fold in the egg whites.Pour the mixture into the hot skillet and cook over medium heat until just set around the edges, about 2 minutes.Transfer the frittata to the oven and bake at 200C until golden and fluffy, about 15 minutes.Sprinkle the parmesan all over the top and bake for 2 minutes.Cut into wedges and serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(498,'Sausage & Pepperoni Stromboli','https://img.spoonacular.com/recipes/776505-556x370.jpg','1  egg, 1 lb sausage, 1 cup parmesan cheese, 1 package pepperoni, 1 ball roll of pizza dough, 2 cups pizza sauce, 1 cup mozzarella cheese','Cook Italian sausage in a medium skillet until browned. Drain on paper towels and crumble into small pieces.Heat oven to 450 degrees.Place parchment paper on a baking pan and lightly flour. Roll dough out to form a large rectangle.Brush a thin layer of pizza sauce on dough. Layer on crumbled sausage then mozzarella cheese.Place pepperoni slices on top of cheese then sprinkle with 3/4 cup Parmesan cheese.Gently roll in short sides of dough to form a seal around filling.Starting on long side of dough, carefully roll into one third of Stromboli. Using parchment, roll dough again until reaching opposite end. Pinch together and place seam side down.Mix egg with 1 tablespoon of water. Brush egg mixture over Stromboli and sprinkle with remaining 1/4 Parmesan cheese.Place in oven and IMMEDIATELY TURN OVEN DOWN to 350 degrees.Bake for approximately 18 minutes. Remove from oven and let rest for 10 minutes. Test center of turnover. If dough is not completely cooked, slice Stromboli in half and bake for additional 5-8 minutes.Serve with warm pizza sauce',28,28,0);
INSERT INTO "Recipe" VALUES(499,'Bacon Wrapped Tofu Tacos','https://img.spoonacular.com/recipes/633352-556x370.jpg','12 oz tofu, 1 package fajita size, 8 oz cream cheese, 3 small jalapeno peppers, 2 cups monterey jack cheese, 1 pound bacon, 1 cup chicken broth, 1 bottle olive oil, 1 teaspoon cumin, 1 teaspoon chili powder, 1 teaspoon paprika, 2  garlic cloves',replace('In a small bowl combine the cumin, chili powder, paprika, 1 minced clove of garlic and 2 tbsp of olive oil.  Slice the tofu very thin, about 1/2 inch per slice, then rub each slice with the spice mixture.  Set aside.\nHeat about 1 tbsp olive oil over medium high heat in a large pan.  Add the tofu, a few slices at a time, watching carefully.  Flip after about 1-2 minutes.  Cook until done  I let mine cook about 2-3 minutes per side.   Half each piece, wrap with bacon, then set aside and cover with aluminum foil.\nDo NOT wash the pan out  now put it back on the stove, reduce heat to medium and add the remaining minced garlic clove, 1 tbsp olive oil and diced jalapeno.  Saute until the peppers are almost getting a little bit brown and everything is fragrant.   Add the cream cheese, 1/2 cup cheese and chicken broth.  Whisk and bring to a slight boil; reducing the heat if you have to, preventing it from scorching. Once its combined and a sauce consistency, salt and pepper to your taste and pour into a separate bowl; cover.\nBring the heat back up to medium-high, and add another tablespoon of olive oil to the pan.  When hot add one tortilla at a time, turning after about 15-20 seconds to the other side.  Your end result will be tortillas slightly brown around the edges and a little bubbly in the middle.\nSet aside and cover.\nTo serve, stuff a tortilla with bacon-wrapped tofu, and drizzle the jalapeno creme on top and some Monterey jack.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(500,'Creamy White Chili','https://img.spoonacular.com/recipes/640722-556x370.jpg','2 teaspoons pepper, 15.5 oz great northern beans, 1 pound chicken, 14 oz chicken broth, 1 teaspoon cumin, 1 clove garlic, 4.5 oz chilies, 0.5 cup heavy whipping cream, 1 tablespoon olive oil, 1 small onion, 1 teaspoon oregano, 0.5 teaspoon salt, 1 cup cheddar cheese, 1 cup cream','In heavy saucepan, saut chicken, onion, and garlic in olive oil.When chicken is cooked, add broth, beans, chilies, and seasonings.Simmer on low heat for 20 minutes. Remove from heat and add sour cream and whipping cream.Top with shredded cheddar cheese.',45,45,0);
INSERT INTO "Recipe" VALUES(501,'Chocolate Almond Bark','https://img.spoonacular.com/recipes/638808-556x370.jpg','0.5 cup almonds, 1 pinch cayenne pepper, 8 ounces candy making chocolate, 0.5 teaspoon sea salt, 0.5 teaspoon worcestershire sauce','Heat oven to 160 degrees.In a medium bowl, mix  cup chopped almonds with the Worcestershire sauce, cayenne and sea salt.Place on baking sheet and roast for 20 minutes.Let the almonds cool.Melt the chocolate using a double boiler or in the microwave (be sure to use low heat) and mix the almonds into the chocolate.Spread into wax-paper lined 8 x 8 inch baking pan.Sprinkle a pinch more of the sea salt on the top and let cool.Break into bite-size pieces.',45,45,0);
INSERT INTO "Recipe" VALUES(502,'Delicious Sausage & Peppers','https://img.spoonacular.com/recipes/641408-556x370.jpg','3  bell peppers, 7 cloves garlic - crushed&, 1 Dashes ground pepper, 4  sausages, 4  sausages, 1  jalapeño, 8 servings olive oil, 1 handful parsley, 3 tablespoons salsa, 1 Dashes sea salt, 1 large onion','Bake the sausages in the oven and set aside.Heat a large frying pan with a drizzle of olive oil and add the peppers. Add the onions, garlic and parsley and let this saut for a few minutes while slicing the sausages lengthwise. Add the sausages to the peppers along with the tablespoons of salsa and toss.Add the dashes of salt and pepper to taste.',30,30,0);
INSERT INTO "Recipe" VALUES(503,'Chicken Parmayonnaise','https://img.spoonacular.com/recipes/638231-556x370.jpg','6 servings kosher salt and coarse pepper, 1 teaspoon herbs, 0.5 cup mayonnaise, 0.5 cup parmesan, 6  chicken breasts','Oven to 375.Lightly pound breasts to uniform thickness ( not thin).Combine ingredients.Place chicken in baking dish.Spread mix evenly over chicken.Bake 25-30 minutes until top starts to brown.',45,45,0);
INSERT INTO "Recipe" VALUES(504,'Black Bean and Veggie Burgers with Corn Salsa',NULL,'1 can black beans, 2 cups corn, 1  carrot, 0.5 cup celery, 1 teaspoon creole seasoning, 0.25 cup flour, 1 teaspoon parsley, 1 cloves garlic, 2  garlic cloves, 2  green onions, 0.5 teaspoon ground pepper, 1 teaspoon ground pepper, 1 teaspoon ground pepper, 0.5  jalapeño pepper, 1  juice of lime, 0.25 cup oatmeal, 0.5 cup onion, 1 cup panko breadcrumbs, 0.5 cup bell pepper, 1 cup salsa, 0.5 teaspoon salt, 1 teaspoon salt, 3 medium tomatoes','Mix all the salsa ingredients together (canned corn, jalapeño pepper, tomatoes, green onions, 1-2 cloves garlic, fresh parsley, juice of 1 lime, 1 tsp salt, 1 tsp pepper, 1 tsp ground red pepper) and chill for about an hour before serving.Preheat your oven to 425 degrees F. Spray two baking sheets lightly with the nonstick spray and set aside.Add the carrot to a bowl with a little water, cover it and microwave for about two minutes. Once cooled, mash them and add them to the mashed black beans. Mix together then add the remaining vegetables and mix well.Add the oatmeal, breadcrumbs, seasoning and salsa. Mix together until combined. Add the flour and mix well. If the mixture is too moist, add more flour and adjust the seasoning, as needed.Form the mixture into patties and place them on the baking sheets. Bake for about 20 minutes, flipping them halfway through cooking. When the burgers are finished, serve with the Corn Salsa or your favorite topping.',45,45,0);
INSERT INTO "Recipe" VALUES(505,'TROPICAL BANANA GREEN SMOOTHIE','https://img.spoonacular.com/recipes/663845-556x370.jpg','0.25 c pineapple, 1 c coconut water, 0.25 c blueberries, 1 scoop protein powder, 2 c spinach','Mix all ingredients into a blender and enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(506,'Authentic Kentucky Bourbon Balls','https://img.spoonacular.com/recipes/633080-556x370.jpg','0.25 cup bourbon, 1 cup pecans, 2 cups powdered sugar, 2 tablespoons cocoa powder, 1 cup vanilla wafer crumbs, 1 teaspoon plus','In a deep bowl combine crushed vanilla wafer crumbs, chopped pecans, powdered sugar, and the cocoa.In a separate bowl, blend the bourbon and corn syrup.Pour the bourbon mixture into the dry mixture; blend well.Cover and chill for 3 hours.Shape small bits of the dough into balls and roll them in the powdered sugar. Store in refrigerator over night in tightly covered containers.You can also make these a few days in advance for best flavor.',45,45,0);
INSERT INTO "Recipe" VALUES(507,'Crockpot Chicken and Dumplings','https://img.spoonacular.com/recipes/640886-556x370.jpg','6 large chicken breasts, 2 tablespoons butter, 2 cans cream of chicken soup, 1 can chicken broth, 1  onion, 1 tablespoon parsley, 4  grands flaky refrigerator biscuits',replace('Place chicken in the crock pot. Add butter, cream of chicken soup, chicken broth, diced onion, and parsley.\nCook on high for 4-6 hours or low for 8-10.\n30 minutes before chicken is finished cooking, cut biscuits into 9 pieces and add to crock pot. Gently stir to coat biscuits. Continue to cook for 30 minutes, then serve!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(508,'Easy Cheesy Pizza Casserole','https://img.spoonacular.com/recipes/641893-556x370.jpg','1 lb equivalent amount of a ground beef/bulk sausage mix, 0.5 cup ricotta, 1 pinch oregano, 1 pinch basil, 1 Tbs parmesan cheese, 26 oz pasta sauce, 1 can pizza sauce, 0.125 tsp pepper flakes, 0.5  pepperoni, 2 cups mozzarella, 0.5 cup aged provolone, 6 servings herbed parmesan drop biscuits, 6 servings additional parmesan cheese, 2.25 cup baking mix, 0.25 cup parmesan cheese, 1 tsp seasoning, 0.6666667 cup milk, 1 serving or, 6 servings or',replace('Brown ground beef in skillet; drain fat.  Mix in pasta or pizza sauce and pepper flakes; set aside.  Mix ricotta cheese with the herbs and Parmesan in a separate bowl; set aside.\nMix the dry ingredients for the biscuits.  Add milk and stir until combined.\nPreheat oven to 375 degrees.  Spray a 13 x 9 pan with non-stick spray.  Drop biscuit dough by teaspoons in the bottom of pan, spacing evenly.  It''s OK if there is space between the dough--it will expand as it''s cooked.  Top with ground beef mixture and dot with the ricotta cheese mixture.  Bake at 375 for about 20 min or until biscuits are puffed and beginning to get golden brown.\nTop with mozzarella and provolone cheeses and distribute pepperoni slices evenly over top, increase oven temperature to 425 degrees.  Return to oven and bake until cheeses are melted and beginning to bubble.  This should take about 10 minutes.\nRemove from oven and let stand 5 minutes before slicing and serving.  May be topped with the additional Parmesan cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(509,'Gluten-Free Pressed Lemon Butter Cookies','https://img.spoonacular.com/recipes/644900-556x370.jpg','1.5 cups butter, 0.75 cup sugar, 3 large egg yolks, 1 teaspoon lemon extract, 1  lemon zest, 1 tablespoon lemon juice, 3.25 cups flour, 1 teaspoon xanthan gum',replace('Preheat oven to 350 degrees.\nMake sure your flours are whisked / sifted well and add xanthan gum if not included.\nIn the bowl of a standing mixer with the paddle attachment, cream butter until fluffy, then add sugar and cream together.\nAdd egg yolks, one at a time, and beat to incorporate.\nAdd lemon zest, extract and juice and beat in.\nAdd flour and slowly beat in, then increase speed until incorporated.\nFill cookie press and press onto ungreased cookie sheets.\nBake one sheet at a time for 12-15 minutes, or until the edges are lightly browned.\nLet cool on sheets completely before removing, gingerly, with a thin spatula.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(510,'Grilled Lemon Garlic Chicken','https://img.spoonacular.com/recipes/645753-556x370.jpg','2 pounds chicken breast, 0.25 cup garlic olive oil, 0.5 cup lemon juice, 2 teaspoons tumeric, 4 servings salt and pepper, 4 servings cilantro',replace('Trim any fat and clean Chicken\nPut Chicken in bowl with Garlic Oil, Lemon Juice, Salt and Pepper and Tumeric, combine all.\nIf you have time, do this in the morning and marinate all day in the fridge.  If this is last minute try to give Chicken about an hour in the marinade)\nPre heat Grill, Medium High Heat.\nGrill Chicken about 5 minutes per side until inside is cooked through.\nPlate and garnish with chopped Cilantro or Parsley','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(511,'My Asian Fried Fish Fillet','https://img.spoonacular.com/recipes/652824-556x370.jpg','0.25 teaspoon all spice, 1 tablespoon baking powder, 500 grams fish fillet, 0.5 cup corn flour, 1 tablespoon curry powder, 2  eggs, 1 teaspoon ground pepper, 5 tablespoons rice wine, 2 tablespoons soy sauce, 1.5 cups sugar','In a bowl, put fish fillet and put the ff also : rice wine, soy sauce, white pepper, sugar, all spice and curry powder.Mix them well and marinate for 30 minutes. Set aside in the fridge.Then beat 2 eggs and slowly add to the marinated fish, add also the corn flour and baking powderMix well and make sure the fillet is well coated.Now you can start frying, the oil should be hot.',45,45,0);
INSERT INTO "Recipe" VALUES(512,'Minestrone Soup','https://img.spoonacular.com/recipes/658024-556x370.jpg','125 gr into strips, 1 can kidney beans, 1 can canned tomatoes, 3  carrots, 3 stalks celery, 1 tbsp thyme leaves, 3 large cloves garlic, 100 gr .5 oz. macaroni, 1 tbsp olive oil, 1 large onion, 8 servings some parmesan to serve, 8 servings salt and pepper, 0.33333334  savoy cabbage, 2 tbsp tomato purée, 2 large tomatoes into 8ths, 1.2 liter vegetable stock','Heat the oil in a very large pan that has a close fitting lid.  Then add the celery, bacon, onion, carrot and garlic.  Fry this off for about 5 to 7 minutes until it has softened a little.  No colour is needed on the vegetables, so make sure the heat isnt too high that they become brown, but high enough the vegetables sweat and soften.Add the tomato pure and  the thyme leaves, stir through and cook for about 30 seconds.3.Add the stock, the tin of tomatoes, fresh tomatoes, and a little salt and pepper. Stir everything through, set the heat so that your soup is on a gentle simmer, cover and cook for about 25 minutes or until the vegetables are cooked al dente.Add the pasta and cook until the pasta is ready.  Follow the timing instructions on the packet, but this is normally about 7 minutes.Add the cabbage and the beans and cook until the cabbage has wilted.  This will take about 5 minutes.Check for seasoning and add some salt and pepper if needed before serving.Sprinkle a little parmesan over each bowl of soup.',45,45,0);
INSERT INTO "Recipe" VALUES(513,'Grilled Ginger Miso Chicken','https://img.spoonacular.com/recipes/645722-556x370.jpg','1 tablespoon five-spice powder, 1  garlic clove, 1 tablespoon ginger root, 2  green onions, 2 tablespoons soy sauce, 2 tablespoons mirin, 2 tablespoons miso, 2 tablespoons sake, 8  boned chicken thighs skin intact','Blend soy sauce, sake, mirin, miso, green onions, ginger root and garlic in a rectangular baking dish. Coat chicken with mixture. Marinate 1 hour or refrigerate overnight, turning several times.Preheat a hibachi, portable tabletop grill or charcoal grill. Shake marinade off chicken; pat dry. Place skin-down on hot grill. Grill 4 to 5 minutes. Turn chicken; grill second side 4 to 5 minutes or until golden brown and done inside. When chicken is done, sprinkle with sesame seeds and spice mixture.This "Recipe" yields 4 servings.Comments: Miso marinade adds a rich flavor to this country-style grilled chicken. Thigh meat stays moist and tender, but boned chicken breasts are delicious, too. The chicken can be sauteed in a skillet.',45,45,0);
INSERT INTO "Recipe" VALUES(514,'Pesto Zucchini "Spaghetti','https://img.spoonacular.com/recipes/655853-556x370.jpg','4 medium zucchini, 1 pinch salt, 6 slices bacon, 0.5 cup green onions, 2 cups broccoli florets, 2 T basil pesto, 4 servings romano cheese',replace('Place zucchini strips in a colander over a bowl or in the sink. Sprinkle zucchini with salt and toss to combine. Let the zucchini sit for 15 minutes while the salt extracts the moisture. Drain excess water, squeezing zucchini, if necessary.\nMeanwhile, cook bacon in a skillet over medium heat until crisp, turning frequently. Remove bacon to a stack of paper towels to drain. Crumble bacon. Remove all but 2 T of bacon drippings from the pan.\nReturn the pan to medium heat. Add the green onions and broccoli, stirring frequently for about 3-5 minutes or until crisp-tender. Add zucchini and 2 T of pesto, tossing to combine all ingredients. Taste and add more pesto, if needed. The mixture only needs to warm up, so 2-3 minutes of cooking ought to do it.\nServe with bacon crumbles and freshly grated Parmesan cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(515,'Easy Chicken Tandoori','https://img.spoonacular.com/recipes/641904-556x370.jpg','2 pounds chicken, 2 cups tikka tandoori paste, 12 servings coriander leaves, 1 cup greek yogurt, 12 servings onions, 12 servings tomatoes','Mix the tandoori paste and yogurt well. Marinate the chicken pieces well for about 30 minutesPlace the chicken pieces along with the marinate into a baking pan and bake until golden brown and then turn over  until chicken is done. Keep turning the chicken pieces a few times while baking. Serve with in a bed of rice. Then lay the chicken fillets on the rice and put a bit of greek yogurt',45,45,0);
INSERT INTO "Recipe" VALUES(516,'Chicken Suya','https://img.spoonacular.com/recipes/716342-556x370.jpg','1.5 Tablespoons suya spice, 1 pound chicken, 1 teaspoon chilli powder, 1  cooking spoon groundnut oil, 1 serving seasoning cubes, 1 serving onions and tomatoes, 1 serving salt','Heat the oven to 500 F.Wash and season the chicken with the Suya spice, chilli powder, seasoning cubes, salt and drizzle the oil over it.Place the chicken in the oven and grill for 40 minutes. Check the chicken occasionally and flip on both sides so it can cook properly.Serve hot garnished with the onions and tomato and a bit of suya spice sprinkled over the chicken.',45,45,0);
INSERT INTO "Recipe" VALUES(517,'Spanish Meatballs In Tomato Sauce','https://img.spoonacular.com/recipes/660868-556x370.jpg','1  bay leaf, 2 cloves garlic, 1 pound ground beef, 1 cup olive oil, 2 tablespoons olive oil, 0.5 cup onion, 20 servings half an onion, 2 tablespoons parsley, 1 pinch pimenton de la vera, 20 servings salt and pepper, 1 teaspoon sugar, 600 g tomatoes, 4 slices sandwich bread, 1 large egg','Start by making the tomato sauce.Finely chop 1 onion.Peel 600g of tomatoes with a serrated peeler. Chop the peeled tomatoes into small pieces.Add 2 tablespoons of olive oil in a sauce pan. Add the chopped onions.Add a pinch of Pimenton de la Vera (Dulce), which is Spanish smoked sweet paprika. I used 1/4 teaspoon. Add more if you prefer the sauce to be spicy.Add the chopped tomatoes to the onions mixture and stir well to combine.Add 1 fresh bay leaf. I used 2 dried pieces here because I couldnt find fresh ones.Add 1 teaspoon of sugar andd salt and pepper to taste. I added 1/2 teaspoon of salt and 1/4 teaspoon of ground black pepper. Adjust seasoning to taste.Cover the sauce pan and reduce the heat to a medium-low and let the tomato mixture simmer gently till it reduces to a sauce like consistency.In the meantime, make the meatballs by adding 1/2 an onion to a food processor.Add 2 cloves of garlic. I used 1 tablespoon of minced garlic. Process till the onions and garlic are finely chopped.Sweat the onion-garlic mixture in a frying pan with some olive oil. I just realised that I had missed this step. The meatballs still tasted great.Add the onion-garlic mixture to 500g ground beef in a mixing bowl.Slice off the crust of 4 slices of white bread. Cut the soft white bread into small cubes of 1cm all round.Add the chopped bread to the beef mixture.Add 2 tablespoons of chopped parsley. Use Italian flat parsley where possible. I couldnt find any, so I used English parsley.Add 1 large egg.Add salt and pepper to taste. I used approximately 1/4 teaspoon of salt and a pinch of black pepper.Mix well to combine.Shape the meat mixture into balls that are slightly bigger than the size of a golf ball size. Roll the meat tightly to form meatballs.Add 3/4 cup of olive oil to frying pan. The layer of oil should be approximately 3/4cm in the pan.Put the pan on medium-high heat and add the meatballs to the oil. Gently roll them around in the oil to brown all surfaces and ensure even cooking.When the meatballs are a deep golden brown, remove them from the frying pan and set aside.The tomatoes-onion mixture should have reduced to a sauce consistency now. You can use a hand blender to puree the mixture. Or leave the small bits of tomatoes and onions as they are.Add the meatballs to the tomato sauce and let the meatballs warm through.Garnish with more chopped parsley.',45,45,0);
INSERT INTO "Recipe" VALUES(518,'Best Chicken Parmesan','https://img.spoonacular.com/recipes/634891-556x370.jpg','2 cups style bread crumbs, 24 ounces chicken cutlets, 3  eggs, 1 cup flour, 4 cups mozzarella cheese, 0.5 cup parmesan cheese, 1 can vegetable oil','Depending on how think your chicken breasts are, place them under plastic wrap and pound until thin. If you don''t have a meat pounder, use a heavy pot of skillet. You can also fillet these with a knife.Get 3 pie plates or containers. Put flour in one, beaten eggs in one and bread crumbs in one.Dredge chicken breast in flour, then in the egg wash, and then the bread crumbs.Fry cutlets in vegetable oil over med heat. Fry until golden brown.Spread a little marinara on the bottom of a 13x9 baking dish.Make a layer of chicken. Add more marinara. Use most of the first quart. Add a layer of the cheeses. Repeat layers. Sprinkle parsley over last layer of cheese. Bake in a pre-heated 350 degree oven covered for 35 minutes. uncover and bake until top is bubbly!',45,45,0);
INSERT INTO "Recipe" VALUES(519,'Mediterranean-Style Haddock','https://img.spoonacular.com/recipes/651455-556x370.jpg','8 ounces haddock, 1 teaspoon olive oil, 0.5 cup bell pepper, 0.5 cup onion, 2 cloves garlic, 2 TBSP white wine, 0.5 cup ground tomatoes, 0.5 teaspoon pepper, 0.25 teaspoon salt, 1 teaspoon oregano',replace('Preheat oven to 350. Heat oil in a small skillet over medium heat. Add red pepper and onion and saut for 7 minutes, or until slightly softened. Add garlic and stir for 30 seconds.\nAdd white wine to deglaze the pan, followed by ground tomatoes, oregano, salt, and pepper. Stir and let simmer for 2 minutes.\nPlace the fish in a single layer in a small oven-safe baking dish and cover with the tomato sauce. Sprinkle with the feta cheese.\nBake for 20 minutes. Serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(520,'Blackberry Honey Cocktail','https://img.spoonacular.com/recipes/635215-556x370.jpg','0.75 ounce home made clover honey syrup, 2 ounces honey vodka, 3  blackberries, 0.75 ounce lemon juice, 3  garnish: blackberry jam',replace('In a pint glass add all spirits and mixers, add ice and shake vigorously for 6 seconds.\nStrain in a Collins glass filled half way with cubed ice.\nTop off with crushed ice. Then crown with hand made jam.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(521,'Spicy Korean Bbq Pork','https://img.spoonacular.com/recipes/661117-556x370.jpg','2 pounds pork loin, 0.25 cup brown sugar, 3 teaspoons chili garlic sauce, 2 teaspoons ginger, 6  garlic cloves, 10 servings rice vinegar, 2 teaspoons sesame oil, 0.25 cup soy sauce','Mix the marinade ingredients (brown sugar, soy sauce, ginger, sesame oil, chili garlic sauce, and ginger). Pour over your sliced pork.Marinate no less then 4 hours; overnight is recommended.Preheat your grill to high. Place pork on grill and grill each side 3 minutes or until cooked through.If you want a sauce to pour over your meat, boil your leftover marinade in a sauce pan for a few minutes until it boils down and thickens. You can then add rice vinegar to taste to thin it and decrease the sweetness. Pour sauce over meat.',45,45,0);
INSERT INTO "Recipe" VALUES(522,'Japanese Curry Puffs','https://img.spoonacular.com/recipes/648470-556x370.jpg','3 small carrots, 2  potatoes, 1 medium size onion, 0.5 package japanese curry, 3 cups water, 1 tablespoon oil, 1 package puff pastry dough sheets',replace('Preheat oven to 350 degrees.\nIn a pot over medium/high heat, add oil and onions. Cook for 2 minutes. Add potatoes and carrots, cook for 5 minutes. Add water and bring to the boil. Lower heat and simmer for 15 minutes. Add curry mix and cook for another 10 minutes.\nOn a sheet pan, cut puff pastry into squares (1 sheet should give you 4 squares) and with a spoon, fill the middle of 1/2 of the squares you have.\nBake for 20 minutes or until the crust is a golden brown and serve!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(523,'Oreo Cookies & Cream No-Bake Cheesecake','https://img.spoonacular.com/recipes/654028-556x370.jpg','1 pound cream cheese, 2 cups heavy cream, 2 tablespoons lemon juice, 0.75 cup oreo cookies, 0.5 teaspoon salt, 0.6666667 cup sugar, 2 teaspoons vanilla powder','Beat heavy cream until medium peaks form. Set aside.Add cream cheese, sugar, salt, vanilla powder, lemon juice to a bowl and beat with a paddle attachment until smooth (approximately 3-5 mins). If you do not have a stand mixer or a paddle attachment a hand beater will work as well, but will take twice as long to achieve a smooth consistency.Add cream cheese mixture to heavy cream and beat until incorporated.Gently fold in crushed Oreo cookies.Fill chosen pan with a slight mound at the center, as the cheesecake will become slightly sunken at the center.Refrigerate for at least 6 hours to set or overnight for best results.Remove from refrigerator and smooth top to level with edges. Serve with whipping cream and garnish with mini Oreos.',45,45,0);
INSERT INTO "Recipe" VALUES(524,'Dreamy Chai Rice Pudding','https://img.spoonacular.com/recipes/641644-556x370.jpg','1 cup rice, 4 cups milk, 1 cup freshly tea, 1 teaspoon cinnamon powder, 1 teaspoon ginger powder, 3  cardomon pods, 1  star anise, 6  large cloves, 1 teaspoon vanilla essence, 0.25 cup brown sugar',replace('METHOD\nPut milk, tea, rice and all spices in a small saucepan and bring to boil. The turn down and simmer for around 20 minutes, stirring occasionally.\nAdd sugar and turn heat back up to high. Cook for three to four minutes, stirring all the time as the pudding thickens.\nServe in individual bowls. If you wish, you can pick out the spices before serving (use a spoon as the pudding will be very hot) but I figure most people can cope with minor details like that.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(525,'Gingerbread','https://img.spoonacular.com/recipes/644674-556x370.jpg','2 Tsp baking powder, 0.5 Tsp baking soda, 0.5 c un-packed brown sugar, 0.33333334 c butter, 1 c pumpkin, 2  eggs, 2 c pastry, 1.5 Tsp ground cinnamon, 0.25 teaspoon ground cloves, 2 teaspoons ground ginger, 1 Tbsp honey, 1 tablespoon molasses, 2 Tbsp turbinado sugar, 6 tablespoons water','Preheat oven to 350Spray 4 Mini Loaf pans with non-cooking spray, set a sideStir together 1 cup of flour, brown sugar, baking powder, cinnamon, ginger, cloves and baking soda.Add the pumpkin, molasses, eggs, honey, water and butter.Beat with an electric mixer on low to medium speed until combined, about 30 seconds.Beat on medium to high speed for 2 minutes, scraping the sides of the bowl occasionally.Add the remaining flour; beat for 2 minutes or until mixed.Divide the batter evenly among the prepared pans.For the topping, sprinkle Turbinado Sugar evenly over all the batter in the pans. Optional Toppings: Sprinkle Crystalized Ginger and Walnuts over other loafsBake in a 350 F oven for 35-40 minutes or until a wooden pick inserted near the center of each loaf comes out clean.Cool the loaves in the pans on wire racks for 10 minutes. Remove the loaves from the pans. Cool thoroughly on the wire racks.If you want a frosting on the bread ("Recipe" from Oh She Glows):  Mix 1 3/4 cups powdered sugar,  1/2 Cups of butter, 1 tsp vanilla, 1 Tbsp of Pumpkin Spice.  Beat together in a bowl until it is the mixture you like.  If it is to thick add milk to water it down.  I served the frosting as a side, for those who are watching there calories.  he heServing Size: 4 Mini LoafsNumber of Servings: 24 (6 slices per loaf)Calories per serving:  85,  Fat:  2.6,  Sodium:  84,  Potassium:  119,  Carbs:  15,  Fiber:  2,  Sugar:  6.6,  Protein:  2',45,45,0);
INSERT INTO "Recipe" VALUES(526,'Easy Homemade Oreo Cookies','https://img.spoonacular.com/recipes/641993-556x370.jpg','4 oz cream cheese, 4  eggs, 4 packages chocolate cake mix, 2 cups icing sugar, 0.5 cup margarine, 0.25 cup milk, 0.6666667 cup oil, 1 teaspoon vanilla','Put all that into a HUGE bowl!Mix it up good, if you can. It''s a lot to deal with, so maybe try mixing it in partsRoll the dough into balls. The smaller the balls, the more cookies you will have, so keep this in mind.Bake for 8  10 minutes at 325 F.When they are done, take them out and slightly flatten them with a spatula. (I just patted them down a wee bit)Remove from pan and cool on wire racks.Let cookies cool completely before icing.Mix icing up really good with electric beaters.If you want to add a little extra, put in some other flavoring and food colouring, as I did, making mine mint oreos with light green icing.Once cookies are cooled, spread the filling in between 2 cookies.Keep in refrigerator or freezer.',120,120,0);
INSERT INTO "Recipe" VALUES(527,'Simple Blueberry Bread','https://img.spoonacular.com/recipes/660080-556x370.jpg','0.5 cup butter, 1 cups sugar, 2 cups flour, 2 teaspoons baking powder, 0.5 teaspoon salt, 2 large eggs, 0.5 cup milk, 1.5 cups blueberries',replace('Preheat over to 350.\nGrease and flour 9 x 5" loaf pan.\nIn large bowl, with mixer at low speed, beat butter and 1 cup sugar just until blended. Increase speed to medium; beat until light and fluffy, about 5 minutes.\nMeanwhile, in medium bowl, combine flour, baking powder, and salt.\nReduce speed to low; add eggs, one at a time, beating after each addition until well blended, occasionally scrapping bowl with rubber spatula.\nAlternately, add flour mixture and milk, mixing until just blended.\nGently stir in blueberries.\nSpoon the batter into loaf pan.\nBake 1 hr and 5 minutes or until toothpick inserted in center, comes out clean.\nCool loaf in pan on wire rack for 10 minutes.\nRemove from pan. Cool the bread on wire rack.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(528,'Guacamole','https://img.spoonacular.com/recipes/645988-556x370.jpg','2 large haas avocados, 2 tablespoons onion, 1 tablespoon jalapeno pepper, 0.25 cup cilantro, 0.5 teaspoon salt, 0.125 teaspoon pepper, 1 tablespoon lime juice, 1 teaspoon basil, 1 teaspoon oregano',replace('Cut the avocados in half lengthwise. Drive chef''s knife into large pit and twist to remove.  Scoop the avocado out from the skin into a bowl.\nMash the avocado with a fork, add in onion and cilantro, oregano and basil..  Mix to incorporate.\nSeason to taste with salt, pepper and lime juice.\nServe immediately or chill.  If you are not going to eat the guacamole immediately, store in refrigerator with plastic film wrap pressed onto the guacamole.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(529,'Halloween Mocha Cupcakes','https://img.spoonacular.com/recipes/646138-556x370.jpg','0.5 teaspoon baking powder, 0.5 teaspoon baking soda, 0.5 cup bittersweet chocolate chips, 0.75 cup bittersweet chocolate chips, 0.5 cup buttermilk, 100 g cake flour, 12 servings chocolate cocoa powder, 60 g natural cocoa powder, 4 teaspoons coffee extract, 1  egg, 12 servings halloween sprinkles, 0.5 cup heavy cream, 8 oz mascarpone cheese, 0.5 cup oil, 0.25 teaspoon salt, 0.6666667 cup sugar, 1 teaspoon vanilla extract','Step 1: Prepare the frosting by melting the chocolate in a double broiler. When the chocolate has melted, add heavy cream and coffee extract. Mix well and chill in the refrigerator until needed. Dont combine the mascarpone cheese, yet.Step 2: Preheat oven to 350 degrees F and line the cupcake pan with Halloween baking cups. In a large bowl, combine the the cake flour, cocoa powder, baking powder, baking soda, and salt.Step 3: In another large mixing bowl, mix together the oil, sugar, egg, and vanilla and coffee extract and mix well. Then add the buttermilk and mix well again.Step 4: Now stir in the flour mixture and mix until well combined.Step 5: Pour the batter into a ziploc or piping bag and pipe into the cupcake pan. Bake for 20 to 25 minutes or until an inserted toothpick comes out clean (I baked mine for about 24 minutes).Step 6: Let the cupcakes cool in the pan for about 5 to 10 minutes and then transfer them to a rack to cool completely.Step 7: While cupcakes are cooling, make the chocolate decorations. Melt the chocolate and use a ziploc or piping bag to pipe out your design onto some parchment paper. Sprinkle the halloween sprinkles before the chocolate hardens. Chill in freezer until needed.Step 8: Finish the frosting. Using an electric mixer, beat the mascarpone cheese until light and fluffy. Add the cooled chocolate cream mixture from earlier and beat until combined.Step 9: Roughly spread the frosting on the cooled cupcakes. Dust with cocoa powder and decorate with sprinkles and chocolate.',45,45,0);
INSERT INTO "Recipe" VALUES(530,'Cheese Pork Chops','https://img.spoonacular.com/recipes/637569-556x370.jpg','2 tablespoons dijon mustard, 0.5 cup gruyere cheese, 0.5 cup heavy cream, 1 teaspoon olive oil, 4  pork chops, 4 servings salt and pepper, 1 tablespoon butter','In a heavy bottom skillet melt the butter with the olive oil. Saut` the pork chops over medium high 3 minutes on each sided. Lower the heat to medium and cook for another 5 to 6 minutes for side.Salt and pepper to taste.Meanwhile turn on the broil. Mix together in a bowl the heavy cream, mustard and the cheese. Remove the chops from the stove and place them in a oven proof dish. Spread the cheese-cream mixture over the chops and broil for about 5 minutes.',30,30,1);
INSERT INTO "Recipe" VALUES(531,'Spiced Apple Cider','https://img.spoonacular.com/recipes/660932-556x370.jpg','0.25 Tsp allspice, 4 cups freshly apple juice, 2  cinnamon sticks, 1 inch ginger, 1 Tbsp maple syrup, 0.125 Tsp nutmeg, 0.5  orange, 1 cup water','In a large non reactive pot, combine all ingredients. Bring to a boil over medium high heat. Boil for about 5 minutes.Cover pot, reduce heat and simmer for 30-40 minutes.Line a collander with cheesecloth and strain the cider.Serve warm. Spike with dark rum if its been one of those days.',45,45,0);
INSERT INTO "Recipe" VALUES(532,'SLOW COOKER CHICKEN GUMBO SOUP','https://img.spoonacular.com/recipes/660283-556x370.jpg','3 cups chicken, 14 ounce can chicken broth, 1  carrot, 1  bell pepper, 1  onion, 14.5 ounce canned tomatoes, 16 ounce okra, 1.5 cups water, 1 teaspoon cajun seasoning, 0.5 teaspoon pepper, 1 teaspoon salt, 6 servings hot sauce, 1 cup rice','Put all ingredients in crockpot and cook on high for 4 hours or low for 6 to 7 hours.',45,45,0);
INSERT INTO "Recipe" VALUES(533,'Cornish Game Hen with Whisky and Cream Pan Sauce','https://img.spoonacular.com/recipes/640151-556x370.jpg','2 large cornish game hens, 2 tablespoons butter, 4 servings olive oil, 4 servings salt and pepper, 4 servings herbs de province, 2 tablespoons butter, 2 medium shallots, 1 teaspoon worcestershire sauce, 1 tablespoon dijon mustard, 0.5 cup heavy cream, 2 teaspoons lemon juice, 0.25  to)',replace('For the Cornish hen:\nPreheat the oven at 450 and position the rack in the middle of the oven.\nPlace a hen, breast side down on a cutting board. Remove the backbone by cutting along both sides with shears or large sharp knife.  Flip the hen and flatten it by pressing down on the breastbone with your palm. Split the hen in two along the breastbone. Repeat with the remaining hen.\nPlace on a heavy baking dish and spread on each half,  of a teaspoon of butter, Herbs de Province, salt and pepper and a drop of olive oil.  Place in the hot oven and cook for 30 to 45 minutes. Poke the hen while cooking to release any juices.\nWhen done, remove from the oven, place the hen in a dish and cover with aluminum foil and let rest.\nTo make the sauce:\nPlace the unwashed cooking pan over the stove and add the remaining 2 tablespoon of butter and let it melt. Lower the heat and add the whisky, very slowly. With a wooden spoon scrape up any bit on the pan.  Add the shallots and cook until tender, 1 minutes.  Add the Worcestershire sauce, mustard and raise the heat to medium high. Bring to a boil stirring constantly.  Add the heavy cream and the lemon juice. Taste the sauce and season with salt and pepper.\nServe hot over the Cornish hen.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(534,'Chicken and White Bean Chili','https://img.spoonacular.com/recipes/637932-556x370.jpg','4 pounds chicken, 1 liter water, 2 tablespoons chicken soup base, 1 large bay leaf, 1 medium size onion, 1  bell pepper, 3 large garlic cloves, 5 tablespoons flour, 439 g .5 can cannellini beans, 2 tablespoons mild chili powder, 1 teaspoon ground coriander, 2 teaspoons ground cumin, 1 tablespoon coriander, 250 ml heavy whipping cream, 187 ml soured cream, 9 servings bell pepper',replace('Rinse the chicken quarters really well and place them in a stock pot.\nTo the chicken in the pot, add the water (water should mostly cover the chicken), bouillon, bay leaf, onion, bell pepper and garlic.\nPlace the stock pot over medium high heat and bring to a boil; reduce the heat to medium, cover and simmer until chicken is cooked through, approximately 30 minutes.\nRemove pot from the heat.\nRemove chicken quarters from the pot and transfer them to a cutting board and cool until they can be comfortably handled. \n \nRemove meat from the bones and chop it into small pieces then shred slightly; set aside.\nRemove approximately 1 cup (250ml) of the liquid from the stock pot and set aside.\nReturn the stock pot to medium heat and bring to a simmer. \n \nPlace the flour into a small bowl.\nWhile stirring constantly, gradually add the reserved liquid to the flour until a smooth paste is formed.\nPour the paste into the stock pot and stir constantly until the mixture starts to thicken.\nAdd the beans, chopped chicken, chili powder, coriander and cumin.\nIncrease the heat to medium and, stirring frequently, simmer, uncovered for approximately 15-20 minutes or until the mixture is thick enough to coat the back of a spoon.\nReduce the heat to low and add the fresh coriander, single cream and soured cream.\nStir well until the single and soured creams are completely incorporated into the chili.\nAdd pepper to taste.\nServe immediately.\nGarnish with chopped avocado, spring onion, fresh coriander or grated cheese.\nLike most soups, this chili is great refrigerated and served the next day but if you intend on freezing it, leave out the whipping cream and soured cream (they separate when frozen) and add them just before serving.\nIf youd like to spice things up a bit, add  -  teaspoon cayenne pepper or red pepper flakes for a slightly hot flavor.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(535,'Tuna Mexi Melts','https://img.spoonacular.com/recipes/663931-556x370.jpg','5 tablespoons butter, 0.25 teaspoon chile powder, 1 bunch of cilantro, 0.25 teaspoon cumin, 1 loaf bread, 6 servings garlic powder, 2  green onions, 0.5  jalapeno, 1  juice of lime, 0.25 teaspoon paprika, 8 ounces pepper jack cheese, 0.75 cup your picante, 5  roma tomatoes, 1 teaspoon salt, 0.75 cup cheddar cheese, 1 cup cream, 360 grams tuna','InstructionsWell whip up the picante first. To do this, go ahead and add all the ingredients into your food processor. Zip it up good and then add in some salt to taste.Next up, grab your french loaf and slice it into 1 slices. Brush the melted butter over your slices of bread and then sprinkle on some cumin, chile powder, and garlic powder.Add all the melt ingredients with the exception of the pepper jack cheese to a bowl and mix it up good. Now grab your bread and lop a large spoonful of the tuna mixture on each piece. Top them all off with a slice of pepper jack cheese. Throw your sandwiches into an oven heated to 350 degrees and let them heat up for about 10 to 15 minutes or until your cheese is melted and bubbling.',45,45,0);
INSERT INTO "Recipe" VALUES(536,'Moist Zucchini Pineapple Sweetbread','https://img.spoonacular.com/recipes/652240-556x370.jpg','0.25 teaspoon baking powder, 8 oz pineapple, 1.5 teaspoons cinnamon, 1 cup dates, 3  eggs, 0.75 teaspoon nutmeg, 1 cup nuts, 1 cup oil, 1 teaspoon salt, 2 teaspoons vanilla extract, 2 cups sugar, 3 cups flour, 2 cups zucchini','Beat eggs, oil, sugar and vanilla together until creamySift together the dry ingredientsAdd by thirds into the liquid, mixing well between each additionFold in the nuts and datesPour into 2 greased loaf pansBake in a preheated oven at 350 degrees for approximately 1 hourIf using a 5x15 inch sweet bread pan, check it at approximately 50 minutes If using the traditional bread pans, the bread will be higher and need a little longer to bake. Therefore, lower the oven temperature to about 325 degrees and bake a little longer.Bread is finished when it is set and knife or toothpick inserted in center comes out cleanCool on wire rack for 15 minutesThen turn bread out of pan and finish cooling on rack',45,45,0);
INSERT INTO "Recipe" VALUES(537,'Ratatouille With Brie','https://img.spoonacular.com/recipes/657939-556x370.jpg','1  brie log such as alouette, 1 small eggplant, 4 oz olive oil, 1  zucchini, 1  squash, 2  plum tomatoes, 1 tsp thyme',replace('Remove outer peel from eggplant and dice into  inch pieces\nHeat 1-2 oz. of olive oil in a heavy gauge skillet\nSaut the diced eggplant for 2-3 minutes then place on a towel to drain\nAfter draining place cooked eggplant into a small oval casserole dish\nPreheat oven to 375 F\nCarefully slice the zucchini , yellow squash , and tomatoes about  inch even slices\nSlice the Brie also into  inch slices (utilizing a cheese wire makes simplifies this)\nBegin placing sliced yellow squash , zucchini , sliced Brie and tomatoes in a shingled pattern working from the outside of the casserole towards the center\nWhen all vegetables and cheese are placed in the casserole, drizzle with the remaining olive oil and sprinkle with chopped thyme\nSeason with salt and pepper and bake in the oven for 10-15 minutes until bubbly','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(538,'Roast Chicken with Apples and Rosemary','https://img.spoonacular.com/recipes/658418-556x370.jpg','4  apples, 3  onions, 3 head garlic, 8 sprigs rosemary, 4  lemons, 0.5 cup raimondo sicilian lemon balsamic vinegar, 8 servings seasoning - make a rub, 2  roasting chickens, 1 can stock',replace('Preheat oven to 400 degrees.  Position a rack in the lower third of the oven.  Rinse the chicken, then dry it very well with paper towels, inside and out.\nPlace apples, rosemary, 3 lemons, onions, and garlic in a single layer in shallow roasting pan. Season with salt and pepper. Toss well and pour in the vinegar. Season the chicken well with the rub and place breast-side-up on top of the veggies and fruits. Put the rest of the veggies and fruit in the cavity of the chicken.\nRoast for 30 minutes, until the breast is firm and just beginning to brown in spots. Using tongs, turn the chicken breast-down and roast for 20 minutes longer, until the skin is lightly browned and the thermometer registers 175 to 180.\nTilt the chicken to drain the cavity juices into the pan and remove the goodies from the inside and bottom of pan.  Now transfer the bird to a cutting board. Remove the rack from the pan and spoon off the fat. Set the pan over high heat. Add the stock and cook, scraping up any browned bits and leftover pieces of goodies. Squeeze the last lemon to release the juices. Carve the chicken and pass the chunky jus at the table.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(539,'Kimchi','https://img.spoonacular.com/recipes/648910-556x370.jpg','6 pounds napa cabbage, 3 tablespoons salt, 2 cups scallions, 3  garlic cloves, 1 tablespoon ginger root, 4 tablespoons ground chili pepper, 2 tablespoons sugar',replace('Shred cabbage in 2 inch strips. Mix with half the salt. Let stand 30 minutes. Wash and drain.   \nMix the scallions, garlic, ginger, chili pepper, cabbage and the rest of salt. Pack into a crock or glass jar.\nPut the containers aside for three or four days in a cool location. After that, store it in the refrigerator.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(540,'Brownie Cupcakes','https://img.spoonacular.com/recipes/636331-556x370.jpg','120 grams chocolate, 113 grams butter, 250 grams granulated sugar, 1 teaspoon vanilla extract, 3 large eggs, 95 grams all purpose flour, 0.25 teaspoon salt',replace('Preheat oven to 325 degrees F (170 degrees C). Turbo broiler 150 Degrees\nMelt the chopped chocolate and butter in a stainless steel bowl placed over a saucepan of simmering water. Once the chocolate is melted and smooth, remove from heat and let cool for a few minutes\nThen stir (can also use a hand mixer) in the sugar. Add the vanilla and then add the eggs, one at a time, mixing well after each addition. Mix in the flour and salt until well blended.\nEvenly divide the batter between the muffin cups. Place in the preheated oven and bake for about 20 - 25 minutes. For turbo broiler 150 Degrees for 13-15 minutes.\nRemove from oven and let cool on a wire rack. Once the cupcakes have completely cooled, frost with icing.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(541,'Cottage pie with Quorn mince','https://img.spoonacular.com/recipes/640185-556x370.jpg','750 g potatoes, 25 g butter, 3 tbsp milk, 1 tbsp parsley, 400 g quorn mince, 1 medium onion, 1  bay leaf, 2  carrots, 4  garlic cloves, 2  chillies, 2 tsp cumin powder, 1 tbsp rosemary, 400 g canned tomatoes, 200 ml water, 1  veg stock cube, 1  egg, 3 servings salt and pepper, 3 servings oil',replace('Add the stock cube to 200 ml of boiling water and keep aside to dissolve.\nBring a saucepan of water to a boil. Add the potatoes and cook until tender - around  15 to 20 minutes. Drain the potatoes, remove in the saucepan and mash till smooth. Add the butter, parsley and milk, mixing thoroughly. (Add more milk if required)\nPreheat the oven to 200 C. In a large frying pan, heat a tablespoon of oil. Add the onion, carrots, garlic, green chillies and the bay leaf and fry for 4-5 minutes on medium heat. Add the frozen Quorn mince  and the cumin powder and cook for further 5 minutes. Then add in the tomatoes, chopped rosemary and stock. Bring to a boil and turn off the heat.\nRemove the bay leaf and transfer the Quorn mince to an oven proof dish in a single layer. Add the mashed potatoes on the top, covering the quorn mince and fluff the mash layer with a fork. Lightly brush the surface with a beaten egg. Cook in the oven for 20-25 minutes.\n* You can also add a layer of grated cheese on top of the potatoes. Skip the egg if using cheese.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(542,'Roast Chicken with Apples and Rosemary','https://img.spoonacular.com/recipes/658418-556x370.jpg','4  apples, 3  onions, 3 head garlic, 8 sprigs rosemary, 4  lemons, 0.5 cup raimondo sicilian lemon balsamic vinegar, 8 servings seasoning - make a rub, 2  roasting chickens, 1 can stock',replace('Preheat oven to 400 degrees.  Position a rack in the lower third of the oven.  Rinse the chicken, then dry it very well with paper towels, inside and out.\nPlace apples, rosemary, 3 lemons, onions, and garlic in a single layer in shallow roasting pan. Season with salt and pepper. Toss well and pour in the vinegar. Season the chicken well with the rub and place breast-side-up on top of the veggies and fruits. Put the rest of the veggies and fruit in the cavity of the chicken.\nRoast for 30 minutes, until the breast is firm and just beginning to brown in spots. Using tongs, turn the chicken breast-down and roast for 20 minutes longer, until the skin is lightly browned and the thermometer registers 175 to 180.\nTilt the chicken to drain the cavity juices into the pan and remove the goodies from the inside and bottom of pan.  Now transfer the bird to a cutting board. Remove the rack from the pan and spoon off the fat. Set the pan over high heat. Add the stock and cook, scraping up any browned bits and leftover pieces of goodies. Squeeze the last lemon to release the juices. Carve the chicken and pass the chunky jus at the table.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(543,'North Carolina-Style BBQ Pulled Pork','https://img.spoonacular.com/recipes/653308-556x370.jpg','2 cups apple cider vinegar, 3 pounds pork shoulder, 0.75 cup firmly-packed brown sugar, 2 teaspoons butter, 0.5 teaspoon celery salt, 0.5 teaspoon mustard, 0.5 teaspoon garlic salt, 1.5 teaspoons ground pepper, 0.6666667 cup ketchup, 2 teaspoons brown sugar, 3 tablespoons liquid hickory smoke, 0.5 teaspoon onion powder, 3 teaspoons pepper flakes, 12 servings salt, 1 cups water','Prepare the rub:Mix paprika, light brown sugar, celery and garlic salts, dry mustard, black pepper, onion powder and salt in a small bowl. Season the entire pork roast and cover overnight in the refrigerator.Preheat the oven to 325F. Place the pork roast in a large, disposable aluminum roasting pan.In a small bowl, mix together the melted butter and the liquid hickory smoke for the basting marinade. Pour the basting marinade over the pork and cover with aluminum foil. Cook for approximately 4 1/2 hours (or until the pork becomes tender enough to start "pulling" away, turning the pork every hour, and basting every 1/2 hour. Alternatively, cook pork over white hot coals, covered, for 3-3 1/2 hours, basting and turning frequently with basting marinade.Transfer the pork roast to a cutting board. Drain the excess juices from the pan. Slice the pork roast and pull apart the meat (trimming the fat) and place back into roasting pan.Prepare the BBQ sauce: In a large bowl, mix the cider vinegar, water, ketchup, dark brown sugar, salt, and red pepper flakes and pour over pulled pork, stirring to make sure all pork is covered; cover with aluminum foil.Place pulled pork back into the oven (still at 325F) or in pan on grill and cook for 1 1/2 hours, stirring pork and BBQ every 30 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(544,'Mediterranean eggplants','https://img.spoonacular.com/recipes/651407-556x370.jpg','50 g almonds, 4 Tbs bread crumbs, 1  egg, 4 small eggplants, 50 g feta cheese, 4 servings dill, 100 g mozzarella cheese, 2 tablespoons olive oil, 0.5 tsp pepper, 350 g sausage without the casing','Wash eggplants, cut the stems and halve lengthwise. Scoop out the middle.In a bowl mix and combine sausage meat, egg, feta cheese, mozzarella, almonds and pepper.With a spoon, stuff the eggplants.Sprinkle with breadcrumbs (about  tablespoon on each eggplant) and olive oil.Place the eggplants on a baking sheet lined with parchment paper and bake in the oven for 25 minutes on 230C.Serve hot, sprinkled with fresh, chopped dill, chives or basil.',45,45,0);
INSERT INTO "Recipe" VALUES(545,'Wasabi & Honey Glazed-Salmon','https://img.spoonacular.com/recipes/664975-556x370.jpg','1 teaspoon ginger root, 2 tablespoons honey, 1 tablespoon soy sauce, 3 tablespoons mirin, 1 tablespoon rice vinegar, 12 ounces salmon fillets, 4 teaspoons wasabi paste','In a small saucepan over medium-high heat, stir together mirin, vinegar, soy sauce, honey, ginger and wasabi to taste. (Add the wasabi incrementally, tasting as you go.)Bring to a boil. Reduce the heat to medium and cook, stirring occasionally, until glaze thickens slightly, about 5-10 minutes. Remove from the heat.Preheat oven to 425F.Lightly coat an oven-proof skillet with olive oil and heat on medium-high.Season the salmon with a little kosher salt &amp; fresh cracked pepper.When the oil is hot and begins to shimmer, add the salmon, skin side up.Sear, without moving it around for 3-4 minutes.  Turn the salmon over, skin side down.  Brush some of the glaze onto the salmon and then place the skillet of salmon into the oven for about 4 minutes.Spoon the remainder of the sauce over the salmon and serve hot.',20,20,0);
INSERT INTO "Recipe" VALUES(546,'Balsamic Marinated Lamb Chops','https://img.spoonacular.com/recipes/633932-556x370.jpg','4  lamb loin chops, 1 Clove garlic, 0.25 cup balsamic vinegar, 1 Tbs dijon mustard, 1 Sprig each; oregano, 2 servings all of these herbs, 1 Tbs red wine vinegar, 2 Tbs olive oil, 1 Tbs brown sugar, 2 servings kosher salt, 2 servings pepper',replace('In a mixing bowl, mix above ingredients, except salt and pepper. Set aside\nSalt and Pepper the Lamb Chops on both sides on a plate\nToss Lamb in bowl with marinade\nCover and refrigerate at least 1 to 2 hours, turning occaisionally\nGet your BBQ ready! Medium-High, indirect heat\nGrill Lamb Chops on the BBQ to a nice medium rare\n5 to 7 minutes per side, depending on thickness','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(547,'Austrian Goulash','https://img.spoonacular.com/recipes/633063-556x370.jpg','4 pounds beef stew cut meat, 0.5 cup beef stock, 1 can tomato sauce, 1 Tbsp caraway seeds, 1 cup flour, 2  garlic cloves, 2 tsp hungarian paprika, 1 small lemon zest, 12 servings olive oil, 2 large onions, 1 Tbsp mild paprika, 1 Tbsp salt & pepper, 2 Tbsp tomato paste','You will need a large Dutch oven with a lid for best results. Add just enough olive oil to coat the pan and turn the heat high enough to make the oil shimmer, but not smoke.Pat the meat dry and dredge in flour, seasoned with kosher salt &amp; cracked pepper.Add one piece of meat to the hot oil to make sure that it sizzles. Add the remaining meat, without crowding the pan and sear for about 3-4 minutes per side. You want a golden crust that will give the gravy great flavor.Cook the meat in batches, if necessary and set aside in a bowl-- to collect the juice.When all the meat is seared, turn the heat to medium and add a little more olive oil to the pan and cook the onion until tender-- 3-4 minutes. Add the sliced garlic and cook till fragrant-- 30 seconds or so.Add the tomato paste and paprika, and cook for 1-2 minutes.Add the tomato sauce, caraway seeds, lemon zest and chicken stock and stir well.Bring to a simmer for about 15 minutes and taste for seasoning. Adjust as necessary. If the sauce is too thick, thin with a little more chicken stock or water until it is the consistency of a gravy.Simmer for 2 hours, or you can use a slow cooker for 4-6 hours.This stew tastes even better if made one day in advance.',130,130,0);
INSERT INTO "Recipe" VALUES(548,'How to Cook Sweet Potatoes on the Grill','https://img.spoonacular.com/recipes/1077392-556x370.jpg','3 medium sweet potatoes, 4 tbsp butter, 3 tbsp cinnamon',replace('Instructions\n\nHeat up the grill to 350 degrees. \n\nSlice the sweet potatoes into 1" rounds.\n\nSpray both sides of the sweet potatoes with butter and sprinkle with cinnamon. \n\nPlace foil over the grilling grates and place the sweet potatoes directly onto the foil. \n\nSpray the sweet potatoes again with a little butter. (To keep the potatoes from sticking to the foil)\n\nClose the grill lid and cook for about 30 minutes. Make sure to turn and flip the sweet potatoes every 10 minutes and add additional sprays of butter to keep from sticking.','\n',chr(10)),40,40,0);
INSERT INTO "Recipe" VALUES(549,'Steak with lemon and capers','https://img.spoonacular.com/recipes/661531-556x370.jpg','400 g beef steak, 2 tablespoons butter, 2 Tbs capers, 0.75 cup wine, 1 cup flour, 2 large cloves garlic, 0.25 tsp ground pepper, 1 teaspoon lemon juice, 2 servings lemon wedges, 2 Tbs olive oil, 2 teaspoons parsley, 0.75 tsp salt','Flatten the steaks lightly with a meat mallet.Combine flour, salt and pepper, dip steaks into the mixture, coating both sides.Saut the steaks in a hot mixture of butter and olive oil over medium heat, about 4 minutes on each side. Remove from the pan and set aside.Saut the garlic in the same fat for about 1 minute, stirring.Add the wine and lemon juice, stir and simmer for 5 minutes to slightly reduce the liquid.Add capers, stir. Return the steaks to the pan, cover and simmer over low heat for 4 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(550,'Neoguri (Spicy Seafood Ramen)','https://img.spoonacular.com/recipes/653008-556x370.jpg','1  egg, 6  mussels, 1 package neoguri ramen, 1  scallion, 1 sheet seaweed','1. Add mussels and sauce packets into boiling water. Let boil with mussels about 5 minutes to cook and deepen the broth. If using fresh mussels, wait until they open and discard closed mussels.2. Include the noodles and cook for a 2, 3 minutes. Add the beaten egg while stirring noodles in a circular motion for even, flaky egg drops. If wanting a poached egg, carefully add the egg off to the side of the pot.3. Meanwhile, cut scallion into thin pieces along with gim (seaweed) sheet.4. Transfer to a serving bowl and add the scallions and gim (seaweed).',45,45,0);
INSERT INTO "Recipe" VALUES(551,'Easy Shepherd''s Pie (Beef And/or Lamb Combo)','https://img.spoonacular.com/recipes/642091-556x370.jpg','1 cup beef stock, 2 tablespoons butter, 1  carrot, 2 tablespoons cream cheese, 1 large egg yolk, 2 tablespoons flour, 2 tablespoons parsley leaves, 2 teaspoons thyme, 1.75 pounds ground lamb, 0.5 cup 1%% milk, 1 tablespoon olive oil, 1  onion, 0.5 cup to 1 peas, 2 pounds potatoes, 6 servings salt and pepper, 1 teaspoon paprika, 2 tablespoons tomato paste, 2 teaspoons worcestershire','Boil potatoes in salted water until tender, about 12 minutes. Drain potatoes and pour them into a bowl.Combine cream cheese (or sour cream), egg yolk and milk (or heavy cream). Add the cream mixture into potatoes and mash until potatoes are almost smooth.While potatoes boil, preheat a large skillet over medium high heat. Add oil to hot pan with beef and/or lamb.Season meat with salt and pepper. Brown and crumble meat for 3 or 4 minutes. If you are using lamb and the pan is fatty, spoon away some of the drippings.Add chopped carrot* and onion to the meat. Cook veggies with meat 5 minutes, stirring frequently.NOTE:*by finely chopping the carrots, they will cook a little faster.Add the thyme.OPTIONAL Add the tomato paste, which gives the meat filling a richer flavor.In a second small skillet over medium heat cook butter and flour together 2 minutes. Whisk in broth and Worcestershire sauce. Thicken gravy 1 minute. Add gravy to meat and vegetables. Stir in peas.Preheat broiler to high.Fill a small rectangular casserole with meat and vegetable mixture. Spoon potatoes over meat evenly.Top potatoes with paprika and broil 6 to 8 inches from the heat until potatoes are evenly browned. Top casserole dish with chopped parsley and serve',45,45,0);
INSERT INTO "Recipe" VALUES(552,'Mediterranean Orzo Salad','https://img.spoonacular.com/recipes/651426-556x370.jpg','1 pound orzo, 10 servings kosher salt, 0.5 cup pine nuts, 8 tablespoons evoo, 4  green onions, 0.5 cup parsley, 1  lemon zest, 1  cucumber, 1  bell pepper, 1 pint cherry tomatoes, 0.5  onion, 12  pepperoncinis, 1.5 cups feta cheese, 4 tablespoons red wine vinegar',replace('Bring a pot of water to a rapid boil. Generously salt water and cook orzo until tender, approximately 7-9 minutes. Drain and set aside.\nWhile orzo is cooking, spread pine nuts on a baking sheet and toast lightly in oven on 400 degrees. Remove from oven and set aside.\nHeat two tablespoons of EVOO on medium heat in a non-stick pan. Saute chopped green onions for approximately 2 minutes. Add parsley, lemon juice, lemon zest, toasted pine nuts and cooked orzo. Saute for 3-4 minutes for flavors to combine and absorb into the orzo. Remove from heat.\nIn a large bowl, combine cucumber, green bell pepper, cherry tomatoes, red onion and pepperoncinis to orzo mixture. Additionally add crumbled feta cheese, red wine vinegar and remaining six tablespoons of EVOO. Mix well. Can be refrigerated or served immediately.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(553,'Lemony Zucchini Fritters','https://img.spoonacular.com/recipes/631754-556x370.jpg','2 tbsp breadcrumbs, 2  eggs, 0.5 cup flour, 1 tsp garlic powder, 1  juice of lemon, 4 tbsp olive oil, 1 tsp onion powder, 1 tbsp parmesan cheese, 0.5 cup parsley, 1 tsp pepper, 3 servings greek yogurt, 16 oz zucchini','Chop the zucchini into small pieces. Place in food processor and pulse until there are small bits left. (If you have a grating attachment on your food processor you can use that instead).In a medium bowl add zucchini, lemon juice, parsley, flour, eggs, spices, Parmesan cheese, and breadcrumbs. Mix together until evenly distributed.Place olive oil in a large frying pan and heat over medium high heat. Working in batches, add a little less than a cup of batter to the frying pan for each fritter. Cook until golden brown on the bottom, about 45 seconds. Flip over and cook until golden brown on the other side.Place a few layers of paper towel on a baking sheet or plate. Once fritters are done, transfer to the lined baking sheet or dish and let the paper towel soak up extra oil.Garnish with more lemon juice and a dollop of Greek yogurt before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(554,'Fried String Cheese Sticks','https://img.spoonacular.com/recipes/643809-556x370.jpg','4  individual string cheese sticks, 0.25 cup flour, 1 tablespoon egg +2 water, 0.5 cup seasoned bread crumbs, 1 serving vegetable oil',replace('Dredge individual cheese sticks in flour. shake off excess.\nRoll sticks in egg wash,\nThen coat with bread crumbs.\nFry in hot oil for 20 seconds, then flip and fry another 20 seconds.\nServe with Pizza sauce or marinara!!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(555,'Guacamole','https://img.spoonacular.com/recipes/645988-556x370.jpg','2 large haas avocados, 2 tablespoons onion, 1 tablespoon jalapeno pepper, 0.25 cup cilantro, 0.5 teaspoon salt, 0.125 teaspoon pepper, 1 tablespoon lime juice, 1 teaspoon basil, 1 teaspoon oregano',replace('Cut the avocados in half lengthwise. Drive chef''s knife into large pit and twist to remove.  Scoop the avocado out from the skin into a bowl.\nMash the avocado with a fork, add in onion and cilantro, oregano and basil..  Mix to incorporate.\nSeason to taste with salt, pepper and lime juice.\nServe immediately or chill.  If you are not going to eat the guacamole immediately, store in refrigerator with plastic film wrap pressed onto the guacamole.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(556,'Warm Duck Salad With Roasted Beetroot','https://img.spoonacular.com/recipes/664960-556x370.jpg','500 g duck breast meat - skin left on, 300 g baby beets, 1  orange zest, 2 teaspoons honey, 1 teaspoon salt, 3 cups arugula greens, 4 tablespoons pine nuts, 1 can mandarin orange segents, 1 Bunch mint, 4 servings feta cheese, 6  juice of orange, 2 tablespoons extra virgin olive oil, 4 teaspoons balsamic vinegar, 4 servings salt and pepper',replace('Pre-heat the oven to 200 deg Celsius (400 F).\nStart by roasting the beetroots. Clean the beets of all mud and trim the stems. Wrap each beet tightly in aluminum foil. Place the wrapped beets on a pan and in a 200 deg Celsius oven for 30 to 40mins. They are done when they are very tender.\nWhile the beets are cooking, use a peeler and peel an orange, taking note to get as much of zest and as little of pith (the white parts) as possible. Stack the strips of orange zest and cut into fine strips with a sharp knife. Set aside.\nClean and dry the duck breasts. Score the skin of the duck. Make cuts into the fat layer and take care not to cut into the meat layer. Rub some salt into the skin side only of the duck. Add the duck breasts to a clean and COLD pan. Do not add any oil. Place the pan on the stove and turn the heat to medium.\nAs the pan heats up, the fat from the duck will render off and the skin will brown beautifully. Always keep the heat to between medium to medium-high. Never use high heat as the skin will burn before the duck is cooked through. Once the skin is a gorgeous dark golden brown, flip the duck breasts to the other side and cook for a few more minutes till the other sides are also golden brown. Be careful not to overcook the duck. Set the cooked duck aside and leave to rest covered with foil. Duck, like beef must be rested. The resting time is half that of cooking time. If the duck was cooked for 6 mins, then it should be rested for at least 3 minutes.\nWhile the duck is resting, make the vinaigrette. Squeeze the juice of the zested orange into a bowl. About 5 to 6 tablespoons of juice. Add 2 tablespoons of extra virgin olive oil. Use the best quality one you have. Add 4 teaspoons of balsamic vinegar. Add salt and pepper to taste. Whisk the mixture well. Set aside.\nWhen the beets are done, remove them from the oven and let them cool for a few minutes so that they are easier to hold. Put on some disposable gloves (else get blood red stained fingers later). Open the foil-wrapped beets. Using the rough surface of each piece of foil, rub the beets with the foil to remove the skin. Cut the cooked beets into small pieces. Set aside in a bowl.\nDrizzle 2 tablespoons of vinaigrette into the beets. Add 2 teaspoons of honey. Toss well to coat the beets with the dressing.\nSlice the rested duck into thin slices. The meat should be a beautiful pink.\nServe by layering the salad with greens, nuts and cheese of your choice, and the duck and beets.\nI like rocket greens with fresh basil or mint, mandarin orange segments, toasted almond flakes or pine nuts and some shaved parmesan cheese or some crumbed feta or goats cheese.\nGarnish with the orange zest.\nTrickle the vinaigrette over the salad.\nBest served immediately.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(557,'Slow Cooker Chicken Taco Soup','https://img.spoonacular.com/recipes/715391-556x370.jpg','15 oz black beans, 20 oz tomatoes, 15 oz canned tomatoes, 15 oz chili beans, 15 oz kernal corn, 1 large onion, 3  chicken breasts','Once you have all of your ingredients added, allow it to cook all day for 8 hours on low. If you are wanting to make this a little faster, turn it on high and cook for 4 hours.When your Chicken Taco Soup is ready to serve, add in some crushed tortilla shells, shredded cheddar cheese, and a little sour cream.',485,485,0);
INSERT INTO "Recipe" VALUES(558,'Upside Down Chicken Cake','https://img.spoonacular.com/recipes/664244-556x370.jpg','180 g strips., 2 tablespoons butter, 60 g canola oil, 0.5  carrot, 0.25 tsp chicken powder, 20 servings chicken stock), 2  eggs, 40 g ice water, 0.5  onion, 1 dash pepper, 45 g flour, 0.25 teaspoon salt, 150 g sponge cake mix, 1 stalk spring onion, 150 grams sugar, 0.5 tsp vanilla extract, 1 tsp ovalette, 1 tsp ovalette','Heat up butter, add onion and fry till fragrant. Add in carrot and chicken cubes, fry well and add seasoning.Sprinkle 1 tbsp plain flour over it, stir well and add chicken stock. Bring mixture to boil, turn off heat and add spring onion and a dash of pepper, mix well and set aside to cool.In the mixing bowl put all the ingredients into it except melted butter and whisk at maximum speed till batter becomes thick and white.Lower speed and gradually add in melted butter or canola oil, mix well.Line cake pan with non stick baking paper at the bottom and grease some butter at the sides of the pan. Add cooked chicken mixture into the two pans evenly, then pour batter into it.Bake at preheated oven at 180 degrees for 25 - 30 minutes or skewer into the center of the cake and comes out clean.Remove the cakes immediately from the pans after baked and place on wire rack.Best to serve warm.',45,45,0);
INSERT INTO "Recipe" VALUES(559,'Saffron Chicken Tikka','https://img.spoonacular.com/recipes/658967-556x370.jpg','350 grams chicken breasts, 0.5 inch cinnamon stick, 1  cardamom seeds, 2  cardamom seeds, 5  cloves, 2  chillies, 0.5 tsp garlic paste, 0.5 tsp ginger paste, 8  pepper corns, 1 pinch saffron, 2 tsp milk, 3 servings salt, 9  skewers, 9  skewers',replace('Soak saffron in warm milk for 15 to 20 minutes.\nIn the meantime, dry roast the cinnamon stick, black cardamom seeds, green cardamom seeds, pepper corns and cloves. Pound them to a powder (not very fine).\nIn a mortar and pestle grind the green chillies to a paste. (Using a pinch of coarse salt will help)\nMix all the ingredients together and your marinade is ready.\nEnsure that you pat dry the chicken cubes.\nTransfer the chicken in a bowl\nAdd the marinade to the chicken cubes and mix it well so that all pieces are well coated.\nCover the bowl with a cling film and put it in the refrigerator.\nLeave the chicken to marinate over-night. (I marinated for almost 18 hours and the result was moist and tender chicken tikkas)\nFor Grilling:\nI grilled these tikkas in my non-stick grill pan. Using a non-stick pan helped me keep the amount of oil to minimal.\nSoak the skewers in water for at least half an hour before you intend to serve them.\nNow take the skewers and start skewering the chicken pieces on them. I leave a little space in between the chicken pieces; else they stick together and do not get cooked well. (Perhaps the reason could be pan grilling)\nKeep the skewers ready and then heat the pan (medium hot).\nYou can use an oil spray or pour a little oil using a spoon in a linear fashion across the grill pan.\nPlace the skewers over the oiled pan and grill them on medium low heat.\nIt will take approximately 45 seconds to a minute for one side to get cooked.\nThen turn around and cook the other side the same way.\nServe them hot as a starter or as a main course with Bakarkhani!! Bon apptit!!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(560,'Barnaby''s Caesar Salad','https://img.spoonacular.com/recipes/634345-556x370.jpg','1 tablespoon anchovy paste, 0.5 loaf ciabatta, 1  juice of lemon, 1 cup olive oil, 1.5 cups parmigiano reggiano cheese, 4 servings cracked pepper, 1 large head romaine lettuce','Combine lemon juice and anchovy paste in a blender.Start blender and drizzle olive into mixture until it thickens.Cut bread into 1 inch cubes and toast until brown. The trick here is to have it crispy on the outside and soft on the inside.Combine lettuce and bread cubes in a salad bowl and cover with Parmigiano Reggiano (Parmesan) cheese.Pour dressing over top and toss.',45,45,0);
INSERT INTO "Recipe" VALUES(561,'Refreshing Strawberry Limeade','https://img.spoonacular.com/recipes/658152-556x370.jpg','1.5 cups strawberries, 0.5 cup sugar, 30 ml lemon lime soda, 60 ml seltzer, 4 servings turbinado sugar, 1  juice of lime, 4 servings limes, 4 servings ice',replace('Add berries and sugar to a bowl and let macerate for about 30 minutes.\nAdd berries to a food processor (or blender) and pulse until smooth.\nIn a large pitcher add ice (about 1/3 of the way), then top with 2 parts seltzer to one part lemon lime soda.\nStir in a few scoops of strawberry puree and add juice from 1 lime.\nStir well then taste. Add more strawberry and lime juice if needed.\nI add thinly slice lime to the pitcher and garnish the glasses with lime wedges and a sugared rim.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(562,'Minestrone','https://img.spoonacular.com/recipes/651922-556x370.jpg','6 tablespoons butter, 4  carrots, 3 Stalks celery, 2  onions, 1 Clove garlic, 1 Head cabbage, 1  canned tomatoes, 8 cups water, 1 cup brown rice, 1 teaspoon salt, 1 tablespoon worcestershire sauce, 1 teaspoon seasoning, 0.25 teaspoon pepper, 4  potatoes, 4  beef bouillon cubes, 2  zucchini, 2 can kidney beans, 10 ounces spinach, 0.75 cup parmesan cheese',replace('Melt butter in large soup kettle; saute carrots, celery, onions, garlic, and cabbage, about 20 minutes; stir often. Add tomatoes, water, rice, seasonings, potatoes, bouillon cubes and zucchini. Bring to a boil. Reduce heat and simmer covered, at least 30 minutes. Add beans and spinach; return to a boil and cook over medium heat until spinach is cooked; add more water if needed. Garnish with Parmesan.\nServes 9','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(563,'Smokey Rainbow Chili','https://img.spoonacular.com/recipes/660395-556x370.jpg','2 tablespoons olive oil, 2 small zucchini, 1  bell pepper, 1  orange bell pepper, 1  jalapeno pepper, 4 cloves garlic, 1  onion, 28 ounce stewed tomatoes, 6 ounce tomato paste, 15 ounce black beans, 15 ounce kernel corn, 15 ounce kidney beans, 0.5 tablespoon paprika, 1 teaspoon chili powder, 0.5 teaspoon oregano, 0.5 teaspoon ground pepper, 0.25 teaspoon cayenne pepper',replace('(if using meat...brown the meat really well, remove and set aside.  Add the meat after sauteing the veggies)\nHeat oil in a large pot over medium-high heat. Stir in zucchini, red bell pepper, orange bell pepper, jalapeno, garlic, and onion. Cook 5 minutes, just until tender.\nAdd tomatoes with liquid, tomato paste, black beans, corn, and kidney beans into the pot. Season with smoked paprika, chili powder, oregano, black pepper, and cayenne pepper. Bring to a boil.\nReduce heat to low and simmer 1 hour, stirring occasionally.  (depending on how big you cut the veggies, you may want to let it simmer a little longer)','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(564,'Beef Braised In Red Wine','https://img.spoonacular.com/recipes/634588-556x370.jpg','0.25 pound bacon, 3 lb beef chuck roast, 1 medium carrot, 2 rib celery, 2 cups full-bodied wine, 4  garlic cloves, 1 tablespoon olive oil, 1 medium onion, 0.5 teaspoon pepper, 2 sprigs rosemary, 1 teaspoon salt, 4 sprigs thyme, 3 teaspoons tomato paste, 0.25 cup water','Put oven rack in the middle and preheat oven to 325Heat oil in a large dutch oven until hot but not smoking. Meanwhile, pat meat dry and season with salt and pepper. Brown meat on both sides for about 10 minutes total. ( if the bottom of your pan starts to scorch turn down the heat some).Remove meat from pan and let rest on a plate. Add bacon to pan and saute until browned.Add the veggies and cook until they are softened and golden brown.Add garlic, thyme, rosemary and saute for 1 minute. Then add tomato paste and stir in and cook for 1 minute. Add wine and boil until liquid is reduced by half.Add water to the pan and bring to a simmer. Return meat and any juices to the pan. Cover the pot with the lid and transfer to the oven.Cook for 2 1/2 to 3 hours or until meat is very tender.Remove from pan and slice across the grain. Serve on top of potatoes or grits and top with sauce from pan.',45,45,0);
INSERT INTO "Recipe" VALUES(565,'Cranberry Orange Biscotti','https://img.spoonacular.com/recipes/640395-556x370.jpg','1.5 teaspoons baking powder, 0.75 cups confectioners'' sugar, 0.75 cup cranberries, 4  eggs, 2 cups flour, 0.25 cup orange juice, 0.5 tablespoon orange zest, 8 ounces pecans, 0.75 teaspoon salt, 1 cup sugar, 0.25 cup butter, 1 teaspoon vanilla extract, 1.25 cup pastry flour','Preheat the oven to 350F degrees, and position the oven racks in the upper and lower thirds positions. Line two baking sheets with parchment paper.In the bowl of an electric mixer fitted with the paddle attachment, beat the butter with the sugar on medium speed until light. Add the eggs, one at a time, beating well after each addition and stopping to scrape down the sides of the bowl as necessary. Continue to beat the mixture for 2 minutes more. Beat in the orange zest and vanilla extract.In a medium bowl, whisk together the flour, baking powder, and salt. Add the dry ingredients to the wet ingredients and mix until just incorporated. On low speed, mix in the cranberries and the pecans.Transfer the dough to a very lightly floured work surface, and divide it into 3 equal pieces. Shape each piece into a 12-inch log, spacing two of the logs apart on one of the prepared baking sheets and the third log on the second sheet.Bake the logs for 15-18 minutes, until golden on top and lightly cracked. Transfer the positions of the baking sheets halfway through the baking process. Remove the sheets from the oven and allow to rest for 10 minutes. Reduce the oven temperature to 300F degrees.Using a serrated knife, cut each log on the diagonal into 3/4-inch slices. Lay the slices on their sides and return the baking sheets to the oven for 10-15 minutes, or until lightly golden.Prepare the glaze: In a medium bowl, whisk together the confectioners sugar, and enough orange juice to make a pourable glaze. Drizzle the glaze over the warm biscotti, then allow the biscotti to rest until the glaze has set.Makes 48 Cookies',60,60,0);
INSERT INTO "Recipe" VALUES(566,'How to Make the Cheesiest Bowtie Mac and Cheese','https://img.spoonacular.com/recipes/715595-556x370.jpg','1 package bowtie pasta cook as directed, 1 cup extra sharp cheddar cheese, 1 cup extra sharp cheddar cheese, 1 tsp salt and pepper, 0.25 cup cream, 0.25 cup butter, 4 servings parsley',replace('Instructions\n\nStep 1: Heat your oven to 350 degrees Fahrenheit, and then cook your pasta as directed. Drain.\n\nStep 2: Shred the cheese. Add cooked noodles, cheese, sour cream, salt and pepper, and butter to a medium mixing bowl and stir until combined.\n\nStep 3: Add to a 9 x 13 prepared casserole dish, top with extra cheese if desired, and bake for 20 minutes.\n\nStep 4: Remove from oven and serve hot.','\n',chr(10)),35,35,0);
INSERT INTO "Recipe" VALUES(567,'Easy Slow Cooker Whole Chicken With Rosemary','https://img.spoonacular.com/recipes/1062882-556x370.jpg','4.5 lb chicken, 1 tbsp olive oil extra virgin, 2 large lemons, 1 medium onion, 1 tsp paprika, 1 tsp pepper, 1 bunch rosemary, 1 tsp salt, 2 tbsp butter, 0.5 cup water','InstructionsCombine all seasonings in a small bowl, reserving half of the rosemary. Baste the chicken with unsalted butter and olive oil and then cover with seasonings. Add half of the onion, lemons, and rosemary to the inner cavity of the chicken. Roll up three small lemon-sized balls of foil and place in the bottom of the slow cooker. Place half of lemons and onion with water into the bottom of the slow cooker. Add remaining rosemary to the top of the chicken.Cover and cook on low for 7-8 hours, or high for 4-5 hours.',430,430,0);
INSERT INTO "Recipe" VALUES(568,'Green Bean Poriyal','https://img.spoonacular.com/recipes/795431-556x370.jpg','0.5 teaspoon asafetida, 1 teaspoon brown mustard seeds, 1 teaspoon chana dal, 2 teaspoons coconut oil, 1 teaspoon cumin seeds, 1 small handful curry leaves, 1  chili, 0.5 teaspoon sea salt, 2 tablespoons tamarind pulp, 4 tablespoons coconut, 1 teaspoon skinned urad dal','Soak the tamarind pulp in 2/3 cup boiling water for 40 minutes. Strain the tamarind into a small bowl, pressing down on the pulp to squeeze as much liquid as you can. Set the drained tamarind liquid aside.In a large frying pan or wok, heat the oil over medium heat until hot. Add the mustard seeds and cumin seeds to the pan and cook for a few minutes. Now add the urad and toor or chana dals, chilli, asafetida and curry leaves. Fry for another few minutes until the mustard seeds turn grey and begin to splutter and pop.Now add the green beans, about 3 tablespoons of the tamarind water, and salt. Reduce the heat to medium-low and cover. Cook until the beans are tender, about 5 to 7 minutes. Stir in the coconut and cook for another few minutes.Remove from heat and taste for seasoning. Serve warm alongside some fresh cooked white rice and your favorite dal dishes.',45,45,0);
INSERT INTO "Recipe" VALUES(569,'Brussel Sprouts in Bacon and Garlic Sauce','https://img.spoonacular.com/recipes/636359-556x370.jpg','250 g brussel sprouts, 0.5 teaspoon salt, 4 cups water, 1 tablespoon butter, 1 tablespoon garlic, 1 tablespoon bacon bits, 0.25 teaspoon salt and pepper, 1 teaspoon lemon juice',replace('Wash 250g of brussel sprouts. Remove any old hard out leaves.\nBring 4 cups of water to the boil and add 1/2 teaspoon of salt.\nAdd the brussel sprouts to the boiling water and leave to boil at medium heat for 4 minutes or until sprouts are tender but still crunchy.\nDrain the brussel sprouts.\nReturn the saucepan to the hot stove and add 1 tablespoon of butter.\nWhile the butter is melting, cut the brussel sprouts in half.\nAdd 1 tablespoon of minced garlic to the melted butter. Saut for a few seconds till garlic is fragrant but not brown.\nReturn the cut brussel sprouts to the saucepan. Toss the brussel sprouts lightly in the garlic-butter sauce.\nAdd 1 tablespoon of bacon bits. I keep a jar of ready to use bacon bits in the fridge at all times for this dish (and for my Mushroom Delight dish). You can also use freshly pan fried and crumbled bacon, but I like to cook this fast.\nSeason to taste with salt and pepper. I always use Masterfoods Garlic Pepper to season my dishes. A few shakes of this and its done.\nAdd a squeeze of fresh lemon juice (about 1 teaspoon).\nToss everything together. Serve with some fresh lemons on the side for extra tangy flavour, if preferred. You can also garnish with some toasted almond flakes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(570,'Cake with wine and olive oil','https://img.spoonacular.com/recipes/636768-556x370.jpg','200 g cake flour, 1  sachet yeast, 1 pinch salt, 150 g sugar, 3  eggs, 1  yolk, 100 ml white wine, 100 ml olive oil, 100 g icing sugar, 150 ml lemon juice',replace('Mix flour, yeast and salt.\nIn another bowl, beat with a hand mixer sugar, eggs and a yolk for 3-4 minutes until pale yellow and foamy.\nGradually stir in wine and olive.\nAdd the flour with yeast, mix and combine until smooth.\nGrease a small baking tin and cover with parchment paper. Pour the cake batter and bake in the oven at 180C for 40 minutes.\nMeanwhile, mix powdered sugar with lemon juice, and stir until the sugar has completely dissolved.\nWhen done, leave the cake to cool a little, pour the syrup over it, cut into squares and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(571,'Broccoli Rabe and Breaded Veal Scallopini','https://img.spoonacular.com/recipes/636207-556x370.jpg','500 g broccoli rabe, 2 tablespoons butter, 1  egg, 4 servings olive oil, 4 servings salt and pepper, 1 small onion','Wash and steam the broccoli rabe for a few minutes (3 or 4) in a pressure cooker.Thinly slice the onion. Peel the garlic clove, cut in half and remove the stem.Heat up 1 or 2 tbsp olive oil in a deep pan.Saut the onion and garlic for a few minutes on medium heat until translucent.Add the broccoli rabe, close with a lid and cook for a few minutes.Cut the tomatoes in 4 or 8 wedges depending on their size, add to the pan and cook several more minutes.Season with salt and pepper and serve.Proceed as follows with each scalopini:Season with salt and pepper.Dip in beaten egg.Dip in bread crumb and cover evenly.Pan fry in a good amount of butter (add more butter before flipping as the bread crumb will absorb it), 1 or 2 minutes on each side over high heat.',45,45,0);
INSERT INTO "Recipe" VALUES(572,'Peruvian Roast Chicken','https://img.spoonacular.com/recipes/655793-556x370.jpg','3 lb chicken, 4  garlic cloves, 0.5  juice of lemon, 3 tablespoons red wine vinegar, 1 tablespoon soy sauce, 3 tablespoons olive oil, 2 tablespoons paprika, 1 tablespoon cumin, 1 teaspoon turmeric, 4 servings salt, 4 servings pepper, 1 serving kitchen twine, 4 servings kitchen twine',replace('1. Mix together the marinade ingredients.\n2. Place the whole chicken into a large (about 2 gallon size) ziploc bag and pour in the marinade.\n3. Spread the marinade so that it covers all the chicken.\n4. Marinade overnight.\n5. Take the chicken out of the fridge about 30-45 minutes before you roast it, so it comes closer to room temperature. This helps the chicken become more moist and cooked evenly.\n6. Preheat the oven to 450F.\n7. Remove the chicken from the marinate and brush off any garlic so it will not burn.\n8. Lay the chicken breast side up in a roasting pan or cast iron skillet.\n9. Truss the chicken. This keeps the juices in during the roasting and makes the meat more tender.\n10. Roast 45-55 minutes.\n11. Let rest 5 minutes before carving.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(573,'Kale & chickpea stew with cumin, smoked paprika and lime','https://img.spoonacular.com/recipes/648709-556x370.jpg','0.5  a bunch of kale, 1 cup chickpeas, 2 medium sweet potatoes, 6 servings olive oil, 1  shallot, 1 large clove garlic, 1 t basil, 0.5 t pepper flakes, 0.5 cup beer, 2 T golden raisins, 1 t paprika, 1 t cumin, 1 Tbsp butter, 1  juice of lime, 6 servings salt & pepper',replace('Warm a few tablespoons of olive oil in a large frying pan over medium heat. Add the shallots, garlic, red pepper and basil and cook till the shallots and garlic start to brown.\nAdd the sweet potatoes and cook till they start to brown and soften. Add the beer. Cook till its thick and syrupy.\nAdd the chickpeas, paprika, cumin, raisins and about 2 cups of water. Bring to a boil and reduce heat and simmer till the sweet potato is nice and soft. You might need to add a cup or two more water as you go along, to keep it a consistency that you like.\nChop the kale into small pieces and add to the stew. Cook until everything is mixed and hot through.\nAdd the butter and lime juice and season with salt and pepper.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(574,'Moist Vegan Spelt Bran Muffins','https://img.spoonacular.com/recipes/652239-556x370.jpg','0.25 cup ground flaxseed, 0.5 cup water, 1 cup wheat bran, 1 cup spelt bran, 0.5 cup spelt flakes, 1 cup spelt flour, 0.5 cup psyllium fibre husks, 0.5 teaspoon stevia extract powder, 0.25 cup flaxseeds, 2 tablespoons chia seeds, 2 teaspoons baking soda, 0.5 teaspoon sea salt, 0.5 teaspoon nutmeg, 1 teaspoon cinnamon, 0.25 cup demerara sugar, 3 tablespoons agave nectar, 0.33333334 cup applesauce, 2  equivalent of eggs in ener-g egg replacer powder, 1 cup vegan" milk, 0.33333334 cup canola oil, 0.5 cup raisins, 0.33333334 cup prunes',replace('Preheat oven to 400F, line 24 muffin cups or grease well.\nIn a small bowl, whisk together flaxseed and hot water. Let stand 10 minutes.\nIn a medium bowl whisk together brans, spelt flakes, flour, psyllium, stevia, flaxseeds, chia seeds, baking soda, salt, nutmeg and cinnamon.\nIn a large bowl beat together sugar, agave, applesauce, egg replacer, flax mixture, "milk" and oil until smooth.\nAdd dry ingredients and stir in just to combine, then fold in the raisins (with their reserved liquid) and prunes.\nBake for 15-17 minutes.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(575,'15 Minute Healthy Dark Chocolate Truffles','https://img.spoonacular.com/recipes/631841-556x370.jpg','15  dates, 0.75 cups slivered almonds, 0.5 cup pecans, 0.25 cup cocoa powder, 1 teaspoon vanilla extract, 1 tablespoon agave nectar, 0.25 teaspoon sea salt, 1 cup water, 12 servings optional: coconut flakes',replace('Soak the dates in hot water while you get the rest of the ingredients and start on step 2 (about 5 minutes). The water should be hot to the touch but not hot enough to burn you.\nProcess the almonds in a food processor until coarse almond meal is formed. Add the pecans and process until they are ground up into a coarse meal as well.\nDrain the dates and use your hand to squeeze out excess water. Add the drained dates, cocoa powder, vanilla extract, agave nectar, and salt to the food processor. Process until a smooth paste forms.\nUse a tablespoon measure to help you form the truffles. Pack a heaping tablespoon of the mixture into the tablespoon measure  really pack it in there. Use your fingers to slide the half-rounded ball out of the tablespoon measure, and then use your hands to form a tightly packed ball of truffle goodness. Be gentle with them  I found that they fall apart if you try to roll them into balls. It is best to squish them with your hand into perfect little spheres.\nForm truffles until you use up all the mixture. The last bit that was not enough for a truffle went straight into my mouth. :)\nIf you choose to, gently roll the truffles in the toppings of your choice. I had some turtle crunch sprinkles, unsweetened coconut flakes, and extra cocoa powder. The cocoa powder definitely gives the the truffles an extra dark chocolate kick, so if you dont like the bitterness of the cocoa powder then dont use that as a topping.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(576,'Avocado Chocolate Bits Frozen Yogurt','https://img.spoonacular.com/recipes/633139-556x370.jpg','2 cups milk, 0.75 cup sugar, 0.5 teaspoon vanilla extract, 4 large egg yolks, 1 cup whole-milk yogurt, 12 oz firm-ripe avocados, 0.5 tablespoon lemon juice, 1 cup bittersweet chocolate, 4 servings condensed milk',replace('Heat milk and sugar over medium heat in a medium saucepan until just comes to a boil, stirring occasionally.  Stir in the vanilla.\nHave ready a large bowl filled with ice and set a small metal bowl over the ice with a strainer set over it.\nPlace egg yolks in a medium bowl, lightly beaten.  Ladle some of the milk into the egg yolk, whisk it to prevent curdling.  Pour this mixture back into the rest of the milk in the saucepan.  Cook over low-medium heat until mixture is thick and can cover the back of a wooden spoon, about 4 to 8 minutes.\nPour the mixture over the strainer into the small bowl; stir in the yogurt.  Whisk the mixture over the ice bath until it cools completely.\nScoop the avocado meat and puree in a blender or food processor along with the lemon juice and some of the cooled custard.  Pour this mixture back to the rest of the custard, blend them together until it is thick and creamy.\nFreeze the custard in an ice cream maker according to the manufacturers instructions.  Halfway through the freezing process, fold in the chopped bittersweet chocolate.  Transfer the frozen yogurt into a freezer-safe container and freeze until solid, at least 4 hours.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(577,'Shrimp and Cucumber Lettuce Wraps With Fresh Dill','https://img.spoonacular.com/recipes/659929-556x370.jpg','8 ounces shrimp, 0.25 cup vegetable broth, 4 cloves garlic, 2 tablespoons white wine vinegar, 1  cucumber, 2 tablespoons dill, 1 small juice from lemon, 8 servings salt and pepper, 8 pieces butter lettuce',replace('Place chicken broth in a skillet and heat to medium-high heat. Add garlic. Cook for a minute or so, then add shrimp. Cook until shrimp are pink and opaque, about 3-5 minutes. Remove shrimp from pan and set aside to cool. Add vinegar to skillet and let the sauce reduce to about a third.\nWhen shrimp are cool enough to handle, remove all the tails and chop coarsely. Combine chopped shrimp in a medium bowl with reduced pan juices/garlic, diced cucumber, dill, lemon juice, and a few pinches of salt and pepper. Spoon filling into lettuce leaves, sprinkle with a little cheese, and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(578,'Aromatic perch fillets','https://img.spoonacular.com/recipes/632726-556x370.jpg','6  bay leaves, 1 tablespoon peppercorn, 0.5 teaspoon cardamom, 1 pinch cinnamon, 100 grams corn flour, 1 tablespoon flour, 4 cloves garlic, 0.25 teaspoon ground nutmeg, 0.5 teaspoon ground paprika, 0.5 teaspoon ground pepper, 300 milliliters beer, 0.5 cup peanut oil, 500 grams perch fillets, 0.5 tablespoon sea salt, 1 tablespoon seasoning mix','Mix flour and corn flour, salt and pepper.Prepare the seasoning mix: finely grind all the spices (in a coffee mill, for example). Since you do not need the whole quantity, store the mix in an airtight glass bottle and refrigerate for future use.Add the seasoning to flour mixture, stir.Slowly add beer, whisking constantly until a batter consistency.Coat filets with batter and fry in hot oil about 3 minutes on each side or until golden brown. Set aside to a warm place.From the remaining batter form small pancakes and fry in the same oil. They make great accompaniment to the fillets.Serve immediately with potato salad.',45,45,0);
INSERT INTO "Recipe" VALUES(579,'Hyderabadi baghara Baingan','https://img.spoonacular.com/recipes/647679-556x370.jpg','4 servings baby eggplants- 10-12, 4 servings kashmiri chilies- 3-4, 3 tbsp coconut, 1 tbsp coriander seeds, 1 tsp cumin seeds, 4 servings curry leaves- 8-10, 2 cloves garlic, 1 piece ginger- 1, 4 servings tamarind- a lime sized, 1 tsp oil, 1 large onion, 4 servings salt, 0.5 tsp nigella seeds, 1 tsp sesame seeds, 0.25 tsp turmeric, 2 tsp jaggeryns, 2 tbsp peanutsns, 2 tbsps cashewnuts, 2 tbsps cashewnuts','Wash the eggplants and pat them dry. Slit the eggplants length wise into fours but keep the stems intact. This way, the egg plants remain joined at the stem. Keep aside.Heat a tspn of oil in a separate pan and add the cumin seeds, peanuts and cashew nuts and fry for a few seconds. Add ginger, garlic and chopped onion and fry for a min. Add the turmeric, coriander seeds, coconut and Kashmiri red chilies and fry till the mixture is brown. Allow the mixture to cool completely and blend to a fine paste using a little water and keep aside.Heat oil in a thick bottomed pan and fry the egg plants till brown and tender, remove and keep aside.Add the nigella seeds to the same oil and allow them to crackle. Stir in the curry leaves and fry for a few seconds. Add the ground paste, tamarind pulp, salt and jaggery and mix well.Add the sauted egg plants and 1/2 cup of water and cook covered over low heat till the egg plants are cooked through and soft.Serve the curry hot with either rice or rot is.',45,45,0);
INSERT INTO "Recipe" VALUES(580,'Greek Yogurt Chicken Salad','https://img.spoonacular.com/recipes/645384-556x370.jpg','0.5 cup cashews, 1 pound chicken breasts, 0.33333334 cup craisins, 2 teaspoon dijon mustard, 4 servings garlic powder, 0.5 cup greek yogurt, 4 servings salt','Start by cooking some chicken breasts. I like boiling them in chicken broth or stock, but feel free to boil in water, too. Boiling the chicken in broth, however, will give it significantly more flavor. Bring the chicken broth/stock to a boil and put in whole chicken breasts. Cook until no pink remains. Depending on the size of the chicken breasts, this could take anywhere from 15 - 20 minutes.While the chicken is boiling, put together your sauce. Whisk together greek yogurt, dijon mustard, and garlic powder together until well mixed. Add in salt and pepper, to taste.Next, stir in dried cranberries or raisins and cashews. If you''re worried about the cashews getting too soft, you could add them right before serving!After the chicken is done boiling, I like to let it rest for about 5 minutes. This ensures that the juice stays in the chicken instead of spilling out when you cut it!Dice up the chicken and mix it into the sauce. Serve.',30,30,0);
INSERT INTO "Recipe" VALUES(581,'Braised Pork: Filipino Humba','https://img.spoonacular.com/recipes/635856-556x370.jpg','0.5 gram pork belly, 0.5 gram pork butt shoulder, 1 head garlic, 0.5 cup vinegar, 4 tablespoons brown sugar, 4 tablespoons soy sauce, 2 pieces bay leaf, 1 tablespoon rice wine, 2 pieces star anise, 0.5 teaspoon oregano, 3 tablespoons fermented black beans, 1 cup peanuts, 0.5 cup olive oil, 0.5 teaspoon paprika, 2 cups water, 4 servings fried bananas',replace('In a bowl, combine these ingredients:meat,garlic,vinegar,brown sugar,soy sauce and rice wine.Marinate for about 30 minutes.Set aside in the fridge.\nAfter 30 minutes, transfer to a sauce pan and add: water,black beans and peanuts.\nCover and bring to a boil, once its boils, turn the heat to a simmering mode and add the rest of the ingredients: bay leaf,star anise,oregano,paprika and olive oil.\nCover and simmer for 1 hour or until the sauce thickens.\nYou can add fried bananas five minutes before turning off the heat or serve it separately.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(582,'Asian Lettuce Wraps','https://img.spoonacular.com/recipes/632847-556x370.jpg','6 servings broccoli slaw, 0.25 cup chicken stock, 2 Tablespoons coconut aminos, 2 Cloves garlic, 1 leaf lettuce, 1 teaspoons ground ginger, 20 ounces extra-lean ground turkey, 1 Tablespoon lime juice, 1 Tablespoon orange marmalade, 1 teaspoon sesame oil, 1 teaspoon tapioca starch, 1 Tablespoons thai fish sauce','Place the ground turkey and minced garlic in a skillet and begin to brown, breaking up as you cook. As the ground meat cooks, you can use a hand-held potato masher to help break up the meat more evenly. Dont add salt to the ground meat here  the fish sauce has enough sodium to replace any added salt in this "Recipe".Meanwhile, place the stock, aminos, fish sauce, marmalade, lime juice, sesame oil, ground ginger, and tapioca starch in a bowl or magic bullet and whisk/process until blended well.Add the sauce to the ground meat and cook until the turkey is cooked through and the sauce has thickened up.Serve with broccoli slaw, wrapped in a large green lettuce leaf. Enjoy!',45,45,0);
INSERT INTO "Recipe" VALUES(583,'Fresh Peach Margarita With Lime Sugar','https://img.spoonacular.com/recipes/643559-556x370.jpg','0.5 cup ice, 1  juice of lime, 2 servings lime sugar, 1 teaspoon orange liquor, 1 medium size peach, 2 ounces peach schnapps, 2 tablespoons sugar, 4 ounces silver tequila','If making lime sugar:  Add 1/2 teaspoon of finely minced lime zest to 1/4 cup granulated sugar and set aside for about 30 minutes, stirring occasionally.For a pretty presentation, coat the rims of the glasses you are using with lime sugar (of course you can alternatively use plain white sugar).  Do this by rubbing the rim with a lime wedge and then placing the rim into a plate that has the sugar in it until the rim is coated with sugar.Place all ingredients into the blender and puree.  Add a little cold water if it is too thick.  Either chill all ingredients before making or add some ice cubes after you have made the margarita and stir it until it is as cold as you like and strain it into your glasses (or serve on the rocks).',45,45,0);
INSERT INTO "Recipe" VALUES(584,'Pasta With Butternut Parmesan Sauce @ Dw Magazine.Com','https://img.spoonacular.com/recipes/654897-556x370.jpg','1 pound butternut squash weighing, 8 ounces bow-tie pasta, 1 tablespoon olive oil, 1 cup shallots, 0.5 cup parmesan cheese, 0.5 cup heavy cream, 0.125 teaspoon nutmeg, 1 tablespoon parsley, 2 teaspoons lemon juice, 4 servings salt and pepper, 4 servings water to the sauce',replace('METHOD\nPreheat the oven to 350F. \n\nCut the butternut squash lengthwise in half* and scoop out the guts and seeds and discard them . \nPour 1/4 cup of water into a pyrex or ceramic baking dish and place the butternut squash halves cut side down. Bake for 40 minutes or until a fork easily pierces the squash. \nAllow to cool for 10 minutes. \nScoop out the squash flesh from the skins and pure with a blender (work in batches or place in a bowl and use a hand blender). \nDiscard the skins.\nFill a pot with water\n and salt (1 tablespoon of salt for every 2 quarts of water). Set over high heat to bring to a hard boil.\n Add the pasta and cook at a hard boil, uncovered until al dente.\nWhile the pasta is cooking, pour the olive oil into a wide skillet on medium heat.\n Add the shallots and saut until soft and translucent, about 5 minutes. \nAdd the butternut squash pure and c\nook for about a minute, mixing it in with the shallots. Add the cream, a tablespoon at a time, slowly stirring it in to incorporate and to avoid lumps. \nStir in the Parmesan. \nAdd the nutmeg, salt and pepper. \nAdd water (or chicken stock) to thin to the consistency you want. \nTake off heat and add the parsley and lemon juice. Cover the pan to keep warm.\nCheck pasta. When ready (al dente) drain and plate. \nPour the sauce over the pasta. \nGarnish with a little extra parsley and Parmesan. Serve immediately.\nBe careful when you cut the squash, winter squash are hard! The best way to do it safely is to slice a bit off of both ends so that you can stand the squash upright without it rolling. Then cut down the middle.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(585,'Lemon Coconut Granola','https://img.spoonacular.com/recipes/649567-556x370.jpg','0.25 cup coconut oil, 1 cup desiccated coconut, 1 cup currants, 0.5 cup flax seeds, 0.25 cup honey, 3  juice of lemon, 1  peel of lemon, 1 cup nuts, 3 cups rolled oats','Preheat oven to 150C.In a pan, combine coconut oil, honey, lemon peel and lemon juice. Bring to boil. Take off the heat when the honey is dissolved. Let cool a little.In another bowl, combine oats, flax seeds and chopped nuts. Mix well. Pour the honey mixture over the dry ingredients and stir until the oat mixture is well coated.Spread the granola evenly on a baking pan, and bake for 20 minutes. Turn over the granola, and stir in the coconut flakes. Bake for another 10 minutes. Let cool and stir in the currants. Keep in airtight container.',45,45,0);
INSERT INTO "Recipe" VALUES(586,'Sweet Potatoes Muffins','https://img.spoonacular.com/recipes/662610-556x370.jpg','2 tsp baking powder, 1 cup chocolate chips, 0.5 teaspoon cinnamon, 1  egg, 1 cup flour, 0.33333334 cup oil, 0.5 cup orange juice, 1 teaspoon salt, 0.25 c sugar, 15 servings sanding sugar, 16 ounces yams- in the oven until','Cook in the oven the sweet potatoes until soft. Remove from the oven and peel them. Place the meat into a dish, smash to reduce to a no chunk pulp and let it cool.Keep the oven at 400.Mix all the flour, baking powder, salt, sugar, cinnamon and chocolate chips if using.Add to the dry ingredients the orange juice, sweet potatoes, egg and oil and mix well.Place muffins cups in muffins pan and pour muffins mix up to cup high.Sprinkle sanding sugar and bake in the oven for 15 to 20 minutes, or until the toothpick comes out clean.Serve at room temperature.',45,45,0);
INSERT INTO "Recipe" VALUES(587,'Italian Meatloaf with Hard Boiled Eggs','https://img.spoonacular.com/recipes/648176-556x370.jpg','6 slices bacon, 8 servings pepper, 0.25 cup butter, 2  carrots, 2 stalks celery, 1 sprig rosemary, 10  sage leaves, 3 cloves garlic, 1.5 pounds ground beef, 1 pound ground pork, 1 pound ground veal, 2 tablespoons olive oil, 2.5 teaspoons sea salt, 7 oz bread, 1 large onion, 6  hardboiled eggs, 7 ounces vin santo','Preheat the oven to 425F.Heat butter and olive oil in a saucepan and saute the onion, garlic, celery, carrots and herbs until lightly golden. Add the vin santo or Marsala and bring to a boil. Boil for about 2 minutes, then remove from heat.Place the meats, salt and pepper in a large bowl and mix together, then add the vegetables. Squeeze the bread of excess milk and break it into the mixture. Add the 2 raw eggs. Using your hands, combine mixture well.Line a large rectangular terrine, casserole, or loaf pan (about 14 inches long) with foil and brush with oil. Place half of the meat mixture in the pan and press down evenly. Arrange the hard boiled eggs in a line down the center, then cover with the remaining meat mixture. Press the mixture down well.Bake the loaf on the bottom shelf of the oven for about 50 minutes; it should be lightly browned on top. Turn onto a serving dish. It is delicious served hot or cold.',45,45,0);
INSERT INTO "Recipe" VALUES(588,'Ground Turkey Stuffed Peppers','https://img.spoonacular.com/recipes/645978-556x370.jpg','4  bell peppers, 1 tsp pepper, 8 oz tomato sauce, 8 oz canned tomatoes, 2 tbsp parsley, 2  eggs, 1 tbsp garlic, 0.5 lb ground beef, 0.5 lb ground turkey, 1  onion, 0.25 cup parmesan cheese, 0.5 cup rice, 1 tbsp sugar, 8 oz tomato soup, 1 tbsp worcestershire sauce','Cook rice then knead it together with remaining filling ingredients. Cut tops off peppers and fill each one. Place in your slow cooker or a large stove-top pot. Mix together sauce ingredients. Top each stuffed pepper with sauce and pour remaining sauce all around the stuffed peppers. Cook on medium/low for about an hour. Top with grated parmesan cheese and a little parsley for looks and serve warm.',45,45,0);
INSERT INTO "Recipe" VALUES(589,'Decadent Black Forest Cake','https://img.spoonacular.com/recipes/641308-556x370.jpg','1 box duncan hines devil''s food cake, 1 can comstock cherry pie filling, 8 oz cream cheese, 2.5 cups powdered sugar, 1.5 cups whipping cream, 0.5 teaspoon almond extract, 20 servings simple syrup glaze, 0.25 cup water, 0.25 cup sugar',replace('Prepare the cake per box directions. Cool 15 minutes and remove from pan and place on a cooling rack. Allow to cool completely.\nPrepare the simple syrup glaze by placing all of the ingredients in a small pot and bringing to a boil. Boil about 3 minutes and remove from heat. Set aside to cool.\nPrepare frosting by beating the softened cream cheese in a medium bowl until creamy and lump free. Add half the whipping cream and beat on low about 30 seconds.\nAdd half the powdered sugar and beat until all the sugar is mixed in.\nAdd remaining whipping cream and beat until creamy.\nAdd the last of the powdered sugar and beat well, about 2 minutes. Add almond extract and beat for about 30 seconds.\nTurn the mixer on high and beat until light and fluffy, about 2 minutes.\nAssemble the cake\nTrim any uneven parts off the top of your first layer by sawing a serrated knife along the top until the top is level.\nPlace on a cake stand or plate. Using a pastry brush, brush the top of the cake with an even layer of the simple syrup.  Trim the second layer of cake and place on a cooling rack. Brush with simple syrup and set aside. Discard any left over syrup.\nAllow syrup to soak into the cake layers for about 5 or 10 minutes.\nSpread about a cup of frosting over the top of the first cake layer to about a  inch from the edge. Spread a layer of cherry pie filling over the frosting to about an  inch from the edge of the frosting.\nCarefully place the second layer of cake on top of the first layer being careful not to put too much pressure on the filling. You dont want the filling to start to ooze out from the sides of the cake.\nTake about 1 cup of frosting out of the bowl and put it into a smaller bowl. This is to prevent the chocolate crumbs from the cake to get into the bowl of frosting.\nYou dont want flecks of cake in your white frosting.\nSpread a thin but even layer of frosting on the sides of the cake. Be sure to fill the space between both cake layers with frosting. This will trap the filling between both cake layers.\nFrost the top of the cake with a thin layer of frosting.\nChill for about an hour to set the frosting.\nRemove the cake from the refrigerator and spread the remaining frosting over the sides and top.\nForm an edge in the frosting on the top of the cake by pushing down into the frosting and building up a ledge of frosting with a small spatula along the edge of the cake.\nYou may have to even out the frosting in the center by removing a thin layer  of frosting until the edges are higher then the center of the cake.\nAdd cherry pie filling to the top filling in the center of the frosting.\nChill before serving.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(590,'Bacon Wrapped Filet Mignon','https://img.spoonacular.com/recipes/633338-556x370.jpg','4 inches beef tenderloin steaks, 4 slices bacon, 2 large cloves garlic, 4 servings salt& pepper',replace('Place the tenderloins on a large dish and wrap a slice of room temperature bacon around each filet, gently stretching the bacon if needed. Secure the ends of the bacon with a toothpick.\nCut the garlic cloves in half and rub both sides of each filet with the cut ends of the garlic. Season well with salt and pepper on both sides.\nPre-heat grill to very hot. With tongs, place each steak on the grill and for medium-rare cook for 3-4 minutes, rotating the steaks halfway through 90 degrees for nice grill marks.\nTurn the steaks over and cook another 3-4 minutes.\nRemove from the grill and let rest loosely covered for 5 minutes before removing toothpicks and serving. Serve as is or with sauted garlic mushrooms','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(591,'How Sweet It Is Sweet Potato Lasagne','https://img.spoonacular.com/recipes/647563-556x370.jpg','12  baby portabella mushrooms, 3 tablespoons curry powder, 2 tablespoons basil leaves, 1  eggplants, 10 ounces spinach, 0.5 cup heavy cream, 12 ounces montery jack & cheddar cheese mix, 2  jalapenos, 3 cups marinara sauce, 6 servings salt & pepper, 4  sweet potatoes, 1 tablespoon vegetable cooking oil','Slice the Sweet Potato into 1/4 inch thick slices. Boil until semi-cooked (about 10 min). Rub the slices with a dry curry powder & olive oil (1cup) mixture. Set aside and let marinate for at least 10 min.Slice Eggplants into 1/4 inch thick slices and rub all over with an olive oil (1 cup)/dried basil/salt & pepper mix. Set aside and let marinate for at least 15 min.Pour canola or vegetable cooking oil into a pan. Saute spinach and mushrooms for about 3-5 min, add in jalapenos and salt & pepper to taste.Turn the heat down and add in some heavy cream and about 1/2 of the mexican cheeses until mixture is creamy, but not watery.Start layering the lasagne in this order: Sweet Potatoes, Spinach/Mushroom Mix, Eggplants, Marinara Sauce, Sweet Potatoes, Spinach/Mushrom Mix, Eggplants, Then finally sprinkle the remaining Monterey Jack/Cheddar Cheese Blend on top.Bake at 350-375 for about 35-45 min, depending on how your oven works. You''ll know it''s ready when you can pass through a fork easily through all the layers.Devour with Passion',45,45,0);
INSERT INTO "Recipe" VALUES(592,'Caramel Apple-Brownie Cheesecake','https://img.spoonacular.com/recipes/636989-556x370.jpg','1.5 cups baking apples, 2.5 teaspoons baking powder, 0.5 cup firmly brown sugar, 0.5 cup butter, 12 oz cream cheese, 3  eggs, 1.5 cups flour, 2 tablespoons granulated sugar, 2 tablespoons ground cinnamon, 0.25 cup pecans, 0.5 teaspoon salt, 8 servings baking apples are apples that have a sweet-tart balance and hold their shape when, 4 teaspoons vanilla extract','Preheat oven to 350F (180 C).  Bake pecans in a single layer in a shallow pan for about 7-8 minutes or until lightly toasted and fragrant, stirring halfway through.Remove from oven, let cool down, and chop.  Reserve.Reduce oven temperature to 325F (about 160 C). Grease and flour a 9-inch (22.5 cm) springform pan. Sprinkle pecans over bottom of the prepared pan and reserve.In a heavy-duty electric stand mixer, beat cream cheese, granulated sugar, and vanilla at medium speed until well-blended and smooth.  Add 3 eggs (1 at a time), beating after  each addition until just blended.  Reserve.In a separate large bowl, whisk together brown sugar, melted butter, and remaining egg until blended.  Then stir in the flour, cinnamon, baking powder, and salt.  Add the peeled and diced apples to the mixture and stir gently.  Spoon batter into prepared pan.  Carefully spoon cream cheese mixture over batter.Bake at 325F ( about 160 C) for 70 minutes or until set.  Remove from oven, and gently run a knife around outer edge of cheesecake to loosen from sides of pan but do NOT remove sides of pan.  Cool completely in pan on a wire rack  for about 2 hours.  Remove side of the pan and transfer to a serving plate.Meanwhile, prepare Caramel Apple Topping and Caramel Sauce.  Spoon topping over cheesecake; drizzle with 1/2 cup Caramel Sauce.  Reserve 1 cup Caramel Sauce to drizzle over the cheesecake later if you have not served the whole dessert at once.For the Caramel Apple Topping: In a large skillet over medium heat, melt the butter; then, add both the sugar and lemon juice.  Cook, stirring constantly with a long-handled wooden spoon, for 5 to 6 minutes or until mixture turns a light golden brown.  Add the apple wedges and cook, stirring often, for 15 to 18 additional minutes or until apples are tender and caramelized.  Remove from heat and let cool for 20 minutes.Meanwhile, prepare Caramel Apple Topping and Caramel Sauce.  Spoon topping over cheesecake; drizzle with 1/2 cup Caramel Sauce.  Reserve 1 cup Caramel Sauce to drizzle over the cheesecake later if you have not served the whole dessert at once.For the Caramel Sauce: In a medium saucepan over medium-high heat, bring the brown sugar, butter, whipping cream, and honey to a boil, stirring constantly; then, boil  stirring constantly for 2 minutes.  Remove from heat, stir in the vanilla, and cool 15 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(593,'Dark Shadows Baileys Chocolate Cheesecake Brownies','https://img.spoonacular.com/recipes/641284-556x370.jpg','1 teaspoon baking powder, 5 ounces bittersweet chocolate, 1 cup butter, 8 ounce cream cheese, 1  egg yolk, 2 medium eggs, 1.25 cups flour, 1 cup granulated sugar, 1 tablespoon baileys irish cream, 1 pinch salt, 16 servings sugar, 0.5 cup cocoa powder, 0.5 teaspoon vanilla extract, 200 gr walnuts','Directions for cheesecake batter:Place the cream cheese, sugar, egg yolk and Baileys Irish Cream in the bowl of a food processor and process until smooth.Directions for Brownies:Preheat the oven to 350 degrees. Lightly grease an 8-by-8-inch baking pan with cooking spray. To make removing the brownies easy, line the pan lengthwise and widthwise with two 7-by-12-inch sheets of parchment paper or aluminum foil, shiny side up, and use the overhang as handles.Place the chocolate in a small heatproof bowl and set in a wide pan or skillet of hot water. Set aside for 5 minutes, stirring 4 to 5 times, and let it melt completely. Stir until smooth. In a medium bowl, whisk the flour, cocoa, baking powder, and salt until well blended. Set aside.With a stand or hand mixer set on low speed, beat the butter and sugar in a medium bowl until well blended. Beat in the eggs, one at a time, until fully blended, scraping down the sides and bottom of the bowl as necessary. Beat in the vanilla until blended. Alternately blend the dry ingredients and the melted chocolate into the egg mixture in increments. Using a rubber spatula or wooden spoon, fold in the walnuts. Stop when the ingredients are just blended. Scrape the batter into the prepared baking pan and spread evenly. Set aside.Place large spoonfuls of the cheesecake mixture on top of the chocolate mixture and, using a butter knife, swirl to partially combine.Place large spoonfuls of the cheesecake mixture on top of the chocolate mixture and, using a butter knife, swirl to partially combine.Bake for 45-50 minutes or until set (do not over-bake).',45,45,0);
INSERT INTO "Recipe" VALUES(594,'No-Bake Chocolate Peanut Butter Pie','https://img.spoonacular.com/recipes/653185-556x370.jpg','2 tablespoons non-dairy cream cheese, 1 cup creamy peanut butter, 0.25 cup chocolate chips, 10  peanut butter cups, 1.25 cups powdered sugar, 0.5 cup roasted peanuts, 5 tablespoons earth balance soy free spread, 3 tablespoons vanilla coconut yogurt, 1.5 containers non-dairy whipped topping','CRUST:Crush the cookies in a food processor until fine crumbs.Transfer to a small bowl and add the earth balance.Combine with a fork, or hands until fully blended and begins to take shape.Press evenly into a 9 inch pie plate. My crust ended at about 1/2 inch before the rim.Chill in the freezer while preparing the filling.FILLING:In a stand mixer set with a paddle attachment, or using a hand held mixer set on medium speed, beat peanut butter with the cream cheese.After about a minute add the coconut yogurt.Once combined, reduce to low speed and add sifted powdered sugar, increase back to medium speed and beat until smooth.Turn off mixer, then add in 1/2 cup peanuts, and broken pieces of peanut butter cups and combine well.Fold in thawed whipped topping until well blended.Pour the filling into the chilled crust and spread evenly.Sprinkle the 3 tablespoons of peanuts, dark chocolate chips, and the reserved cookie crumbs on top.Chill for at least another 90 minutes before serving.Slice with a sharp knife to pierce through all the peanut butter chunks in the pie.',45,45,0);
INSERT INTO "Recipe" VALUES(595,'Banana Smoothie Boost','https://img.spoonacular.com/recipes/634180-556x370.jpg','0.6666667 cup almond milk, 1  banana, 4 servings chocolate, 2 teaspoons coffee, 1 teaspoon honey','Mix everything but shaved chocolate up in a blender. pour into glass and sprinkle chocolate on top.',45,45,0);
INSERT INTO "Recipe" VALUES(596,'Smokey Rainbow Chili','https://img.spoonacular.com/recipes/660395-556x370.jpg','2 tablespoons olive oil, 2 small zucchini, 1  bell pepper, 1  orange bell pepper, 1  jalapeno pepper, 4 cloves garlic, 1  onion, 28 ounce stewed tomatoes, 6 ounce tomato paste, 15 ounce black beans, 15 ounce kernel corn, 15 ounce kidney beans, 0.5 tablespoon paprika, 1 teaspoon chili powder, 0.5 teaspoon oregano, 0.5 teaspoon ground pepper, 0.25 teaspoon cayenne pepper',replace('(if using meat...brown the meat really well, remove and set aside.  Add the meat after sauteing the veggies)\nHeat oil in a large pot over medium-high heat. Stir in zucchini, red bell pepper, orange bell pepper, jalapeno, garlic, and onion. Cook 5 minutes, just until tender.\nAdd tomatoes with liquid, tomato paste, black beans, corn, and kidney beans into the pot. Season with smoked paprika, chili powder, oregano, black pepper, and cayenne pepper. Bring to a boil.\nReduce heat to low and simmer 1 hour, stirring occasionally.  (depending on how big you cut the veggies, you may want to let it simmer a little longer)','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(597,'Fettuccine With Bacon Mushroom and Peas','https://img.spoonacular.com/recipes/642719-556x370.jpg','200 grams bacon, 4 servings cheese, 1 small can condensed cream of mushroom, 4 servings basil, 10 ounces fettuccine, 4 servings ground pepper, 1 small can mushroom, 4 servings oregano powder, 0.6666667 cup peas','Bring a pot of water to boil over high heat, add salt and fettuccine, cook for about 9 minutes.Meanwhile, brown bacon in a pan over medium high heat. Drain on paper towels and set aside.Pour the oil out of the pan, saute mushroom for about a minute then pour a can of cream of mushroom, add a can of water. Season with ground black pepper and oregano and/or basil if using, bring to boil; add green peas and a little grated cheese.Taste it first before adding the cheese since the cream of mushroom is already salty. Add the cooked fettuccine, mix then crumble the bacon and add it to the pasta.Serve and enjoy! ',25,25,0);
INSERT INTO "Recipe" VALUES(598,'Southwest Egg Rolls with Cilantro Lime Pesto','https://img.spoonacular.com/recipes/660707-556x370.jpg','1 bunch cilantro, 3 cloves garlic, 1 Tbsp almonds, 12  juice of lime, 12 servings olive oil, 12 servings salt & pepper, 12  egg roll wrappers, 1 small bell pepper, 0.5 cup corn, 0.5 cup black beans',replace('Oven at 385 degrees.\nMake the pesto: In a small food processor add the garlic and almonds. Pulse until finely chopped. Add the cilantro leaves and about 3-4 Tbsp olive oil, the amount is really a preference of how loose or thick you like the pesto. Start with a little and add a little at a time until you reach the consistency of your preference. Stir in the juice of 1/2 a lime. If you are making this ahead of time...place in a bowl and drizzle just enough olive oil on top to coat, this keeps the air from getting to the cilantro. Cover with plastic wrap and refrigerate.\nSaut the peppers with a drizzle of olive oil in a pan over medium high heat for just a couple minutes. Mix the peppers, corn and black beans in a bowl.\nLay out the egg roll wrappers. Smear some of the cilantro lime pesto on the end closest to you, leaving about an inch of the wrapper on the very end.\nAdd a spoon full of the veggies along the line of pesto. Brush the ends of the wrapper with water, this will help seal the egg roll. Fold the end nearest you over the veggies and the two\nsides fold in as well.\nRoll up the wrapper to the end. Place seam side down on a lined baking sheet that his been brushed with a bit of olive oil to prevent sticking.\nBrush the egg rolls lightly with olive oil as well, this will help get that golden color. Bake for approx 18 minutes, or until golden and crispy.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(599,'Grilled Lemon Garlic Chicken','https://img.spoonacular.com/recipes/645753-556x370.jpg','2 pounds chicken breast, 0.25 cup garlic olive oil, 0.5 cup lemon juice, 2 teaspoons tumeric, 4 servings salt and pepper, 4 servings cilantro',replace('Trim any fat and clean Chicken\nPut Chicken in bowl with Garlic Oil, Lemon Juice, Salt and Pepper and Tumeric, combine all.\nIf you have time, do this in the morning and marinate all day in the fridge.  If this is last minute try to give Chicken about an hour in the marinade)\nPre heat Grill, Medium High Heat.\nGrill Chicken about 5 minutes per side until inside is cooked through.\nPlate and garnish with chopped Cilantro or Parsley','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(600,'Turkey Pot Pie With Cornbread Crust','https://img.spoonacular.com/recipes/664058-556x370.jpg','1 tablespoon baking powder, 2 tablespoons canola oil, 2 large carrots, 3 stalks celery, 2 cups chicken stock, 1 large egg, 0.25 cup flour, 0.75 cup flour, 2 cloves garlic, 0.5 cup green beans, 2 teaspoons ground sage, 2 teaspoons ground thyme, 0.75 cup milk, 2 tablespoons olive oil, 1 medium onion, 5 servings cracked pepper, 0.5 teaspoon salt, 1.5 tablespoons sugar, 3 cups turkey, 0.75 cup cornmeal','To make filling: Preheat the oven to 400F. Coat a pie plate (or any baking dish you like) generously with nonstick cooking spray. Heat olive oil in a large pan over medium heat. Add onion, carrots, celery, and green beans, and saut for about 10 minutes, until tender. Add garlic and stir constantly for 30 seconds. Sprinkle the flour into the pan and stir until it coats the vegetables, about 30 seconds. Slowly stir in 2 cups of hTo make crust: In a large bowl, whisk the cornmeal, flour, baking powder, sugar and salt. Stir milk, egg and canola oil until well combined in a separate bowl. Stir wet ingredients into dry ingredients. Spoon the batter evenly over the filling. Bake until the top is golden brown, about 22 to 25 minutes. Let cool for at least 15 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(601,'Tasty Easy Meatloaf','https://img.spoonacular.com/recipes/662917-556x370.jpg','1 cup breadcrumbs, 3 Tbs brown sugar, 0.5 lb bulk sausage, 16 oz tomato sauce, 3 Tbs cider vinegar, 0.5 tsp cumin, 1  egg, 1 tsp garlic powder, 1 lb ground beef, 1 small onion, 0.5 tsp pepper, 1.5 tsp salt, 0.5 cup water, 2 Tbs grain mustard, 2 Tbs worcestershire','Mix beef, sausage, bread crumbs, onion, egg, salt, pepper, cumin, garlic powder,  cup tomato sauce. Do not over mix or your meatloaf will become chewy. Simply use your fingers and mush it together and only do this until it is just mixed.Place in a shallow oven proof pan and form into a loaf. Stir together the remaining sauce, vinegar, sugar, mustard, water and WorcestershirePour the sauce over the meatloaf and bake x 1 hour until cooked through. While cooking, spoon the sauce over the top of the meatloaf about every 20 minutes.Remove from the oven and spoon the sauce over the top a final time. Allow to rest for 10 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(602,'Kahlua Tiramisu','https://img.spoonacular.com/recipes/648698-556x370.jpg','500 grams mascarpone, 2 teaspoons vanilla extract, 6 tablespoons kahlúa, 1.5 cups espresso, 250 ml whipping cream, 8 tablespoons icing sugar, 30 inches lady fingers depending on how you will try to fit them the dish, 11 servings cocoa powder',replace('Put the mascarpone, vanilla, Kahla and a little less than 1/2 of coffee in a medium mixing bowl, blend until everything is smoothly mixed together.\nIn another medium bowl, beat the cream with the icing sugar until smooth, then fold in the mascarpone mix.\nPlace the remaining coffee into large deep plate, quickly dip the biscuits flipping sides, one by one, enough to make one layer in a 11x7 casserole dish.\nSpread evenly half of the mascarpone mix on top.\nRepeat with another layer of biscuits and the rest of the mascarpone mix. Refrigerate.\nBefore serving, fill a small sieve with cocoa powder and lightly dust the top.\nIf you are fancy, grate some of bittersweet chocolate or make chocolate curls and scatter them all over','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(603,'Lemon Poppy Seed Muffins','https://img.spoonacular.com/recipes/1003210-556x370.jpg','4 large eggs, 3.4 oz lemon pudding mix, 1 box lemon cake mix, 2 Tbsp poppy seeds, 0.25 cup vegetable oil, 1 cup water',replace('Preheat oven to 350 and line 2 muffin tins with cupcake wrappers.\nIn a large bowl, combine all of the ingredients, except water, and mix well.\nSlowly add the bowling water into the mixture, and mix as you add it.\nPour the batter into the muffin pan and fill the liners  way full.\nBake for 15-17 minutes or until the muffins are a light golden brown on top.','\n',chr(10)),20,20,0);
INSERT INTO "Recipe" VALUES(604,'Chicken Ranch Burgers','https://img.spoonacular.com/recipes/991010-556x370.jpg','0.5 medium bell pepper, 0.5 cup bread crumbs, 0.5 cup purple onion, 1 packet ranch seasoning, 1 lb chicken',replace('Heat oven to 400.\nAdd chicken, onion, pepper, bread crumbs, and ranch seasoning to a mixing bowl.\nMix ingredients well.\nScoop and make 3 large burger patties.\nPlace in skillet and cook on medium low heat to sear juices and brown the patties.\nPlace skillet with patties into the oven and bake for 15 minutes, or until patties are cooked thoroughly.\nServe with your favorite toppings.','\n',chr(10)),25,25,0);
INSERT INTO "Recipe" VALUES(605,'Oatmeal Coconut Cookies','https://img.spoonacular.com/recipes/653445-556x370.jpg','100 grams rolled oats, 75 grams coconut, 120 grams flour, 100 grams caster sugar, 1 teaspoon salt, 100 grams butter, 25 grams inverted sugar syrup, 1 teaspoon baking soda, 2 tablespoons water',replace('Heat the oven to 150C/300F and prepare two baking trays covered with parchment. In a large bowl, stir together the oats, coconut, flour, sugar and salt. Meanwhile melt the butter and syrup together in a small pot over low heat.\nStir the baking soda into the boiling water, then stir this into the butter and syrup mixture. And pour all of it over the flour mixture. Mix well, then shape the mixture into 32 balls and place onto the prepared baking sheets. Press down to flatten the cookie balls with your palm.\nBake for 12-15 minutes, switching the pan around if you need to for even baking, until the cookies are golden brown. Leave them on the baking trays for 5 minutes before removing them with a spatula to cool on a rack.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(606,'Baked Lemon~Lime Chicken Wings','https://img.spoonacular.com/recipes/633668-556x370.jpg','3 lbs chicken wings, 1  juice of lemon, 1  juice of lime, 3 cloves garlic, 4 tablespoons honey, 0.5 cup sugar, 0.5 cup red wine, 1 cup chicken broth, 0.25 cup vegetable oil, 1 Handful parsley, 1 Handful cilantro, 1 Dashes salt, 1 Dashes ground pepper',replace('Combine all of the ingredients for the marinade. Add the chicken wings and place in the refrigerator for at least 1 hour or up to a few hours.\nPreheat Oven 350 degrees:\nPlace the chicken wings in a baking pan and spoon the marinade over the wings.\nPlace in the oven for 35-40 minutes until a beautiful golden color.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(607,'Black Lentil and Couscous Salad','https://img.spoonacular.com/recipes/635126-556x370.jpg','2 cups couscous, 2 cups lentils, 1 teaspoon ground cumin, 0.5 teaspoon cayenne pepper, 0.5 teaspoon paprika, 1 cup almond flakes, 1 cup raisins, 3 tablespoons parsley, 2.5 tablespoons mint, 0.25 cup olive oil, 0.25 cup apple cider vinegar, 2 tablespoons dijon mustard, 1  orange zest, 0.5  juice of orange, 3 tablespoons honey, 3 ounces feta',replace('Whisk together the olive oil, apple cider vinegar, Dijon mustard, orange zest and juice and honey. Set aside.\nIn a large bowl, mix the remaining ingredients until well incorporated. Drizzle the dressing on top, toss and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(608,'Salmon Frittata','https://img.spoonacular.com/recipes/659081-556x370.jpg','2 cans salmon, 0.25 teaspoon cayenne pepper, 1 teaspoon basil, 12  eggs, 10 ounces spinach, 1 pint nonfat cottage cheese, 2 cups swiss cheese','Drain and flake salmon. Spray 9 x 13-inch baking pan with non-stick vegetable coating. Combine flaked salmon with remaining ingredients and pour into prepared baking pan. Bake at 375 F for 30 minutes, or until frittata is set.',45,45,0);
INSERT INTO "Recipe" VALUES(609,'Chile Underground''s Texas Caviar','https://img.spoonacular.com/recipes/638533-556x370.jpg','1 ounce quality balsamic vinegar, 15 oz black beans, 15 oz blackeyed peas, 1 can corn, 0.5 bunch cilantro, 2 cloves garlic, 1 pint super-sweet grape tomatoes, 1  bell pepper, 1 teaspoon ground cumin, 3  jalapeño chiles, 1 ounce olive oil, 1 ounce olive oil, 1 teaspoon oregano, 2 oz red wine vinegar, 0.5 teaspoon salt, 1 bunch scallions, 0.5 large onion','Heat the oil in a large skillet over medium-high heatAdd onion and cook for just a minute or two with stirringAdd bell pepper and stir for another minuteAdd minced chiles and tomatoes and stir for only a couple of minutes, to slightly soften the tomatoesAdd the garlic and stir for 30 seconds or soTransfer skillet contents to a large mixing bowlCombine in the peas, beans and cornStir in the sliced scallions; set asideIn a small mixing bowl, combine remaining ingredients and whisk until smoothPour sauce over the CaviarTake most of the cilantro leaves and mince themAdd minced cilantro to the CaviarRefrigerate for at least 2 hours.Garnish with remaining cilantro leavesServe with hearty corn chips (no wimpy chips allowed!)',180,180,0);
INSERT INTO "Recipe" VALUES(610,'Indian Lentil Dahl','https://img.spoonacular.com/recipes/647830-556x370.jpg','2 T canola oil, 0.33333334 c cilantro, 1 c coconut milk, 1 T ginger, 1 t garam masala, 4  garlic cloves, 1 T lime juice, 1  onion, 3  plum tomatoes, 1.25 c lentils, 0.75 t salt, 3 c water',' In a large saucepan, combine oil, onion and salt at medium-high heat. Cook until onion starts to brown, around 5 minutes or so. Add garlic, ginger and Garam Masala , cook until fragrant, about 1 minute.Add lentils, coconut milk and water. Bring to a boil, then reduce heat to low and simmer, partially covered until lentils are fully tender and broken down to an almost paste-like consistency, about 25-30 minutes.Add lime juice and cilantro. Check for seasoning. Serve (over rice if you like), topped with the diced tomatoes.',45,45,0);
INSERT INTO "Recipe" VALUES(611,'Chavrie Stuffed Turkey Burgers','https://img.spoonacular.com/recipes/637488-556x370.jpg','2  ea. eggs, 1 teaspoon ½ garlic, 4 ounces chavrie goat cheese, 2 pounds ground turkey, 6  ea. hamburger rolls, 1 teaspoon ½ thyme leaves','Slice Chavrie goat cheese log into 6 equal disksIn a large bowl, combine the ground turkey, eggs, garlic and a pinch each of salt and pepper.Mix gently to bring all the ingredients together; do not over mix.Form meat mixture into 12 patties. On 6 of the patties, gently place Chavrie disks onto patties, pressing down lightly.Place remaining patties on top, press, and seal edges to totally enclose filling, forming 6 total patties.Place patties on grill 4 minutes, until bottom is brown. Turn the burgers over and cook an additional 4 minutes, or until done to your preference.Place in rolls and serve with your favorite accompaniments',45,45,0);
INSERT INTO "Recipe" VALUES(612,'Jean''s Seafood Gumbo',NULL,'2 pounds shrimp, 12  crabs, 4 stalks celery, 0.5 cup parsley, 2  peppers, 1 large onion, 1 cup green onions, 4 cloves garlic, 3  bay leaves, 1 ounce tomato paste, 4 teaspoons vegetable oil, 0.5 cup flour, 2 teaspoons salt, 2 teaspoons ground pepper, 0.5 teaspoon thyme, 1 teaspoon worcestershire sauce, 1 can canned tomatoes, 1 can all the tabasco sauce you handle, 9 servings creole seasoning, 1 pound andouille, 2 tablespoons filé powder, 1 pound okra, 1 bag louisiana rice',replace('Fill a 14-16-quart pot with two quarts of water and bring to a boil.\nMeanwhile, peel and devein the shrimp, keeping the heads and hulls. Set the shrimp aside in cold water. In the large "gumbo pot" boil heads and hulls for 30 minutes to an hour. This will give you Creole gumbo. Strain shrimp heads and hulls from stock and set aside. Discard heads and hull immediately. Otherwise, the next day your kitchen will smell like Bayou St. John.\nClean the fresh crabs  If the crabs are fresh, you must take time to clean them. Discard the hard back shell and some of the so-called "dead man," or yellow insides. Clean and separate crabs and set aside. (Note: If necessary, you can use meat from king, Dungeness, snow or stone crabs for your gumbo).\nBefore you fire up the stove again, cut up your celery, parsley, peppers, onions and garlic, especially if you''re alone and there is no one to help you stir the pots. It takes time peeling the onions and garlic  Put the celery and parsley in a separate container from the other chopped ingredients and refrigerate until needed to keep them fresh.\nPlace the gumbo pot with the shrimp stock on the stove. Add cleaned crabs and bay leaves. Stir slowly. You don''t want your shrimp stock messing up the floor. Add celery, parsley, and tomato paste to the gumbo brewing on the stove. Bring to a boil. Turn down heat, cover, and let simmer.\nHere comes the roux -- a thick and flavorful sauce that has become one of the most important staples of Louisiana cuisine. Pour oil or shortening into a separate heavy skillet (please do not use a thin omelet pan) over a medium-low heat. Slowly stir in flour to make the roux. Keep your eyes on the skillet. If the phone rings, let the answering machine pick it up. Cook roux until it has a dark mahogany color. Do not stop stirring until roux appears nutty or grainy. If black specks appear, the roux is burned. Throw it out and start from scratch. A good roux could take 30 to 45 minutes cooking time.\nNow you are ready to add the holy trinity of onions, garlic, and green peppers to the roux mixture. Stir ingredients in slowly because the flour is still sizzling. The moisture will begin to disappear. This is when Jean would add another quart or two of water to the gumbo pot. Add roux to the gumbo pot. Bring to a boil, stirring constantly. Lower heat and cover. The kitchen should smell good right now. Pour yourself another cold something-or-other. You''re halfway there. Come back to look and stir in an hour or so.\nSeason to taste: add salt, pepper, thyme, Worcestershire sauce, Tabasco sauce and any Creole seasoning you like. Don''t overdo it right now. Let the roux work its magic absorbing all the wonderful ingredients. Gumbo is usually very spicy, but you can keep it mild. Remember, if you have decided to use andouille sausage it is also hot.\nFry sausages and okra with a little bit of the leftover grease. Sprinkle a little leftover flour if the okra is fresh. Add to gumbo pot. Add chopped peeled tomatoes, stirring until well blended. Add more water if necessary. The roux will keep it thick and tasty. Return to a boil and simmer for 10 minutes. Reduce heat and let simmer, uncovered, for 2 1/2 to 3 hours over low heat.\nSkim any excess fat. Add shrimp. Stir in slowly as you increase the heat one last time. It''s time to stir in the fil powder. Cook another 20 to 30 minutes until the gumbo is thick. Taste and adjust seasonings one more time. Did I mention the rice? Seafood gumbo is served over Louisiana rice. Of course, you can substitute for your own favorite rice. Just plain old brown or white rice will do. Before serving, taste one more time and adjust seasoning. Turn off heat and remove seafood gumbo from the stove.\nTo cool down the pot before serving, place it in the sink with a few inches of ice-cold water. If needed, add additional salt and Tabasco sauce. If you can see through the gumbo to the bottom of the pot, work on your roux next time.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(613,'Pork Carnitas with Chipotle BBQ Sauce and Slaw',NULL,'4  pork chops, 1 cup orange juice, 1 cup pineapple juice, 3 cloves garlic, 1 TBSP ground coriander, 1 TBSP ground cumin, 1 TBSP chili powder, 1 TBSP garlic powder, 1 TBSP onion powder, 1 TBSP pepper, 1 cup ketchup, 2 TBSP brown sugar, 2 TBSP dijon mustard, 0.5 cup distilled vinegar, 0.5 cup orange juice, 2 TBSP honey, 1 TBSP salt, 2 TBSP chipotles in adobo, 2 cup cabbage, 1 cup onion, 0.5 cup cilantro, 2  juice of lime, 0.5 cup nonfat greek yogurt',replace('Directions:\n1.Lay 4 Pork Chops in the slow cooker. Add the juices, garlic and powders evenly over the pork chops. Place lid on slow cooker and turn the slow cooker on low for 6 hrs, rotating pork chops half way through.  Once done,let pork chops cool slightly and shred into bite sized pieces.\n2.  Make BBQ Sauce: Add all ingredients into a medium sauce pan and whisk. Bring up to a simmer and cook for 15 min, until thickened. Remove from heat and add the pork to the BBQ Sauce and toss together.\n3. Make the slaw: Chop the cabbage and red onion. Place in a medium bowl and add cilantro. Add Lime juice and greek yogurt. Toss  together until evenly distributed.\n4. Serve in corn tortillas and chips with salsa.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(614,'Shrimp pasta with white wine tomato cream sauce','https://img.spoonacular.com/recipes/659988-556x370.jpg','250 g cherry tomatoes, 1 small bunch coriander/cilantro, 2 teaspoons garlic, 2 tbsp heavy cream, 350 g .4 oz. linguine, 1 tbsp olive oil, 4 servings salt & pepper, 2 medium shallots, 400 g .5 oz. shrimp','If you are using frozen shrimp, remove them from the fridge and allow to come to room temperature before using.Bring a large pot of water to a boil and cook your pasta according to package directions. 1 or 2 minutes before your pasta is done cooking, ladle about 250ml / 1 cup of the cooking water into a cup.In the meantime, heat the olive oil in a large frying pan over medium heat. Add the shallots and garlic, season with salt and pepper, and saut until soft and translucent, about 3 to 5 minutes.Add the wine and stir.Add the tomatoes and simmer until the wine has evaporated, about 5 minutes.Drain the pasta and add it to the sauce, along with the shrimp and cream, and toss to combine. If you find the sauce is too thick, add a splash of the pasta water.Add the coriander and serve immediately.Find more "Recipe"s on my blog http://alalemon.com',45,45,0);
INSERT INTO "Recipe" VALUES(615,'Lebanese Tabouleh','https://img.spoonacular.com/recipes/649411-556x370.jpg','3 tablespoons bulgur wheat, 3 cups flat leaf parsley, 1 tablespoon mint, 3 tablespoons green onions, 1  juice from lemon, 2 tablespoons olive oil, 0.25 cup roma tomatoes','Remove stems from parsley and mint. Rinse leaves in a colander. Pat dry with paper towel.In a food processor pulse parsley and mint until finely chopped. Transfer to a large mixing bowl.Add green onions, tomatoes and bulgur wheat; stir to combine.Toss with lemon juice and olive oil. Refrigerate for an hour before serving.Serve on its own or with pita breadServes 2',45,45,0);
INSERT INTO "Recipe" VALUES(616,'Bittersweet Chocolate Ice Cream','https://img.spoonacular.com/recipes/635040-556x370.jpg','2 cups half& half, 1 cup heavy whipping cream, 0.25 teaspoon coffee- try starbuck''s via, 2 teaspoons vanilla extract','Prep your ice cream maker according to the manufacturers directions.In a medium sauce pan, heat the half & half until warm- not hot.In a bowl, whisk the egg yolks until blended.Add the sugar and about 1/2 of the warm half and half. Stir to combine well and add the mixture back to the saucepan. Whisking briskly while combining.Cook over medium heat until the mixture coats the back of a silicone spatula (about 10-12 minutes). Remove from heat and add the chocolate and coffee, stir to melt and combine thoroughly.Place the pan with the custard in an ice bath to cool, stirring occasionally, until it reaches room temperature.Add the whipping cream and vanillaPour into another container and chill until cold -several hours-or you are ready pour into the ice cream maker.Freeze in the ice cream maker according to the manufacturers directions. Makes about a quart.',45,45,0);
INSERT INTO "Recipe" VALUES(617,'Sweet-N-Smoky Salmon With Ginger Mahogany Rice','https://img.spoonacular.com/recipes/662654-556x370.jpg','1 cup brown sugar, 2 cups chicken stock, 3 inches ginger, 1.5 teaspoons liquid smoke, 2 Tb peanut oil, 1 cup mahogany rice, 4 fillet salmon, 4 servings salt and pepper, 2 tablespoons soy sauce','Place the salmon in bowl, or large zip bag with soy sauce, liquid smoke and brown sugar. Let it marinate for at least 1 hourbut you could marinate over night! When ready to use, preheat the grill or an iron skillet to high heat.In a medium sauce pan, over high heat, toast the rice in 1 Tb. of oil for 2 minutes. Then add the chicken stock and a large pinch of salt and pepper. Bring to a boil. Lower the heat to a simmer and cover. Simmer the rice for about 40 minutesor as directed on the package.Meanwhile, peel the ginger and cut into thin strips. (julienne)Heat a small skillet over medium-high. Add 1 Tb. of oil to the skillet. When the oil is hot, drop the ginger in and pan-fry for 1-2 minutes, moving with a spatula, until they are light brown.Remove from the pan and drain on a paper towel. Sprinkle with salt.While the rice is cooking, CAREFULLY brush the grill with vegetable oil. (You could also use grill spray.) Pepper the salmon and place it on the grill, top-side-down. Cook 3 minutes.Flip, then carefully sprinkle the tops with a little extra brown sugar and grill for another 3-5 minutesuntil just cooked through.Cover with foil and let them rest for 5-10 minutes before serving.',45,45,0);
INSERT INTO "Recipe" VALUES(618,'Honey Sweet Corn Bread','https://img.spoonacular.com/recipes/647287-556x370.jpg','4 teaspoons baking powder, 2 tablespoons butter, 1 cup corn meal, 1  egg, 1 cup flour, 2 tablespoons honey, 3 teaspoons milk, 0.5 teaspoon salt, 1 teaspoon vanilla, 0.25 cup sugar','Start off by mixing your dry ingredients together; the corn meal, flour, baking powder, sugar, and salt.Next up, youll mix together your vanilla, honey, egg, and milk. Now add it to the dry mixture and combine well.Finally youll stir in the melted butter.Now, pour the mixture into a greased up 9x9 pan and cook it in an oven preheated to 350 degrees for 25 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(619,'Impossible" Coconut Pie','https://img.spoonacular.com/recipes/631785-556x370.jpg','3  eggs, 130 g sugar, 75 g butter, 60 g desiccated coconut, 5.5 tbsp lemon zest, 1.5 tbsp orange zest, 60 ml lemon juice, 10 servings m orange juice, 200 ml coconut milk, 70 g flour',replace('Preheat oven to 170C.\nPlace the eggs, sugar, butter, desiccated coconut, lemon and orange zest and juice, coconut milk and flour in a food processor and blend until well combined. Pour into a buttered 22cm (9 inch) pie tray.\nPlace pie tray at the lower rack of the oven and bake for 60 - 80 minutes. Loosely cover with aluminium foil when you find the pie turning brown during half way of baking.  Set aside to cool, then refrigerate for 1 hour to chill.\nSlice and serve with a little whipped cream and passionfruit or  blueberry jam and sprinkle some toasted desiccated coconut over it.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(620,'How to Make the Best Chili','https://img.spoonacular.com/recipes/1066893-556x370.jpg','0.25 cup bell pepper, 15 oz kidney beans, 0.25 tsp cayenne pepper, 0.5 tbsp chili powder, 1.5 tsp cumin, 2 lbs ground beef, 1.5 cups onions, 0.5 tsp oregano, 1 tsp group pepper, 1 can z pinto beans, 46 oz tomato juice, 12 oz tomato paste can be subbed, 1 cup water, 0.5 tsp sugar',replace('Instructions\n\nStep 1: Brown the lean ground beef in a deep skillet. Cook over medium heat until cooked all the way through, and then drain.\n\nStep 2: In a large pan over high heat add in all of your additional ingredients: cooked ground beef, tomato juice, kidney beans, pinto beans, water, tomato paste, chili powder, cumin, black pepper, oregano, sugar, cayenne pepper, bell pepper, and chopped onions. Bring to a boil.\n\nStep 3: Once your large pot of chili has started to boil, lower the heat and simmer for 2 hours uncovered.','\n',chr(10)),130,130,0);
INSERT INTO "Recipe" VALUES(621,'Mascarpone & Ricotta Cheese Cake','https://img.spoonacular.com/recipes/651189-556x370.jpg','0.25 cup almonds, 1 tablespoon butter, 16 oz whipped cream cheese, 4 large eggs, 2 tbsp flour, 1.5 cups graham crackers, 1 tbsp lemon juice, 8 oz mascarpone cheese, 8 oz ricotta cheese, 0.5 tsp salt, 1.25 cups sugar, 2 tbsp sugar, 1 tsp vanilla extract','DirectionsPreheat oven to 325.Crust:Grind graham crackers and almonds using food processor or a mortar and pestle. Add melted butter and salt and press into bottom of greased springform pan or deep dish pie pan. Bake for 10 minutes. Let cool. Mix sugar and flour together and sprinkle over top of crust. (This prevents crust from getting soggy)Filling:Beat cream cheese, mascarpone cheese, ricotta cheese and sugar in a large bowl until smooth. Beat in lemon juice and vanilla. Add in eggs one at a time. Pour cheese mixture over crust in pan. Bake until the center of the cheesecake is wobbly when shaken, about 1hr and 5 mins. Let cool then refrigerate, preferably overnight.',45,45,0);
INSERT INTO "Recipe" VALUES(622,'Homemade Apple Almond Granola Bars','https://img.spoonacular.com/recipes/646906-556x370.jpg','2.5 C rolled oats, 0.25 C ground flax seed, 0.25 C oat bran, 0.25 C wheat bran, 0.5 tsp salt, 2 tsp baking powder, 1 tsp cinnamon, 0.33333334 C sugar substitute, 0.25 C coconut, 1 C non-fat milk, 0.25 C honey, 1  egg, 1 tsp vanilla extract, 1 small apple, 0.6666667 C almonds',replace('1. Preheat oven to 350. Spray 9x13 pan with non-stick cooking spray.\n2. In a large bowl, stir together the oats, flax seed, oat bran, wheat bran, salt, powder, cinnamon, sugar substitute, and coconut until well combined.\n3. Add in the milk, honey, egg, and vanilla. Stir until combined.\n4. Stir in the apples and almonds.\n5. Press into pan. Bake for 15-20 minutes or until edges start to brown.\n6. Let cool for 10 minutes, then cut into bars. Let cool completely.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(623,'Double Chocolate Brownie Semifreddo','https://img.spoonacular.com/recipes/641586-556x370.jpg','9 ounces chocolate, 3  eggs, 2  egg yolks, 1 teaspoon vanilla extract, 1 cup sugar, 2 cups heavy cream, 12 ounces chocolate brownies',replace('Place chocolate in a medium-sized heatproof bowl. Place over a saucepan of simmering water and using a spatula stir until the chocolate has melted. Set aside.\nPlace the eggs, extra yolks, vanilla, and sugar in a large-sized, heatproof bowl. Place over a saucepan of simmering water and, using a hand-held electric mixer, beat for 6 to 8 minutes or until the egg mixture becomes thick and pale. Remove from heat and allow to cool slightly.\nIn a medium-sized bowl, whisk the cream until stiff peaks form. Using a large spatula, gently fold through the egg mixture until well combined. Fold in the melted chocolate and brownies. Pour into 2 loaf pans and freeze for at least 6 hours or overnight.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(624,'Chocoholic''s Deep Dark Dream Chiffon Cake','https://img.spoonacular.com/recipes/638797-556x370.jpg','1 cup all purpose flour, 2 teaspoons baking powder, 0.25 cup butter, 2 tablespoons butter, 3.5 ounces 0%% belgium chocolate, 0.25 cup cocoa, 0.25 cup 5%% cream, 0.5 cup 5%% cream, 0.25 teaspoon cream of tartar, 0.75  dutch cocoa, 6  egg whites, 5  egg yolks, 2 cups icing sugar, 0.5 teaspoon salt, 1 cup sugar, 1 cup sugar, 0.5 teaspoon vanilla, 1 cup vegetable oil, 0.6666667 cup water','Cake:In a bowl add the cocoa and pour in the boiling water. Stir to combine and let cool.In a large mixing bowl combine the flour, 1 cup sugar, baking powder and salt.In a separate bowl add the 6 egg whites and cream of tartar. With an electric mixer beat the egg whites until soft peaks form, gradually add the 1/3 cup sugar and beat until firm but not dry.Make a well in the dry ingredients.Add the oil, egg yolks, vanilla and cooled cocoa. Beat until smooth.Mix in about a 1/4 of the egg whites to loosen the batter and then fold in the remainder of the egg whites.Pour into 2-8 inch prepared cake pans and bake at a preheated 350 F oven for 30-35 minutes. The cake is done when a wooden skewer inserted in the center comes out clean.Filling:With and electric mixer, blend the sugar, cocoa and butter, add the vanilla and cream. Mix and add more cream to obtain the desired texture.Topping:In a double boiler or microwave bring the cream to just below the boiling point. Add the chocolate pieces and butter, and with a wooden spoon stir to blend. Allow to cool, this will thicken the ganache gor the topping.Assembly:With a long knife, slice the cakes in the center to  obtain 4 layers in all.  Sprinkle some Kirsch or other favourite liqueur on the first layer of cake and spread a thin layer of the filling. Place raspberry halves on the filling and place a second layer of cake on top. Continue in the same manner until the remaining 2 layer are filled, leaving the top layer to be iced with the ganache topping.',45,45,0);
INSERT INTO "Recipe" VALUES(625,'Falafel Burgers','https://img.spoonacular.com/recipes/642540-556x370.jpg','2 cans garbanzo beans, 1 tablespoon chili powder, 1 tablespoon coriander, 1 tablespoon cumin, 4 tablespoons flour, 1 large handful parsley, 2 cloves garlic, 2  juice of lemon, 4  pita pockets, 1 small onion, 4 servings salt and pepper, 0.5 cup tahini, 1.5 teaspoons turmeric, 0.25 cup vegetable oil, 3 tablespoons water','Combine the chickpeas, onion, garlic, parsley, flour, spices, and salt, and pulse until the mixture is well combined. Form the mixture into 4 large patties.Heat the oil in a large, nonstick skillet set over medium-high heat. Cook for about 3 minutes per side.Make the tahini sauce: Whisk the tahini paste with the water, lemon juice and zest, salt, and freshly ground black pepper in a mixing bowl.Serve the burgers in pita pockets or on a bun. Top them with tahini sauce, lettuce, and tomato.',45,45,0);
INSERT INTO "Recipe" VALUES(626,'Stuffed Salmon With Tomato-Olive Tapenade','https://img.spoonacular.com/recipes/662087-556x370.jpg','2 servings brie cheese, 2 servings dill weed, 6 cloves garlic, 2 servings olive oil, 1 cup olives, 1  onion, 2  salmon filets, 2 servings salt and pepper, 1 cup spinach, 2 large tomatoes','Preheat oven to 350F.Pound salmon fillets and rub with olive oil and dill.In bowl, combine chopped spinach, onions, and garlic. Season with salt.Spread spinach mixture on salmon fillet. Slice brie and add on top. Carefully roll salmon and tie with string.Bake for about 15-18 minutes.Chop olives in food processor. Add chopped tomatoes and blend. Spread on top of salmon.',45,45,0);
INSERT INTO "Recipe" VALUES(627,'Sardine Croquettes (Croquetas De Sardinas)','https://img.spoonacular.com/recipes/659270-556x370.jpg','1 can sardines, 2 cups cassava, 4 tablespoons parmesan cheese, 2  egg yolks, 2  egg whites, 2 teaspoons baking powder, 1 cup bread crumbs, 0.125 cup cilantro, 14 servings oil, 14 servings salt& pepper','I used frozen cassava because it is a time saver! So no judging. In a pot with salted water cook the cassava also known as in Spanish yuca until fork tender.Once the cassava is cooked throughly, mash it till smooth. Then add in the sardines, cheese, egg yolks, baking powder, salt, pepper, and cilantro/parsley, mix well.Preheat oil in frying pan. With wet hands start forming balls with the sardine batter, dip it in the egg whites then roll it in the bread crumbs, use all the batter. Fry corquettes till golden brown on all sides. Let it rest on a double-lined paper towel to remove excess oil. Serve with ketchup.',45,45,0);
INSERT INTO "Recipe" VALUES(628,'Chicken Burritos','https://img.spoonacular.com/recipes/637999-556x370.jpg','3  avocadoes, 600 grams chicken thigh meat, 1 bunch cilantro, 4  flour tortillas, 1  juice from lemon, 1 large onion, 1 teaspoon pepper, 2 teaspoons salt, 4 large tomatoes','Cut the chicken thighs into one inch sized pieces.Add about 2 teaspoons of salt and 2 teaspoons of pepper. Or do what I always do for dishes that call for salt and pepper. I use Masterfoods Garlic Pepper. Give it a good sprinkle, about 1 tablespoon of it. Set aside to marinate for a couple of hours.Slice the top of the tomatoes off.Using a small spoon, scoop out the soft insides of the tomatoes. This reduces the moisture in the dish and prevents sogginess.Chop the tomatoes up into small bits.Chop the onions into small bits.Place the onions and tomatoes in a large bowl.Chop up a bunch of cilantro. Use as much or as little as you like.Add the cilantro to the onions-tomatoes mixture. Toss together and set aside.Cut a slit round an avocado, against its seed.Holding each side of the cut avocado, twist the avocado open to reveal the seed.Remove the seed and scoop out the flesh. Place the avocado flesh in a large bowl and mash it up evenly till it becomes creamy.Add the tomatoes mixture to the avocados.Combine well.Squeeze in juice from one lemon.Add a generous portion of salt to taste. About 1 to 2 teaspoons.At this point, youll have guacamole. If you like, dish it up in a serving bowl and serve it with chips.Now cook the chicken. Heat a pan with a few tablespoons of cooking oil till its very hot. It has to be very hot or the chicken wont brown.Add the chicken to the pan. Be careful! Itll sizzle and splatter.Turn the pieces over to brown the other side after a few minutes.When the chicken are browned, remove them from the pan and set aside at a warm place.Using a clean, dry pan, toast the tortillas one at a time on each side.They are ready to be used when they are soft and warm.Add a serving of the guacamole mixture.Add a serving of the chicken.Quickly wrap the burrito up. If it cools, the tortilla will crack and it would be impossible to roll it up.Roll over once. Fold in the sides, and roll over again till its fully wrapped.Serve immediately or wrap in aluminum foil and keep them in the oven till ready to eat.',45,45,0);
INSERT INTO "Recipe" VALUES(629,'Venison Stew','https://img.spoonacular.com/recipes/664786-556x370.jpg','2 pounds venison stew meat, 8 cups baby carrots 4 stalks celery 1 can mushrooms 1 piece pepper 1 cup flour and 3 tbsp 2 tablespoons bee, 8 cups water, 4 pieces potatoes, 1 piece onion, 4 pieces baby carrots, 4 stalks celery, 1 can mushrooms, 1 piece bell pepper, 1 cup flour and 3 tbsp, 2 tablespoons beef bouillon','Cut all ingredients into 1 inch pieces. Dredge venison with flour and spices. Brown venison in hot vegetable oil. Boil and simmer venison 2 hours with beef bouillon and water. Add remaining ingredients and simmer for 1/2 hour. Mix 3 tablespoons flour and 1 cup cold water and add to stew to thicken.',45,45,0);
INSERT INTO "Recipe" VALUES(630,'Soft Croatian corn bread - proja','https://img.spoonacular.com/recipes/660504-556x370.jpg','1.5 cups all purpose flour, 1 packet baking powder, 0.5 cup corn grits, 2 cups cornmeal, 250 g cottage cheese, 2  eggs, 1 cup natural yogurt, 0.5 cup olive oil, 1 tsp salt, 2 cups mineral water','Mix and combine eggs, salt, corn and wheat flour, instant polenta, baking powder, olive oil, and yogurtGradually add as much mineral water as needed to make a quite thin batter.Mix in and combine cottage cheese.Pour batter into the baking pan lightly greased with butter and bake in oven at 220C for about 30 minutes or until the proja - corn bread is baked (trick with a toothpick).',45,45,0);
INSERT INTO "Recipe" VALUES(631,'Ricotta Orange Pound Cake With Amaretto Strawberries','https://img.spoonacular.com/recipes/658339-556x370.jpg','1.5 cups cake flour, 2.5 teaspoons baking powder, 1 teaspoon kosher salt, 0.75 cup butter, 1.5 cups milk ricotta cheese, 1.5 tablespoons sugar, 3 large eggs, 1 teaspoon vanilla extract, 1  orange zest, 2 tablespoons amaretto, 1 pint strawberries, 8 servings whipping cream',replace('Preheat the oven to 350 F. Grease a 9 X 5 X 3 inch loaf pan with butter. In a medium bowl combine the flour, baking powder, and salt. Stir to combine.\nUsing an electric mixer, cream together the butter, ricotta, and sugar until light and fluffy, about 3 minutes. With the machine running, add the eggs one at a time. Add the vanilla, orange zest, and Amaretto until combined. Add the dry ingredients, a small amount at a time, until just incorporated. Pour the mixture into the prepared pan and bake until a tooth pick comes out clean and the cake is beginning to pull away from the sides of the pan, about 45-50 minutes. Let the cake cool in the pan for 10 minutes and then transfer to a wire rack to cool completely. Using a mesh sieve, dust the cooled cake with powdered sugar.\nMeanwhile, place the strawberries in a small bowl with the remaining one Tablespoon sugar. Let sit until the juices have pooled around the strawberries.\nPrepare whipping cream, flavoring it with vanilla and Amaretto.\nTo serve, slice the cake and serve with a spoonful of strawberries and their juices over the top of the cake. Add a dollop of whipped cream.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(632,'Radish & Snap Pea Quinoa Salad','https://img.spoonacular.com/recipes/657719-556x370.jpg','1 cup quinoa, 2 cups water, 1 pint snap peas, 7 medium radishes, 1 large handful flat leaf parsley, 0.25 cup yogurt, 2 tbsp tahini, 0.5  juice of lemon, 4 servings sea salt, 4 servings water',replace('Make the quinoa: combine the quinoa and water in a sauce pan and bring to a boil.  Reduce the heat to a simmer (medium-low), stir the quinoa, then cover it and cook for 10 to 15 minutes until all of the water has been absorbed.  Remove it from the heat, let it sit for 5 minutes, then fluff it up with a fork.  Cool the quinoa a bit before making the salad.  The quinoa can be made several days in advance and kept in the fridge if needed before using.\nMake the dressing: Combine the yogurt, tahini, lemon juice, and a pinch of sea salt in a bowl and whisk until smooth.  Thin the dressing out with a bit of water if it is too thick.  Set aside.\nMake the salad:  Combine the quinoa, snap peas, radishes, and parsley in a bowl.  Pour over about half of the dressing, then toss to combine.  Taste the salad and add more dressing or sea salt if desired.  Enjoy at room temperature or chilled.  Makes 3 to 4 main dish servings or 6 to 8 side servings.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(633,'Apple Persimmon Sauce','https://img.spoonacular.com/recipes/632574-556x370.jpg','2  persimmons, 6  apples, 1 Tsp ground cinnamon, 0.25 Tsp nutmeg, 1 cup water, 0.33333334 cup brown sugar, 1 Tsp lemon juice',replace('Combine all ingredients in a medium pot and bring to a boil.\nCover and reduce heat to medium low. Simmer for 25-30 minutes.\nMash apple sauce with a potato masher until its your desired consistency.\nStore in an airtight container in the fridge for up to two weeks.\nCan also be frozen and stored for up to a year.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(634,'Cherry Coconut Milk Smoothie','https://img.spoonacular.com/recipes/794350-556x370.jpg','1  banana, 2 cups cherries, 0.6666667 cup coconut milk, 0.33333334 cup hemp milk, 1 teaspoon vanilla','Combine all of the ingredients in a blender and process until smooth. Add a bit more almond or hemp milk if the mixture is too thick.Tip: To freeze bananas for smoothies, peel the banana and cut into slices. Place the slices on a baking sheet lined with parchment paper and freeze. Once frozen, transfer to a freezer-friendly container or freezer bag. The bananas will freeze well for up to 4 to 6 months.',45,45,0);
INSERT INTO "Recipe" VALUES(635,'Water-Cado Salad','https://img.spoonacular.com/recipes/664997-556x370.png','2  avocados, 1.5 lbs watermelon, 2  juice of lime, 0.5  onion, 1 tablespoons olive oil, 0.5 bunch cilantro, 4 servings salt and pepper','Add all ingredients into a bowl and toss gently.',45,45,0);
INSERT INTO "Recipe" VALUES(636,'Easy Key Lime Pie','https://img.spoonacular.com/recipes/642003-556x370.jpg','1 cup butter, 3  egg yolks, 1.25 cups graham crackers, 0.5 cup lime juice, 3 tablespoons sugar, 14 ounces condensed milk, 1 tablespoon water, 8 servings whipped cream','Crust: melt butter and stir in 1/4 cup sugar. Add crushed crackers and toss to mix well. Spread evenly into a 9-inch pie plate and press onto bottom and sides. Chill 1 hour or until firm. Can also bake in a 375 degree oven for 4-5 minutes and then cool before filling.In a medium bowl, beat egg yolks with a whisk or a fork. gradually whisk/stir in condensed milk. Add lime juice, water, and a few drops of green food coloring if desired. Mixture will thicken as you stir.Spoon filling into the crust. Bake in a 350 degree oven for 25 minutes and cool for 1 hour, then chill for 3-4 hours. Top with whipped cream and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(637,'Breaded Shrimp and Spicy Mayo Appetizer','https://img.spoonacular.com/recipes/716297-556x370.jpg','0.75 cup all purpose flour, 0.75 cup bread crumbs, 0.5 teaspoon chili powder, 1  egg, 0.5 teaspoon garlic powder, 2 tablespoon mayonnaise, 0.5 teaspoon onion powder, 0.5 teaspoon suya pepper, 0.5 teaspoon salt, 12 jumbo shrimps, 1 tablespoon sriracha sauce','Peel and devein your shrimp. You can leave the tail of the shrimp if you like. Season with the suya pepper spice and set aside.Whisk your egg and set aside.In your bowl of flour, mix in the onion powder, garlic powder, salt, chilli powder and set aside.Take your seasoned shrimp and rub in the seasoned flour, dunk it in the egg mixture and coat with the breadcrumbs.Heat up your oil for frying and fry your shrimps till golden brown on both sides.For your spicy Mayo, Mix 2 tablespoons of mayonnaise with one table spoon of sriracha sauce till properly mixed. Serve it with your breaded shrimp.',20,20,0);
INSERT INTO "Recipe" VALUES(638,'Cod with Tomato-Olive-Chorizo Sauce and Mashed Potatoes','https://img.spoonacular.com/recipes/639851-556x370.jpg','50 g olives, 500 g cod fillets, 4 Tbs parsley, 2 servings parsley leaves, 1 Tbs lemon juice, 1 Tbs olive oil, 2 Tbs olive oil, 240 g plum tomatoes, 300 g potatoes, 100 g bell pepper, 0.5 tsp salt, 100 g a semi-smoked sausage','If frozen, thaw completely the cod fillets, and dry them with paper towels. season with salt and set aside.Peel and quarter the potatoes, and cook in lightly salted water until tender.Meanwhile, fry the pepper in olive oil for 3-4 minutes.Add cubed sausage, saut for another 2-3 minutes.Add the whole plum tomatoes,  halve them with a flat end of a wooden spoon.Stir in olives and parsley, cook the sauce gently for 2 minutes. Set aside.Drain the potatoes and season with parsley, olive oil and lemon juice. Use a hand masher to mix and mash. Leave in a warm place.Place the cod fillets into a hot oiled non-stick pan and cook over a high heat for 5 minutes on each side or until golden brown.Serve with mashed potatoes and sauce.',45,45,0);
INSERT INTO "Recipe" VALUES(639,'Sweet Mustard BBQ Pork Chops','https://img.spoonacular.com/recipes/662535-556x370.jpg','4  pork chops, 0.25 cup dijon mustard, 2 cloves garlic, 3 teaspoons coarsely ground pepper, 0.5 cup honey, 0.25 cup lemon juice, 0.25 cup soy sauce','Combine honey, Dijon mustard, lemon juice, soy sauce, and garlic in a bowl. Stir until sugar dissolves.Place pork chops in large resealable plastic container or bag. Pour marinade over pork chops; seal bag/container. Refrigerate for at least 4 hours (preferably overnight), shaking container or turning bag occasionally.Prepare barbecue (medium-high heat). Sprinkle pork chops with fresh cracked pepper.Grill pork chops until instant-read thermometer inserted into center of chops registers 145 F to 150 F, about 5-7 minutes per side, brushing with leftover marinade and moving chops to cooler part of rack if burning.Transfer chops to platter; cover with foil, and let stand 5 minutes. Serve.',45,45,0);
INSERT INTO "Recipe" VALUES(640,'Quick and Easy Caprese Salad','https://img.spoonacular.com/recipes/657537-556x370.jpg','4 servings balsamic vinegar, 0.25 cup basil leaves, 8 ounces mozzarella cheese, 4 servings olive oil, 4 servings bell pepper, 0.5 tsp salt, 4  tomatoes','Slice mozzarella and tomatoes into 1/4 inch slices and arrange on platterSprinkle basil leaves over allDrizzle with oil and vinegarSalt and pepper to taste',45,45,0);
INSERT INTO "Recipe" VALUES(641,'Herb chicken with sweet potato mash and sautéed broccoli','https://img.spoonacular.com/recipes/646651-556x370.jpg','1 medium head broccoli, 4 servings pack maggi so herbs, 60 mL olive oil, 1 large russet potato, 4 servings pepper and salt, 1.5 pounds chicken breasts, 3 large sweet potatoes, 2 tablespoons butter',' Preheat the oven to 350F (180C) or 320F (160C) for convection oven and cook the chicken according to the pack instructions. About 15 minutes before the end of the chicken cooking time, place the diced potato into boiling water for 5 minutes, then add the sweet potato and cook until the potatoes are tender. Roughly mash, adding butter, salt, and pepper to taste, then mash thoroughly. Heat the oil in a pan and quickly saut the broccoli until tender. Cover to keep warm. Remove the chicken from the oven, leave to cool for a minute then cut the bag open and gently tip the contents into a dish. Slice the chicken breasts into chunky pieces on a board, keeping the chicken breast shape together. Serve the mash potato topped with the chicken and remaining sauce with a side of broccoli.',45,45,0);
INSERT INTO "Recipe" VALUES(642,'Fusilli With Zucchini Flowers, Ricotta and Saffron','https://img.spoonacular.com/recipes/644108-556x370.jpg','2 servings almonds, 2 servings oil evo, 2 servings bell pepper, 1  onion, 100 grams ricotta cheese, 1 packet saffron, 2 servings salt, 12  zucchini flowers, 160 grams fusilloro verrigni o fusilloni, 160 grams fusilloro verrigni o fusilloni','Fusilli with zucchini flowers, ricotta and saffronWhat do I need for 2 peopleWash and finely chop the onion  dry them gently in a pan with a drizzle of extra virgin olive oil, a pinch of salt and the sliced almonds.Discard the stem and pistil of the flowers of pumpkin, cut into strips and add them to the mixture, stir briefly and turn off.Drop the Fusilloro in plenty of boiling salted water and cook for 9 minutes (al dente).In a bowl mix the ricotta with saffron, add a spoonful of pasta cooking water to obtain a smooth cream, add salt and pepper.Drain the pasta into the pan with the fried zucchini flowers, add saffron cream and mix gently.Serve immediately.',45,45,0);
INSERT INTO "Recipe" VALUES(643,'Quick and Easy Caprese Salad','https://img.spoonacular.com/recipes/657537-556x370.jpg','4 servings balsamic vinegar, 0.25 cup basil leaves, 8 ounces mozzarella cheese, 4 servings olive oil, 4 servings bell pepper, 0.5 tsp salt, 4  tomatoes','Slice mozzarella and tomatoes into 1/4 inch slices and arrange on platterSprinkle basil leaves over allDrizzle with oil and vinegarSalt and pepper to taste',45,45,0);
INSERT INTO "Recipe" VALUES(644,'Andouille Sausage and Potato Hash','https://img.spoonacular.com/recipes/632353-556x370.jpg','1 medium yukon gold potato, 0.5 cup bell pepper, 0.5 cup bell pepper, 0.5 cup onion, 1 link pork andouille sausage, 1 teaspoon canola oil, 1 pinch garlic salt, 1 Dash cayenne pepper',replace('Preheat the oven to 425. Toss the potato, peppers, and onions with 1 teaspoon canola oil.\nSpread onto a baking sheet. Sprinkle with garlic salt and pepper. Roast for 10 minutes.\nAdd the sliced sausage to the pan and roast for an additional 10 minutes.\nSprinkle with a dash of cayenne pepper.\nGarnish with finely chopped scallions if desired. Enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(645,'Gluten-Free Chocolate-Pecan Quickbread','https://img.spoonacular.com/recipes/644878-556x370.jpg','4 tablespoons butter, 2 cups flour, 0.25 cup sugar, 0.25 cup brown sugar, 0.75 teaspoon baking soda, 0.5 teaspoon salt, 1 cup semi-sweet chocolate chips, 0.5 cup pecans, 2  eggs, 1 cup applesauce, 0.5 cup vanilla-honey greek yogurt, 0.25 teaspoon vanilla extract',replace('Preheat oven to 350 degrees Fahrenheit.\nButter a 5"x9" loaf pan.\nHeat the butter until just melted and set aside to cool.\nIn a large bowl, combine the flour, sugars, baking soda and salt.\nStir in the chocolate chips and pecans.\nIn a separate bowl, combine the eggs, applesauce, yogurt, vanilla and melted butter.\nPour the wet mixture into the bowl of dry ingredients and stir until just combined, making certain not to over-mix.\nPour the batter into the loaf pan.\nBake for 1 hour or until a toothpick inserted into the center comes out clean.\nAllow to cool for 10 minutes before removing from pan and transferring to a wire rack.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(646,'Crock Pot Boneless Beef Ribs','https://img.spoonacular.com/recipes/640856-556x370.jpg','1.5 cups beef broth, 4 pounds beef ribs, 0.5 cup brown sugar, 0.25 cup butter, 0.6666667 cup flour, 1 cup ketchup, 0.5 cup mustard, 1  onion, 0.5 teaspoon pepper, 2 teaspoons salt, 2 tablespoons tabasco sauce','In a large zippy bag place the flour, salt &amp; pepper, mix to combine. Add the ribs in batches and shake to coat. In a large frying pan melt the butter and brown the ribs on all sides, transfer the browned ribs to the bottom of a 5 qt crock pot. In the same frying pan combine the remaining items and bring to a boil, pour over the ribs. Cover and cook on low for 10-12 hours or until meat is tender and falling apart. Serve hot over mashed taters then ladle some of the sauce over top.',45,45,0);
INSERT INTO "Recipe" VALUES(647,'Chocolate Pudding - Rave Diet','https://img.spoonacular.com/recipes/639177-556x370.jpg','2 cups water, 0.5 cup maple syrup, 4 tablespoons corn flour, 3 tablespoons cocoa powder, 1 teaspoon vanilla, 3 servings roasted hazelnuts',replace('Combine water, maple syrup, cocoa, cornstarch or corn flour and vanilla together in a saucepan.\nWhisk smooth with a spoon or hand whisker.\nCook over medium heat and stir constantly until pudding is very thick.\nPour into dessert dishes and top with chopped hazelnuts.\nCool and serve.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(648,'Pasta with Peas and Italian Sausage','https://img.spoonacular.com/recipes/654935-556x370.jpg','2 tablespoons butter, 1 kilo canned tomatoes, 1 box farfalle pasta, 4 servings sausage, 1 tablespoon olive oil, 1 cup peas, 4 servings salt and pepper, 26 oz pomi strained tomato sauce','Cook the pasta following the package directions. Meanwhile in a very large skillet over medium heat add the olive oil and add the sausages. Saut` the sausage meat until slightly brown all over, add the frozen peas and the tomatoes. Season to taste with salt and pepper. Lower the heat to medium and cook for another 10 to 15 minutes.Drain the pasta and return it to the pan, add the butter and the tomatoes with sausage. Mix well and server hot.',45,45,0);
INSERT INTO "Recipe" VALUES(649,'Banana Bread','https://img.spoonacular.com/recipes/634006-556x370.jpg','3  bananas, 1 cup butter, 1 cup sugar, 1  egg, 1 teaspoon vanilla, 1 teaspoon baking soda, 1 teaspoon salt, 1.5 cups flour','Preheat the oven to 350 degree. In big bow smashed banana and add melted butter, then add sugar, egg, and vanilla. Keep mixer then add flour, salt and baking soda mixed well then pour buttered into 8 X 3.75 inch loaf pan. Bake for 1 hour. keep cool on the rack. Slice and serve.',45,45,0);
INSERT INTO "Recipe" VALUES(650,'Peruvian Roast Chicken','https://img.spoonacular.com/recipes/655793-556x370.jpg','3 lb chicken, 4  garlic cloves, 0.5  juice of lemon, 3 tablespoons red wine vinegar, 1 tablespoon soy sauce, 3 tablespoons olive oil, 2 tablespoons paprika, 1 tablespoon cumin, 1 teaspoon turmeric, 4 servings salt, 4 servings pepper, 1 serving kitchen twine, 4 servings kitchen twine',replace('1. Mix together the marinade ingredients.\n2. Place the whole chicken into a large (about 2 gallon size) ziploc bag and pour in the marinade.\n3. Spread the marinade so that it covers all the chicken.\n4. Marinade overnight.\n5. Take the chicken out of the fridge about 30-45 minutes before you roast it, so it comes closer to room temperature. This helps the chicken become more moist and cooked evenly.\n6. Preheat the oven to 450F.\n7. Remove the chicken from the marinate and brush off any garlic so it will not burn.\n8. Lay the chicken breast side up in a roasting pan or cast iron skillet.\n9. Truss the chicken. This keeps the juices in during the roasting and makes the meat more tender.\n10. Roast 45-55 minutes.\n11. Let rest 5 minutes before carving.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(651,'I Like My Peas with Pancetta','https://img.spoonacular.com/recipes/647698-556x370.jpg','12 oz gr of peas, 4 oz guanciale, 1 small onion, 1 cloves garlic, 2  cherry tomatoes, 4 servings spoonful red wine vinegar, 1 small handful parsley, 4 servings salt & pepper, 4 servings extra virgin olive oil',replace('Bring a medium pot up to boil. In the meantime, in a medium skillet on medium-low heat, slowly render down the pancetta for 4-5 minutes, trying not to brown it and not crispy. If it starts to brown remove the pan from the heat or lower the flame.\nNext add garlic & onion, saut for 5-6 minutes.\n(Vegetarian Note: Just omit the the pancetta & saut the onions & garlic in olive oil.)\nWhen the onions & garlic are about 2 minutes from being ready, add the tomatoes.\nAt the same time toss the peas in the water and blanch for 2-3 minutes. You want them approximately half-cooked. Strain the peas and throw them directly into the pan with the pancetta adding a spoonful of the pea-water. Allow to cook until peas are cooked but still have a bite.\nTaste and adjust the seasoning with salt & pepper.\nJust before you serve, toss in the herbs and drizzle with good extra virgin olive oil.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(652,'Stuffed Artichoke Main Dish','https://img.spoonacular.com/recipes/640921-556x370.jpg','1  artichoke, 2  chicken breasts, 2 cloves garlic, 1  lemon, 1 teaspoon maple syrup, 1 teaspoon olive olive oil, 1 teaspoon parmesan, 2 servings bell pepper, 1 large potato, 1 sprig rosemary, 2 servings salt, 1 handful mozzarella cheese','Preparation of the artichokePull apart center leaves of artichokeCut the center so that you take the prickly centerUse spoon to get all that out so you only have the center being emptyAdd a bit of lemon juice to make sure it doesn''t change colorAdd artichoke to boiling waterLet boil for 10 min so it gets kind of softTake outAdd cold water so it coolsCut the edges of artichokeHow to make the stuffing.Boil the potato, or put into microwave to cook it up. (it just needs to be soft)In a sauce pan at med-high heat add the olive oil, rosemary, maple syrup, crushed and finely sliced garlic and the chicken. Add the lemon sliced  up to the saucepan and cook it all together for for 15 min. So that it is all cooked up.  and put it onto a plate to cool.Now there should be some sauce still left in the pan, so slice the cooked potatoe and add it to the pan to get all that tasty sauce.Now cut up the chicken, potato and some grated mozzarella cheese and mash it up so that you can stuff it into the artichoke.Bake in oven at 350 for 20ish min.',60,60,0);
INSERT INTO "Recipe" VALUES(653,'Peppermint White Chocolate Fudge','https://img.spoonacular.com/recipes/655687-556x370.jpg','2 cups chocolate chips, 12 ounce vanilla frosting, 8 servings food coloring, 0.5 tsp peppermint flavoring, 1 handful peppermint candies',replace('Line an 8X8 pan with plastic wrap or wax paper\nIn a large bowl, melt white chocolate chips by microwaving 30 seconds at a time, stirring between sessions.\nAdd the container of vanilla frosting\nStir well\nAdd Peppermint flavoring and stir well\nReheat for 10 seconds if needed, so the mixture is still soft enough to pour\nPour mixture into lined pan\nPlace 6-8 drops of red food coloring on the top of the warm fudge\nWith a toothpick or knife, swirl the color into the top of the fudge\nSprinkle crushed candies over the top of the fudge\nCool in fridge until hard\nCut and enjoy!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(654,'Roasted Brussels Sprouts With Red Onions and Pancetta','https://img.spoonacular.com/recipes/658517-556x370.jpg','1.5 pounds brussels sprouts, 8 slices pancetta, 4 cloves garlic, 4  olive oil, 1 slice bread',replace('In a large plastic zippered bag, toss the Brussels sprouts, 3 pressed garlic cloves and 2 tablespoons Olive Oil.\nEmpty the contents into a ovenproof dish and roast at 350 degrees for 40 minutes.\nWhile the Brussels sprouts are roasting, in a pan heat 1/4 cup olive oil.  When the olive oil is heated through, saute a slice of bread until browned on both sides.  Set aside.\nWhen the Brussels sprouts have finished roasting... In the same pan that you sauteed the bread, add the onion and saute for about 3 minutes.  Do not let them get fully tender.  Add the pancetta and heat through for an additional minute.\nAdd the Brussels sprouts and heat through for an additional 3 minutes.  Remove from heat.\nIn a food processor, blend the bread and 1 - 2 cloves of garlic.\nSprinkle on top of the Brussels sprouts mixture and finish by a last drizzle of Olive Oil!','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(655,'Cajun Shrimp Chowder','https://img.spoonacular.com/recipes/636742-556x370.jpg','8 ounces asparagus spears, 3 slices bacon, 2 cups seafood broth, 1 tablespoon cajun spice, 1 cup corn, 3 cloves garlic, 0.5 cup heavy cream, 1 teaspoon lemon pepper, 0.5 teaspoon old bay seasoning, 1  onion, 8 servings salt and pepper, 1 pound shrimp, 14.5 Oz tomatoes','Grab up your frying pan and cook up the three strips of bacon. When they''re cooked up, pull them out, chop them up, and drain the bacon fat, reserving about a tablespoon. Turn your heat up to medium and add in your asparagus, onion, and garlic. Cook it up for 2 to 3 minutes.Add in the corn and tomatoes.Mix it together, give it a minute or two to warm up and then add in the broth, the chopped bacon and your spices; the old bay, cajun, lemon pepper, and salt and pepper to taste.Let the whole kit and kaboodle heat up for a good five minutes and then add in your cream.And last but most definitely not least, grab up your shrimp and pop them into the pan.Give the whole pan a swirl or two and allow the soup a couple minutes to heat back up.Serve with green onions sprinkled over the top.',30,30,0);
INSERT INTO "Recipe" VALUES(656,'10 Minute Brownies','https://img.spoonacular.com/recipes/631830-556x370.jpg','1 teaspoon baking powder, 0.25 cup canola oil, 0.75 cup finely-chopped walnuts, 1 cup semisweet chocolate chips, 0.75 cup sugar, 1 cup unbleached flour, 0.5 cup applesauce, 1 teaspoon vanilla extract','Preheat oven to 350 degrees F. Lightly oil a 6 x 9 inch baking pan and set aside.In a small saucepan over low heat, combine the oil and chocolate chips, stirring occasionally until melted. Remove from heat and set aside.To a large bowl, add the applesauce, sugar and vanilla. Blend well. Stir in the chocolate mixture. Whip and blend well. Add the flour, baking powder and walnuts, and mix just to combine. Spoon the batter into the baking pan. Bake for 25 to 30 minutes or until the top springs back when lightly touched. Be careful not to overbake the brownies or they will be dry. Let cool completely before cutting into squares. Store in a covered, airtight container in the refrigerator.',45,45,0);
INSERT INTO "Recipe" VALUES(657,'Baked Rigatoni','https://img.spoonacular.com/recipes/633766-556x370.jpg','14 ounces broccoli flowerets, 1 teaspoon basil, 0.25 teaspoon fennel seeds, 26 ounces pasta sauce, 1 pound rigatoni, 6 ounces mozzarella cheese, 14.5 ounces ready-cut tomatoes, 6 ounces vegetable burger crumbles','1. Preheat oven to 400 degrees. Cook pasta according to package directions, drain.2. Combine pasta, pasta sauce, tomatoes, broccoli, burger crumbles, basil, fennel seeds and 4 oz. of the mozzarella in a 9x13 baking dish. Top with remaining 2 oz. mozzarella. Bake until heated through, about 20 minutes.',45,45,0);
INSERT INTO "Recipe" VALUES(658,'Dessert That''s No Problem: Baked Pears with Oatmeal Crumble','https://img.spoonacular.com/recipes/641445-556x370.jpg','2  pears, 1.5 cups oatmeal, 0.25 cup brown sugar, 0.33333334 cup flour, 0.25 teaspoon cinnamon, 2 tablespoons butter',replace('Preheat your oven to 400 degrees F.\nIn a small bowl, mix together the oatmeal, brown sugar, flour and cinnamon.\nPlace the halved pears in a baking dish.\nSpoon the oatmeal mixture onto the top of each pear half and pat down to make a small mound.\nDot each of the pear halves with the pieces of butter.\nBake, uncovered, for about 15 minutes. Turn the oven to broil to allow the topping to brown, just for about 30 seconds. Watch the pears carefully at this point so they dont burn.\nServe with vanilla ice cream, caramel sauce or plain.','\n',chr(10)),45,45,0);
INSERT INTO "Recipe" VALUES(659,'Holiday Egg Nog','https://img.spoonacular.com/recipes/646833-556x370.jpg','0.25 teaspoon allspice, 0.5 teaspoon cinnamon, 4  egg yolks, 1 cup heavy cream, 2 cups milk, 0.5 teaspoon nutmeg, 0.5 cup sugar','Add the egg yolks and sugar to your mixer. Whip it up good until the mixture turns a light yellow color.Now, grab your small saucepan and add to it the milk, heavy cream, allspice, nutmeg, and cinnamon.Heat it up to just boiling and remove it from the heat. Grab about a half a cup of the hot milk and add it into the egg mixture, whisking constantly. Now add the tempered egg mixture back into the rest of your milk mixture, continuing to whisk constantly.Put the mixture back on medium low heat and cook it until just boiling and thickened.Pop it into a container and set it in the fridge to cool completely.',45,45,0);
INSERT INTO "Recipe" VALUES(660,'Tantalizing White Onion & Tuna Tart','https://img.spoonacular.com/recipes/662859-556x370.jpg','2 sheets ready-made puff pastry, 2 tbsp butter, 3 large onions, 3 large eggs, 1 cup cream, 6 servings salt and pepper, 1 pinch nutmeg, 0.5 cup ground mild cheese, 1 lbs mildly fish fillets',replace('Cut fish into 1/2 thick slices (if its not already). Sprinkle salt and fresh ground black pepper liberally all over the fish, and set aside.\nMelt butter in a Dutch oven over medium heat\nAdd the onions and saute for a few minutes, until they become translucent. Be sure not to brown them in any way.\nreduce heat to very low, cover the Dutch oven tightly, and cook onions for about 20 minutes, stirring once or twice to prevent browning. Onions should be fully flavored, lightly yellow, but not brown, and most of the onion juices should be gone. If this state isnt reached in 20 minutes, cover and cook longer, checking every 5 minutes for doneness.\nWhisk the eggs and cream together\nRemove onions from heat, add egg and cream mixture and stir very thoroughly, until creamy and uniform.\nSeason with salt and pepper to taste, add nutmeg.\nFinally, add the cheese and stir gently to distribute.\nAdd paprika if desire.\nSprinkle the surface of the table with flour lightly\nRoll out puff pastry to be slightly larger than the baking pan (I used a 10 pie pan).\nLine the baking pan with the layer of puff pastry, press it into the sides of the pan to form a pie shell.\nPierce the shell all over with the fork\nFold out half of the egg and onion mixture into the baking pan\nArrange the fish slices over in a single layer, covering the entire surface of the pie\nFold out the other half of the egg and onion mixture over the fish layer\nIf you wish to make patterns in the pie, make them at this time. I improvised and used a plastic cap of a water bottle to cut out incomplete circles in the crust. While baking, the circles puffed out and shrunk, creating little peek-a-boo openings in the pie.\nCarefully transfer the top pie crust onto the top of the pie. Stretch out if necessary to distribute your patterns nicely.\nUsing a rolling pin, press the pie crusts together to the rim of the baking pan, thus cutting the extras off without stretching the crusts.\nBake for about 30 minutes at 425F, or until the egg and onion mixture is set in the middle, and pie crust is golden and flaky.','\n',chr(10)),45,45,0);
